mcp/audit.go.content:
package mcp

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"log/slog"
	"maps"
	"os"
	"slices"
	"strings"
	"time"

	mcp "github.com/modelcontextprotocol/go-sdk/mcp"
)

// Audit logs retain tool names, outcomes, duration, and summarized arguments.
// Unclassified strings become their byte length and a truncated SHA-256 digest.

// AuditEnvironmentVariable names the variable that turns the record on and
// says where it goes: "stderr", or a path to append to.
const AuditEnvironmentVariable = "LIBTMUX_AUDIT"

// auditIdentifiers is the cleartext allowlist. User-chosen names remain summarized.
var auditIdentifiers = map[string]bool{
	"pane_id": true, "window_id": true, "session_id": true, "other_pane_id": true,
	"direction": true, "scope": true, "layout": true, "position": true,
	"max_lines": true, "max_matches_per_pane": true, "timeout": true,
	"percent": true, "width": true, "height": true, "index": true,
	"regex": true, "history": true, "effective": true, "suppress_history": true,
	"literal": true, "enter": true, "attach": true, "enabled": true,
	"confirm_self": true, "drain_first": true, "lines": true,
	"on_error": true, "tool": true,
}

func auditWriter() (io.Writer, io.Closer) {
	switch destination := strings.TrimSpace(os.Getenv(AuditEnvironmentVariable)); destination {
	case "":
		return nil, nil
	case "stderr":
		return os.Stderr, nil
	default:
		// New files use mode 0600; existing destination permissions are unchanged.
		file, err := os.OpenFile(destination, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o600)
		if err != nil {
			fmt.Fprintf(os.Stderr, "libtmux-mcp: cannot write the audit record to %s: %v\n",
				destination, err)
			return nil, nil
		}
		return file, file
	}
}

// audit records each tool call after summarizeArguments applies the cleartext
// allowlist.
func audit(writer io.Writer) mcp.Middleware {
	logger := slog.New(slog.NewJSONHandler(writer, &slog.HandlerOptions{Level: slog.LevelInfo}))
	return func(next mcp.MethodHandler) mcp.MethodHandler {
		return func(
			ctx context.Context,
			method string,
			request mcp.Request,
		) (mcp.Result, error) {
			if method != "tools/call" {
				return next(ctx, method, request)
			}
			params, _ := request.GetParams().(*mcp.CallToolParamsRaw)
			started := time.Now()
			result, err := next(ctx, method, request)

			name := "unknown"
			var arguments json.RawMessage
			if params != nil {
				name = params.Name
				arguments = params.Arguments
			}
			logger.LogAttrs(ctx, slog.LevelInfo, "tool call",
				slog.String("tool", name),
				slog.String("outcome", auditOutcome(result, err)),
				slog.Int64("elapsedMillis", time.Since(started).Milliseconds()),
				slog.Any("arguments", summarizeArguments(arguments)),
			)
			return result, err
		}
	}
}

// MCP tools may report failure in a result rather than an error.
func auditOutcome(result mcp.Result, err error) string {
	if err != nil {
		return "error"
	}
	if call, ok := result.(*mcp.CallToolResult); ok && call.IsError {
		return "refused"
	}
	return "ok"
}

func summarizeArguments(raw json.RawMessage) map[string]any {
	if len(raw) == 0 {
		return map[string]any{}
	}
	var decoded map[string]any
	if err := json.Unmarshal(raw, &decoded); err != nil {
		return map[string]any{"unreadable": true}
	}
	summary := make(map[string]any, len(decoded))
	for key, value := range decoded {
		summary[key] = summarizeValue(key, value)
	}
	return summary
}

func summarizeValue(key string, value any) any {
	switch typed := value.(type) {
	case string:
		if auditIdentifiers[key] {
			return typed
		}
		return digest(typed)
	case bool, float64, nil:
		return typed
	case []any:
		items := make([]any, 0, len(typed))
		for _, item := range typed {
			items = append(items, summarizeValue(key, item))
		}
		return items
	case map[string]any:
		nested := make(map[string]any, len(typed))
		for nestedKey, nestedValue := range typed {
			nested[nestedKey] = summarizeValue(nestedKey, nestedValue)
		}
		return nested
	default:
		return map[string]any{"redacted": true}
	}
}

// digest supports correlation but may identify guessable inputs.
func digest(value string) map[string]any {
	sum := sha256.Sum256([]byte(value))
	return map[string]any{
		"len":    len(value),
		"sha256": hex.EncodeToString(sum[:6]),
	}
}

func auditedIdentifierNames() []string {
	return slices.Sorted(maps.Keys(auditIdentifiers))
}

mcp/handshake_transport.go.content:
package mcp

import (
	"context"
	"sync"

	"github.com/modelcontextprotocol/go-sdk/jsonrpc"
	mcp "github.com/modelcontextprotocol/go-sdk/mcp"
)

// notificationToolListChanged is emitted by the SDK during handshake.
const notificationToolListChanged = "notifications/tools/list_changed"

// HandshakeOrdered holds the SDK's early tool-list notification until
// notifications/initialized; strict legacy clients reject the earlier ordering.
func HandshakeOrdered(inner mcp.Transport) mcp.Transport {
	return handshakeOrderedTransport{inner: inner}
}

// handshakeOrderedTransport delays SDK tool-list notifications until
// notifications/initialized rather than dropping them.
type handshakeOrderedTransport struct {
	inner mcp.Transport
}

func (t handshakeOrderedTransport) Connect(ctx context.Context) (mcp.Connection, error) {
	connection, err := t.inner.Connect(ctx)
	if err != nil {
		return nil, err
	}
	return &handshakeOrderedConnection{inner: connection}, nil
}

type handshakeOrderedConnection struct {
	inner       mcp.Connection
	mutex       sync.Mutex
	initialized bool
	held        jsonrpc.Message
}

func (c *handshakeOrderedConnection) Read(ctx context.Context) (jsonrpc.Message, error) {
	message, err := c.inner.Read(ctx)
	if err != nil {
		return nil, err
	}
	if request, ok := message.(*jsonrpc.Request); ok &&
		request.Method == "notifications/initialized" {
		c.mutex.Lock()
		c.initialized = true
		held := c.held
		c.held = nil
		if held != nil {
			if writeErr := c.inner.Write(ctx, held); writeErr != nil {
				c.mutex.Unlock()
				return nil, writeErr
			}
		}
		c.mutex.Unlock()
	}
	return message, nil
}

func (c *handshakeOrderedConnection) Write(ctx context.Context, message jsonrpc.Message) error {
	c.mutex.Lock()
	defer c.mutex.Unlock()
	if !c.initialized {
		if request, ok := message.(*jsonrpc.Request); ok &&
			request.Method == notificationToolListChanged {
			c.held = message
			return nil
		}
	}
	return c.inner.Write(ctx, message)
}

func (c *handshakeOrderedConnection) Close() error { return c.inner.Close() }

func (c *handshakeOrderedConnection) SessionID() string { return c.inner.SessionID() }

mcp/instance_connect.go.content:
package mcp

import (
	"context"

	"github.com/modelcontextprotocol/go-sdk/jsonrpc"
	sdk "github.com/modelcontextprotocol/go-sdk/mcp"
)

// Connect starts and tracks one client session. It requires tmux 3.3a or newer
// and rejects an opaque transport unless [AssumeResponseCommit] marks its
// response-write contract. Incoming messages remain gated until the SDK
// session has an installed scope.
func (i *Instance) Connect(
	ctx context.Context,
	transport sdk.Transport,
	options *sdk.ServerSessionOptions,
) (*ServerSession, error) {
	if i == nil {
		return nil, ErrInstanceClosed
	}
	i.mutex.Lock()
	if i.closing {
		i.mutex.Unlock()
		return nil, ErrInstanceClosed
	}
	i.connecting.Add(1)
	i.mutex.Unlock()
	defer i.connecting.Done()

	connectCtx, cancelConnect := context.WithCancel(ctx)
	stopConnect := context.AfterFunc(i.ctx, cancelConnect)
	defer cancelConnect()
	defer stopConnect()
	if i.ctx.Err() != nil {
		cancelConnect()
	}
	versionCtx, cancelVersion := context.WithTimeout(connectCtx, runtimeSetupTimeout)
	err := i.requireTmuxVersion(versionCtx)
	cancelVersion()
	if err != nil {
		return nil, err
	}
	transport, err = normalizeResponseTransport(transport)
	if err != nil {
		return nil, err
	}

	ready := make(chan struct{})
	scope := newSessionScope(i.ctx)
	var responseConnection *sessionReadyConnection
	managedTransport := sessionReadyTransport{
		inner:     transport,
		ready:     ready,
		onRequest: func(message jsonrpc.Message) error { return i.requestRead(scope, message) },
		onSettled: func(message jsonrpc.Message) { i.responseSettled(scope, message) },
		onConnect: func(connection *sessionReadyConnection) { responseConnection = connection },
		onTerminal: func(err error) {
			scope.terminate(err)
			i.connectionTerminated(scope)
		},
	}
	connected, err := i.server.Connect(
		connectCtx,
		HandshakeOrdered(managedTransport),
		options,
	)
	if err != nil {
		if responseConnection != nil {
			_ = responseConnection.Close()
		}
		close(ready)
		scope.close()
		return nil, err
	}
	session := &ServerSession{
		instance:   i,
		sdk:        connected,
		connection: responseConnection,
		scope:      scope,
		done:       make(chan struct{}),
	}

	i.mutex.Lock()
	if i.closing {
		i.mutex.Unlock()
		close(ready)
		scope.stop()
		_ = connected.Close()
		scope.close()
		return nil, ErrInstanceClosed
	}
	i.sessions[connected] = session
	i.mutex.Unlock()
	close(ready)
	go session.await()
	return session, nil
}

// Run serves one tracked session until the client, context, or instance ends.
// Its transport requirements are the same as [Instance.Connect].
func (i *Instance) Run(ctx context.Context, transport sdk.Transport) error {
	session, err := i.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	select {
	case <-ctx.Done():
		_ = session.Close()
		return ctx.Err()
	case <-session.done:
		return session.waitErr
	}
}

mcp/instance_lifecycle.go.content:
package mcp

import (
	"context"
	"errors"
	"sync"
	"time"

	sdk "github.com/modelcontextprotocol/go-sdk/mcp"
)

// Close starts shutdown and waits on a bounded internal context.
func (i *Instance) Close() error {
	if i == nil {
		return nil
	}
	ctx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
	defer cancel()
	return i.CloseContext(ctx)
}

// CloseContext starts shutdown unconditionally. ctx bounds only this call's
// wait; a later call can resume waiting for the same shutdown.
func (i *Instance) CloseContext(ctx context.Context) error {
	if i == nil {
		return nil
	}
	i.startClose()
	if err := ctx.Err(); err != nil {
		return err
	}
	select {
	case <-i.closeDone:
		return i.closeErr
	case <-ctx.Done():
		return ctx.Err()
	}
}

func (i *Instance) startClose() {
	i.closeOnce.Do(func() {
		i.mutex.Lock()
		i.closing = true
		clear(i.responses)
		if i.drainTimer != nil {
			i.drainTimer.Stop()
			i.drainTimer = nil
		}
		i.mutex.Unlock()
		i.cancel()
		go i.shutdown()
	})
}

// terminal preserves the first classified tmux failure. It gives admitted
// responses the drain limit before forced session closure begins.
func (i *Instance) terminal(err error) {
	if err == nil {
		return
	}
	i.mutex.Lock()
	if i.terminalErr != nil {
		i.mutex.Unlock()
		return
	}
	i.terminalErr = err
	i.closing = true
	awaitResponse := i.responses.count() > 0
	scopes := make([]*sessionScope, 0, len(i.sessions))
	for _, session := range i.sessions {
		scopes = append(scopes, session.scope)
	}
	if awaitResponse {
		i.drainTimer = time.AfterFunc(i.drainWait, i.startClose)
	}
	i.mutex.Unlock()
	for _, scope := range scopes {
		scope.terminate(err)
	}
	if !awaitResponse {
		i.startClose()
	}
}

func (i *Instance) terminalCause() error {
	i.mutex.Lock()
	defer i.mutex.Unlock()
	return i.terminalErr
}

func (i *Instance) shutdown() {
	i.connecting.Wait()
	i.mutex.Lock()
	sessions := make([]*ServerSession, 0, len(i.sessions))
	for _, session := range i.sessions {
		sessions = append(sessions, session)
	}
	i.mutex.Unlock()

	// Cancel every session before asking the SDK to join its handlers.
	for _, session := range sessions {
		session.scope.stop()
	}
	failures := make([]error, len(sessions), len(sessions)+1)
	var closing sync.WaitGroup
	for index, session := range sessions {
		closing.Add(1)
		go func() {
			defer closing.Done()
			failures[index] = session.Close()
		}()
	}
	closing.Wait()
	failures = append(failures, i.runtime.Close())
	failures = append(failures, i.terminalCause())
	if i.audit != nil {
		failures = append(failures, i.audit.Close())
	}
	i.closeErr = errors.Join(failures...)
	close(i.closeDone)
}

func (s *ServerSession) await() {
	s.finish(s.sdk.Wait())
}

// Close stops scoped work, closes the transport, and joins SDK session cleanup.
func (s *ServerSession) Close() error {
	if s == nil {
		return nil
	}
	s.scope.stop()
	var transportErr error
	if s.connection != nil {
		transportErr = s.connection.Close()
	}
	err := s.sdk.Close()
	<-s.done
	return errors.Join(transportErr, err)
}

// Wait waits for client termination and session cleanup.
func (s *ServerSession) Wait() error {
	if s == nil {
		return nil
	}
	<-s.done
	return s.waitErr
}

func (s *ServerSession) finish(err error) {
	s.finishOnce.Do(func() {
		var connectionErr error
		if s.connection != nil {
			connectionErr = s.connection.connectionTerminalError()
		}
		s.waitErr = errors.Join(err, connectionErr, s.scope.terminalCause())
		s.instance.dropSession(s)
		close(s.done)
	})
}

func (i *Instance) dropSession(session *ServerSession) {
	i.mutex.Lock()
	delete(i.sessions, session.sdk)
	i.mutex.Unlock()
	session.scope.close()
}

func (i *Instance) scope(session *sdk.ServerSession) (*sessionScope, error) {
	i.mutex.Lock()
	defer i.mutex.Unlock()
	if i.closing {
		return nil, ErrInstanceClosed
	}
	tracked := i.sessions[session]
	if tracked == nil {
		return nil, ErrInstanceClosed
	}
	return tracked.scope, nil
}

func (i *Instance) scoped(next sdk.MethodHandler) sdk.MethodHandler {
	return func(
		ctx context.Context,
		method string,
		request sdk.Request,
	) (sdk.Result, error) {
		session, ok := request.GetSession().(*sdk.ServerSession)
		if !ok {
			return nil, ErrInstanceClosed
		}
		scope, err := i.scope(session)
		if err != nil {
			return nil, err
		}
		requestCtx, cancel := context.WithCancel(ctx)
		stop := context.AfterFunc(scope.ctx, cancel)
		defer cancel()
		defer stop()
		if scope.ctx.Err() != nil {
			cancel()
			return nil, ErrInstanceClosed
		}
		return next(requestCtx, method, request)
	}
}

mcp/instance.go.content:
package mcp

import (
	"context"
	"errors"
	"io"
	"sync"
	"time"

	sdk "github.com/modelcontextprotocol/go-sdk/mcp"
)

var (
	// ErrInstanceClosed identifies work refused after instance shutdown starts.
	ErrInstanceClosed = errors.New("libtmux MCP instance is closed")
	// ErrRequestCapacity identifies a client session closed after it exceeded
	// the server's finite unsettled-call capacity.
	ErrRequestCapacity = errors.New("libtmux MCP request capacity exceeded")
)

const (
	terminalResponseDrainTimeout = 5 * time.Second
	defaultMaxSessionCalls       = 32
	defaultMaxInstanceCalls      = 128
)

// Instance owns the SDK server, all connected client sessions, and every
// resource allocated on their behalf. The SDK server is composed so Connect
// and Run cannot bypass lifecycle tracking.
type Instance struct {
	server  *sdk.Server
	tools   *tools
	runtime *tmuxRuntime
	audit   io.Closer
	ctx     context.Context
	cancel  context.CancelFunc

	mutex       sync.Mutex
	closing     bool
	terminalErr error
	responses   responseLedger
	// Calls are admitted before the SDK's unbounded handler queue. These fields
	// are private so tests can exercise small limits without widening the API.
	maxSessionCalls  int
	maxInstanceCalls int
	drainTimer       *time.Timer
	drainWait        time.Duration
	sessions         map[*sdk.ServerSession]*ServerSession
	connecting       sync.WaitGroup
	closeOnce        sync.Once
	closeDone        chan struct{}
	closeErr         error
}

func newInstance() *Instance {
	ctx, cancel := context.WithCancel(context.Background())
	return &Instance{
		sessions:         map[*sdk.ServerSession]*ServerSession{},
		responses:        responseLedger{},
		closeDone:        make(chan struct{}),
		drainWait:        terminalResponseDrainTimeout,
		maxSessionCalls:  defaultMaxSessionCalls,
		maxInstanceCalls: defaultMaxInstanceCalls,
		ctx:              ctx,
		cancel:           cancel,
	}
}

// ServerSession owns one SDK session and the resources scoped to its client.
type ServerSession struct {
	instance   *Instance
	sdk        *sdk.ServerSession
	connection *sessionReadyConnection
	scope      *sessionScope

	finishOnce sync.Once
	done       chan struct{}
	waitErr    error
}

mcp/minimal_config.go.content:
package mcp

import (
	"bytes"
	_ "embed"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sync"
)

//go:embed minimal.conf
var shippedMinimalConfig []byte

// Content equality cannot prove provenance: an operator may supply the same bytes.
var materializedMinimalConfigs sync.Map

// MaterializeMinimalConfig writes the embedded dedicated-server configuration
// for tmux's -f option. The caller keeps it until the MCP process stops.
func MaterializeMinimalConfig() (string, func() error, error) {
	file, err := os.CreateTemp("", "libtmux-mcp-minimal-*.conf")
	if err != nil {
		return "", nil, fmt.Errorf("create minimal tmux config: %w", err)
	}
	path := file.Name()
	cleanup := func() error {
		materializedMinimalConfigs.Delete(filepath.Clean(path))
		err := os.Remove(path)
		if errors.Is(err, os.ErrNotExist) {
			return nil
		}
		return err
	}
	if err := file.Chmod(0o600); err != nil {
		_ = file.Close()
		_ = cleanup()
		return "", nil, fmt.Errorf("protect minimal tmux config: %w", err)
	}
	if _, err := file.Write(shippedMinimalConfig); err != nil {
		_ = file.Close()
		_ = cleanup()
		return "", nil, fmt.Errorf("write minimal tmux config: %w", err)
	}
	if err := file.Close(); err != nil {
		_ = cleanup()
		return "", nil, fmt.Errorf("close minimal tmux config: %w", err)
	}
	materializedMinimalConfigs.Store(filepath.Clean(path), struct{}{})
	return path, cleanup, nil
}

func isShippedMinimalConfig(path string) (bool, error) {
	if path == "" || path == os.DevNull {
		return false, nil
	}
	if _, owned := materializedMinimalConfigs.Load(filepath.Clean(path)); !owned {
		return false, nil
	}
	contents, err := os.ReadFile(path)
	if err != nil {
		return false, fmt.Errorf("read selected tmux config: %w", err)
	}
	return bytes.Equal(contents, shippedMinimalConfig), nil
}

mcp/resources.go.content:
package mcp

import (
	"context"
	"encoding/json"

	mcp "github.com/modelcontextprotocol/go-sdk/mcp"
)

// CapabilitiesResourceURI is the only MCP resource exposed by this server.
const CapabilitiesResourceURI = "tmux://capabilities"

func addResources(server *mcp.Server, t *tools) {
	server.AddResource(&mcp.Resource{
		URI:         CapabilitiesResourceURI,
		Name:        "tmux capabilities",
		Title:       "Startup-frozen tmux MCP capabilities",
		Description: "The selected socket, effective tools, schemas, input literalization, and aggregate authority.",
		MIMEType:    "application/json",
	}, t.readCapabilities)
}

func (t *tools) readCapabilities(
	_ context.Context,
	request *mcp.ReadResourceRequest,
) (*mcp.ReadResourceResult, error) {
	return jsonResource(request.Params.URI, t.surface.capabilityReport())
}

func jsonResource(uri string, value any) (*mcp.ReadResourceResult, error) {
	encoded, err := json.MarshalIndent(value, "", "  ")
	if err != nil {
		return nil, err
	}
	return &mcp.ReadResourceResult{Contents: []*mcp.ResourceContents{{
		URI:      uri,
		MIMEType: "application/json",
		Text:     string(encoded),
	}}}, nil
}

mcp/response_transport.go.content:
package mcp

import (
	"context"
	"errors"
	"fmt"
	"io"
	"reflect"

	mcp "github.com/modelcontextprotocol/go-sdk/mcp"
)

// ErrResponseCommitUnknown identifies a transport whose successful Write may
// leave one response buffered behind another response in a JSON-RPC batch.
var ErrResponseCommitUnknown = errors.New(
	"libtmux MCP: transport does not guarantee independent response writes",
)

// AssumeResponseCommit marks transport as committing each response before its
// Connection.Write returns nil. It does not change transport behavior. Use it
// only for a transport that rejects JSON-RPC batches or writes every response
// independently; direct IO and stdio transports are handled automatically.
func AssumeResponseCommit(transport mcp.Transport) mcp.Transport {
	return assumedResponseCommitTransport{inner: transport}
}

type assumedResponseCommitTransport struct {
	inner mcp.Transport
}

func (t assumedResponseCommitTransport) Connect(ctx context.Context) (mcp.Connection, error) {
	if err := validateAssumedResponseTransport(t.inner); err != nil {
		return nil, err
	}
	return t.inner.Connect(ctx)
}

func validateAssumedResponseTransport(transport mcp.Transport) error {
	if nilInterface(transport) {
		return fmt.Errorf("%w: nil %T", ErrResponseCommitUnknown, transport)
	}
	switch transport := transport.(type) {
	case handshakeOrderedTransport:
		return validateAssumedResponseTransport(transport.inner)
	case *mcp.LoggingTransport:
		if nilInterface(transport.Writer) {
			return fmt.Errorf("%w: incomplete *mcp.LoggingTransport", ErrResponseCommitUnknown)
		}
		return validateAssumedResponseTransport(transport.Transport)
	case *mcp.IOTransport:
		if nilInterface(transport.Reader) || nilInterface(transport.Writer) {
			return fmt.Errorf("%w: incomplete *mcp.IOTransport", ErrResponseCommitUnknown)
		}
		return nil
	case assumedResponseCommitTransport:
		return validateAssumedResponseTransport(transport.inner)
	default:
		return nil
	}
}

func nilInterface(value any) bool {
	if value == nil {
		return true
	}
	dynamic := reflect.ValueOf(value)
	kind := dynamic.Kind()
	return (kind == reflect.Chan || kind == reflect.Func ||
		kind == reflect.Interface || kind == reflect.Map ||
		kind == reflect.Pointer || kind == reflect.Slice) && dynamic.IsNil()
}

// normalizeResponseTransport keeps known IO transports on one-message framing
// and refuses opaque transports without an explicit response-commit contract.
func normalizeResponseTransport(transport mcp.Transport) (mcp.Transport, error) {
	return normalizeResponseTransportTrustingOpaque(transport, false)
}

func normalizeResponseTransportTrustingOpaque(
	transport mcp.Transport,
	trustedOpaque bool,
) (mcp.Transport, error) {
	if nilInterface(transport) {
		return nil, fmt.Errorf("%w: nil %T", ErrResponseCommitUnknown, transport)
	}
	switch transport := transport.(type) {
	case handshakeOrderedTransport:
		inner, err := normalizeResponseTransportTrustingOpaque(
			transport.inner,
			trustedOpaque,
		)
		return handshakeOrderedTransport{inner: inner}, err
	case *mcp.LoggingTransport:
		if nilInterface(transport.Transport) || nilInterface(transport.Writer) {
			return nil, fmt.Errorf("%w: incomplete *mcp.LoggingTransport", ErrResponseCommitUnknown)
		}
		inner, err := normalizeResponseTransportTrustingOpaque(
			transport.Transport,
			trustedOpaque,
		)
		if err != nil {
			return nil, err
		}
		return &mcp.LoggingTransport{
			Transport: inner,
			Writer:    transport.Writer,
		}, nil
	case *mcp.IOTransport:
		if nilInterface(transport.Reader) || nilInterface(transport.Writer) {
			return nil, fmt.Errorf("%w: incomplete *mcp.IOTransport", ErrResponseCommitUnknown)
		}
		if _, wrapped := transport.Reader.(*jsonLineReader); wrapped {
			return transport, nil
		}
		return jsonLineTransport(transport.Reader, transport.Writer, io.Discard), nil
	case *mcp.StdioTransport:
		return stdio(), nil
	case assumedResponseCommitTransport:
		return normalizeResponseTransportTrustingOpaque(transport.inner, true)
	default:
		if trustedOpaque {
			return assumedResponseCommitTransport{inner: transport}, nil
		}
		return nil, fmt.Errorf("%w: %T", ErrResponseCommitUnknown, transport)
	}
}

mcp/runtime.go.content:
package mcp

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"sync/atomic"
	"time"

	"github.com/libtmux/libtmux-go/tmux"
)

// ErrRuntimeTargetBound identifies a target already bound to a terminal
// Connection. An MCP runtime must own the connection it creates.
var ErrRuntimeTargetBound = errors.New("libtmux MCP target is already connection-bound")

// runtimeSetupTimeout bounds selector probes and control registration even
// when an MCP request has no deadline.
const runtimeSetupTimeout = 5 * time.Second

type runtimeState uint8

const (
	runtimeUnbound runtimeState = iota
	runtimeBinding
	runtimeBound
	runtimeTerminal
	runtimeClosed
)

func (s runtimeState) String() string {
	switch s {
	case runtimeUnbound:
		return "unbound"
	case runtimeBinding:
		return "binding"
	case runtimeBound:
		return "bound"
	case runtimeTerminal:
		return "terminal"
	case runtimeClosed:
		return "closed"
	default:
		return fmt.Sprintf("runtimeState(%d)", s)
	}
}

// tmuxRuntime is the sole mutable owner of MCP execution. Its selector is
// frozen at construction. Once a daemon is materialized, every command stays
// on terminal connections opened from the same original session: one retained
// command lane and one owned connection per active wait. A terminal transport
// failure never falls back to a different daemon while it is current, but it
// is never fatal to the process either: the runtime heals back to
// unbound on the next acquisition and may bind or bootstrap a fresh daemon
// then.
type tmuxRuntime struct {
	base tmux.Server
	ctx  context.Context
	deps mcpDependencies

	mutex                 sync.Mutex
	state                 runtimeState
	probe                 chan struct{}
	binding               chan struct{}
	unboundActive         int
	unboundDrained        chan struct{}
	cause                 error
	original              tmux.Session
	commandConnection     *tmux.Connection
	ownObservationClients map[tmux.ClientName]tmux.SessionID
	observations          sync.WaitGroup
	connectionCloseOnce   sync.Once
	connectionsClosed     chan struct{}
	connectionCloseErr    error
}

type runtimeAcquisition struct {
	server   tmux.Server
	runtime  *tmuxRuntime
	unbound  bool
	released atomic.Bool
	once     sync.Once
}

func (a *runtimeAcquisition) release() {
	if a == nil {
		return
	}
	a.once.Do(func() {
		a.released.Store(true)
		if a.unbound {
			a.runtime.releaseUnbound()
		}
	})
}

func (a *runtimeAcquisition) liveUnbound() bool {
	return a != nil && a.unbound && !a.released.Load()
}

func newRuntime(
	ctx context.Context,
	base tmux.Server,
) *tmuxRuntime {
	return &tmuxRuntime{
		base:              base,
		ctx:               ctx,
		deps:              defaultMCPDependencies(),
		state:             runtimeUnbound,
		connectionsClosed: make(chan struct{}),
	}
}

// command returns the command lane. An absent selector remains unbound and
// returns the frozen process handle so read-only absence checks keep working.
func (r *tmuxRuntime) command(ctx context.Context) (tmux.Server, error) {
	acquired, err := r.acquireCommand(ctx, false)
	if err != nil {
		return tmux.Server{}, err
	}
	return acquired.server, nil
}

// process returns the exact materialized daemon's process lane. Before a daemon
// exists, it returns the frozen selector.
func (r *tmuxRuntime) process(ctx context.Context) (tmux.Server, error) {
	if acquired := acquiredServerFromContext(ctx); acquired.liveUnbound() {
		return acquired.server, nil
	}
	if _, err := r.command(ctx); err != nil {
		return tmux.Server{}, err
	}
	r.mutex.Lock()
	defer r.mutex.Unlock()
	if r.state == runtimeUnbound {
		return r.base, nil
	}
	if r.state != runtimeBound {
		return tmux.Server{}, r.stateErrorLocked()
	}
	return r.original.Server(), nil
}

// acquire retains an unbound process handle until release. That lease prevents
// first creation from materializing a daemon while an MCP surface can still
// issue work through the previously absent selector.
func (r *tmuxRuntime) acquire(
	ctx context.Context,
) (*runtimeAcquisition, error) {
	return r.acquireCommand(ctx, true)
}

func (r *tmuxRuntime) acquireCommand(
	ctx context.Context,
	leaseUnbound bool,
) (*runtimeAcquisition, error) {
	reprobed := false
	for {
		r.mutex.Lock()
		switch r.state {
		case runtimeBound:
			server := r.commandConnection.Server()
			r.mutex.Unlock()
			return &runtimeAcquisition{server: server}, nil
		case runtimeClosed:
			err := r.stateErrorLocked()
			r.mutex.Unlock()
			return nil, err
		case runtimeTerminal:
			// A daemon this runtime already lost is never fatal to the
			// process. Discard it and retry this acquisition as if starting
			// fresh; the call that hit the loss already reported its own
			// error at the point it happened.
			lost := r.healTerminalLocked()
			r.mutex.Unlock()
			r.closeLostConnection(lost)
			continue
		case runtimeBinding:
			ready := r.binding
			r.mutex.Unlock()
			if err := waitRuntime(ctx, ready); err != nil {
				return nil, err
			}
			continue
		case runtimeUnbound:
			if r.probe != nil {
				ready := r.probe
				r.mutex.Unlock()
				if err := waitRuntime(ctx, ready); err != nil {
					return nil, err
				}
				continue
			}
			probe := make(chan struct{})
			r.probe = probe
			r.mutex.Unlock()

			sessions, err := r.probeSessions(ctx)
			if err != nil || len(sessions) == 0 {
				if errors.Is(err, tmux.ErrNoServer) || err == nil {
					acquired, ok := r.finishAbsentProbe(probe, leaseUnbound)
					if ok {
						return acquired, nil
					}
					continue
				}
				r.finishProbe(probe)
				r.observe(err)
				return nil, err
			}
			drained, ok := r.beginBinding(probe)
			if !ok {
				continue
			}
			if drained != nil {
				if err := waitRuntime(ctx, drained); err != nil {
					r.failBinding(tmux.Session{}, nil, err, false)
					return nil, err
				}
			}
			server, reset, err := r.bind(ctx, sessions[0], nil)
			if err != nil {
				if reset && !reprobed && !isContextError(err) {
					reprobed = true
					continue
				}
				return nil, err
			}
			return &runtimeAcquisition{server: server}, nil
		}
	}
}

func (r *tmuxRuntime) finishAbsentProbe(
	probe chan struct{},
	lease bool,
) (*runtimeAcquisition, bool) {
	r.mutex.Lock()
	defer r.mutex.Unlock()
	if r.probe != probe {
		return nil, false
	}
	r.probe = nil
	defer close(probe)
	if r.state != runtimeUnbound {
		return nil, false
	}
	if !lease {
		return &runtimeAcquisition{server: r.base}, true
	}
	if r.unboundActive == 0 {
		r.unboundDrained = make(chan struct{})
	}
	r.unboundActive++
	return &runtimeAcquisition{
		server:  r.base,
		runtime: r,
		unbound: true,
	}, true
}

func (r *tmuxRuntime) releaseUnbound() {
	r.mutex.Lock()
	defer r.mutex.Unlock()
	if r.unboundActive == 0 {
		return
	}
	r.unboundActive--
	if r.unboundActive == 0 {
		close(r.unboundDrained)
		r.unboundDrained = nil
	}
}

// current returns the handle selected by the most recent successful surface
// acquisition. MCP surface wrappers call command before invoking handlers.
func (r *tmuxRuntime) current() tmux.Server {
	r.mutex.Lock()
	defer r.mutex.Unlock()
	if r.commandConnection != nil {
		return r.commandConnection.Server()
	}
	if r.state == runtimeUnbound {
		return r.base
	}
	return tmux.Server{}
}

// createSession serializes first creation with discovery. The first session
// retains its creating control process as the command connection. Later
// sessions are created on the exact provenance process lane and resolved back
// through the command connection.
func (r *tmuxRuntime) createSession(
	ctx context.Context,
	request tmux.NewSessionRequest,
) (tmux.Session, error) {
	releaseAcquiredServer(ctx)
	reprobed := false
	for {
		r.mutex.Lock()
		switch r.state {
		case runtimeBound:
			r.mutex.Unlock()
			return r.createBoundSession(ctx, request)
		case runtimeClosed:
			err := r.stateErrorLocked()
			r.mutex.Unlock()
			return tmux.Session{}, err
		case runtimeTerminal:
			// The next create_session starts a new server rather than
			// staying poisoned by a daemon this runtime already lost.
			lost := r.healTerminalLocked()
			r.mutex.Unlock()
			r.closeLostConnection(lost)
			continue
		case runtimeBinding:
			ready := r.binding
			r.mutex.Unlock()
			if err := waitRuntime(ctx, ready); err != nil {
				return tmux.Session{}, err
			}
			continue
		case runtimeUnbound:
			if r.probe != nil {
				ready := r.probe
				r.mutex.Unlock()
				if err := waitRuntime(ctx, ready); err != nil {
					return tmux.Session{}, err
				}
				continue
			}
			r.state = runtimeBinding
			r.binding = make(chan struct{})
			drained := r.unboundDrained
			r.mutex.Unlock()

			if drained != nil {
				if err := waitRuntime(ctx, drained); err != nil {
					r.failBinding(tmux.Session{}, nil, err, true)
					return tmux.Session{}, err
				}
			}
			sessions, err := r.probeSessions(ctx)
			switch {
			case err == nil && len(sessions) > 0:
				_, reset, bindErr := r.bind(ctx, sessions[0], nil)
				if reset && !reprobed && !isContextError(bindErr) {
					reprobed = true
					continue
				}
				if bindErr != nil {
					return tmux.Session{}, bindErr
				}
				continue
			case err != nil && !errors.Is(err, tmux.ErrNoServer):
				r.failBinding(tmux.Session{}, nil, err, true)
				return tmux.Session{}, err
			default:
				return r.bootstrap(ctx, request)
			}
		}
	}
}

func (r *tmuxRuntime) createBoundSession(
	ctx context.Context,
	request tmux.NewSessionRequest,
) (tmux.Session, error) {
	process, err := r.process(ctx)
	if err != nil {
		return tmux.Session{}, err
	}
	created, err := process.NewSession(ctx, request)
	if err != nil {
		r.observe(err)
		return created, err
	}
	command, err := r.command(ctx)
	if err != nil {
		return created, err
	}
	bound, err := command.Session(ctx, created.ID())
	r.observe(err)
	if err != nil {
		return created, err
	}
	return bound, nil
}

func (r *tmuxRuntime) bootstrap(
	ctx context.Context,
	request tmux.NewSessionRequest,
) (tmux.Session, error) {
	operationCtx, cancel := r.operationContext(ctx)
	defer cancel()
	original, commandConnection, err := r.deps.newSessionConnection(
		operationCtx, r.base, request,
	)
	if err != nil {
		r.failBinding(original, commandConnection, err, true)
		return original, err
	}
	if err := r.finishBinding(original, commandConnection); err != nil {
		return original, err
	}
	return commandConnection.Session(), nil
}

func (r *tmuxRuntime) bind(
	ctx context.Context,
	original tmux.Session,
	commandConnection *tmux.Connection,
) (tmux.Server, bool, error) {
	operationCtx, cancel := r.operationContext(ctx)
	defer cancel()
	var err error
	if commandConnection == nil {
		commandConnection, err = original.OpenControl(operationCtx, tmux.ConnectionOptions{})
		if err != nil {
			reset := r.failBinding(original, nil, err, false)
			return tmux.Server{}, reset, err
		}
	}
	if err := r.finishBinding(original, commandConnection); err != nil {
		return tmux.Server{}, false, err
	}
	return commandConnection.Server(), false, nil
}

func (r *tmuxRuntime) probeSessions(ctx context.Context) ([]tmux.Session, error) {
	operationCtx, cancel := r.operationContext(ctx)
	defer cancel()
	return r.deps.probeSessions(operationCtx, r.base)
}

func (r *tmuxRuntime) operationContext(ctx context.Context) (context.Context, context.CancelFunc) {
	timeoutCtx, cancelTimeout := context.WithTimeout(ctx, runtimeSetupTimeout)
	operationCtx, cancel := context.WithCancel(timeoutCtx)
	stop := context.AfterFunc(r.ctx, cancel)
	return operationCtx, func() {
		stop()
		cancel()
		cancelTimeout()
	}
}

func (r *tmuxRuntime) beginBinding(probe chan struct{}) (<-chan struct{}, bool) {
	r.mutex.Lock()
	defer r.mutex.Unlock()
	if r.probe == probe {
		r.probe = nil
		close(probe)
	}
	if r.state != runtimeUnbound {
		return nil, false
	}
	r.state = runtimeBinding
	r.binding = make(chan struct{})
	return r.unboundDrained, true
}

func (r *tmuxRuntime) finishProbe(probe chan struct{}) {
	r.mutex.Lock()
	defer r.mutex.Unlock()
	if r.probe == probe {
		r.probe = nil
		close(probe)
	}
}

func (r *tmuxRuntime) finishBinding(
	original tmux.Session,
	commandConnection *tmux.Connection,
) error {
	r.mutex.Lock()
	if r.state != runtimeBinding {
		err := r.stateErrorLocked()
		r.finishBindingSignalLocked()
		r.mutex.Unlock()
		_ = closeRuntimeConnections(commandConnection)
		return err
	}
	r.original = original
	r.commandConnection = commandConnection
	r.state = runtimeBound
	r.finishBindingSignalLocked()
	r.mutex.Unlock()
	return nil
}

func (r *tmuxRuntime) failBinding(
	original tmux.Session,
	commandConnection *tmux.Connection,
	err error,
	creation bool,
) bool {
	r.mutex.Lock()
	if r.state != runtimeBinding {
		r.finishBindingSignalLocked()
		r.mutex.Unlock()
		_ = closeRuntimeConnections(commandConnection)
		return false
	}
	retryable := commandConnection == nil &&
		!isIntrinsicTerminalRuntimeError(err) &&
		(!creation || original.ID() == "")
	if retryable {
		r.state = runtimeUnbound
		r.cause = nil
		r.finishBindingSignalLocked()
		r.mutex.Unlock()
		return true
	}
	// A lost or untrusted daemon (including ErrDaemonReplaced) is never
	// fatal to the process. Record it as terminal for this attempt - the
	// caller's own error already reports the loss - without adopting the
	// connection as current, so a concurrent current() never hands it out
	// while it closes; the next top-level acquisition heals back to unbound
	// and starts fresh. original is retained (an acted creation still names
	// the session it made) even though commandConnection is not.
	r.original = original
	r.commandConnection = nil
	r.cause = err
	r.state = runtimeTerminal
	r.finishBindingSignalLocked()
	r.mutex.Unlock()
	r.closeLostConnection(commandConnection)
	return false
}

func (r *tmuxRuntime) finishBindingSignalLocked() {
	if r.binding != nil {
		close(r.binding)
		r.binding = nil
	}
}

func (r *tmuxRuntime) stateErrorLocked() error {
	switch r.state {
	case runtimeClosed:
		if r.cause != nil {
			return r.cause
		}
		return ErrInstanceClosed
	case runtimeTerminal:
		if r.cause != nil {
			return r.cause
		}
		return tmux.ErrControlClosed
	case runtimeUnbound, runtimeBinding, runtimeBound:
		return fmt.Errorf("libtmux MCP runtime is %s", r.state)
	default:
		return fmt.Errorf("libtmux MCP runtime is %s", r.state)
	}
}

func waitRuntime(ctx context.Context, ready <-chan struct{}) error {
	select {
	case <-ready:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

mcp/server.go.content:
package mcp

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"maps"
	"os"
	"path/filepath"
	"runtime/debug"
	"slices"
	"strings"
	"sync"
	"time"

	"github.com/google/jsonschema-go/jsonschema"
	"github.com/libtmux/libtmux-go/tmux"
	"github.com/modelcontextprotocol/go-sdk/jsonrpc"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

// Version is reported during MCP initialization. Installed binaries derive it
// from build metadata; source builds use fallbackVersion.
var Version = buildVersion()

const fallbackVersion = "v0.0.1-alpha.14"

// minimumTmuxVersion follows the terminal Connection capability floor because
// every MCP runtime owns one.
const minimumTmuxVersion = tmux.MinimumConnectionVersion

const (
	minimalOwnerEnvironment = "LIBTMUX_MCP_OWNER"
	minimalOwnerOption      = "@libtmux_mcp_owner"
)

func (i *Instance) requireTmuxVersion(ctx context.Context) error {
	minimum, err := tmux.ParseVersion(minimumTmuxVersion)
	if err != nil {
		return err
	}
	return explainVersionRefusal(i.runtime.base.RequireVersion(ctx, minimum))
}

func buildVersion() string {
	info, ok := debug.ReadBuildInfo()
	if !ok || info.Main.Version == "" || info.Main.Version == "(devel)" {
		return fallbackVersion
	}
	return info.Main.Version
}

// closedArguments adds enums that jsonschema-go cannot express through these tags.
var closedArguments = map[string]map[string][]any{
	"show_option":           {"scope": scopeValues},
	"show_hooks":            {"scope": scopeValues},
	"split_window":          {"direction": placementValues},
	"call_read_tools_batch": {"on_error": {onErrorStop, onErrorContinue}},
	"send_keys_batch":       {"on_error": {onErrorStop, onErrorContinue}},
	"find_pane_by_position": {"position": {"top-left", "top-right", "bottom-left", "bottom-right"}},
	"create_window":         {"direction": {"before", "after"}},
}

// minimumArguments adds numeric lower bounds that jsonschema-go cannot express
// through struct tags.
var minimumArguments = map[string]map[string]float64{
	"wait_for_channel":  {"timeout": 0},
	"wait_for_text":     {"timeout": 0},
	"run_shell_command": {"timeout": 0, "max_lines": 0},
}

var maximumArguments = map[string]map[string]float64{
	"search_panes": {
		"max_matches_per_pane": searchCeilingMatchesPerPane,
		"max_lines":            searchCeilingPanes,
	},
}

var boundedStringArguments = map[string]map[string]int{
	"search_panes": {"pattern": patternBytesLimit},
}

var boundedPatternArrays = map[string][]string{
	"wait_for_text": {"patterns", "stop"},
}

var scopeValues = []any{"", "global", scopeServer, scopeSession, scopeWindow, scopePane}

var placementValues = []any{"", "below", "above", "right", "left"}

// listsAreLists removes nullable alternatives inferred for slices.
func listsAreLists(schema *jsonschema.Schema) {
	if schema == nil {
		return
	}
	if len(schema.Types) > 1 && slices.Contains(schema.Types, "array") {
		schema.Types = slices.DeleteFunc(schema.Types, func(kind string) bool {
			return kind == "null"
		})
	}
	listsAreLists(schema.Items)
	for _, property := range schema.Properties {
		listsAreLists(property)
	}
}

func constrain(name string, schema *jsonschema.Schema) {
	for argument, values := range closedArguments[name] {
		if property, ok := schema.Properties[argument]; ok {
			property.Enum = values
		}
	}
	for argument, minimum := range minimumArguments[name] {
		if property, ok := schema.Properties[argument]; ok {
			minimum := minimum
			property.Minimum = &minimum
		}
	}
	for argument, maximum := range maximumArguments[name] {
		if property, ok := schema.Properties[argument]; ok {
			maximum := maximum
			property.Maximum = &maximum
		}
	}
	for argument, maximum := range boundedStringArguments[name] {
		if property, ok := schema.Properties[argument]; ok {
			maximum := maximum
			property.MaxLength = &maximum
		}
	}
	for _, argument := range boundedPatternArrays[name] {
		if property, ok := schema.Properties[argument]; ok {
			maximumItems := patternCountLimit
			maximumLength := patternBytesLimit
			property.MaxItems = &maximumItems
			if property.Items == nil {
				property.Items = &jsonschema.Schema{Type: "string"}
			}
			property.Items.MaxLength = &maximumLength
		}
	}
}

// NewServer returns a closeable MCP instance exposing target. It rejects an
// invalid target before allocating instance-owned resources.
func NewServer(target tmux.Server) (*Instance, error) {
	profile, err := profileForTarget(target, "unknown")
	if err != nil {
		return nil, fmt.Errorf("construct MCP server: %w", err)
	}
	if target.ConnectionBound() {
		return nil, ErrRuntimeTargetBound
	}
	surface, err := resolveToolSurface(profile)
	if err != nil {
		return nil, fmt.Errorf("construct MCP server: %w", err)
	}
	return newServer(target, surface)
}

func newServer(target tmux.Server, surface toolSurface) (*Instance, error) {
	instance := newInstance()
	runtime := newRuntime(instance.ctx, target)
	instance.runtime = runtime
	tools := newToolRegistry(surface)
	tools.instance = instance
	tools.runtime = runtime
	serverOptions := &mcp.ServerOptions{
		Instructions: "Operate only on tmux objects through the startup-frozen tool surface. " +
			"Read tmux://capabilities before delegating executable or destructive work.",
	}
	server := mcp.NewServer(&mcp.Implementation{
		Name:    "libtmux",
		Version: Version,
	}, serverOptions)
	instance.server = server
	instance.tools = tools
	// Each middleware wraps those added before it. Audit wraps the backstop so
	// oversized refusals are recorded, and both wrap namedArguments so its
	// blank-id refusals are recorded too.
	server.AddReceivingMiddleware(tools.namedArguments)
	server.AddReceivingMiddleware(backstop())
	writer, auditOwner := auditWriter()
	if writer != nil {
		server.AddReceivingMiddleware(audit(writer))
	}
	server.AddReceivingMiddleware(instance.scoped)

	if err := registerToolManifest(server, tools); err != nil {
		_ = instance.Close()
		return nil, fmt.Errorf("construct MCP server: %w", err)
	}
	addResources(server, tools)

	instance.audit = auditOwner
	return instance, nil
}

func newToolRegistry(configured ...toolSurface) *tools {
	var surface toolSurface
	var configurationErr error
	if len(configured) != 0 {
		surface = configured[0]
	} else {
		surface, configurationErr = resolveToolSurface(socketProfile{
			Selector:                "name:libtmux-mcp",
			SelectionProvenance:     "default-dedicated",
			ServerState:             "unknown",
			ConfigurationProvenance: "minimal",
			NamespaceBoundary:       "tmux-objects-only",
			AttachCommand:           "tmux -N -L 'libtmux-mcp' attach",
		})
	}
	return &tools{
		surface:         surface,
		waitCeiling:     waitCeilingFromEnvironment(),
		dispatchers:     map[string]dispatcher{},
		registrationErr: configurationErr,
	}
}

func registerToolManifest(server *mcp.Server, tools *tools) error {
	for _, definition := range tools.surface.tools {
		definition.register(server, tools, definition)
		if tools.registrationErr != nil {
			return tools.registrationErr
		}
	}
	definitions, err := toolManifest()
	if err != nil {
		return err
	}
	all := make(map[string]toolDefinition, len(definitions))
	for _, definition := range definitions {
		all[definition.name] = definition
	}
	for _, aggregate := range tools.surface.tools {
		if !aggregate.aggregate {
			continue
		}
		for _, name := range aggregate.nestedAuthority {
			if _, bound := tools.dispatchers[name]; bound {
				continue
			}
			definition := all[name]
			definition.bindDispatcher(tools, definition)
			if tools.registrationErr != nil {
				return tools.registrationErr
			}
		}
	}
	return nil
}

// Run serves target over stdin and stdout until ctx is done.
func Run(ctx context.Context, target tmux.Server) error {
	if target.ConnectionBound() {
		return ErrRuntimeTargetBound
	}
	environment := currentStartupEnvironment()
	profile, err := profileForTarget(target, "unknown")
	if err != nil {
		return fmt.Errorf("construct MCP server: %w", err)
	}
	if _, err := resolveToolSurfaceFrom(environment, profile); err != nil {
		return fmt.Errorf("construct MCP server: %w", err)
	}
	alive, err := target.IsAlive(ctx)
	if err != nil {
		return fmt.Errorf("inspect selected tmux socket: %w", explainVersionRefusal(err))
	}
	state := "absent"
	if alive {
		state = "existing"
	}
	profile, err = profileForTarget(target, state)
	if err != nil {
		return fmt.Errorf("construct MCP server: %w", err)
	}
	surface, err := resolveToolSurfaceFrom(environment, profile)
	if err != nil {
		return fmt.Errorf("construct MCP server: %w", err)
	}
	return runPinnedSurface(ctx, target, surface)
}

// RunDefaultMinimal serves a package-created default dedicated target. It
// starts or joins the daemon with a one-use owner marker and grants default
// teardown only when the marker proves this process created that daemon.
func RunDefaultMinimal(ctx context.Context, target tmux.Server) error {
	if target.ConnectionBound() {
		return ErrRuntimeTargetBound
	}
	environment := currentStartupEnvironment()
	conservative, err := profileForTarget(target, "unknown")
	if err != nil {
		return fmt.Errorf("construct MCP server: %w", err)
	}
	// Invalid selection must fail before a tmux subprocess can open the socket.
	if _, err := resolveToolSurfaceFrom(environment, conservative); err != nil {
		return fmt.Errorf("construct MCP server: %w", err)
	}
	nonce, err := newMinimalOwnerNonce()
	if err != nil {
		return fmt.Errorf("construct MCP server: owner marker: %w", err)
	}
	profile, err := pinDefaultMinimal(ctx, target, nonce)
	if err != nil {
		return fmt.Errorf("pin default minimal tmux server: %w", err)
	}
	surface, err := resolveToolSurfaceFrom(environment, profile)
	if err != nil {
		return fmt.Errorf("construct MCP server: %w", err)
	}
	return runPinnedSurface(ctx, target, surface)
}

func runPinnedSurface(ctx context.Context, target tmux.Server, surface toolSurface) error {
	instance, err := newServer(target, surface)
	if err != nil {
		return err
	}
	defer func() { _ = instance.Close() }()
	return instance.Run(ctx, stdio())
}

// ensureSocketDirectory creates dir with the same permissions tmux gives
// tmux-<uid>/ (mode 0700) when this process is the one choosing its own
// socket. It tolerates the directory already existing and leaves any
// ownership or permission mismatch for tmux itself to refuse.
func ensureSocketDirectory(dir string) error {
	if dir == "" {
		return nil
	}
	if err := os.Mkdir(dir, 0o700); err != nil && !os.IsExist(err) {
		return err
	}
	return nil
}

func newMinimalOwnerNonce() (string, error) {
	value := make([]byte, 16)
	if _, err := rand.Read(value); err != nil {
		return "", err
	}
	return hex.EncodeToString(value), nil
}

func pinDefaultMinimal(
	ctx context.Context,
	target tmux.Server,
	nonce string,
) (socketProfile, error) {
	minimal, err := isShippedMinimalConfig(target.ConfigFile())
	if err != nil {
		return socketProfile{}, err
	}
	if !minimal {
		return socketProfile{}, fmt.Errorf("default minimal target does not use the package-owned config")
	}
	launcher, err := target.WithProcessEnvironmentValue(minimalOwnerEnvironment, nonce)
	if err != nil {
		return socketProfile{}, err
	}
	// The launcher pins its resolved endpoint as an explicit -S path (see
	// WithProcessEnvironmentValue), which skips tmux's own tmux-<uid>/
	// creation for -L and the default socket. This process chose that
	// directory, unlike an operator-supplied -socket-path, so it may
	// create it the way tmux itself would.
	selection, err := launcher.SocketSelection()
	if err != nil {
		return socketProfile{}, err
	}
	if err := ensureSocketDirectory(selection.NamedDirectory); err != nil {
		return socketProfile{}, fmt.Errorf("create tmux socket directory: %w", err)
	}
	if err := launcher.Start(ctx); err != nil {
		return socketProfile{}, err
	}
	marker, present, err := target.GlobalSessionScope().RawOption(ctx, minimalOwnerOption)
	if err != nil {
		return socketProfile{}, err
	}
	return defaultMinimalProfile(target, present && marker == nonce)
}

// defaultMinimalProfile describes the default dedicated target, granting
// default teardown only when owned: this process created that tmux server.
func defaultMinimalProfile(target tmux.Server, owned bool) (socketProfile, error) {
	selection, err := target.SocketSelection()
	if err != nil {
		return socketProfile{}, err
	}
	selector := "path:" + selection.Path
	if filepath.Base(selection.Path) == "libtmux-mcp" {
		selector = "name:libtmux-mcp"
	}
	profile := socketProfile{
		Selector:                selector,
		SelectionProvenance:     "default-dedicated",
		ServerState:             "existing",
		ConfigurationProvenance: "unknown",
		NamespaceBoundary:       "tmux-objects-only",
		ResolvedSocketPath:      selection.Path,
		AttachCommand: shellQuote(target.Executable()) + " -N -S " +
			shellQuote(selection.Path) + " attach",
		defaultTeardown: owned,
	}
	if selection.Path == "" {
		return socketProfile{}, fmt.Errorf("default minimal target has no socket path")
	}
	if owned {
		profile.ServerState = "created"
		profile.ConfigurationProvenance = "minimal"
	}
	return profile, nil
}

func profileForTarget(target tmux.Server, state string) (socketProfile, error) {
	selection, err := target.SocketSelection()
	if err != nil {
		return socketProfile{}, err
	}
	profile := socketProfile{
		Selector:                "path:" + selection.Path,
		SelectionProvenance:     "operator-current",
		ServerState:             state,
		ConfigurationProvenance: "unknown",
		NamespaceBoundary:       "tmux-objects-only",
		ResolvedSocketPath:      selection.Path,
		AttachCommand: shellQuote(target.Executable()) + " -N -S " +
			shellQuote(selection.Path) + " attach",
	}
	if state == "absent" {
		profile.ConfigurationProvenance = "user-configured"
	}
	return profile, nil
}

type tools struct {
	instance        *Instance
	runtime         *tmuxRuntime
	surface         toolSurface
	waitCeiling     time.Duration
	dispatchers     map[string]dispatcher
	registrationErr error
	// A process cannot change its containing pane. Failed discovery is not
	// cached because cancellation or transport loss may be transient.
	callerMutex  sync.Mutex
	caller       callerIdentity
	callerCached bool
	// pending tracks each pane's own unsubmitted input, so wait_for_text never
	// reports a match confined to it.
	pending pendingInput
}

// An invalid target has no socket identity and cannot match the caller.
func (t *tools) socketPath(_ context.Context) string {
	selection, err := t.runtime.base.SocketSelection()
	if err != nil {
		return ""
	}
	return selection.Path
}

// namedArguments completes the SDK's unknown-argument rejection, which names
// only the rejected argument, with the arguments the tool does accept. It also
// says which toolset grants a tool this server was not started with, and what
// an id looks like when one was malformed.
func (t *tools) namedArguments(next mcp.MethodHandler) mcp.MethodHandler {
	return func(ctx context.Context, method string, request mcp.Request) (mcp.Result, error) {
		if method != "tools/call" {
			return next(ctx, method, request)
		}
		params, ok := request.GetParams().(*mcp.CallToolParamsRaw)
		if !ok {
			return next(ctx, method, request)
		}
		if refusal := t.blankRequiredID(params.Name, params.Arguments); refusal != "" {
			return &mcp.CallToolResult{
				IsError: true, Content: []mcp.Content{&mcp.TextContent{Text: refusal}},
			}, nil
		}
		result, err := next(ctx, method, request)
		if err != nil {
			return result, t.withUngrantedTool(params.Name, err)
		}
		call, ok := result.(*mcp.CallToolResult)
		if !ok || !call.IsError {
			return result, err
		}
		for i, content := range call.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				call.Content[i] = &mcp.TextContent{Text: withTargetShape(text.Text)}
			}
		}
		if explained := t.explainBatchRejection(params.Name, params.Arguments); explained != "" {
			call.Content = []mcp.Content{&mcp.TextContent{Text: explained}}
			return result, err
		}
		for _, definition := range t.surface.tools {
			if definition.name != params.Name {
				continue
			}
			for i, content := range call.Content {
				if text, ok := content.(*mcp.TextContent); ok {
					call.Content[i] = &mcp.TextContent{
						Text: withAcceptedArguments(errors.New(text.Text), definition.inputSchema).Error(),
					}
				}
			}
			break
		}
		return result, err
	}
}

// idShapes is an example of each kind of id a tool can require, and the tool
// that lists real ones.
var idShapes = map[string][2]string{
	"pane_id":       {"%3", "list_panes"},
	"other_pane_id": {"%3", "list_panes"},
	"window_id":     {"@3", "list_windows"},
	"session_id":    {"$3", "list_sessions"},
}

// requiredIDs lists where a tool's input schema requires an id: in its own
// arguments, in each element of an operations array, or, for an aggregate, in
// the arguments of each operation, which are those of the tool it names.
type requiredIDs struct {
	top        []string
	operations []string
	nested     bool
}

// requiredIDsByTool is computed once so that a call to a tool without ids is
// not decoded.
var requiredIDsByTool = buildRequiredIDs(authoritativeToolManifest)

func buildRequiredIDs(definitions []toolDefinition) map[string]requiredIDs {
	idFields := func(schema *jsonschema.Schema) []string {
		if schema == nil {
			return nil
		}
		return slices.DeleteFunc(slices.Clone(schema.Required), func(field string) bool {
			_, isID := idShapes[field]
			return !isID
		})
	}
	byTool := make(map[string]requiredIDs, len(definitions))
	for _, definition := range definitions {
		ids := requiredIDs{top: idFields(definition.inputSchema), nested: definition.aggregate}
		if definition.inputSchema != nil && !definition.aggregate {
			if operations := definition.inputSchema.Properties["operations"]; operations != nil {
				ids.operations = idFields(operations.Items)
			}
		}
		byTool[definition.name] = ids
	}
	return byTool
}

// blankRequiredID refuses a call whose schema requires an id that the call
// sends empty, at the top level or inside a batch. A schema's required check
// is met by an empty string, and the handlers read an empty id as "the active
// one", which in a shared terminal can be the person's pane. A blank id is far
// more likely a value the caller meant to fill in.
func (t *tools) blankRequiredID(name string, arguments json.RawMessage) string {
	ids := requiredIDsByTool[name]
	if len(ids.top) == 0 && len(ids.operations) == 0 && !ids.nested {
		return ""
	}
	if _, served := t.surface.byName[name]; !served {
		return ""
	}
	var values map[string]json.RawMessage
	if json.Unmarshal(arguments, &values) != nil {
		return ""
	}
	if field := blankID(values, ids.top); field != "" {
		return blankIDRefusal(field, field)
	}
	if len(ids.operations) == 0 && !ids.nested {
		return ""
	}
	var operations []map[string]json.RawMessage
	if json.Unmarshal(values["operations"], &operations) != nil {
		return ""
	}
	for index, operation := range operations {
		path := fmt.Sprintf("operations[%d].", index)
		if !ids.nested {
			if field := blankID(operation, ids.operations); field != "" {
				return blankIDRefusal(path+field, field)
			}
			continue
		}
		var tool string
		var called map[string]json.RawMessage
		if json.Unmarshal(operation["tool"], &tool) != nil ||
			json.Unmarshal(operation["arguments"], &called) != nil {
			continue
		}
		if field := blankID(called, requiredIDsByTool[tool].top); field != "" {
			return blankIDRefusal(path+"arguments."+field, field)
		}
	}
	return ""
}

// blankID returns the first of fields that values sends as an empty string.
func blankID(values map[string]json.RawMessage, fields []string) string {
	for _, field := range fields {
		var value string
		if json.Unmarshal(values[field], &value) == nil && strings.TrimSpace(value) == "" {
			return field
		}
	}
	return ""
}

func blankIDRefusal(path, field string) string {
	shape := idShapes[field]
	return fmt.Sprintf("%s is empty; give an id such as %s, which %s reports",
		path, shape[0], shape[1])
}

// withUngrantedTool adds, to the SDK's rejection of a tool it does not serve,
// the toolset that would grant it, when the tool exists but this server was
// not started with that toolset.
func (t *tools) withUngrantedTool(name string, err error) error {
	wire, ok := errors.AsType[*jsonrpc.Error](err)
	if !ok || !strings.HasPrefix(wire.Message, "unknown tool") {
		return err
	}
	if _, served := t.surface.byName[name]; served {
		return err
	}
	for _, definition := range authoritativeToolManifest {
		if definition.name != name {
			continue
		}
		explained := *wire
		explained.Message = fmt.Sprintf(
			"%s: it belongs to the %s toolset, which this server was not started with; "+
				"%s chooses the toolsets",
			wire.Message, definition.toolset, ToolsetsEnvironmentVariable,
		)
		return &explained
	}
	return err
}

// targetShapes is what each kind of tmux id looks like, and the tool that
// lists the real ones.
var targetShapes = map[string]string{
	"pane":    "a pane id looks like %3, and list_panes reports them",
	"window":  "a window id looks like @3, and list_windows reports them",
	"session": "a session id looks like $3, and list_sessions reports them",
}

// withTargetShape says what an id looks like after a rejection of a malformed
// one, which otherwise names the value and not what was expected.
func withTargetShape(text string) string {
	for object, shape := range targetShapes {
		if strings.Contains(text, tmux.ErrInvalidTarget.Error()+": "+object+" ") {
			return text + "; " + shape
		}
	}
	return text
}

// withAcceptedArguments appends the schema's argument names to an
// unknown-argument rejection and leaves every other error alone.
func withAcceptedArguments(err error, schema *jsonschema.Schema) error {
	if !strings.Contains(err.Error(), "unexpected additional properties") || schema == nil {
		return err
	}
	accepted := slices.Sorted(maps.Keys(schema.Properties))
	if len(accepted) == 0 {
		return fmt.Errorf("%w; this tool takes no arguments", err)
	}
	return fmt.Errorf("%w; this tool takes %s", err, strings.Join(accepted, ", "))
}

// toolFailure preserves a partial result; returning err makes the SDK discard it.
func toolFailure(err error) *mcp.CallToolResult {
	return &mcp.CallToolResult{
		IsError: true,
		Content: []mcp.Content{&mcp.TextContent{Text: err.Error()}},
	}
}

// versionRefusalError is a tmux refusal an agent can act on: it names the
// floor and how to meet it, and keeps the library error for errors.As.
type versionRefusalError struct {
	err error
}

// Error replaces the library's own remedy, which addresses a Go caller, with
// the one that applies to this server. The library's reason already names the
// floor.
func (e *versionRefusalError) Error() string {
	refused, ok := errors.AsType[*tmux.VersionTooLowError](e.err)
	if !ok {
		return e.err.Error()
	}
	remedy := refused.Reason() + "; restart the tmux server on this socket from a newer tmux, " +
		"or set " + BinaryEnvironmentVariable + " to one and restart this server"
	return strings.Replace(e.err.Error(), refused.Error(), remedy, 1)
}

func (e *versionRefusalError) Unwrap() error { return e.err }

// explainVersionRefusal adds the remedy to a core version refusal and leaves
// every other error, including an optional-feature refusal, alone.
func explainVersionRefusal(err error) error {
	if _, explained := errors.AsType[*versionRefusalError](err); explained {
		return err
	}
	refused, ok := errors.AsType[*tmux.VersionTooLowError](err)
	if !ok || refused.Feature != "" || refused.Minimum.String() != tmux.MinimumSupportedVersion {
		return err
	}
	return &versionRefusalError{err: err}
}

