package tmux

import (
	"context"
	"errors"
)

// ClientAttachment is one immutable view of a client's live attachment.
// Session, Window, and Pane return values from the same observational Snapshot.
type ClientAttachment struct {
	session    Session
	window     Window
	pane       Pane
	hasSession bool
	hasWindow  bool
	hasPane    bool
}

// Session returns the attached session, if it remained live in the snapshot.
func (a ClientAttachment) Session() (Session, bool) {
	return a.session, a.hasSession
}

// Window returns the attached session's active winlink, if present.
func (a ClientAttachment) Window() (Window, bool) {
	return a.window, a.hasWindow
}

// Pane returns the attached session's active window's active pane, if present.
func (a ClientAttachment) Pane() (Pane, bool) {
	return a.pane, a.hasPane
}

// ResolveAttachment re-reads the client's live attached hierarchy.
//
// One resolution materializes one strict Snapshot. Snapshot collection is a
// multi-command observational read, so concurrent tmux changes may produce a
// partial hierarchy. A missing client, detached client, or stale session
// returns an empty attachment without an error. Other collection, decoding,
// and cardinality errors remain visible.
func (c Client) ResolveAttachment(ctx context.Context) (ClientAttachment, error) {
	if err := validateTypedTarget(
		"resolve-attachment", "ClientName", "client", c.clientName.String(),
	); err != nil {
		return ClientAttachment{}, err
	}
	snapshot, err := c.server.Snapshot(ctx)
	if err != nil {
		return ClientAttachment{}, err
	}
	live, err := snapshot.ClientByName(c.clientName)
	if errors.Is(err, ErrNotFound) {
		return ClientAttachment{}, nil
	}
	if err != nil {
		return ClientAttachment{}, err
	}
	if !live.attachment.hasSession {
		return ClientAttachment{}, nil
	}

	session, err := snapshot.SessionByID(live.attachment.sessionID)
	if errors.Is(err, ErrNotFound) {
		return ClientAttachment{}, nil
	}
	if err != nil {
		return ClientAttachment{}, err
	}
	attachment := ClientAttachment{session: session, hasSession: true}

	window, found, err := attachmentActiveWindow(session)
	if err != nil {
		return ClientAttachment{}, err
	}
	if !found {
		return attachment, nil
	}
	attachment.window = window
	attachment.hasWindow = true

	pane, found, err := attachmentActivePane(window)
	if err != nil {
		return ClientAttachment{}, err
	}
	if !found {
		return attachment, nil
	}
	attachment.pane = pane
	attachment.hasPane = true
	return attachment, nil
}

func attachmentActiveWindow(session Session) (Window, bool, error) {
	var active Window
	matches := 0
	windows, ok := session.Windows()
	if !ok {
		return Window{}, false, nil
	}
	for _, window := range windows {
		value, queried := window.Active()
		if !queried || !value {
			continue
		}
		active = window
		matches++
	}
	if matches > 1 {
		return Window{}, false, &SnapshotLookupError{
			Object:     "active window",
			Identifier: session.sessionID.String(),
			Matches:    matches,
		}
	}
	return active, matches == 1, nil
}

func attachmentActivePane(window Window) (Pane, bool, error) {
	var active Pane
	matches := 0
	panes, ok := window.Panes()
	if !ok {
		return Pane{}, false, nil
	}
	for _, pane := range panes {
		value, queried := pane.Active()
		if !queried || !value {
			continue
		}
		active = pane
		matches++
	}
	if matches > 1 {
		return Pane{}, false, &SnapshotLookupError{
			Object:     "active pane",
			Identifier: window.windowID.String(),
			Matches:    matches,
		}
	}
	return active, matches == 1, nil
}

tmux/command.go.content:
package tmux

import (
	"bytes"
	"errors"
	"fmt"
	"os/exec"
	"slices"
	"strings"

	"github.com/libtmux/libtmux-go/tmux/internal/tmuxcmd"
)

// ErrUnknownColor identifies an unsupported tmux color mode. It is matched by
// errors.Is for [ColorError].
var ErrUnknownColor = errors.New("tmux: unknown color mode")

// ErrCommand identifies a failed high-level tmux command. It is matched by
// errors.Is for [CommandError].
var ErrCommand = errors.New("tmux: command failed")

// ErrNoServer identifies a command that no tmux server answered. A
// [CommandError] may match both ErrNoServer and [ErrCommand]. tmux cannot
// reliably distinguish an absent or unreachable server from one that exited
// during the command.
var ErrNoServer = errors.New("tmux: no server reached")

// ErrNotFound identifies an operation naming a tmux object that does not
// exist. A lookup that found nothing matches it, and so does a command tmux
// refused because the target it named was gone — the same condition reached
// from either direction. [SnapshotLookupError] and [CommandError] match it
// through errors.Is.
//
// Only a claim of absence this package has not disproved matches. A lookup
// that reaches a replaced daemon, or whose diagnostic names an object it did
// not target, reports what it saw rather than an absence.
var ErrNotFound = errors.New("tmux: object not found")

// ColorMode selects a tmux color-capability override for [ServerOptions].
type ColorMode int

// Supported tmux color-capability overrides.
const (
	// ColorDefault preserves tmux's detected color capability.
	ColorDefault ColorMode = 0
	// Color256 requests tmux's 256-color capability mode.
	Color256 ColorMode = 256
)

// ColorError reports an unsupported color mode. It matches [ErrUnknownColor]
// through errors.Is; callers can recover Mode with errors.As.
type ColorError struct {
	// Mode is the rejected color-capability override.
	Mode ColorMode
}

// Error implements error.
func (e *ColorError) Error() string {
	return fmt.Sprintf("%v %d", ErrUnknownColor, e.Mode)
}

// Unwrap makes ColorError compatible with ErrUnknownColor.
func (e *ColorError) Unwrap() error {
	return ErrUnknownColor
}

// CommandResult contains one completed tmux invocation. [Server.Cmd] returns
// it even when tmux exits nonzero. Library operations clone its slices before
// returning it, so the caller owns Command, Stdout, RawStdout, and Stderr.
type CommandResult struct {
	// Command is the executed tmux argument vector.
	Command []string
	// Stdout contains one decoded standard-output line per element.
	Stdout []string
	// RawStdout contains exact captured standard-output bytes, including line
	// delimiters and trailing newlines. It is nil when no output was captured.
	RawStdout []byte
	// Stderr contains one decoded standard-error line per element.
	Stderr []string
	// ExitCode is tmux's completed process exit code, or -1 when no tmux
	// command ran: this package refused the request, or a transport failed
	// before tmux answered. A negative code is therefore never tmux's opinion
	// of the request, and an error carrying one has a reason of its own.
	ExitCode int
}

type commandTransportError struct {
	err error
}

func (e *commandTransportError) Error() string { return e.err.Error() }

func (e *commandTransportError) Unwrap() error { return e.err }

// commandTransportFailure leaves executable-resolution and truncated-read
// failures strict so configuration errors or partial output cannot become empty rows.
func commandTransportFailure(err error) error {
	if errors.Is(err, ErrDaemonReplaced) {
		return err
	}
	if _, ok := errors.AsType[*tmuxcmd.OutcomeUnknownError](err); ok {
		return outcomeUnknown(err)
	}
	if _, ok := errors.AsType[*exec.Error](err); ok {
		return err
	}
	if errors.Is(err, exec.ErrWaitDelay) {
		return err
	}
	return &commandTransportError{err: err}
}

// CommandError reports a completed failed high-level tmux operation. It matches
// [ErrCommand] through errors.Is; callers can recover its fields with errors.As.
// Generic library operations retain an owned copy of the completed command and
// output so tmux diagnostics remain available. Operations whose primary payload
// may contain secrets return an exit-code-only result instead. Callers must
// treat retained argv and output as potentially sensitive.
type CommandError struct {
	// Subcommand is the failed tmux subcommand.
	Subcommand string
	// Result is the owned completed result, or an exit-code-only redacted result
	// for a secret-bearing operation.
	Result CommandResult

	targetNotFound bool
	noServer       bool
}

// Error implements error.
func (e *CommandError) Error() string {
	detail := strings.Join(e.Result.Stderr, "\n")
	if detail == "" {
		return fmt.Sprintf("%v: %s exited %d", ErrCommand, e.Subcommand, e.Result.ExitCode)
	}
	return fmt.Sprintf("%v: %s exited %d: %s", ErrCommand, e.Subcommand, e.Result.ExitCode, detail)
}

// Unwrap makes CommandError compatible with ErrCommand.
func (e *CommandError) Unwrap() error {
	return ErrCommand
}

// Is reports [ErrNoServer] for a failure that means no tmux server answered —
// either the command never reached one, or the one it reached is gone — and
// [ErrNotFound] for one tmux refused because the object it named was absent.
func (e *CommandError) Is(target error) bool {
	switch target {
	case ErrNoServer:
		return e.noServer
	case ErrNotFound:
		return e.targetNotFound
	default:
		return false
	}
}

// withoutAbsenceClaim returns err with any claim that tmux's target was
// missing removed, for a caller that has disproved the absence the claim
// would otherwise assert.
//
// err has to be the [CommandError] itself rather than one wrapping it, because
// clearing a claim inside a chain would mean rebuilding the chain. Its callers
// hold what snapshotListing returned, which is unwrapped. Anything else is
// returned unchanged.
func withoutAbsenceClaim(err error) error {
	//nolint:errorlint // must be the unwrapped error, not one wrapping it; see above
	commandError, ok := err.(*CommandError)
	if !ok || !commandError.targetNotFound {
		return err
	}
	cleared := *commandError
	cleared.targetNotFound = false
	return &cleared
}

func newCommandError(subcommand string, result CommandResult) *CommandError {
	return &CommandError{
		Subcommand:     subcommand,
		Result:         cloneCommandResult(result),
		targetNotFound: commandTargetNotFound(result.Stderr),
		noServer:       commandServerUnreachable(result.Stderr),
	}
}

func newRedactedCommandError(subcommand string, result CommandResult) *CommandError {
	if commandServerUnreachable(result.Stderr) ||
		commandFixedRefusal(result.Stderr) ||
		commandTargetNotFound(result.Stderr) {
		return newCommandError(subcommand, result)
	}
	return &CommandError{
		Subcommand:     subcommand,
		Result:         CommandResult{ExitCode: result.ExitCode},
		targetNotFound: commandTargetNotFound(result.Stderr),
		noServer:       commandServerUnreachable(result.Stderr),
	}
}

// These pre-command diagnostics contain only socket paths and errno text, so
// secret-redacting errors may disclose them. tmux 3.2a and 3.3a use different
// socket-path wording, and tmux may exit zero after failing to create a socket.
var commandServerUnreachablePrefixes = [...]string{
	"no server running on ",
	"error connecting to ",
	"error creating ",
	"couldn't create directory ",
	"couldn't read directory ",
	"no suitable socket path",
}

// These socket-path failures put the variable path before the fixed diagnostic.
var commandServerUnreachableSuffixes = [...]string{
	" is not a directory",
	" has unsafe permissions",
}

// Fixed refusals contain no caller values and remain safe in redacted errors.
var commandFixedRefusals = [...]string{
	// The tmux client refuses a command larger than one message to the
	// server, 16 KiB (MAX_IMSGSIZE), before sending it.
	"command too long",
	"no space for a new pane",
	// tmux 3.2a through 3.6a word the same refusal without "a"; layout.c moved
	// and reworded it at 3.7.
	"no space for new pane",
}

func commandFixedRefusal(stderr []string) bool {
	for _, line := range stderr {
		for _, refusal := range commandFixedRefusals {
			if strings.Contains(line, refusal) {
				return true
			}
		}
	}
	return false
}

// commandServerUnreachable detects safe-to-disclose failures before a command ran.
func commandServerUnreachable(stderr []string) bool {
	for _, line := range stderr {
		for _, prefix := range commandServerUnreachablePrefixes {
			if strings.HasPrefix(line, prefix) {
				return true
			}
		}
		for _, suffix := range commandServerUnreachableSuffixes {
			if strings.HasSuffix(line, suffix) {
				return true
			}
		}
		for _, message := range commandServerGoneMessages {
			if line == message {
				return true
			}
		}
	}
	return false
}

// These exact, locale-independent messages cover a server lost after connect.
// Treating them like connect failures avoids a race-dependent ErrNoServer result.
var commandServerGoneMessages = [...]string{
	// CLIENT_EXIT_LOST_SERVER: the connection went while the command was in
	// flight.
	"server exited unexpectedly",
	// CLIENT_EXIT_SERVER_EXITED: the server shut down and said so.
	"server exited",
}

// tmux exposes missing targets only through these words in its diagnostics.
var commandTargetNotFoundObjects = [...]string{"session", "window", "pane", "client"}

// Match the object word because terminfo and "next session" failures also begin
// with "can't find" but do not mean the requested target was absent.
func commandTargetNotFound(stderr []string) bool {
	for _, line := range stderr {
		for _, object := range commandTargetNotFoundObjects {
			if strings.Contains(line, "can't find "+object+":") ||
				strings.HasSuffix(line, "can't find "+object) {
				return true
			}
		}
	}
	return false
}

// commandNoCurrentTarget recognizes tmux's "no current target" refusal: an
// all-server listing that resolves an implicit current session (list-windows
// -a, list-panes -a, list-clients) refuses this way when the server holds no
// sessions at all. A server with zero sessions is still a working server.
func commandNoCurrentTarget(stderr []string) bool {
	for _, line := range stderr {
		if strings.Contains(line, "no current target") {
			return true
		}
	}
	return false
}

func cloneCommandResult(result CommandResult) CommandResult {
	result.Command = slices.Clone(result.Command)
	result.Stdout = slices.Clone(result.Stdout)
	result.RawStdout = bytes.Clone(result.RawStdout)
	result.Stderr = slices.Clone(result.Stderr)
	return result
}

// validateLiteralCommandArguments rejects NUL, which no process argv can carry.
func validateLiteralCommandArguments(arguments []string) error {
	for _, argument := range arguments {
		if strings.ContainsRune(argument, '\x00') {
			return invalidServerCommandRequest(
				"command",
				"Arguments",
				"[redacted]",
				"contains NUL, which cannot cross process argv",
			)
		}
	}
	return nil
}

// escapeCommandListSeparators protects final semicolons from a subprocess's
// outer tmux parser. Control mode quotes arguments and must not add this escape.
func escapeCommandListSeparators(arguments []string) []string {
	escaped := make([]string, len(arguments))
	for index, argument := range arguments {
		escaped[index] = escapeTrailingTmuxCommandSeparator(argument)
	}
	return escaped
}

// escapeTrailingTmuxCommandSeparator preserves a literal final semicolon in
// one already-split argv value. tmux otherwise consumes it as a command-list
// separator even when no shell is involved.
func escapeTrailingTmuxCommandSeparator(value string) string {
	if !strings.HasSuffix(value, ";") {
		return value
	}
	return value[:len(value)-1] + `\;`
}

type serverCommandArgument struct {
	field string
	value string
}

func validateServerCommandArguments(
	subcommand string,
	arguments ...serverCommandArgument,
) error {
	for _, argument := range arguments {
		if err := validateServerCommandArgument(
			subcommand,
			argument.field,
			argument.value,
			true,
		); err != nil {
			return err
		}
	}
	return nil
}

tmux/complex_options.go.content:
package tmux

import (
	"errors"
	"fmt"
	"math/big"
	"strings"
)

// ErrMalformedComplexOption identifies an invalid entry in a parsed complex option.
var ErrMalformedComplexOption = errors.New("tmux: malformed complex option")

// ComplexOptionDecodeError identifies one malformed sparse-array entry without
// retaining its raw value.
type ComplexOptionDecodeError struct {
	// Option is the option name whose sparse-array entry was malformed.
	Option string
	// Index is the zero-based sparse-array entry index.
	Index int
	// Reason describes the syntax failure without retaining raw option contents.
	Reason string
}

// Error implements error.
func (e *ComplexOptionDecodeError) Error() string {
	return fmt.Sprintf(
		"%v: %s[%d]: %s",
		ErrMalformedComplexOption,
		e.Option,
		e.Index,
		e.Reason,
	)
}

// Unwrap makes ComplexOptionDecodeError compatible with ErrMalformedComplexOption.
func (e *ComplexOptionDecodeError) Unwrap() error { return ErrMalformedComplexOption }

// CommandAlias is one parsed command-alias entry.
type CommandAlias struct {
	// Name is the alias name.
	Name string
	// Command is the tmux command text associated with Name.
	Command string
}

// CommandAliases is an immutable parsed command-alias option. Its zero value
// is an empty collection: Len is zero, Lookup reports false, and Entries
// returns a nonnil empty slice.
type CommandAliases struct {
	entries []CommandAlias
	byName  map[string]int
}

// Lookup returns the command registered for name.
func (a CommandAliases) Lookup(name string) (string, bool) {
	index, ok := a.byName[name]
	if !ok {
		return "", false
	}
	return a.entries[index].Command, true
}

// Entries returns a fresh slice in first-definition order.
func (a CommandAliases) Entries() []CommandAlias {
	return append(make([]CommandAlias, 0, len(a.entries)), a.entries...)
}

// Len returns the number of distinct aliases.
func (a CommandAliases) Len() int { return len(a.entries) }

// TerminalFeature is one terminal pattern and its enabled features.
type TerminalFeature struct {
	// Terminal is the terminal pattern.
	Terminal string
	// Features is an owned feature list for Terminal.
	Features []string
}

// TerminalFeatures is an immutable parsed terminal-features option. Its zero
// value is an empty collection: Len is zero, Lookup reports false, and Entries
// returns a nonnil empty slice.
type TerminalFeatures struct {
	entries    []TerminalFeature
	byTerminal map[string]int
}

// Lookup returns a fresh feature slice for terminal.
func (f TerminalFeatures) Lookup(terminal string) ([]string, bool) {
	index, ok := f.byTerminal[terminal]
	if !ok {
		return nil, false
	}
	return append(make([]string, 0, len(f.entries[index].Features)), f.entries[index].Features...), true
}

// Entries returns a deep fresh copy in first-definition order.
func (f TerminalFeatures) Entries() []TerminalFeature {
	entries := make([]TerminalFeature, len(f.entries))
	for index, entry := range f.entries {
		entries[index] = TerminalFeature{
			Terminal: entry.Terminal,
			Features: append(make([]string, 0, len(entry.Features)), entry.Features...),
		}
	}
	return entries
}

// Len returns the number of distinct terminal patterns.
func (f TerminalFeatures) Len() int { return len(f.entries) }

// TerminalOverrideValueKind identifies one closed terminal capability value form.
type TerminalOverrideValueKind uint8

const (
	// TerminalOverrideValueFlag identifies a capability without an assigned value.
	TerminalOverrideValueFlag TerminalOverrideValueKind = iota + 1
	// TerminalOverrideValueInteger identifies an unsigned decimal integer.
	TerminalOverrideValueInteger
	// TerminalOverrideValueText identifies an assigned non-integer string.
	TerminalOverrideValueText
)

// TerminalOverrideValue is a flag, arbitrary-precision integer, or string. Its
// zero value has no recognized kind: IsFlag is false, Integer and Text report
// false, and it represents no parsed capability assignment.
type TerminalOverrideValue struct {
	kind TerminalOverrideValueKind
	text string
}

// Kind returns the value's closed form.
func (v TerminalOverrideValue) Kind() TerminalOverrideValueKind { return v.kind }

// IsFlag reports whether the capability has no assigned value.
func (v TerminalOverrideValue) IsFlag() bool {
	return v.kind == TerminalOverrideValueFlag
}

// Integer returns a fresh arbitrary-precision integer when the value is numeric.
func (v TerminalOverrideValue) Integer() (*big.Int, bool) {
	if v.kind != TerminalOverrideValueInteger {
		return nil, false
	}
	integer, ok := new(big.Int).SetString(v.text, 10)
	return integer, ok
}

// Text returns the assigned string when the value is textual.
func (v TerminalOverrideValue) Text() (string, bool) {
	if v.kind != TerminalOverrideValueText {
		return "", false
	}
	return v.text, true
}

// TerminalCapability is one parsed terminal override capability.
type TerminalCapability struct {
	// Name is the capability name.
	Name string
	// Value is the parsed capability value.
	Value TerminalOverrideValue
}

// TerminalOverride is the immutable capability set for one terminal pattern.
// Its zero value is an empty immutable collection: Len is zero, Lookup reports
// false, and Entries returns a nonnil empty slice.
type TerminalOverride struct {
	entries []TerminalCapability
	byName  map[string]int
}

// Lookup returns one capability value.
func (o TerminalOverride) Lookup(name string) (TerminalOverrideValue, bool) {
	index, ok := o.byName[name]
	if !ok {
		return TerminalOverrideValue{}, false
	}
	return o.entries[index].Value, true
}

// Entries returns a fresh slice in first-definition order.
func (o TerminalOverride) Entries() []TerminalCapability {
	return append(make([]TerminalCapability, 0, len(o.entries)), o.entries...)
}

// Len returns the number of distinct capabilities.
func (o TerminalOverride) Len() int { return len(o.entries) }

// TerminalOverrideEntry is one terminal pattern and its parsed capabilities.
type TerminalOverrideEntry struct {
	// Terminal is the terminal pattern.
	Terminal string
	// Capabilities is the immutable capability set for Terminal.
	Capabilities TerminalOverride
}

// TerminalOverrides is an immutable parsed terminal-overrides option. Its zero
// value is an empty immutable collection: Len is zero, Lookup reports false,
// and Entries returns a nonnil empty slice.
type TerminalOverrides struct {
	entries    []TerminalOverrideEntry
	byTerminal map[string]int
}

// Lookup returns the capabilities for terminal.
func (o TerminalOverrides) Lookup(terminal string) (TerminalOverride, bool) {
	index, ok := o.byTerminal[terminal]
	if !ok {
		return TerminalOverride{}, false
	}
	return o.entries[index].Capabilities, true
}

// Entries returns a fresh outer slice in first-definition order. Nested
// TerminalOverride values remain immutable.
func (o TerminalOverrides) Entries() []TerminalOverrideEntry {
	return append(make([]TerminalOverrideEntry, 0, len(o.entries)), o.entries...)
}

// Len returns the number of distinct terminal patterns.
func (o TerminalOverrides) Len() int { return len(o.entries) }

// CommandAliases parses command-alias while preserving option presence and origin.
// A nonnil joined error contains [ComplexOptionDecodeError] values, each usable
// with [errors.Is] or [errors.As]; the returned projection still contains every
// valid entry and is owned by the caller.
func (v ServerOptionValues) CommandAliases() (OptionValue[CommandAliases], error) {
	raw, ok := v.commandAlias.Get()
	if !ok {
		return OptionValue[CommandAliases]{}, nil
	}
	aliases := CommandAliases{byName: make(map[string]int)}
	var decodeErrors []error
	for index, item := range raw.All() {
		name, command, found := strings.Cut(item, "=")
		if !found {
			decodeErrors = append(decodeErrors, &ComplexOptionDecodeError{
				Option: "command-alias",
				Index:  index,
				Reason: "expected alias=command",
			})
			continue
		}
		aliases.set(name, command)
	}
	return projectOptionValue(v.commandAlias, aliases), errors.Join(decodeErrors...)
}

// ParsedTerminalFeatures parses terminal-features while preserving option
// presence and origin. A nonnil joined error contains
// [ComplexOptionDecodeError] values and the returned owned projection contains
// every valid entry.
func (v ServerOptionValues) ParsedTerminalFeatures() (OptionValue[TerminalFeatures], error) {
	raw, ok := v.terminalFeatures.Get()
	if !ok {
		return OptionValue[TerminalFeatures]{}, nil
	}
	features := TerminalFeatures{byTerminal: make(map[string]int)}
	var decodeErrors []error
	for index, item := range raw.All() {
		terminal, featureList, found := strings.Cut(item, ":")
		if !found {
			decodeErrors = append(decodeErrors, &ComplexOptionDecodeError{
				Option: "terminal-features",
				Index:  index,
				Reason: "expected terminal:features",
			})
			continue
		}
		features.set(terminal, strings.Split(featureList, ":"))
	}
	return projectOptionValue(v.terminalFeatures, features), errors.Join(decodeErrors...)
}

// ParsedTerminalOverrides parses terminal-overrides while preserving option
// presence and origin. Terminal-overrides syntax is permissive: no malformed
// entry error is returned, and the result owns its parsed projection.
func (v ServerOptionValues) ParsedTerminalOverrides() (OptionValue[TerminalOverrides], error) {
	raw, ok := v.terminalOverrides.Get()
	if !ok {
		return OptionValue[TerminalOverrides]{}, nil
	}
	overrides := TerminalOverrides{byTerminal: make(map[string]int)}
	for _, item := range raw.Values() {
		parts := strings.Split(item, ":")
		terminal := parts[0]
		for _, capability := range parts[1:] {
			if capability == "" {
				continue
			}
			name, assigned, hasAssignment := strings.Cut(capability, "=")
			value := TerminalOverrideValue{kind: TerminalOverrideValueFlag}
			if hasAssignment {
				value = TerminalOverrideValue{kind: TerminalOverrideValueText, text: assigned}
				if decimalDigits(assigned) {
					value.kind = TerminalOverrideValueInteger
				}
			}
			overrides.set(terminal, name, value)
		}
		overrides.ensureTerminal(terminal)
	}
	return projectOptionValue(v.terminalOverrides, overrides), nil
}

func (a *CommandAliases) set(name, command string) {
	if index, ok := a.byName[name]; ok {
		a.entries[index].Command = command
		return
	}
	a.byName[name] = len(a.entries)
	a.entries = append(a.entries, CommandAlias{Name: name, Command: command})
}

func (f *TerminalFeatures) set(terminal string, features []string) {
	owned := append(make([]string, 0, len(features)), features...)
	if index, ok := f.byTerminal[terminal]; ok {
		f.entries[index].Features = owned
		return
	}
	f.byTerminal[terminal] = len(f.entries)
	f.entries = append(f.entries, TerminalFeature{Terminal: terminal, Features: owned})
}

func (o *TerminalOverrides) ensureTerminal(terminal string) int {
	if index, ok := o.byTerminal[terminal]; ok {
		return index
	}
	index := len(o.entries)
	o.byTerminal[terminal] = index
	o.entries = append(o.entries, TerminalOverrideEntry{
		Terminal: terminal,
		Capabilities: TerminalOverride{
			byName: make(map[string]int),
		},
	})
	return index
}

func (o *TerminalOverrides) set(terminal, name string, value TerminalOverrideValue) {
	index := o.ensureTerminal(terminal)
	capabilities := &o.entries[index].Capabilities
	if capabilityIndex, ok := capabilities.byName[name]; ok {
		capabilities.entries[capabilityIndex].Value = value
		return
	}
	capabilities.byName[name] = len(capabilities.entries)
	capabilities.entries = append(capabilities.entries, TerminalCapability{Name: name, Value: value})
}

func projectOptionValue[Raw, Parsed any](
	raw OptionValue[Raw],
	parsed Parsed,
) OptionValue[Parsed] {
	return OptionValue[Parsed]{value: parsed, origin: raw.origin}
}

func decimalDigits(value string) bool {
	if value == "" {
		return false
	}
	for index := range len(value) {
		if value[index] < '0' || value[index] > '9' {
			return false
		}
	}
	return true
}

