package tmux

import (
	"bytes"
	"errors"
	"io"
	"os/exec"
	"sync"
	"sync/atomic"
)

// ErrControlClosed identifies an operation attempted after a control client
// began closing or lost its protocol stream. A notification read after either
// end matches it, so one errors.Is check covers a stream the caller closed and
// one tmux ended; [ErrControlStreamLost] tells the second apart.
var ErrControlClosed = errors.New("tmux: control client is closed")

// ErrControlStreamLost identifies a [ControlClient.NextNotification] stream
// that ended before the caller asked to close it, distinct from the clean
// end an explicit Close or CloseContext produces. Such an error also matches
// [ErrControlClosed]. It is most often the
// underlying tmux client process exiting because the server it was attached
// to did.
var ErrControlStreamLost = errors.New("tmux: control stream lost")

// ErrOutcomeUnknown identifies a command whose write began but whose reply
// boundary was not observed. The operation may have changed tmux.
var ErrOutcomeUnknown = errors.New("tmux: command outcome is unknown")

// ErrControlReplyCount identifies a call to [ControlClient.Cmd] for a command
// that produced zero or multiple reply frames.
var ErrControlReplyCount = errors.New("tmux: control command did not return exactly one reply")

// ControlClient is one attached tmux control-mode process. Create one with
// [Server.OpenControl]. Concurrent Cmd, Wait, close, and NextNotification calls
// are supported; concurrent notification reads are serialized.
//
// It is the low-level handle: it carries commands and notifications on one
// client and can [ControlClient.Reconnect], but records do not run through it.
// [Session.OpenControl] returns a [Connection] instead, whose lanes the
// sessions, windows and panes obtained from it use for their own commands.
type ControlClient struct {
	server     Server
	session    Session
	clientName ClientName

	command       *exec.Cmd
	stdin         io.WriteCloser
	stdout        io.ReadCloser
	stderr        *controlLockedBuffer
	notifications *controlNotificationQueue
	frames        chan controlFrame
	requests      chan *controlRequest
	stopRequests  chan struct{}
	requestDone   chan struct{}
	closing       chan struct{}
	readDone      chan struct{}
	done          chan struct{}
	closeDone     chan struct{}

	stateMu          sync.Mutex
	readErr          error
	waitErr          error
	currentSessionID SessionID
	// lastExitReason is the tail of the most recent %exit notification read
	// off the wire, tracked as notifications arrive rather than as a caller
	// consumes them. Empty means either none arrived or tmux sent a bare
	// %exit with no reason.
	lastExitReason string

	closeRequested atomic.Bool
	closeOnce      sync.Once
	closeErr       error
	replyFence     controlReplyFence

	// parser reads the stream. It lives here so a request can arm it to
	// capture a command's output; see [controlCapture].
	parser controlStreamParser

	// dispatching excludes flags-0 frames after the attach reply.
	dispatching atomic.Bool

	// outputFrom, once set, names the one pane whose output this client
	// keeps; output from every other pane is dropped as it arrives. A pane
	// observation sets it on the client it opened for itself. tmux sends a
	// control client the output of every pane in its session, and a busy
	// sibling would otherwise fill the observation's queue and end it.
	outputFrom atomic.Pointer[string]
}

// outputFromAnotherPane reports whether record is pane output that this
// client was told to drop.
func (c *ControlClient) outputFromAnotherPane(record []byte) bool {
	kept := c.outputFrom.Load()
	if kept == nil {
		return false
	}
	var rest []byte
	switch {
	case bytes.HasPrefix(record, []byte("%output ")):
		rest = record[len("%output "):]
	case bytes.HasPrefix(record, []byte("%extended-output ")):
		rest = record[len("%extended-output "):]
	default:
		return false
	}
	pane, _, _ := bytes.Cut(rest, []byte(" "))
	return string(pane) != *kept
}

// ownReply uses tmux's CMDQ_STATE_CONTROL guard flag. Treating a key-binding
// command as our reply would shift every later reply on the connection.
func (f controlFrame) ownReply() bool {
	return f.flags != 0
}

type controlLockedBuffer struct {
	mu sync.Mutex
	bytes.Buffer
}

func (b *controlLockedBuffer) Write(data []byte) (int, error) {
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.Buffer.Write(data)
}

func (b *controlLockedBuffer) String() string {
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.Buffer.String()
}

// ClientName returns the tmux-assigned identity captured during registration.
func (c *ControlClient) ClientName() ClientName { return c.clientName }

// Server returns the server handle used to start the control client.
func (c *ControlClient) Server() Server { return c.server }

// Session returns the materialized session selected during startup.
func (c *ControlClient) Session() Session { return c.session }

tmux/control_lifecycle.go.content:
package tmux

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"time"
)

const (
	controlClientStopGrace    = 250 * time.Millisecond
	controlClientStopTimeout  = 2 * time.Second
	controlClientCloseTimeout = controlClientStopTimeout + 2*controlClientStopGrace
)

// Wait blocks until the control process exits or ctx ends. It does not close
// the notification queue; callers may drain final notifications before Close.
func (c *ControlClient) Wait(ctx context.Context) error {
	select {
	case <-c.done:
		c.stateMu.Lock()
		defer c.stateMu.Unlock()
		return c.waitErr
	case <-ctx.Done():
		return ctx.Err()
	}
}

// CloseContext starts idempotent control-client shutdown and waits within ctx.
// The context bounds only the wait: an already-ended context still starts
// shutdown, and a later call may resume waiting for the same close.
func (c *ControlClient) CloseContext(ctx context.Context) error {
	c.startClose()
	return c.waitClose(ctx)
}

func (c *ControlClient) startClose() {
	c.closeOnce.Do(func() {
		c.closeRequested.Store(true)
		close(c.stopRequests)
		go c.closeAfterRequests()
	})
}

func (c *ControlClient) waitClose(ctx context.Context) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	select {
	case <-c.closeDone:
		return c.closeErr
	case <-ctx.Done():
		return ctx.Err()
	}
}

// Close stops the control process and releases its notification queue. It is
// safe to call concurrently and more than once.
func (c *ControlClient) Close() error {
	ctx, cancel := context.WithTimeout(
		context.Background(),
		controlClientCloseTimeout,
	)
	defer cancel()
	return c.CloseContext(ctx)
}

// Reconnect registers a replacement on the last attached session observed at a
// reply boundary, then closes the receiver. Failed replacement setup does not
// initiate receiver shutdown. If shutdown fails, Reconnect returns the live
// replacement with that error; the caller owns every non-nil result. A receiver
// whose stream ended cleanly can recover from its last observation. Commands
// are never replayed.
func (c *ControlClient) Reconnect(ctx context.Context) (*ControlClient, error) {
	session, err := c.reconnectSession(ctx)
	if err != nil {
		return nil, err
	}
	replacement, err := c.server.OpenControl(ctx, session)
	if err != nil {
		return nil, err
	}
	if err := c.CloseContext(ctx); err != nil {
		return replacement, err
	}
	return replacement, nil
}

func (c *ControlClient) reconnectSession(ctx context.Context) (Session, error) {
	barrierErr := c.crossReplyFence(ctx)
	if barrierErr != nil {
		if err := ctx.Err(); err != nil {
			return Session{}, err
		}
		select {
		case <-c.readDone:
		case <-ctx.Done():
			return Session{}, ctx.Err()
		}
		if err := ctx.Err(); err != nil {
			return Session{}, err
		}
	}

	c.stateMu.Lock()
	current := c.currentSessionID
	readErr := c.readErr
	c.stateMu.Unlock()

	if barrierErr != nil {
		if readErr != nil {
			return Session{}, readErr
		}
		if c.closeRequested.Load() {
			return Session{}, barrierErr
		}
	}

	session := c.session.withServer(c.server)
	if current == "" || current == session.ID() {
		return session, nil
	}
	return c.server.Session(ctx, current)
}

func (c *ControlClient) closeAfterRequests() {
	timer := time.NewTimer(controlClientStopGrace)
	defer timer.Stop()
	select {
	case <-c.requestDone:
	case <-timer.C:
	}
	close(c.closing)
	c.close()
}

func (c *ControlClient) waitProcess() {
	err := c.command.Wait()
	c.stateMu.Lock()
	c.waitErr = err
	c.stateMu.Unlock()
	close(c.done)
}

func (c *ControlClient) registrationExitError() error {
	c.stateMu.Lock()
	waitErr := c.waitErr
	c.stateMu.Unlock()
	stderr := c.stderr.String()
	if waitErr == nil {
		return fmt.Errorf("control process exited before registration; stderr=%q", stderr)
	}
	return fmt.Errorf(
		"control process exited before registration: %w; stderr=%q",
		waitErr,
		stderr,
	)
}

func (c *ControlClient) operationError() error {
	c.stateMu.Lock()
	readErr := c.readErr
	waitErr := c.waitErr
	c.stateMu.Unlock()
	if readErr != nil {
		return readErr
	}
	if waitErr != nil {
		return fmt.Errorf("%w: %w", ErrControlClosed, waitErr)
	}
	return ErrControlClosed
}

func (c *ControlClient) classifyOperationError(err error) error {
	if c.isClosing() || errors.Is(err, os.ErrClosed) || errors.Is(err, io.ErrClosedPipe) {
		return ErrControlClosed
	}
	return fmt.Errorf("write control command: %w", err)
}

func (c *ControlClient) isClosing() bool {
	select {
	case <-c.closing:
		return true
	default:
		return false
	}
}

func (c *ControlClient) close() {
	defer close(c.closeDone)
	stdinErr := c.stdin.Close()
	if errors.Is(stdinErr, os.ErrClosed) {
		stdinErr = nil
	}
	select {
	case <-c.done:
	case <-time.After(controlClientStopGrace):
		killErr := c.command.Process.Kill()
		if errors.Is(killErr, os.ErrProcessDone) {
			killErr = nil
		}
		c.closeErr = errors.Join(c.closeErr, killErr)
		select {
		case <-c.done:
		case <-time.After(controlClientStopTimeout):
			c.closeErr = errors.Join(
				c.closeErr,
				errors.New("control process did not exit after kill"),
			)
		}
	}
	stdoutErr := c.stdout.Close()
	if errors.Is(stdoutErr, os.ErrClosed) {
		stdoutErr = nil
	}
	c.closeErr = errors.Join(
		c.closeErr,
		stdinErr,
		stdoutErr,
		c.notifications.Close(),
	)
}

