package tmux

import (
	"bytes"
	"errors"
	"fmt"
	"slices"
	"strconv"
	"strings"
)

var (
	// ErrMalformedControlNotification identifies a structurally invalid
	// control-mode notification.
	ErrMalformedControlNotification = errors.New("tmux: malformed control notification")
	// ErrUnknownControlNotification identifies a well-framed notification kind
	// outside the pinned control-mode vocabulary.
	ErrUnknownControlNotification = errors.New("tmux: unknown control notification")
)

// ControlNotificationError reports where a control-mode notification failed
// validation without retaining or disclosing the notification contents.
// Callers can use [errors.Is] with Category or [errors.As] to inspect its
// secret-safe location metadata. Category is [ErrMalformedControlNotification]
// or [ErrUnknownControlNotification].
type ControlNotificationError struct {
	// Offset is the byte offset of the malformed protocol element.
	Offset int
	// Reason describes the framing or vocabulary error without retaining input.
	Reason string
	// Category is ErrMalformedControlNotification or ErrUnknownControlNotification.
	Category error
}

// Error implements error.
func (e *ControlNotificationError) Error() string {
	return fmt.Sprintf("%v at byte %d: %s", e.Category, e.Offset, e.Reason)
}

// Unwrap makes ControlNotificationError compatible with its Category.
func (e *ControlNotificationError) Unwrap() error { return e.Category }

// ControlNotification is an immutable parsed tmux control-mode notification.
// Its zero value has an empty kind and no arguments. Values returned by
// [ParseControlNotification] own copied arguments and are safe to retain.
type ControlNotification struct {
	kind       ControlNotificationKind
	arguments  []string
	outputPane PaneID
	output     []byte
	hasOutput  bool
}

// Kind returns the notification's protocol kind.
func (n ControlNotification) Kind() ControlNotificationKind { return n.kind }

// Arguments returns an owned copy of the notification arguments. Arguments
// before a documented free-form tail are individual values; the tail is the
// final value and preserves its spacing and tmux escaping.
func (n ControlNotification) Arguments() []string { return slices.Clone(n.arguments) }

// Output returns the pane identity and decoded caller-owned bytes carried by
// an output or extended-output notification. Other notification kinds return
// zero values and false.
func (n ControlNotification) Output() (PaneID, []byte, bool) {
	if !n.hasOutput {
		return "", nil, false
	}
	return n.outputPane, bytes.Clone(n.output), true
}

// SubscriptionChange is one evaluated format value reported by a subscription
// armed with [NotificationStream.Subscribe]. The scope fields tmux did not
// evaluate against are zero: a session-scoped subscription reports no window
// or pane, and a window-scoped one reports no pane.
type SubscriptionChange struct {
	// Name is the subscription name given when it was armed.
	Name string
	// Session is the session the value was evaluated for.
	Session SessionID
	// Window is the window the value was evaluated for, when scoped to one.
	Window WindowID
	// WindowIndex is Window's index in Session. It means nothing when Window
	// is zero.
	WindowIndex int
	// Pane is the pane the value was evaluated for, when scoped to one.
	Pane PaneID
	// Value is the format expanded by tmux.
	Value string
}

// Subscription returns the change carried by a subscription-changed
// notification. Other notification kinds return a zero value and false.
func (n ControlNotification) Subscription() (SubscriptionChange, bool) {
	if n.kind != ControlNotificationSubscriptionChanged || len(n.arguments) < 6 {
		return SubscriptionChange{}, false
	}
	// Grammar: name, session, window, window index, pane, reserved..., value.
	// Reserved arguments may grow, so the value is the last argument rather
	// than the sixth.
	change := SubscriptionChange{
		Name:  n.arguments[0],
		Value: n.arguments[len(n.arguments)-1],
	}
	if id := n.arguments[1]; id != "-" {
		change.Session = SessionID(id)
	}
	if id := n.arguments[2]; id != "-" {
		change.Window = WindowID(id)
	}
	if index, err := strconv.Atoi(n.arguments[3]); err == nil {
		change.WindowIndex = index
	}
	if id := n.arguments[4]; id != "-" {
		change.Pane = PaneID(id)
	}
	return change, true
}

// ParseControlNotification parses one newline-free tmux control-mode
// notification record. It requires exact control framing and a supported kind,
// returns errors compatible with [ErrMalformedControlNotification] or
// [ErrUnknownControlNotification], and copies all caller-owned input before
// returning. It never returns a partial notification.
func ParseControlNotification(line []byte) (ControlNotification, error) {
	if len(line) == 0 {
		return ControlNotification{}, malformedControlNotification(0, "record is empty")
	}
	if offset := bytes.IndexAny(line, "\x00\r\n"); offset >= 0 {
		return ControlNotification{}, malformedControlNotification(offset, "record contains framing byte")
	}
	if line[0] != '%' {
		return ControlNotification{}, malformedControlNotification(0, "record does not start with a notification kind")
	}

	record := string(line)
	kindEnd := strings.IndexByte(record, ' ')
	if kindEnd < 0 {
		kindEnd = len(record)
	}
	if offset, ok := validControlNotificationKind(record[:kindEnd]); !ok {
		return ControlNotification{}, malformedControlNotification(offset, "notification kind is malformed")
	}
	kind := ControlNotificationKind(record[:kindEnd])
	definition, ok := controlNotificationDefinition(kind)
	if !ok {
		return ControlNotification{}, &ControlNotificationError{
			Offset:   0,
			Reason:   "notification kind is not recognized",
			Category: ErrUnknownControlNotification,
		}
	}

	arguments, err := parseControlNotificationArguments(record, kindEnd, definition)
	if err != nil {
		return ControlNotification{}, err
	}
	notification := ControlNotification{kind: kind, arguments: arguments}
	if kind == ControlNotificationOutput || kind == ControlNotificationExtendedOutput {
		tail := arguments[len(arguments)-1]
		output, err := decodeControlOutput(tail, len(record)-len(tail))
		if err != nil {
			return ControlNotification{}, err
		}
		notification.outputPane = PaneID(arguments[0])
		notification.output = output
		notification.hasOutput = true
	}
	return notification, nil
}

func decodeControlOutput(value string, baseOffset int) ([]byte, error) {
	output := make([]byte, 0, len(value))
	for offset := 0; offset < len(value); {
		if value[offset] != '\\' {
			output = append(output, value[offset])
			offset++
			continue
		}
		if offset+4 > len(value) {
			return nil, malformedControlNotification(
				baseOffset+offset,
				"output escape is incomplete",
			)
		}
		decoded := 0
		for digitOffset := 1; digitOffset <= 3; digitOffset++ {
			digit := value[offset+digitOffset]
			if digit < '0' || digit > '7' {
				return nil, malformedControlNotification(
					baseOffset+offset+digitOffset,
					"output escape is not three-digit octal",
				)
			}
			decoded = decoded*8 + int(digit-'0')
		}
		if decoded > 0xff {
			return nil, malformedControlNotification(
				baseOffset+offset,
				"output escape exceeds one byte",
			)
		}
		output = append(output, byte(decoded))
		offset += 4
	}
	return output, nil
}

func validControlNotificationKind(kind string) (int, bool) {
	if len(kind) < 2 || kind[0] != '%' || kind[1] < 'a' || kind[1] > 'z' {
		return min(1, len(kind)), false
	}
	previousHyphen := false
	for offset := 2; offset < len(kind); offset++ {
		value := kind[offset]
		letter := value >= 'a' && value <= 'z'
		digit := value >= '0' && value <= '9'
		if letter || digit {
			previousHyphen = false
			continue
		}
		if value != '-' || previousHyphen {
			return offset, false
		}
		previousHyphen = true
	}
	if previousHyphen {
		return len(kind) - 1, false
	}
	return 0, true
}

func controlNotificationDefinition(
	kind ControlNotificationKind,
) (generatedControlNotificationDefinition, bool) {
	for _, definition := range generatedControlNotificationDefinitions {
		if definition.kind == kind {
			return definition, true
		}
	}
	return generatedControlNotificationDefinition{}, false
}

func parseControlNotificationArguments(
	record string,
	position int,
	definition generatedControlNotificationDefinition,
) ([]string, error) {
	arguments := make([]string, 0, definition.prefixArguments+1)
	for range definition.prefixArguments {
		if position == len(record) {
			return nil, malformedControlNotification(position, "required argument is missing")
		}
		if record[position] != ' ' {
			return nil, malformedControlNotification(position, "argument delimiter is missing")
		}
		position++
		if position == len(record) || record[position] == ' ' {
			return nil, malformedControlNotification(position, "required argument is empty")
		}
		end := strings.IndexByte(record[position:], ' ')
		if end < 0 {
			end = len(record)
		} else {
			end += position
		}
		arguments = append(arguments, record[position:end])
		position = end
	}

	switch definition.tail {
	case generatedControlNotificationTailNone:
		if position != len(record) {
			return nil, malformedControlNotification(position, "record has unexpected trailing data")
		}
	case generatedControlNotificationTailRequired:
		var err error
		arguments, err = appendControlNotificationTail(
			record,
			position,
			arguments,
			definition.allowEmptyTail,
			false,
		)
		if err != nil {
			return nil, err
		}
	case generatedControlNotificationTailOptional:
		if position != len(record) {
			var err error
			arguments, err = appendControlNotificationTail(
				record,
				position,
				arguments,
				definition.allowEmptyTail,
				true,
			)
			if err != nil {
				return nil, err
			}
		}
	case generatedControlNotificationTailColon:
		var err error
		arguments, err = appendColonControlNotificationTail(
			record,
			position,
			arguments,
			definition.allowEmptyTail,
		)
		if err != nil {
			return nil, err
		}
	default:
		return nil, malformedControlNotification(position, "notification definition is invalid")
	}
	return arguments, nil
}

func appendControlNotificationTail(
	record string,
	position int,
	arguments []string,
	allowEmpty bool,
	optional bool,
) ([]string, error) {
	if position == len(record) {
		if optional {
			return arguments, nil
		}
		return nil, malformedControlNotification(position, "required tail is missing")
	}
	if record[position] != ' ' {
		return nil, malformedControlNotification(position, "tail delimiter is missing")
	}
	tail := record[position+1:]
	if tail == "" && !allowEmpty {
		return nil, malformedControlNotification(position+1, "tail is empty")
	}
	return append(arguments, tail), nil
}

func appendColonControlNotificationTail(
	record string,
	position int,
	arguments []string,
	allowEmpty bool,
) ([]string, error) {
	separatorOffset := strings.Index(record[position:], " : ")
	if separatorOffset < 0 {
		return nil, malformedControlNotification(position, "colon tail delimiter is missing")
	}
	separator := position + separatorOffset
	if separator != position {
		futureArguments := record[position:separator]
		if futureArguments[0] != ' ' {
			return nil, malformedControlNotification(position, "argument delimiter is missing")
		}
		for argument := range strings.SplitSeq(futureArguments[1:], " ") {
			if argument == "" {
				return nil, malformedControlNotification(position, "future argument is empty")
			}
			arguments = append(arguments, argument)
		}
	}
	tail := record[separator+3:]
	if tail == "" && !allowEmpty {
		return nil, malformedControlNotification(separator+3, "tail is empty")
	}
	return append(arguments, tail), nil
}

func malformedControlNotification(offset int, reason string) error {
	return &ControlNotificationError{
		Offset:   offset,
		Reason:   reason,
		Category: ErrMalformedControlNotification,
	}
}

tmux/control_observation.go.content:
package tmux

import (
	"context"
	"crypto/rand"
	"errors"
	"fmt"
	"io"
	"iter"
	"os"
	"path/filepath"
	"slices"
	"strings"

	"github.com/libtmux/libtmux-go/tmux/internal/tmuxcmd"
)

// ErrPaneObservationLost identifies a pane observation whose control client
// can no longer receive every byte after its baseline. Stream failures that
// wrap it also preserve their underlying cause.
var ErrPaneObservationLost = errors.New("tmux: pane observation lost")

// PaneObservation is one visible pane baseline followed by the exact control
// notification stream after that baseline. That stream is the observation's
// whole control connection, so a caller wanting only this pane's output selects
// it by identifier. Create one with [Pane.OpenObservation] and close it when
// finished. Copies share notification
// reader ownership, terminal loss, and client lifetime; closing one closes them
// all.
type PaneObservation struct {
	client    *ControlClient
	paneID    PaneID
	windowID  WindowID
	sessionID SessionID
	after     uint64
	baseline  []string
	state     *paneObservationState
}

type paneObservationState struct {
	readToken chan struct{}
	loss      error
	// exitReason is what tmux said as it ended the stream, kept so the loss
	// that follows names a cause instead of a bare EOF.
	exitReason string
}

func newPaneObservationState() *paneObservationState {
	state := &paneObservationState{readToken: make(chan struct{}, 1)}
	state.releaseReadToken()
	return state
}

// PaneID returns the pane selected at the observation boundary.
func (o *PaneObservation) PaneID() PaneID {
	if o == nil {
		return ""
	}
	return o.paneID
}

// SessionID returns the session the observation's own control client
// attached to, resolved live when the observation opened - the session a
// listing must count this client's attachment against, not merely the
// pane's session at some other, possibly stale, snapshot.
func (o *PaneObservation) SessionID() SessionID {
	if o == nil {
		return ""
	}
	return o.sessionID
}

// ClientName returns the observation's own control client identity - the
// name a listing of attached clients must exclude, the same way it already
// excludes a caller's long-lived command connection, so a caller's own
// stream never reads as another person watching.
func (o *PaneObservation) ClientName() ClientName {
	if o == nil || o.client == nil {
		return ""
	}
	return o.client.ClientName()
}

// Baseline returns an owned copy of the pane's visible text at the observation
// boundary.
func (o *PaneObservation) Baseline() []string {
	if o == nil {
		return nil
	}
	return slices.Clone(o.baseline)
}

// NextNotification returns the next notification strictly after the pane
// baseline, from the whole connection rather than this pane alone.
// Notifications queued before that boundary are discarded.
// Concurrent calls are serialized. Caller context errors and
// [ControlNotificationError] affect only one call. Explicit close returns an
// error matching [ErrControlClosed] and [os.ErrClosed].
//
// Topology loss, natural stream EOF, and terminal reader errors return
// [ErrPaneObservationLost]. Stream failures preserve their cause. Later calls
// return that loss without consuming more notifications.
func (o *PaneObservation) NextNotification(
	ctx context.Context,
) (ControlNotification, error) {
	if o == nil || o.client == nil {
		return ControlNotification{}, ErrControlClosed
	}
	state := o.state
	if state == nil {
		return ControlNotification{}, ErrControlClosed
	}
	if err := state.acquireReadToken(ctx); err != nil {
		return ControlNotification{}, err
	}
	defer state.releaseReadToken()
	notification, _, err := o.read(ctx, true)
	return notification, err
}

// read returns the next notification after the baseline, applying the loss
// rules NextNotification documents. The caller holds the read token. With
// block false it returns ok false at once when nothing is queued.
func (o *PaneObservation) read(
	ctx context.Context,
	block bool,
) (_ ControlNotification, ok bool, _ error) {
	state := o.state
	if state.loss != nil {
		return ControlNotification{}, false, state.loss
	}
	var notification ControlNotification
	var err error
	if block {
		notification, err = o.client.nextNotificationAfter(ctx, o.after)
	} else {
		notification, ok, err = o.client.readyNotificationAfter(o.after)
		if err == nil && !ok {
			return ControlNotification{}, false, nil
		}
	}
	if err != nil {
		return ControlNotification{}, false, state.classifyReadError(
			ctx,
			err,
			o.client.closeRequested.Load(),
		)
	}
	arguments := notification.Arguments()
	if notification.Kind() == ControlNotificationUnlinkedWindowClose &&
		len(arguments) != 0 && WindowID(arguments[0]) == o.windowID {
		state.loss = fmt.Errorf(
			"%w: observed window is no longer linked into the attached session",
			ErrPaneObservationLost,
		)
		return ControlNotification{}, false, state.loss
	}
	// %window-close for the observed window is ambiguous rather than a direct
	// signal: tmux emits it to every client whose own attached session still
	// lists the window, regardless of which session the unlink actually
	// happened on - so it fires both when the attached session itself just
	// lost the window (before tmux 3.8 that case reported
	// %unlinked-window-close instead; the events rewrite since fires this
	// notification while the winlink removal it reflects is still pending,
	// so it reports the state from just before the unlink) and whenever some
	// other, unrelated session drops a window this one still holds. A live
	// membership check resolves which case this is.
	if notification.Kind() == ControlNotificationWindowClose &&
		len(arguments) != 0 && WindowID(arguments[0]) == o.windowID {
		linked, err := o.windowLinkedIntoAttachedSession(ctx)
		if err != nil {
			return ControlNotification{}, false, state.classifyReadError(
				ctx,
				err,
				o.client.closeRequested.Load(),
			)
		}
		if !linked {
			state.loss = fmt.Errorf(
				"%w: observed window is no longer linked into the attached session",
				ErrPaneObservationLost,
			)
			return ControlNotification{}, false, state.loss
		}
	}
	if notification.Kind() == ControlNotificationSessionChanged &&
		len(arguments) != 0 && SessionID(arguments[0]) != o.sessionID {
		state.loss = fmt.Errorf(
			"%w: control client changed sessions",
			ErrPaneObservationLost,
		)
		return ControlNotification{}, false, state.loss
	}
	if notification.Kind() == ControlNotificationExit && len(arguments) != 0 {
		state.exitReason = arguments[0]
	}
	// tmux has no pane-close notification: a pane that ends while its window
	// survives is only visible as the window's new arrangement, which no longer
	// lists it.
	if notification.Kind() == ControlNotificationLayoutChange &&
		len(arguments) > 1 && WindowID(arguments[0]) == o.windowID &&
		!layoutListsPane(arguments[1], o.paneID) {
		state.loss = fmt.Errorf(
			"%w: the observed pane left its window's arrangement",
			ErrPaneObservationLost,
		)
		return ControlNotification{}, false, state.loss
	}
	return notification, true, nil
}

// windowLinkedIntoAttachedSession reports whether the observed window is
// still linked into the observation's attached session, straight from tmux.
func (o *PaneObservation) windowLinkedIntoAttachedSession(ctx context.Context) (bool, error) {
	result, err := o.client.Cmd(
		ctx, "list-windows", "-t", o.sessionID.String(), "-F", "#{window_id}",
	)
	if err != nil {
		return false, err
	}
	if result.Failed {
		return false, failedPaneObservationCommand("list attached-session windows", result)
	}
	return slices.Contains(tmuxcmd.SplitStdout(result.RawStdout), o.windowID.String()), nil
}

func (s *paneObservationState) acquireReadToken(ctx context.Context) error {
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-s.readToken:
		if err := ctx.Err(); err != nil {
			s.releaseReadToken()
			return err
		}
		return nil
	}
}

func (s *paneObservationState) releaseReadToken() {
	s.readToken <- struct{}{}
}

func (s *paneObservationState) classifyReadError(
	ctx context.Context,
	err error,
	closeRequested bool,
) error {
	if ctxErr := ctx.Err(); ctxErr != nil && errors.Is(err, ctxErr) {
		return err
	}
	if errors.Is(err, os.ErrClosed) {
		return err
	}
	if _, ok := errors.AsType[*ControlNotificationError](err); ok {
		return err
	}
	if closeRequested {
		return errControlNotificationsClosed
	}
	if s.exitReason != "" {
		s.loss = fmt.Errorf("%w: server ended the stream: %s: %w",
			ErrPaneObservationLost, s.exitReason, err)
		return s.loss
	}
	s.loss = fmt.Errorf("%w: %w", ErrPaneObservationLost, err)
	return s.loss
}

// Close stops the dedicated control client. It is safe to call more than once.
func (o *PaneObservation) Close() error {
	if o == nil || o.client == nil {
		return nil
	}
	return o.client.Close()
}

// CloseContext starts idempotent observation shutdown and waits within ctx.
func (o *PaneObservation) CloseContext(ctx context.Context) error {
	if o == nil || o.client == nil {
		return nil
	}
	return o.client.CloseContext(ctx)
}

// OpenObservation captures the pane's visible text and returns an owned
// observation whose notifications begin at the capture's exact control-wire
// boundary. It resolves the pane's exact linked session before opening a
// dedicated control client. The caller must close the result.
func (p Pane) OpenObservation(
	ctx context.Context,
) (*PaneObservation, error) {
	session, err := p.ResolveSession(ctx)
	if err != nil {
		return nil, err
	}
	client, err := p.server.OpenControl(ctx, session)
	if err != nil {
		return nil, err
	}
	// The client is this observation's alone, so the rest of the session's
	// output is nothing it needs to hold.
	paneID := p.ID().String()
	client.outputFrom.Store(&paneID)
	observation, err := client.observePane(ctx, p)
	if err != nil {
		return nil, errors.Join(err, client.CloseContext(ctx))
	}
	return observation, nil
}

// observePane stages the capture through an ephemeral, uniquely named tmux
// buffer because printed pane content can imitate control protocol guards.
//
// The pane must select the control client's server. The returned observation
// borrows the client; closing the client ends its notification stream.
func (c *ControlClient) observePane(
	ctx context.Context,
	pane Pane,
) (*PaneObservation, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if pane.ID() == "" {
		return nil, invalidServerCommandRequest(
			"observe-pane", "Pane", "", "must have a materialized pane ID",
		)
	}
	if !pane.Server().Equal(c.server) {
		return nil, invalidServerCommandRequest(
			"observe-pane", "Pane", "[redacted]", "belongs to a different server selector",
		)
	}
	if pane.server.daemon != nil && c.server.daemon != nil &&
		!sameSnapshotIdentity(*pane.server.daemon, *c.server.daemon) {
		return nil, ErrDaemonReplaced
	}

	directory, err := os.MkdirTemp("", "libtmux-go-observe-")
	if err != nil {
		return nil, fmt.Errorf("create pane observation directory: %w", err)
	}
	path := filepath.Join(directory, "pane")
	defer func() {
		_ = os.Remove(path)
		_ = os.Remove(directory)
	}()

	buffer := "libtmux-go-observe-" + rand.Text()
	results, err := c.cmd(
		ctx,
		true,
		"refresh-client", "-A", pane.ID().String()+":on", ";",
		"list-windows", "-t", c.session.ID().String(), "-F", "#{window_id}", ";",
		"capture-pane", "-b", buffer, "-t", pane.ID().String(), ";",
		"save-buffer", "-b", buffer, "--", path, ";",
		"delete-buffer", "-b", buffer,
	)
	if err != nil {
		return nil, errors.Join(
			fmt.Errorf("stage pane observation: %w", err),
			c.cleanupObservationBuffer(buffer),
		)
	}
	actions := []string{
		"enable pane observation output",
		"list attached-session windows",
		"capture pane observation",
		"save pane observation",
		"delete pane observation buffer",
	}
	for index, action := range actions[:min(len(results), len(actions))] {
		if results[index].Failed {
			failure := failedPaneObservationCommand(action, results[index])
			if index <= 2 {
				return nil, failure
			}
			return nil, errors.Join(
				failure,
				c.cleanupObservationBuffer(buffer),
			)
		}
	}
	if len(results) != len(actions) {
		var cleanupErr error
		if len(results) > 2 && !results[2].Failed {
			cleanupErr = c.cleanupObservationBuffer(buffer)
		}
		return nil, errors.Join(
			fmt.Errorf(
				"stage pane observation: got %d command results, want %d",
				len(results), len(actions),
			),
			cleanupErr,
		)
	}
	if !slices.Contains(
		tmuxcmd.SplitStdout(results[1].RawStdout),
		pane.WindowID().String(),
	) {
		return nil, invalidServerCommandRequest(
			"observe-pane",
			"Pane",
			"[redacted]",
			"window is not linked into the control client's attached session",
		)
	}
	contents, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read pane observation: %w", err)
	}
	return &PaneObservation{
		client:    c,
		paneID:    pane.ID(),
		windowID:  pane.WindowID(),
		sessionID: c.session.ID(),
		after:     results[2].notificationSequence,
		baseline:  tmuxcmd.SplitStdout(contents),
		state:     newPaneObservationState(),
	}, nil
}

func (c *ControlClient) cleanupObservationBuffer(buffer string) error {
	ctx, cancel := context.WithTimeout(
		context.Background(),
		controlClientStopGrace,
	)
	defer cancel()
	if err := c.server.DeleteBuffer(ctx, &buffer); err != nil {
		return fmt.Errorf("clean pane observation buffer: %w", err)
	}
	return nil
}

func failedPaneObservationCommand(
	action string,
	result ControlCommandResult,
) error {
	detail := strings.TrimSpace(string(result.RawStdout))
	if detail == "" {
		detail = "tmux rejected the command"
	}
	return fmt.Errorf("%s: %s", action, detail)
}

// Reader returns the pane's output after the baseline as a byte stream: what
// the program in the pane writes to its terminal, in order, and nothing from
// any other pane on the connection. Reads block until the pane writes, ctx
// ends, or the observation closes. A lost observation ends the stream with
// [ErrPaneObservationLost] rather than [io.EOF]. The bytes are the terminal's:
// escape sequences and carriage returns arrive as written, and the echo of
// what is typed into the pane arrives before the reply, as it does on screen.
// Exactly one reader or direct notification read may run at a time.
//
// A malformed notification on the connection is skipped, as
// [PaneObservation.Notifications] skips it; every other error ends the stream.
func (o *PaneObservation) Reader(ctx context.Context) io.Reader {
	return &paneOutputReader{ctx: ctx, observation: o}
}

type paneOutputReader struct {
	ctx         context.Context
	observation *PaneObservation
	pending     []byte
}

func (r *paneOutputReader) Read(p []byte) (int, error) {
	if len(p) == 0 {
		return 0, nil
	}
	for len(r.pending) == 0 {
		notification, err := r.observation.NextNotification(r.ctx)
		if err != nil {
			if _, unreadable := errors.AsType[*ControlNotificationError](err); unreadable {
				continue
			}
			return 0, err
		}
		pane, output, ok := notification.Output()
		if !ok || pane != r.observation.paneID {
			continue
		}
		r.pending = output
	}
	n := copy(p, r.pending)
	r.pending = r.pending[n:]
	return n, nil
}

// Notifications returns [PaneObservation.NextNotification] as a range loop;
// exactly one iterator or direct read may run at a time. Malformed
// notifications yield their error and iteration continues; every other error
// ends the loop after being yielded.
func (o *PaneObservation) Notifications(
	ctx context.Context,
) iter.Seq2[ControlNotification, error] {
	return notificationSeq(ctx, o.NextNotification)
}

tmux/control_protocol.go.content:
package tmux

import (
	"bytes"
	"errors"
	"fmt"
	"slices"
	"strconv"
	"strings"
	"sync"
)

// ErrControlProtocol identifies malformed tmux control-mode framing.
var ErrControlProtocol = errors.New("tmux: malformed control protocol")

// ControlProtocolError reports a control-stream state violation without
// retaining or disclosing command output or notification contents. It matches
// [ErrControlProtocol] through errors.Is.
type ControlProtocolError struct {
	// State is the parser state in which the violation occurred.
	State string
	// Reason describes the structural violation without quoting input.
	Reason string
}

// Error implements error.
func (e *ControlProtocolError) Error() string {
	return fmt.Sprintf("%v in %s state: %s", ErrControlProtocol, e.State, e.Reason)
}

// Unwrap makes ControlProtocolError compatible with ErrControlProtocol.
func (e *ControlProtocolError) Unwrap() error { return ErrControlProtocol }

// ControlCommandResult is one completed control-mode command frame. A failed
// tmux command remains result data through Failed; local, protocol, transport,
// and context failures are returned separately by [Connection.Call],
// [ControlClient.Cmd], and [ControlClient.Call]. All slices are owned by the
// caller.
type ControlCommandResult struct {
	// Command is the safely encoded command's original argument vector.
	Command []string
	// RawStdout contains exact frame payload bytes, including each line's LF.
	RawStdout []byte
	// Timestamp is tmux's frame timestamp in Unix seconds.
	Timestamp int64
	// Number is tmux's command number for the frame. tmux counts commands the
	// server processed rather than commands this client sent, so a command from
	// any other client advances it too and the gap between two frames is not a
	// count of this client's work.
	Number uint64
	// Flags contains tmux's frame flags.
	Flags int
	// Failed reports whether tmux closed the frame with %error instead of %end.
	Failed bool

	// notificationSequence is the control-wire position of this frame's
	// closing guard. It remains private because only an observation created by
	// the originating client can use the position safely.
	notificationSequence uint64
}

type controlGuardKind uint8

const (
	controlGuardNone controlGuardKind = iota
	controlGuardBegin
	controlGuardEnd
	controlGuardError
)

type controlGuard struct {
	timestamp int64
	number    uint64
	flags     int
}

type controlFrame struct {
	timestamp    int64
	number       uint64
	flags        int
	rawStdout    []byte
	failed       bool
	wireSequence uint64

	// fence marks the reply to a capture request's fence command, and
	// captured holds the lines that came before it.
	fence    bool
	captured [][]byte
}

func (f controlFrame) result(command []string) ControlCommandResult {
	return ControlCommandResult{
		Command:              slices.Clone(command),
		RawStdout:            bytes.Clone(f.rawStdout),
		Timestamp:            f.timestamp,
		Number:               f.number,
		Flags:                f.flags,
		Failed:               f.failed,
		notificationSequence: f.wireSequence,
	}
}

type controlStreamParser struct {
	guard  *controlGuard
	output bytes.Buffer

	mu      sync.Mutex
	capture *controlCapture
}

// controlCapture holds the lines tmux prints between a command's reply frame
// and a fence of the caller's making. A foreground run-shell is answered with
// an empty frame at once; its output follows later as bare lines outside any
// frame, and nothing on the wire ends it. The fence is a command sent behind
// it whose reply holds a nonce only the caller knows, and tmux runs it only
// when the shell command is done, so what lies before it is the output.
//
// Those lines are the shell command's text, not tmux's protocol: one that
// reads like a guard is just a line. They are kept apart from the parser's
// framing until the fence proves where they end.
type controlCapture struct {
	nonce string
	// started is set once the command's own reply frame has closed.
	started bool
	// fencing is set once the fence's opening guard has been recognized.
	fencing bool
	lines   [][]byte
}

// arm makes the parser capture what follows the next reply frame, up to the
// fence frame that holds nonce. Call it before writing the command.
func (p *controlStreamParser) arm(nonce string) {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.capture = &controlCapture{nonce: nonce}
}

func (p *controlStreamParser) activeCapture() *controlCapture {
	p.mu.Lock()
	defer p.mu.Unlock()
	return p.capture
}

func (p *controlStreamParser) disarm() {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.capture = nil
}

func (p *controlStreamParser) consume(
	line []byte,
) (*controlFrame, []byte, error) {
	capture := p.activeCapture()
	if capture == nil {
		return p.consumeFramed(line)
	}
	if capture.started && !capture.fencing {
		return p.consumeCaptured(capture, line)
	}
	frame, notification, err := p.consumeFramed(line)
	if frame != nil {
		switch {
		case capture.fencing:
			frame.fence = true
			frame.captured = capture.lines
			p.disarm()
		case frame.ownReply():
			capture.started = true
		}
	}
	return frame, notification, err
}

// consumeCaptured takes one line after the command's reply. Only a
// well-formed notification is tmux's; every other line is the command's
// output, whatever it looks like, until the fence arrives.
func (p *controlStreamParser) consumeCaptured(
	capture *controlCapture,
	line []byte,
) (*controlFrame, []byte, error) {
	if string(line) == capture.nonce && len(capture.lines) != 0 {
		last := len(capture.lines) - 1
		if kind, guard, isGuard, err := parseControlGuard(capture.lines[last]); err == nil &&
			isGuard && kind == controlGuardBegin {
			capture.lines = capture.lines[:last]
			capture.fencing = true
			p.guard = &guard
			p.output.Reset()
			_, _ = p.output.Write(line)
			_ = p.output.WriteByte('\n')
			return nil, nil, nil
		}
	}
	if _, err := ParseControlNotification(line); err == nil {
		return nil, bytes.Clone(line), nil
	}
	capture.lines = append(capture.lines, bytes.Clone(line))
	return nil, nil, nil
}

func (p *controlStreamParser) consumeFramed(
	line []byte,
) (*controlFrame, []byte, error) {
	kind, guard, isGuard, err := parseControlGuard(line)
	if p.guard != nil {
		if err == nil && isGuard && guard == *p.guard &&
			(kind == controlGuardEnd || kind == controlGuardError) {
			frame := &controlFrame{
				timestamp: p.guard.timestamp,
				number:    p.guard.number,
				flags:     p.guard.flags,
				rawStdout: bytes.Clone(p.output.Bytes()),
				failed:    kind == controlGuardError,
			}
			p.guard = nil
			p.output.Reset()
			return frame, nil, nil
		}
		_, _ = p.output.Write(line)
		_ = p.output.WriteByte('\n')
		return nil, nil, nil
	}
	if err != nil {
		return nil, nil, err
	}

	if isGuard {
		if kind != controlGuardBegin {
			return nil, nil, controlProtocolError("idle", "closing guard has no active frame")
		}
		p.guard = &guard
		return nil, nil, nil
	}
	if len(line) == 0 || line[0] != '%' {
		return nil, nil, controlProtocolError("idle", "record is neither a begin guard nor notification")
	}
	return nil, bytes.Clone(line), nil
}

func (p *controlStreamParser) finish() error {
	if p.guard != nil {
		return controlProtocolError("frame", "stream ended before closing guard")
	}
	return nil
}

func parseControlGuard(
	line []byte,
) (controlGuardKind, controlGuard, bool, error) {
	record := string(line)
	var kind controlGuardKind
	switch {
	case record == "%begin" || strings.HasPrefix(record, "%begin "):
		kind = controlGuardBegin
	case record == "%end" || strings.HasPrefix(record, "%end "):
		kind = controlGuardEnd
	case record == "%error" || strings.HasPrefix(record, "%error "):
		kind = controlGuardError
	default:
		return controlGuardNone, controlGuard{}, false, nil
	}

	fields := strings.Split(record, " ")
	if len(fields) != 4 {
		return controlGuardNone, controlGuard{}, false,
			controlProtocolError("guard", "guard must contain three numeric fields")
	}
	timestamp, err := strconv.ParseInt(fields[1], 10, 64)
	if err != nil || timestamp < 0 {
		return controlGuardNone, controlGuard{}, false,
			controlProtocolError("guard", "timestamp is not a nonnegative integer")
	}
	number, err := strconv.ParseUint(fields[2], 10, 64)
	if err != nil {
		return controlGuardNone, controlGuard{}, false,
			controlProtocolError("guard", "command number is not a nonnegative integer")
	}
	flags, err := strconv.ParseInt(fields[3], 10, strconv.IntSize)
	if err != nil || flags < 0 {
		return controlGuardNone, controlGuard{}, false,
			controlProtocolError("guard", "flags are not a nonnegative integer")
	}
	return kind, controlGuard{
		timestamp: timestamp,
		number:    number,
		flags:     int(flags),
	}, true, nil
}

// encodeControlCommand quotes every value. A bare semicolon is emitted only for
// command lists; quoting it makes it an operand, and send-keys may type the
// remaining commands into a pane.
func encodeControlCommand(arguments []string, commandList bool) (string, error) {
	if len(arguments) == 0 || arguments[0] == "" {
		return "", invalidServerCommandRequest(
			"control", "Command", "", "must not be empty",
		)
	}
	var encoded strings.Builder
	for argumentIndex, argument := range arguments {
		if strings.IndexByte(argument, 0) >= 0 {
			return "", invalidServerCommandRequest(
				"control", "Arguments", "[redacted]", "contains NUL, which tmux cannot represent",
			)
		}
		if argumentIndex != 0 {
			_ = encoded.WriteByte(' ')
		}
		if commandList && argument == ";" {
			_ = encoded.WriteByte(';')
			continue
		}
		if argument == "" {
			_, _ = encoded.WriteString("''")
			continue
		}
		quoted := false
		for offset := range len(argument) {
			value := argument[offset]
			if value >= 0x20 && value <= 0x7e && value != '\'' {
				if !quoted {
					_ = encoded.WriteByte('\'')
					quoted = true
				}
				_ = encoded.WriteByte(value)
				continue
			}
			if quoted {
				_ = encoded.WriteByte('\'')
				quoted = false
			}
			if value == '\'' {
				_, _ = encoded.WriteString(`"'"`)
			} else {
				_, _ = fmt.Fprintf(&encoded, `\%03o`, value)
			}
		}
		if quoted {
			_ = encoded.WriteByte('\'')
		}
	}
	return encoded.String(), nil
}

func controlProtocolError(state, reason string) error {
	return &ControlProtocolError{State: state, Reason: reason}
}

tmux/control_request.go.content:
package tmux

import (
	"context"
	"crypto/rand"
	"errors"
	"fmt"
	"io"
	"slices"
	"sync/atomic"
	"time"
)

const (
	// Two distinct parser failures delimit a request whose alias may produce
	// any number of frames. Startup records tmux's version-specific replies.
	controlReplyFenceInput = "\\400\n\\uZZZZ\n"
)

type controlRequest struct {
	ctx context.Context
	// command is the request's original argument vector.
	command   []string
	line      string
	fenceOnly bool
	// nonce, when set, makes this a capture request: a fence command holding
	// nonce is sent behind the command, and the lines tmux prints before it
	// are the command's output. shellOutput says those lines are a shell
	// command's stdout, where otherwise they are tmux's own error text.
	nonce       string
	shellOutput bool
	response    chan controlResponse
	state       atomic.Uint32
}

type controlResponse struct {
	results []ControlCommandResult
	err     error
}

type controlRequestState uint32

const (
	controlRequestPending controlRequestState = iota
	controlRequestAccepted
	controlRequestWriting
	controlRequestFinished
	controlRequestCanceled
)

type controlFrameFingerprint struct {
	flags     int
	rawStdout string
}

func (f controlFrameFingerprint) matches(frame controlFrame) bool {
	return frame.failed && frame.flags == f.flags && string(frame.rawStdout) == f.rawStdout
}

type controlReplyFence struct {
	first  controlFrameFingerprint
	second controlFrameFingerprint
}

func newControlReplyFence(first, second controlFrame) (controlReplyFence, error) {
	if !first.failed || !second.failed || !first.ownReply() || !second.ownReply() {
		return controlReplyFence{}, errors.New("control reply fence calibration did not fail")
	}
	fence := controlReplyFence{
		first:  controlFrameFingerprint{flags: first.flags, rawStdout: string(first.rawStdout)},
		second: controlFrameFingerprint{flags: second.flags, rawStdout: string(second.rawStdout)},
	}
	if fence.first == fence.second {
		return controlReplyFence{}, errors.New("control reply fence calibration is not distinct")
	}
	return fence, nil
}

type outcomeUnknownError struct {
	cause error
}

func (e *outcomeUnknownError) Error() string {
	return ErrOutcomeUnknown.Error() + ": " + e.cause.Error()
}

func (e *outcomeUnknownError) Unwrap() []error {
	return []error{ErrOutcomeUnknown, e.cause}
}

func outcomeUnknown(cause error) error {
	if cause == nil {
		return ErrOutcomeUnknown
	}
	return &outcomeUnknownError{cause: cause}
}

// Cmd executes one safely encoded tmux command through the control client. It
// requires exactly one reply frame and returns [ErrControlReplyCount]
// otherwise. Use [ControlClient.Call] for aliases that may produce zero or
// multiple frames.
func (c *ControlClient) Cmd(
	ctx context.Context,
	args ...string,
) (ControlCommandResult, error) {
	results, err := c.Call(ctx, args...)
	if err != nil {
		return ControlCommandResult{}, err
	}
	if len(results) != 1 {
		return ControlCommandResult{}, fmt.Errorf(
			"%w: got %d; use ControlClient.Call",
			ErrControlReplyCount,
			len(results),
		)
	}
	return results[0], nil
}

// Call executes one safely encoded tmux command and returns all its reply
// frames. Cancellation after writing returns [ErrOutcomeUnknown] with the
// context error while the client drains through the boundary before reuse. A
// transport failure returns any frames proven before the failure together with
// [ErrOutcomeUnknown].
func (c *ControlClient) Call(
	ctx context.Context,
	args ...string,
) ([]ControlCommandResult, error) {
	return c.cmd(ctx, false, args...)
}

// cmd returns one result per executed command in a command list. A failed list
// includes the failure and omits commands tmux dropped after it.
// cmd observes what it runs. A caller already observing the command it drives
// uses cmdUnobserved instead, so one command produces one trace.
func (c *ControlClient) cmd(
	ctx context.Context,
	commandList bool,
	args ...string,
) (results []ControlCommandResult, err error) {
	if observer := c.server.commandObserver(); observer != nil {
		started := time.Now()
		defer func() {
			observeCommand(observer, args, started, CommandTransportConnection,
				controlExitCode(results, err), err)
		}()
	}
	return c.cmdUnobserved(ctx, commandList, args...)
}

func (c *ControlClient) cmdUnobserved(
	ctx context.Context,
	commandList bool,
	args ...string,
) ([]ControlCommandResult, error) {
	return c.cmdWith(ctx, commandList, "", false, args...)
}

// cmdCaptured is cmdUnobserved for a command that can print after its reply
// frame, as a foreground run-shell or if-shell does. The lines it prints come
// back as results, never as protocol; see [controlCapture]. shellOutput says
// the command prints a shell command's stdout.
func (c *ControlClient) cmdCaptured(
	ctx context.Context,
	commandList bool,
	shellOutput bool,
	args ...string,
) ([]ControlCommandResult, error) {
	return c.cmdWith(ctx, commandList, rand.Text(), shellOutput, args...)
}

func (c *ControlClient) cmdWith(
	ctx context.Context,
	commandList bool,
	nonce string,
	shellOutput bool,
	args ...string,
) ([]ControlCommandResult, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	command := slices.Clone(args)
	line, err := encodeControlCommand(command, commandList)
	if err != nil {
		return nil, err
	}
	request := &controlRequest{
		ctx:         ctx,
		command:     command,
		line:        line,
		nonce:       nonce,
		shellOutput: shellOutput,
		response:    make(chan controlResponse, 1),
	}
	return c.submitControlRequest(request)
}

func (c *ControlClient) crossReplyFence(ctx context.Context) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	request := &controlRequest{
		ctx:       ctx,
		fenceOnly: true,
		response:  make(chan controlResponse, 1),
	}
	_, err := c.submitControlRequest(request)
	return err
}

func (c *ControlClient) submitControlRequest(request *controlRequest) ([]ControlCommandResult, error) {
	if c.closeRequested.Load() {
		return nil, ErrControlClosed
	}
	select {
	case c.requests <- request:
	case <-request.ctx.Done():
		return nil, request.ctx.Err()
	case <-c.requestDone:
		return nil, c.operationError()
	case <-c.stopRequests:
		return nil, ErrControlClosed
	}
	return request.await(request.ctx)
}

func (r *controlRequest) await(ctx context.Context) ([]ControlCommandResult, error) {
	select {
	case response := <-r.response:
		return response.results, response.err
	case <-ctx.Done():
		if r.cancelBeforeWrite() {
			return nil, ctx.Err()
		}
		if controlRequestState(r.state.Load()) == controlRequestFinished {
			response := <-r.response
			return response.results, response.err
		}
		return nil, outcomeUnknown(ctx.Err())
	}
}

func (r *controlRequest) cancelBeforeWrite() bool {
	for {
		state := controlRequestState(r.state.Load())
		if state != controlRequestPending && state != controlRequestAccepted {
			return state == controlRequestCanceled
		}
		if r.state.CompareAndSwap(uint32(state), uint32(controlRequestCanceled)) {
			return true
		}
	}
}

func (c *ControlClient) runRequests() {
	defer close(c.requestDone)
	for {
		select {
		case request := <-c.requests:
			if !request.state.CompareAndSwap(
				uint32(controlRequestPending),
				uint32(controlRequestAccepted),
			) {
				request.response <- controlResponse{err: request.ctx.Err()}
				continue
			}
			if c.closeRequested.Load() {
				request.state.Store(uint32(controlRequestFinished))
				request.response <- controlResponse{err: ErrControlClosed}
				return
			}
			response, keepRunning := c.executeControlRequest(request)
			request.response <- response
			if !keepRunning {
				return
			}
		case <-c.stopRequests:
			return
		}
	}
}

func (c *ControlClient) executeControlRequest(
	request *controlRequest,
) (controlResponse, bool) {
	if err := request.ctx.Err(); err != nil {
		request.state.Store(uint32(controlRequestCanceled))
		return controlResponse{err: err}, true
	}
	if !request.state.CompareAndSwap(
		uint32(controlRequestAccepted),
		uint32(controlRequestWriting),
	) {
		return controlResponse{err: request.ctx.Err()}, true
	}
	input := controlReplyFenceInput
	if !request.fenceOnly {
		input = request.line + "\n" + input
		if request.nonce != "" {
			// The nonce is letters and digits, so it needs no quoting.
			c.parser.arm(request.nonce)
			input = request.line + "\ndisplay-message -p " + request.nonce + "\n" +
				controlReplyFenceInput
		}
	}
	if _, err := io.WriteString(c.stdin, input); err != nil {
		return request.finish(
			controlResponse{err: outcomeUnknown(c.classifyOperationError(err))},
			false,
		)
	}
	results := make([]ControlCommandResult, 0, 1)
	// A request can itself fail with the first fence's fingerprint. Hold that
	// frame until the next one distinguishes request A,A,B from boundary A,B.
	var pendingFirst *controlFrame
	var captured [][]byte
	for {
		frame, err := c.nextOwnFrame(context.Background())
		if err != nil {
			return request.finish(
				controlResponse{results: results, err: outcomeUnknown(err)},
				false,
			)
		}
		if frame.fence {
			captured = frame.captured
			continue
		}
		if pendingFirst != nil {
			if c.replyFence.second.matches(frame) {
				results = append(results, request.capturedResults(captured)...)
				return request.finish(controlResponse{results: results}, true)
			}
			results = append(results, pendingFirst.result(request.command))
			pendingFirst = nil
		}
		if c.replyFence.first.matches(frame) {
			pendingFirst = &frame
			continue
		}
		results = append(results, frame.result(request.command))
	}
}

// capturedResults turns the lines a capture request collected into results.
// A shell command's output is stdout. Otherwise the lines are tmux's own error
// text, such as a branch that failed to parse, interleaved with the reply
// frames of commands the command inserted; lines that do not form a frame are
// errors.
func (r *controlRequest) capturedResults(lines [][]byte) []ControlCommandResult {
	if len(lines) == 0 {
		return nil
	}
	if r.shellOutput {
		return []ControlCommandResult{{
			Command:   slices.Clone(r.command),
			RawStdout: joinCapturedLines(lines),
		}}
	}
	var results []ControlCommandResult
	var bare, open [][]byte
	flush := func() {
		if len(bare) != 0 {
			results = append(results, ControlCommandResult{
				Command:   slices.Clone(r.command),
				RawStdout: joinCapturedLines(bare),
				Failed:    true,
			})
			bare = nil
		}
	}
	var parser controlStreamParser
	for _, line := range lines {
		if parser.guard == nil {
			kind, _, isGuard, err := parseControlGuard(line)
			if err != nil || !isGuard || kind != controlGuardBegin {
				bare = append(bare, line)
				continue
			}
		}
		open = append(open, line)
		frame, _, err := parser.consumeFramed(line)
		if err != nil {
			bare = append(bare, open...)
			open = nil
			parser = controlStreamParser{}
			continue
		}
		if frame != nil {
			flush()
			results = append(results, frame.result(r.command))
			open = nil
		}
	}
	// A frame that never closed is not a frame.
	bare = append(bare, open...)
	flush()
	return results
}

func joinCapturedLines(lines [][]byte) []byte {
	var joined []byte
	for _, line := range lines {
		joined = append(joined, line...)
		joined = append(joined, '\n')
	}
	return joined
}

func (r *controlRequest) finish(
	response controlResponse,
	keepRunning bool,
) (controlResponse, bool) {
	r.state.Store(uint32(controlRequestFinished))
	return response, keepRunning
}

func (c *ControlClient) calibrateReplyFence(ctx context.Context) error {
	if _, err := io.WriteString(c.stdin, controlReplyFenceInput); err != nil {
		return fmt.Errorf("calibrate control reply fence: %w", err)
	}
	first, err := c.nextOwnFrame(ctx)
	if err != nil {
		return fmt.Errorf("calibrate first control reply fence: %w", err)
	}
	second, err := c.nextOwnFrame(ctx)
	if err != nil {
		return fmt.Errorf("calibrate second control reply fence: %w", err)
	}
	fence, err := newControlReplyFence(first, second)
	if err != nil {
		return err
	}
	c.replyFence = fence
	return nil
}

// controlExitCode renders a control-mode outcome as the exit code a trace
// carries. tmux reports a failed command over control mode by closing its
// frame with %error rather than with a status, so a failed frame reads as 1
// and a local failure as the -1 that means no tmux command ran.
func controlExitCode(results []ControlCommandResult, err error) int {
	if err != nil {
		return -1
	}
	for _, result := range results {
		if result.Failed {
			return 1
		}
	}
	return 0
}

tmux/control_startup.go.content:
package tmux

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"slices"
	"strconv"
	"strings"
	"time"
)

const controlRegistrationPoll = 10 * time.Millisecond

type controlClientProfile uint8

const (
	controlCommands controlClientProfile = iota
	controlNotificationsNoPaneOutput
	controlNotificationsFull
)

func (profile controlClientProfile) retainsNotifications() bool {
	return profile == controlNotificationsNoPaneOutput ||
		profile == controlNotificationsFull
}

func (profile controlClientProfile) receivesPaneOutput() bool {
	return profile == controlNotificationsFull
}

// OpenControl starts a control-mode client attached to session. The startup
// context bounds process start, attach framing, and client registration but
// does not own the returned client's lifetime. Session must belong to the same
// configured server selector.
func (s Server) OpenControl(
	ctx context.Context,
	session Session,
) (*ControlClient, error) {
	return s.openControl(ctx, session, controlNotificationsFull)
}

func (s Server) openControl(
	ctx context.Context,
	session Session,
	profile controlClientProfile,
) (*ControlClient, error) {
	return s.openControlWithBacklog(ctx, session, profile, defaultControlNotificationLimit)
}

// openControlWithBacklog is openControl with the notification queue bound a
// retaining profile uses; command profiles retain none and ignore it.
func (s Server) openControlWithBacklog(
	ctx context.Context,
	session Session,
	profile controlClientProfile,
	backlog int,
) (*ControlClient, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if _, err := s.stateForUse(); err != nil {
		return nil, err
	}
	if session.ID() == "" {
		return nil, invalidServerCommandRequest(
			"control", "Session", "", "must have a materialized session ID",
		)
	}
	if !session.Server().Equal(s) {
		return nil, invalidServerCommandRequest(
			"control", "Session", "[redacted]", "belongs to a different server selector",
		)
	}
	if session.server.daemon != nil {
		if s.daemon != nil && !sameSnapshotIdentity(*s.daemon, *session.server.daemon) {
			return nil, ErrDaemonReplaced
		}
		s = s.withDaemon(*session.server.daemon)
	}
	if s.connection != nil {
		return nil, s.connection.routeError(ctx, commandProcess)
	}
	checked, err := s.checkCore(ctx, false)
	if err != nil {
		return nil, err
	}
	s = checked
	version, err := s.Version(ctx)
	if err != nil {
		return nil, err
	}

	attach := []string{"attach-session"}
	flags := (controlDialect{version: version}).clientFlags(profile)
	if len(flags) > 0 {
		attach = append(attach, "-f", strings.Join(flags, ","))
	}
	attach = append(attach, "-t", session.ID().String())
	attach, guard, err := s.guardCommand(attach, false)
	if err != nil {
		return nil, err
	}
	attach = append([]string{"-C"}, attach...)
	return s.startControlWithBacklog(
		ctx,
		session,
		profile,
		backlog,
		attach,
		func(client *ControlClient) error {
			return client.acceptAttach(ctx, guard)
		},
	)
}

// startControl owns process setup shared by existing-session attachment and
// first-session creation. accept consumes the startup command's frames and may
// replace the client's initially unknown server and session provenance.
func (s Server) startControl(
	ctx context.Context,
	session Session,
	profile controlClientProfile,
	startup []string,
	accept func(*ControlClient) error,
) (*ControlClient, error) {
	return s.startControlWithBacklog(
		ctx, session, profile, defaultControlNotificationLimit, startup, accept,
	)
}

func (s Server) startControlWithBacklog(
	ctx context.Context,
	session Session,
	profile controlClientProfile,
	backlog int,
	startup []string,
	accept func(*ControlClient) error,
) (*ControlClient, error) {
	state, err := s.stateForUse()
	if err != nil {
		return nil, err
	}

	var notifications *controlNotificationQueue
	if profile.retainsNotifications() {
		notifications = newControlNotificationQueue(backlog)
	}
	arguments := s.commandArguments(startup)
	if s.daemon != nil {
		arguments = append([]string{"-N"}, arguments...)
	}
	command := exec.Command(state.config.executable, arguments...)
	command.Env = slices.Clone(state.config.processEnvironment)
	command.Dir = state.config.directory
	command.WaitDelay = controlClientStopGrace
	stderr := &controlLockedBuffer{}
	command.Stderr = stderr
	stdin, err := command.StdinPipe()
	if err != nil {
		return nil, errors.Join(
			fmt.Errorf("open control stdin: %w", err),
			notifications.Close(),
		)
	}
	stdout, stdoutWriter, err := os.Pipe()
	if err != nil {
		return nil, errors.Join(
			fmt.Errorf("open control stdout: %w", err),
			stdin.Close(),
			notifications.Close(),
		)
	}
	command.Stdout = stdoutWriter
	client := &ControlClient{
		server:        s,
		session:       session,
		command:       command,
		stdin:         stdin,
		stdout:        stdout,
		stderr:        stderr,
		notifications: notifications,
		frames:        make(chan controlFrame, 1),
		requests:      make(chan *controlRequest),
		stopRequests:  make(chan struct{}),
		requestDone:   make(chan struct{}),
		closing:       make(chan struct{}),
		readDone:      make(chan struct{}),
		done:          make(chan struct{}),
		closeDone:     make(chan struct{}),
	}
	if err := command.Start(); err != nil {
		return nil, errors.Join(
			fmt.Errorf("start control process: %w", err),
			stdin.Close(),
			stdout.Close(),
			stdoutWriter.Close(),
			notifications.Close(),
		)
	}
	if err := stdoutWriter.Close(); err != nil {
		killErr := command.Process.Kill()
		if errors.Is(killErr, os.ErrProcessDone) {
			killErr = nil
		}
		return nil, errors.Join(
			fmt.Errorf("close parent control stdout writer: %w", err),
			killErr,
			command.Wait(),
			stdin.Close(),
			stdout.Close(),
			notifications.Close(),
		)
	}
	go client.waitProcess()
	go client.readStream()

	if err := accept(client); err != nil {
		return nil, client.failStartup(err)
	}
	client.stateMu.Lock()
	if client.currentSessionID == "" {
		client.currentSessionID = client.session.ID()
	}
	client.stateMu.Unlock()
	client.dispatching.Store(true)
	if err := client.calibrateReplyFence(ctx); err != nil {
		return nil, client.failStartup(err)
	}
	clientName, err := client.waitForRegistration(ctx)
	if err != nil {
		return nil, client.failStartup(err)
	}
	client.clientName = clientName
	go client.runRequests()
	return client, nil
}

func (c *ControlClient) acceptAttach(
	ctx context.Context,
	guard *daemonCommandGuard,
) error {
	frame, err := c.nextStartupFrame(ctx, guard)
	if err != nil {
		return err
	}
	if frame.failed {
		return fmt.Errorf(
			"control attach failed: %s",
			strings.TrimSpace(string(frame.rawStdout)),
		)
	}
	return nil
}

func (c *ControlClient) nextStartupFrame(
	ctx context.Context,
	guard *daemonCommandGuard,
) (controlFrame, error) {
	if guard != nil {
		// if-shell completes before the startup command it schedules.
		frame, err := c.nextFrame(ctx)
		if err != nil {
			return controlFrame{}, err
		}
		if frame.failed &&
			string(frame.rawStdout) == "unknown command: "+guard.failure+"\n" {
			return controlFrame{}, ErrDaemonReplaced
		}
		if frame.failed {
			return controlFrame{}, fmt.Errorf(
				"control startup guard failed: %s",
				strings.TrimSpace(string(frame.rawStdout)),
			)
		}
	}
	return c.nextFrame(ctx)
}

// Use a printable separator because tmux rewrites control characters for clients
// without a UTF-8 locale. Neither numeric PIDs nor client names contain it.
const registrationFormat = "#{client_pid}" + string(formatFieldSeparator) + "#{client_name}"

func (c *ControlClient) waitForRegistration(ctx context.Context) (ClientName, error) {
	pid := strconv.Itoa(c.command.Process.Pid)
	ticker := time.NewTicker(controlRegistrationPoll)
	defer ticker.Stop()
	for {
		result, err := c.server.Cmd(ctx, "list-clients", "-F", registrationFormat)
		if err != nil {
			return "", err
		}
		if result.ExitCode == 0 {
			for _, line := range result.Stdout {
				clientPID, clientName, ok := strings.Cut(line, string(formatFieldSeparator))
				if ok && clientPID == pid && strings.TrimSpace(clientName) != "" {
					return ClientName(strings.TrimSpace(clientName)), nil
				}
			}
		}
		select {
		case <-c.done:
			return "", c.registrationExitError()
		case <-ctx.Done():
			return "", ctx.Err()
		case <-ticker.C:
		}
	}
}

func (c *ControlClient) failStartup(err error) error {
	return errors.Join(err, c.Close())
}

tmux/control_stream.go.content:
package tmux

import (
	"bufio"
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"iter"
	"os"
)

// NextNotification returns the next ordered control-mode notification.
// Concurrent calls are serialized, as for [PaneObservation.NextNotification]:
// each notification goes to exactly one call, in order, and a call waiting its
// turn returns when ctx ends.
//
// Every end of the client matches [ErrControlClosed]. Close releases the queue
// and makes subsequent reads report an error matching both [ErrControlClosed]
// and [os.ErrClosed]. Natural process exit before a caller asked to close
// instead reports an error matching both [ErrControlClosed] and
// [ErrControlStreamLost] - most often because the server the underlying tmux
// client was attached to exited - naming the tmux exit reason when one was
// sent. A terminal reader error follows notifications queued before that
// failure. A full bounded queue likewise drains before reporting
// [ControlNotificationOverflowError], which does not match [ErrControlClosed]:
// the process is still running, and the caller decides to close it.
func (c *ControlClient) NextNotification(
	ctx context.Context,
) (ControlNotification, error) {
	if err := c.notifications.acquireReader(ctx); err != nil {
		return ControlNotification{}, err
	}
	defer c.notifications.releaseReader()
	notification, err := c.nextNotificationAfter(ctx, 0)
	if err == nil || !errors.Is(err, io.EOF) {
		return notification, err
	}
	if c.closeRequested.Load() {
		return ControlNotification{}, errControlNotificationsClosed
	}
	c.stateMu.Lock()
	reason := c.lastExitReason
	c.stateMu.Unlock()
	if reason != "" {
		return ControlNotification{}, fmt.Errorf(
			"%w: %w: tmux exited the client: %s: %w",
			ErrControlStreamLost, ErrControlClosed, reason, err,
		)
	}
	return ControlNotification{}, fmt.Errorf(
		"%w: %w: %w", ErrControlStreamLost, ErrControlClosed, err,
	)
}

func (c *ControlClient) nextNotificationAfter(
	ctx context.Context,
	sequence uint64,
) (ControlNotification, error) {
	record, err := c.notifications.next(ctx, sequence)
	if err != nil {
		return ControlNotification{}, err
	}
	return ParseControlNotification(record)
}

// readyNotificationAfter is nextNotificationAfter without the wait; ok is
// false when nothing is queued.
func (c *ControlClient) readyNotificationAfter(
	sequence uint64,
) (notification ControlNotification, ok bool, err error) {
	record, err := c.notifications.nextReady(sequence)
	if err != nil || record == nil {
		return ControlNotification{}, false, err
	}
	notification, err = ParseControlNotification(record)
	return notification, true, err
}

// Notifications returns an iterator over what tmux says without being asked:
// pane output, and the events behind [ControlNotification].
//
// It is [ControlClient.NextNotification] as a range loop. Reads from several
// iterators or direct calls are serialized, so a notification reaches one of
// them rather than all.
//
//	for notification, err := range client.Notifications(ctx) {
//		if err != nil {
//			return err
//		}
//		if pane, output, ok := notification.Output(); ok {
//			handle(pane, output)
//		}
//	}
//
// Malformed or unknown notifications yield their error and iteration continues.
// Every other error ends the stream after being yielded, including the
// [ErrControlStreamLost] or [os.ErrClosed] error [ControlClient.NextNotification]
// reports at a natural end, both of which match [ErrControlClosed].
//
// Leaving early preserves queued notifications for the next read.
func (c *ControlClient) Notifications(
	ctx context.Context,
) iter.Seq2[ControlNotification, error] {
	return notificationSeq(ctx, c.NextNotification)
}

// notificationSeq turns one blocking read into a range loop with the
// [ControlClient.Notifications] contract.
func notificationSeq(
	ctx context.Context,
	next func(context.Context) (ControlNotification, error),
) iter.Seq2[ControlNotification, error] {
	return func(yield func(ControlNotification, error) bool) {
		for {
			notification, err := next(ctx)
			// Identity, not errors.Is: a richly wrapped loss such as
			// ErrPaneObservationLost or ErrControlStreamLost can unwrap to
			// io.EOF too, and must still be yielded rather than silently
			// swallowed here. Only the bare sentinel itself means "clean end,
			// nothing more to report."
			if err == io.EOF { //nolint:errorlint // see comment above
				return
			}
			if !yield(notification, err) {
				return
			}
			var unreadable *ControlNotificationError
			if err != nil && !errors.As(err, &unreadable) {
				return
			}
		}
	}
}

func (c *ControlClient) readStream() {
	var finalErr error
	var wireSequence uint64
	parser := &c.parser
	reader := bufio.NewReader(c.stdout)
	defer func() {
		if finalErr == nil && !c.isClosing() {
			finalErr = parser.finish()
		}
		c.stateMu.Lock()
		c.readErr = finalErr
		c.stateMu.Unlock()
		c.notifications.finish(finalErr)
		close(c.frames)
		close(c.readDone)
		if finalErr != nil && !c.isClosing() {
			_ = c.command.Process.Kill()
		}
	}()

	for {
		line, err := reader.ReadBytes('\n')
		if len(line) != 0 {
			if line[len(line)-1] != '\n' {
				finalErr = controlProtocolError("stream", "record ended without LF")
				return
			}
			line = line[:len(line)-1]
			frame, notification, parseErr := parser.consume(line)
			if parseErr != nil {
				finalErr = parseErr
				return
			}
			if notification != nil {
				c.trackSessionChange(notification)
				c.trackExitReason(notification)
				wireSequence++
				if c.outputFromAnotherPane(notification) {
					continue
				}
				if appendErr := c.notifications.append(
					wireSequence,
					notification,
				); appendErr != nil {
					if errors.Is(appendErr, ErrControlNotificationOverflow) {
						continue
					}
					if c.isClosing() && errors.Is(appendErr, os.ErrClosed) {
						return
					}
					finalErr = appendErr
					return
				}
			}
			if frame != nil {
				wireSequence++
				frame.wireSequence = wireSequence
				// Somebody else's block. Dropping it is what keeps this
				// client's replies matched to its own commands.
				if c.dispatching.Load() && !frame.ownReply() {
					continue
				}
				select {
				case c.frames <- *frame:
				case <-c.closing:
					return
				}
			}
		}
		if err != nil {
			if errors.Is(err, io.EOF) || c.isClosing() {
				return
			}
			finalErr = fmt.Errorf("read control stream: %w", err)
			return
		}
	}
}

func (c *ControlClient) trackSessionChange(record []byte) {
	if !bytes.HasPrefix(record, []byte(ControlNotificationSessionChanged+" ")) {
		return
	}
	notification, err := ParseControlNotification(record)
	if err != nil || notification.Kind() != ControlNotificationSessionChanged {
		return
	}
	arguments := notification.arguments
	if len(arguments) == 0 || validateStableTarget("session", arguments[0]) != nil {
		return
	}
	c.stateMu.Lock()
	c.currentSessionID = SessionID(arguments[0])
	c.stateMu.Unlock()
}

// trackExitReason records the tail of a %exit notification as it streams
// past, so a later unsolicited EOF can name why tmux ended the connection
// even though the caller may have already read past that notification.
func (c *ControlClient) trackExitReason(record []byte) {
	const kind = ControlNotificationExit
	if !bytes.HasPrefix(record, []byte(kind)) {
		return
	}
	if len(record) > len(kind) && record[len(kind)] != ' ' {
		return
	}
	notification, err := ParseControlNotification(record)
	if err != nil || notification.Kind() != ControlNotificationExit {
		return
	}
	var reason string
	if arguments := notification.Arguments(); len(arguments) != 0 {
		reason = arguments[0]
	}
	c.stateMu.Lock()
	c.lastExitReason = reason
	c.stateMu.Unlock()
}

func (c *ControlClient) nextFrame(ctx context.Context) (controlFrame, error) {
	select {
	case frame, ok := <-c.frames:
		if !ok {
			return controlFrame{}, c.operationError()
		}
		return frame, nil
	case <-ctx.Done():
		return controlFrame{}, ctx.Err()
	case <-c.closing:
		return controlFrame{}, ErrControlClosed
	}
}

func (c *ControlClient) nextOwnFrame(ctx context.Context) (controlFrame, error) {
	for {
		frame, err := c.nextFrame(ctx)
		if err != nil || frame.ownReply() {
			return frame, err
		}
	}
}

tmux/display_message.go.content:
package tmux

import (
	"context"
	"strconv"
	"strings"
	"time"
)

var (
	displayMessageVersion34 = Version{raw: "3.4", major: 3, minor: 4}
	displayMessageVersion36 = Version{raw: "3.6", major: 3, minor: 6}
)

// DisplayMessageRequest configures display-message options shared by server,
// window, and pane scope. A zero request displays tmux's default message and
// returns nil. Print returns an owned stdout slice instead of displaying only
// to a client status line. Nil pointer fields omit their flags while pointers
// to empty values are explicit; a zero TargetClient omits its flag.
type DisplayMessageRequest struct {
	// Message is the optional status message; an empty message leaves tmux's default behavior.
	Message string
	// Print returns message output instead of only displaying it.
	Print bool
	// Format selects tmux output formatting.
	Format *string
	// AllFormats includes every available format value.
	AllFormats bool
	// Verbose requests verbose tmux output.
	Verbose bool
	// NoExpand disables format expansion and requires tmux 3.4; see
	// UnsupportedPolicy.
	NoExpand bool
	// TargetClient selects the stable client receiving the display; zero omits -c.
	TargetClient ClientName
	// Delay sets the display duration. Nil uses tmux's display-time option;
	// an explicit zero waits for a key press unless Notify is set. Values must
	// be whole milliseconds from zero through 4294967295 milliseconds.
	// Invalid values return ErrInvalidServerCommandRequest before tmux I/O.
	Delay *time.Duration
	// Notify makes the status message ignore key presses, closing only once
	// Delay elapses.
	Notify bool
}

// PaneDisplayMessageRequest adds the pane-only update behavior to the common
// display-message options.
type PaneDisplayMessageRequest struct {
	// DisplayMessageRequest supplies the shared display options.
	DisplayMessageRequest
	// UpdatePane updates pane state and requires tmux 3.6; see
	// UnsupportedPolicy.
	UpdatePane bool
}

type displayMessageValues struct {
	message      string
	format       string
	targetClient string
	delay        int64
	print        bool
	allFormats   bool
	verbose      bool
	noExpand     bool
	notify       bool
	hasFormat    bool
	hasClient    bool
	hasDelay     bool
}

// DisplayMessage displays or prints a server-scoped tmux message. Print
// returns an owned stdout slice even when tmux exits nonzero; completed stderr
// is delivered synchronously through [WarningCommandStderr], not returned as a
// completed-error classification. Unsupported flags follow [UnsupportedPolicy].
// Any warnings run on the caller goroutine before return. Cancellation does not
// prove display did not occur.
func (s Server) DisplayMessage(
	ctx context.Context,
	request DisplayMessageRequest,
) ([]string, error) {
	values, err := captureDisplayMessageRequest(request)
	if err != nil {
		return nil, err
	}
	return runDisplayMessage(ctx, s, "", values, false)
}

// DisplayMessage displays or prints a message at this window's exact target.
// Print returns an owned stdout slice even on a completed nonzero exit;
// completed stderr reaches [WarningHandler] as [WarningCommandStderr]. NoExpand
// follows [UnsupportedPolicy]. Warnings run synchronously before return; context
// cancellation does not prove display did not occur.
func (w Window) DisplayMessage(
	ctx context.Context,
	request DisplayMessageRequest,
) ([]string, error) {
	target, err := exactWindowTarget(w)
	if err != nil {
		return nil, err
	}
	values, err := captureDisplayMessageRequest(request)
	if err != nil {
		return nil, err
	}
	return runDisplayMessage(ctx, w.server, target, values, false)
}

// DisplayMessage displays or prints a message at this pane's exact target.
// Embedded NoExpand requires tmux 3.4 and UpdatePane requires tmux 3.6; each
// follows [UnsupportedPolicy]. Print returns an owned stdout slice even on a
// completed nonzero exit. Completed stderr synchronously reaches
// [WarningHandler] as [WarningCommandStderr], not an error; cancellation does
// not prove display or pane update did not occur.
func (p Pane) DisplayMessage(
	ctx context.Context,
	request PaneDisplayMessageRequest,
) ([]string, error) {
	target, err := exactPaneTarget(p)
	if err != nil {
		return nil, err
	}
	values, err := captureDisplayMessageRequest(request.DisplayMessageRequest)
	if err != nil {
		return nil, err
	}
	return runDisplayMessage(ctx, p.server, target, values, request.UpdatePane)
}

func captureDisplayMessageRequest(
	request DisplayMessageRequest,
) (displayMessageValues, error) {
	if err := validateServerCommandArgument(
		"display-message", "Message", request.Message, true,
	); err != nil {
		return displayMessageValues{}, err
	}
	values := displayMessageValues{
		message:    request.Message,
		print:      request.Print,
		allFormats: request.AllFormats,
		verbose:    request.Verbose,
		noExpand:   request.NoExpand,
		notify:     request.Notify,
	}
	if request.Format != nil {
		if err := validateServerCommandArgument(
			"display-message", "Format", *request.Format, true,
		); err != nil {
			return displayMessageValues{}, err
		}
		values.format = *request.Format
		values.hasFormat = true
	}
	if request.TargetClient != "" {
		values.targetClient = request.TargetClient.String()
		if err := validateServerCommandArgument(
			"display-message", "TargetClient", values.targetClient, true,
		); err != nil {
			return displayMessageValues{}, err
		}
		if err := validateTypedTarget(
			"display-message", "TargetClient", "client", values.targetClient,
		); err != nil {
			return displayMessageValues{}, err
		}
		values.hasClient = true
	}
	if request.Delay != nil {
		delay := *request.Delay
		if delay < 0 || delay%time.Millisecond != 0 || delay/time.Millisecond > 1<<32-1 {
			return displayMessageValues{}, invalidServerCommandRequest(
				"display-message", "Delay", delay.String(),
				"must be whole milliseconds from 0 through 4294967295",
			)
		}
		values.delay = delay.Milliseconds()
		values.hasDelay = true
	}
	return values, nil
}

func runDisplayMessage(
	ctx context.Context,
	server Server,
	target string,
	request displayMessageValues,
	updatePane bool,
) ([]string, error) {
	var current Version
	if request.noExpand || updatePane {
		var err error
		current, err = server.Version(ctx)
		if err != nil {
			return nil, err
		}
	}

	arguments := []string{"display-message"}
	if target != "" {
		arguments = append(arguments, "-t", target)
	}
	if request.print {
		arguments = append(arguments, "-p")
	}
	if request.allFormats {
		arguments = append(arguments, "-a")
	}
	if request.verbose {
		arguments = append(arguments, "-v")
	}
	if request.noExpand {
		if current.AtLeast(displayMessageVersion34) {
			arguments = append(arguments, "-l")
		} else if err := server.unsupportedFeature(
			"display-message",
			"no_expand",
			current,
			displayMessageVersion34,
		); err != nil {
			return nil, err
		}
	}
	if request.notify {
		arguments = append(arguments, "-N")
	}
	if updatePane {
		if current.AtLeast(displayMessageVersion36) {
			arguments = append(arguments, "-C")
		} else if err := server.unsupportedFeature(
			"display-message",
			"update_pane",
			current,
			displayMessageVersion36,
		); err != nil {
			return nil, err
		}
	}
	if request.hasClient {
		arguments = append(arguments, "-c", request.targetClient)
	}
	if request.hasDelay {
		arguments = append(arguments, "-d", strconv.FormatInt(request.delay, 10))
	}
	if request.hasFormat {
		arguments = append(arguments, "-F", request.format)
	}
	if request.message != "" {
		if strings.HasPrefix(request.message, "-") {
			arguments = append(arguments, "--")
		}
		arguments = append(arguments, request.message)
	}

	result, err := server.literalCmd(ctx, arguments...)
	if err != nil {
		return nil, err
	}
	if len(result.Stderr) != 0 {
		server.warn(newCommandStderrWarning("display-message", result.Stderr))
	}
	if !request.print {
		return nil, nil
	}
	output := make([]string, len(result.Stdout))
	copy(output, result.Stdout)
	return output, nil
}

tmux/environment.go.content:
package tmux

import (
	"context"
	"errors"
	"fmt"
	"strings"
)

var (
	// ErrInvalidEnvironmentName identifies a name tmux cannot store.
	ErrInvalidEnvironmentName = errors.New("tmux: invalid environment variable name")
	// ErrInvalidEnvironmentValue identifies a value the line-oriented read API cannot round-trip.
	ErrInvalidEnvironmentValue = errors.New("tmux: invalid environment variable value")
	// ErrMalformedEnvironment identifies output that is not a tmux environment entry.
	ErrMalformedEnvironment = errors.New("tmux: malformed environment output")
)

// SetEnvironmentOptions controls tmux's value expansion and visibility flags.
// Its zero value stores Value literally and exposes it to child processes.
type SetEnvironmentOptions struct {
	// ExpandFormat expands tmux format expressions in Value before storing it.
	ExpandFormat bool
	// Hidden keeps the value available to tmux but out of child environments.
	Hidden bool
}

// EnvironmentValue is one tmux environment value or removal marker. Its zero
// value is an ordinary empty value, not a removal marker.
type EnvironmentValue struct {
	// Value is the exact value after tmux format expansion, if any.
	Value string
	// Removed reports that tmux will remove the variable from new processes.
	Removed bool
}

// EnvironmentNameError reports a name that tmux cannot store.
type EnvironmentNameError struct {
	// Name is the invalid environment variable name.
	Name string
}

// Error implements error.
func (e *EnvironmentNameError) Error() string {
	return fmt.Sprintf("%v %q", ErrInvalidEnvironmentName, e.Name)
}

// Unwrap makes EnvironmentNameError compatible with ErrInvalidEnvironmentName.
func (e *EnvironmentNameError) Unwrap() error { return ErrInvalidEnvironmentName }

// EnvironmentValueError reports a value that cannot round-trip through show-environment.
// It intentionally does not retain or print the environment value.
type EnvironmentValueError struct{}

// Error implements error without disclosing the environment value.
func (*EnvironmentValueError) Error() string {
	return ErrInvalidEnvironmentValue.Error() + ": contains a line or NUL delimiter"
}

// Unwrap makes EnvironmentValueError compatible with ErrInvalidEnvironmentValue.
func (*EnvironmentValueError) Unwrap() error { return ErrInvalidEnvironmentValue }

// EnvironmentDecodeError reports one malformed show-environment record.
// It never retains the record because environment output may contain secrets.
type EnvironmentDecodeError struct {
	// Record is the zero-based malformed output record number.
	Record int
	// Reason describes malformed framing without retaining the record value.
	Reason string
}

// Error implements error.
func (e *EnvironmentDecodeError) Error() string {
	return fmt.Sprintf("%v: record %d: %s", ErrMalformedEnvironment, e.Record, e.Reason)
}

// Unwrap makes EnvironmentDecodeError compatible with ErrMalformedEnvironment.
func (e *EnvironmentDecodeError) Unwrap() error { return ErrMalformedEnvironment }

// SetEnvironment stores a value in the server's global tmux environment.
// ExpandFormat and Hidden select tmux flags; cancellation does not prove the
// value was not stored.
func (s Server) SetEnvironment(
	ctx context.Context,
	name string,
	value string,
	options SetEnvironmentOptions,
) error {
	return setEnvironment(ctx, s, []string{"-g"}, name, value, options)
}

// UnsetEnvironment deletes a value from the server's global tmux environment.
// Cancellation does not prove deletion did not occur.
func (s Server) UnsetEnvironment(ctx context.Context, name string) error {
	return changeEnvironmentState(ctx, s, []string{"-g"}, "-u", name)
}

// RemoveEnvironment marks a variable for removal from new process environments.
func (s Server) RemoveEnvironment(ctx context.Context, name string) error {
	return changeEnvironmentState(ctx, s, []string{"-g"}, "-r", name)
}

// ShowEnvironment returns an owned server-global non-hidden tmux environment.
// Completed command failures return an empty map unless strict errors are enabled.
// Externally injected multiline entries return ErrMalformedEnvironment because
// tmux's multi-entry output does not frame continuation lines. Decode errors
// are compatible with [ErrMalformedEnvironment] and return no partial map.
func (s Server) ShowEnvironment(ctx context.Context) (map[string]EnvironmentValue, error) {
	return showEnvironment(ctx, s, []string{"-g"})
}

// GetEnvironment returns one non-hidden global environment entry.
// A missing or hidden variable reports ok false.
func (s Server) GetEnvironment(
	ctx context.Context,
	name string,
) (EnvironmentValue, bool, error) {
	return getEnvironment(ctx, s, []string{"-g"}, name)
}

// SetEnvironment stores a value in this session's tmux environment, targeted
// by its stable SessionID.
func (s Session) SetEnvironment(
	ctx context.Context,
	name string,
	value string,
	options SetEnvironmentOptions,
) error {
	server, scope, err := s.environmentScope()
	if err != nil {
		return err
	}
	return setEnvironment(ctx, server, scope, name, value, options)
}

// UnsetEnvironment deletes a value from this session's tmux environment,
// targeted by its stable SessionID.
func (s Session) UnsetEnvironment(ctx context.Context, name string) error {
	server, scope, err := s.environmentScope()
	if err != nil {
		return err
	}
	return changeEnvironmentState(ctx, server, scope, "-u", name)
}

// RemoveEnvironment marks a variable for removal from new process environments
// for this stable session target.
func (s Session) RemoveEnvironment(ctx context.Context, name string) error {
	server, scope, err := s.environmentScope()
	if err != nil {
		return err
	}
	return changeEnvironmentState(ctx, server, scope, "-r", name)
}

// ShowEnvironment returns an owned session-scoped non-hidden tmux environment.
// Completed command failures return an empty map unless strict errors are enabled.
// Externally injected multiline entries return ErrMalformedEnvironment because
// tmux's multi-entry output does not frame continuation lines. Decode errors
// are compatible with [ErrMalformedEnvironment] and return no partial map.
func (s Session) ShowEnvironment(ctx context.Context) (map[string]EnvironmentValue, error) {
	server, scope, err := s.environmentScope()
	if err != nil {
		return nil, err
	}
	return showEnvironment(ctx, server, scope)
}

// GetEnvironment returns one non-hidden session environment entry for this
// stable session target.
// A missing or hidden variable reports ok false.
func (s Session) GetEnvironment(
	ctx context.Context,
	name string,
) (EnvironmentValue, bool, error) {
	server, scope, err := s.environmentScope()
	if err != nil {
		return EnvironmentValue{}, false, err
	}
	return getEnvironment(ctx, server, scope, name)
}

func (s Session) environmentScope() (Server, []string, error) {
	target := s.sessionID.String()
	if err := validateServerCommandArgument(
		"environment", "Target", target, true,
	); err != nil {
		return Server{}, nil, err
	}
	if err := validateTypedTarget("environment", "Target", "session", target); err != nil {
		return Server{}, nil, err
	}
	return s.server, []string{"-t", target}, nil
}

func setEnvironment(
	ctx context.Context,
	server Server,
	scope []string,
	name string,
	value string,
	options SetEnvironmentOptions,
) error {
	if err := validateEnvironmentName(name); err != nil {
		return err
	}
	if err := validateEnvironmentValue(value); err != nil {
		return err
	}
	arguments := make([]string, 0, 6+len(scope))
	arguments = append(arguments, "set-environment")
	arguments = append(arguments, scope...)
	if options.ExpandFormat {
		arguments = append(arguments, "-F")
	}
	if options.Hidden {
		arguments = append(arguments, "-h")
	}
	arguments = append(arguments, "--", name, value)
	return runEnvironmentMutation(ctx, server, arguments)
}

func changeEnvironmentState(
	ctx context.Context,
	server Server,
	scope []string,
	flag string,
	name string,
) error {
	if err := validateEnvironmentName(name); err != nil {
		return err
	}
	arguments := make([]string, 0, 4+len(scope))
	arguments = append(arguments, "set-environment")
	arguments = append(arguments, scope...)
	arguments = append(arguments, flag, "--", name)
	return runEnvironmentMutation(ctx, server, arguments)
}

func runEnvironmentMutation(ctx context.Context, server Server, arguments []string) error {
	result, err := server.literalCmd(ctx, arguments...)
	if err != nil {
		return err
	}
	if result.ExitCode != 0 || len(result.Stderr) != 0 {
		return newRedactedCommandError(arguments[0], result)
	}
	return nil
}

func showEnvironment(
	ctx context.Context,
	server Server,
	scope []string,
) (map[string]EnvironmentValue, error) {
	arguments := make([]string, 0, 1+len(scope))
	arguments = append(arguments, "show-environment")
	arguments = append(arguments, scope...)
	result, err := server.literalCmd(ctx, arguments...)
	if err != nil {
		return nil, err
	}
	if result.ExitCode != 0 {
		return nil, newRedactedCommandError(arguments[0], result)
	}
	return parseEnvironmentLines(result.Stdout)
}

func getEnvironment(
	ctx context.Context,
	server Server,
	scope []string,
	name string,
) (EnvironmentValue, bool, error) {
	if err := validateEnvironmentName(name); err != nil {
		return EnvironmentValue{}, false, err
	}
	arguments := make([]string, 0, 2+len(scope))
	arguments = append(arguments, "show-environment")
	arguments = append(arguments, scope...)
	arguments = append(arguments, "--", name)
	result, err := server.literalCmd(ctx, arguments...)
	if err != nil {
		return EnvironmentValue{}, false, err
	}
	if result.ExitCode != 0 {
		if environmentVariableMissing(result, name) {
			return EnvironmentValue{}, false, nil
		}
		return EnvironmentValue{}, false, newRedactedCommandError(arguments[0], result)
	}
	values, err := parseEnvironmentLines(result.Stdout)
	if err != nil {
		return EnvironmentValue{}, false, err
	}
	if len(values) == 0 {
		return EnvironmentValue{}, false, nil
	}
	value, ok := values[name]
	if !ok || len(values) != 1 {
		return EnvironmentValue{}, false, &EnvironmentDecodeError{
			Record: 0,
			Reason: "entry does not match requested variable",
		}
	}
	return value, true, nil
}

func validateEnvironmentName(name string) error {
	if name == "" || strings.ContainsAny(name, "=\r\n\x00") {
		return &EnvironmentNameError{Name: name}
	}
	return nil
}

func validateEnvironmentValue(value string) error {
	if strings.ContainsAny(value, "\r\n\x00") {
		return &EnvironmentValueError{}
	}
	return nil
}

func parseEnvironmentLines(lines []string) (map[string]EnvironmentValue, error) {
	values := make(map[string]EnvironmentValue, len(lines))
	for record, line := range lines {
