type filterValidationState struct {
	sessions map[*SessionFilter]struct{}
	windows  map[*WindowFilter]struct{}
	panes    map[*PaneFilter]struct{}
	clients  map[*ClientFilter]struct{}
}

func newFilterValidationState() filterValidationState {
	return filterValidationState{
		sessions: make(map[*SessionFilter]struct{}),
		windows:  make(map[*WindowFilter]struct{}),
		panes:    make(map[*PaneFilter]struct{}),
		clients:  make(map[*ClientFilter]struct{}),
	}
}

// Validate checks structure, regular expressions, and contradictory criteria; failures wrap [ErrInvalidFilter].
func (filter SessionFilter) Validate() error {
	state := newFilterValidationState()
	if err := (&filter).validateStructure(&state, 0); err != nil {
		return err
	}
	if err := (&filter).validatePatterns(); err != nil {
		return err
	}
	return (&filter).validateCriteria()
}

func (filter *SessionFilter) validateStructure(state *filterValidationState, depth int) error {
	if depth > maxFilterDepth {
		return invalidFilter("session filter exceeds maximum depth")
	}
	if _, found := state.sessions[filter]; found {
		return invalidFilter("session filter contains a cycle")
	}
	state.sessions[filter] = struct{}{}
	defer delete(state.sessions, filter)
	if filter.IDIn != nil && len(filter.IDIn) == 0 {
		return invalidFilter("idIn must not be empty")
	}
	if filter.NameIn != nil && len(filter.NameIn) == 0 {
		return invalidFilter("nameIn must not be empty")
	}
	if filter.AnyOf != nil && len(filter.AnyOf) == 0 {
		return invalidFilter("anyOf must not be empty")
	}
	for index := range filter.AnyOf {
		if err := filter.AnyOf[index].validateStructure(state, depth+1); err != nil {
			return err
		}
	}
	if filter.Not != nil {
		if err := filter.Not.validateStructure(state, depth+1); err != nil {
			return err
		}
	}
	if filter.Windows != nil {
		if filter.Windows.Some == nil && filter.Windows.Every == nil && filter.Windows.None == nil {
			return invalidFilter("windows requires some, every, or none")
		}
		if filter.Windows.Some != nil {
			if err := filter.Windows.Some.validateStructure(state, depth+1); err != nil {
				return err
			}
		}
		if filter.Windows.Every != nil {
			if err := filter.Windows.Every.validateStructure(state, depth+1); err != nil {
				return err
			}
		}
		if filter.Windows.None != nil {
			if err := filter.Windows.None.validateStructure(state, depth+1); err != nil {
				return err
			}
		}
	}
	if filter.Panes != nil {
		if filter.Panes.Some == nil && filter.Panes.Every == nil && filter.Panes.None == nil {
			return invalidFilter("panes requires some, every, or none")
		}
		if filter.Panes.Some != nil {
			if err := filter.Panes.Some.validateStructure(state, depth+1); err != nil {
				return err
			}
		}
		if filter.Panes.Every != nil {
			if err := filter.Panes.Every.validateStructure(state, depth+1); err != nil {
				return err
			}
		}
		if filter.Panes.None != nil {
			if err := filter.Panes.None.validateStructure(state, depth+1); err != nil {
				return err
			}
		}
	}
	return nil
}

func (filter *SessionFilter) validatePatterns() error {
	if filter.NameRegex != "" {
		if _, err := regexp.Compile(filter.NameRegex); err != nil {
			return invalidFilter("nameRegex: %v", err)
