package tmux

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"strconv"
	"strings"
)

type snapshotServerIdentity struct {
	version    Version
	pid        string
	startTime  string
	socketPath string
}

// ErrDaemonReplaced identifies an operation refused because the tmux server
// instance that produced a materialized value no longer occupies its socket.
var ErrDaemonReplaced = errors.New("tmux: materialized value's server was replaced")

type daemonCommandGuard struct {
	failure string
}

// Equal reports whether both handles currently select the same socket path.
// It evaluates relative paths and environment-dependent named and default
// sockets against each handle's frozen binding.
func (s Server) Equal(other Server) bool {
	left, err := s.SocketSelection()
	if err != nil {
		return false
	}
	right, err := other.SocketSelection()
	return err == nil && left.Path == right.Path
}

// String returns a concise representation of the server selector.
func (s Server) String() string {
	if s.state == nil {
		return "Server(invalid)"
	}
	flag, value := effectiveSocketSelectorValues(
		s.state.config.socketPath,
		s.state.config.socketName,
	)
	switch flag {
	case "-S":
		return fmt.Sprintf("Server(socket_path=%s)", value)
	case "-L":
		return fmt.Sprintf("Server(socket_name=%s)", value)
	}
	return "Server(default)"
}

// Equal reports whether two session records carry the same stable ID and tmux
// server provenance.
func (s Session) Equal(other Session) bool {
	return s.sessionID == other.sessionID && sameMaterializedDaemon(s.server, other.server)
}

// String returns the session's stable ID and queried name.
func (s Session) String() string {
	if name, ok := s.Name(); ok {
		return fmt.Sprintf("Session(%s %s)", s.sessionID, name)
	}
	return fmt.Sprintf("Session(%s)", s.sessionID)
}

// Equal reports whether two window records carry the same stable window ID.
// It intentionally collapses linked-session views with different sessions or
// indexes; use SessionID, WindowID, and WindowIndex for exact view identity.
func (w Window) Equal(other Window) bool {
	return w.windowID == other.windowID && sameMaterializedDaemon(w.server, other.server)
}

// String returns the winlink identity and its materialized parent, when present.
func (w Window) String() string {
	name, _ := w.Name()
	identity := fmt.Sprintf("Window(%s %d:%s", w.windowID, w.windowIndex, name)
	if session, ok := w.Session(); ok {
		return identity + ", " + session.String() + ")"
	}
	return identity + ")"
}

// Equal reports whether two pane records carry the same stable pane ID. It
// intentionally collapses linked-session views; a pane's exact view identity
// includes SessionID, WindowID, WindowIndex, and PaneID.
func (p Pane) Equal(other Pane) bool {
	return p.paneID == other.paneID && sameMaterializedDaemon(p.server, other.server)
}

// String returns the pane identity and its materialized parent, when present.
func (p Pane) String() string {
	identity := fmt.Sprintf("Pane(%s", p.paneID)
	if window, ok := p.Window(); ok {
		return identity + " " + window.String() + ")"
	}
	return identity + ")"
}

// Equal reports whether two clients carry the same stable client name and tmux
// server provenance.
func (c Client) Equal(other Client) bool {
	return c.clientName == other.clientName && sameMaterializedDaemon(c.server, other.server)
}

// String returns the client's stable name.
func (c Client) String() string { return fmt.Sprintf("Client(%s)", c.clientName) }

func sameMaterializedDaemon(left, right Server) bool {
	if left.daemon == nil || right.daemon == nil {
		return left.daemon == nil && right.daemon == nil && left.Equal(right)
	}
	return sameSnapshotIdentity(*left.daemon, *right.daemon)
}

func (s Server) withDaemon(identity snapshotServerIdentity) Server {
	s.daemon = &identity
	s.startupVersion = nil
	return s
}

func (s Server) withoutDaemon() Server {
	s.daemon = nil
	s.startupVersion = nil
	return s
}

func (s Server) guardCommand(
	arguments []string,
	commandList bool,
) ([]string, *daemonCommandGuard, error) {
	if (s.daemon == nil && s.startupVersion == nil) || s.boundToInstance() {
		return arguments, nil, nil
	}
	if !commandList {
		arguments = escapeCommandListSeparators(arguments)
	}
	guard := &daemonCommandGuard{
		failure: "__libtmux_daemon_replaced_" + rand.Text() + "__",
	}
	var condition string
	if s.daemon == nil {
		// A daemon can appear after the absent-socket probe. Its version must
		// still match the executable checked to create it.
		condition = "#{==:#{version}," + escapeFormatLiteral(s.startupVersion.String()) + "}"
	} else {
		// pid and start_time identify the daemon generation. The socket path
		// is not compared: no format escaping makes tmux match every byte of
		// it (braces never match), and a handle addresses its socket with -S.
		condition = fmt.Sprintf(
			"#{&&:#{==:#{pid},%s},#{==:#{start_time},%s}}",
			s.daemon.pid,
			s.daemon.startTime,
		)
	}
	guarded := []string{"if-shell", "-F", condition, "", guard.failure, ";"}
	return append(guarded, arguments...), guard, nil
}

func escapeFormatLiteral(value string) string {
	var escaped strings.Builder
	escaped.Grow(len(value))
	for _, character := range value {
		// A leading # makes tmux's format parser treat its operator and
		// expansion punctuation as literal text.
		if strings.ContainsRune(",#{}:", character) {
			escaped.WriteByte('#')
		}
		escaped.WriteRune(character)
	}
	return escaped.String()
}

func (g *daemonCommandGuard) rejected(exitCode int, stderr []string) bool {
	return g != nil && exitCode != 0 &&
		len(stderr) == 1 && stderr[0] == "unknown command: "+g.failure
}

func snapshotIdentityChangeError(identity snapshotServerIdentity) error {
	return newSnapshotDecodeError(
		"server",
		1,
		"server_identity",
		formatSnapshotIdentity(identity),
		"tmux server changed while materializing snapshot",
	)
}

func snapshotIdentityFields() []formatField {
	return []formatField{
		{name: "version"},
		{name: "pid"},
		{name: "start_time"},
		{name: "socket_path"},
	}
}

// probeClosingIdentity verifies one daemon produced the listing. A bound
// transport already proves this and reuses the opening identity.
func (s Server) probeClosingIdentity(
	ctx context.Context,
	opening snapshotServerIdentity,
) (snapshotServerIdentity, error) {
	if s.boundToInstance() {
		return opening, nil
	}
	return s.probeSnapshotIdentity(ctx)
}

func (s Server) probeSnapshotIdentity(ctx context.Context) (snapshotServerIdentity, error) {
	return s.probeServerIdentity(ctx, snapshotIdentityFields())
}

func (s Server) probeServerIdentity(ctx context.Context, fields []formatField) (snapshotServerIdentity, error) {
	if s.daemon != nil {
		return *s.daemon, nil
	}
	marker := newIdentityProbeMarker()
	probe := s
	probe.probesIdentity = true
	result, err := probe.runCheckedCommand(ctx, commandServer,
		identityProbeArguments(marker, fields), nil, false)
	commandResult := cloneCommandResult(CommandResult{
		Command: result.Command, Stdout: result.Stdout, RawStdout: result.RawStdout,
		Stderr: result.Stderr, ExitCode: result.ExitCode,
	})
	if err != nil {
		return snapshotServerIdentity{}, commandTransportFailure(err)
	}
	values, ok := identityProbeReport(marker, fields, result.ExitCode, result.Stderr)
	if !ok {
		if predatesIdentityProbe(result.ExitCode, result.Stderr) {
			return snapshotServerIdentity{}, &VersionTooLowError{
				Current: s.predatedVersion(ctx, result.Stderr), Minimum: minimumSupportedVersion,
			}
		}
		return snapshotServerIdentity{}, newCommandError("run-shell", commandResult)
	}
	row, err := newFormatValues(Version{}, fields, values)
	if err != nil {
		return snapshotServerIdentity{}, err
	}
	rows := []formatValues{row}
	if len(rows) != 1 {
		return snapshotServerIdentity{}, newSnapshotDecodeError(
			"server",
			0,
			"identity",
			strconv.Itoa(len(rows)),
			"expected one identity record",
		)
	}
	identity, err := decodeSnapshotIdentity("server", 0, rows[0])
	if err != nil {
		return snapshotServerIdentity{}, err
	}
	return s.normalizeSnapshotIdentityVersion(ctx, identity)
}

// predatesProbeVersion stands for any tmux before 3.2, which has no
// run-shell -C and so cannot report its version without a hook.
var predatesProbeVersion = Version{raw: "older than 3.2", major: 3, minor: 1}

// predatedVersion names the tmux that failed the probe. A client that rejects
// -N is the executable itself, whose own -V gives the release; a daemon that
// cannot answer never reports one.
func (s Server) predatedVersion(ctx context.Context, stderr []string) Version {
	if len(stderr) < 2 || !strings.HasSuffix(stderr[0], "unknown option -- N") {
		return predatesProbeVersion
	}
	version, err := s.withoutDaemon().Version(ctx)
	if err != nil {
		return predatesProbeVersion
	}
	if _, recognized := versionKey(version.raw); !recognized || version.meetsMinimum(minimumSupportedVersion) {
		return predatesProbeVersion
	}
	return version
}

// predatesIdentityProbe reports the ways a tmux older than 3.2 answers
// the probe: a client that does not know -N, a 3.1 daemon whose run-shell has
// no -C, and a 3.0 daemon the newer client cannot talk to at all.
func predatesIdentityProbe(exitCode int, stderr []string) bool {
	if exitCode != 1 || len(stderr) == 0 {
		return false
	}
	if len(stderr) == 1 {
		return stderr[0] == "server version is too old for client" ||
			strings.HasPrefix(stderr[0], "usage: run-shell ")
	}
	// A client without -N prints its refusal, then its own usage.
	return strings.HasSuffix(stderr[0], "unknown option -- N") &&
		strings.HasPrefix(stderr[1], "usage: tmux ")
}

// identityProbeMarkerPrefix opens the private word the identity probe asks
// tmux to run. No command carries that name, so tmux refuses it and reports
// the word, with every format already expanded, on stderr.
const identityProbeMarkerPrefix = "libtmux-version-"

// newIdentityProbeMarker is replaced only by this package's tests, which pin
// the marker so scripted executors can answer the probe.
var newIdentityProbeMarker = randomIdentityProbeMarker

func randomIdentityProbeMarker() string {
	random := make([]byte, 8)
	if _, err := rand.Read(random); err != nil {
		panic("tmux: read random bytes: " + err.Error())
	}
	return identityProbeMarkerPrefix + hex.EncodeToString(random) + "-"
}

// identityProbeArguments builds the hook-free identity probe. Unlike
// display-message, run-shell has no after-hook, and with -C the expanded
// string fails in the parser before any command-error hook can fire.
//
// tmux reports only the first unparseable word, so every field expands into
// one. The parser removes backslash quoting before it prints that word, so the
// socket path, the only field with arbitrary bytes, is single-quoted with its
// own quotes re-opened and goes last; the others are quoted by #{q:}.
func identityProbeArguments(marker string, fields []formatField) []string {
	var template strings.Builder
	template.WriteString(marker)
	for _, field := range identityProbeOrder(fields) {
		if field.name == "socket_path" {
			template.WriteString(`'#{s/'/'\\''/:socket_path}'`)
		} else {
			template.WriteString("#{q:" + field.name + "}")
			template.WriteByte(formatFieldSeparator)
		}
	}
	template.WriteByte(formatRecordTerminator)
	return []string{"run-shell", "-C", template.String()}
}

// identityProbeOrder keeps the socket path, whose bytes are unconstrained,
// last so it can be recovered without escaping rules.
func identityProbeOrder(fields []formatField) []formatField {
	ordered := make([]formatField, 0, len(fields))
	for _, field := range fields {
		if field.name != "socket_path" {
			ordered = append(ordered, field)
		}
	}
	for _, field := range fields {
		if field.name == "socket_path" {
			ordered = append(ordered, field)
		}
	}
	return ordered
}

// identityProbeReport extracts the field values, in the order of fields, from
// the refusal tmux prints for the probe's marker word. Anything other than one
// matching line is not an identity report; a path with a newline is refused.
func identityProbeReport(
	marker string,
	fields []formatField,
	exitCode int,
	stderr []string,
) ([]string, bool) {
	if exitCode != 1 || len(stderr) != 1 {
		return nil, false
	}
	record, ok := strings.CutPrefix(stderr[0], "unknown command: "+marker)
	if !ok {
		return nil, false
	}
	record, ok = strings.CutSuffix(record, string(formatRecordTerminator))
	if !ok {
		return nil, false
	}
	ordered := identityProbeOrder(fields)
	parts := strings.SplitN(record, string(formatFieldSeparator), len(ordered))
	if len(parts) != len(ordered) {
		return nil, false
	}
	byName := make(map[string]string, len(ordered))
	for index, field := range ordered {
		byName[field.name] = parts[index]
	}
	values := make([]string, len(fields))
	for index, field := range fields {
		values[index] = byName[field.name]
	}
	return values, true
}

func (s Server) normalizeSnapshotIdentityVersion(
	ctx context.Context,
	identity snapshotServerIdentity,
) (snapshotServerIdentity, error) {
	if !isOpenBSDVersionToken(identity.version.String()) {
		return identity, nil
	}
	capabilities, err := s.Version(ctx)
	if err != nil {
		return snapshotServerIdentity{}, err
	}
	if capabilities.String() != identity.version.String() {
		return snapshotServerIdentity{}, newVersionQueryError(
			CommandResult{},
			"tmux binary version differed from server version",
		)
	}
	identity.version.major = capabilities.major
	identity.version.minor = capabilities.minor
	identity.version.patch = capabilities.patch
	identity.version.development = capabilities.development
	return identity, nil
}

func sameSnapshotIdentity(left, right snapshotServerIdentity) bool {
	return left.version.String() == right.version.String() &&
		left.pid == right.pid &&
		left.startTime == right.startTime &&
		left.socketPath == right.socketPath
}

func formatSnapshotIdentity(identity snapshotServerIdentity) string {
	return identity.version.String() + "/" + identity.pid + "/" +
		identity.startTime + "/" + identity.socketPath
}

tmux/lifecycle_kill.go.content:
package tmux

import (
	"context"
	"errors"
	"fmt"
	"strconv"
)

// SessionKillRequest configures kill-session on tmux 3.3a or later. Its zero
// value destroys the receiver session. AllExcept destroys other sessions
// instead, while ClearAlerts is non-destructive. AllExcept, ClearAlerts, and
// Group are mutually exclusive because tmux applies a hidden precedence when
// more than one mode is supplied; the package rejects those combinations
// before execution. Group's compatibility behavior is documented on that field.
type SessionKillRequest struct {
	// AllExcept terminates every other session and detaches their clients while
	// preserving the receiver session.
	AllExcept bool
	// ClearAlerts clears bell, activity, and silence alerts in every window linked
	// to the receiver without destroying a session or detaching its clients.
	ClearAlerts bool
	// Group terminates every session in the receiver's group and detaches their
	// clients. It requires tmux 3.7; see UnsupportedPolicy.
	Group bool
}

// KillWindowRequest selects a window for [Session.KillWindow] on tmux 3.3a or
// later. A zero request kills the receiver session's current window, and Index
// is scoped to that session. Target is unrestricted tmux target syntax and may
// select a window in another session. Target and Index are mutually exclusive
// and are checked before execution. Pointer values are read during the call
// and are not retained; callers must not mutate them concurrently. A nil
// pointer omits its selector, while a nonnil pointer is explicit even when
// Target points to an empty string.
type KillWindowRequest struct {
	// Target is passed through as unrestricted tmux target syntax when nonnil.
	Target *string
	// Index selects a winlink index within the receiver session when nonnil.
	Index *int
}

// Kill terminates the configured tmux server and all of its sessions, windows,
// panes, and clients. After a completed failed kill, a liveness probe makes
// repeated calls harmless when no daemon answers. Transport or context errors
// can be delivery-ambiguous; no rollback is attempted.
//
// tmux leaves the socket file in place, so cleanup that waits for the path to
// disappear does not finish. Use [Server.IsAlive] to observe the daemon, and
// remove a socket path this process chose itself.
func (s Server) Kill(ctx context.Context) error {
	result, err := s.literalCmd(ctx, "kill-server")
	if err != nil {
		return err
	}
	if result.ExitCode == 0 && len(result.Stderr) == 0 {
		return nil
	}
	commandErr := newCommandError("kill-server", result)
	alive, probeErr := s.cleanupServerAlive(ctx)
	if probeErr != nil {
		return errors.Join(
			commandErr,
			fmt.Errorf("verify server stopped: %w", probeErr),
		)
	}
	if !alive {
		return nil
	}
	return commandErr
}

// cleanupServerAlive permits an absent-server cleanup check without version-checking
// another public operation or starting a daemon.
func (s Server) cleanupServerAlive(ctx context.Context) (bool, error) {
	result, err := s.runCheckedCommand(ctx, commandServer, []string{"list-sessions"}, nil, false)
	if err != nil {
		return false, commandTransportFailure(err)
	}
	if result.ExitCode == 0 {
		return true, nil
	}
	commandErr := newCommandError("list-sessions", CommandResult{
		ExitCode: result.ExitCode, Stderr: result.Stderr,
	})
	if errors.Is(commandErr, ErrNoServer) {
		return false, nil
	}
	return false, commandErr
}

// KillSession terminates the session selected by tmux target syntax. Pattern
// and prefix matching are deliberately left to tmux. Completed nonzero exits
// without stderr are ignored. Transport and context errors are delivery-ambiguous.
func (s Server) KillSession(ctx context.Context, target string) error {
	if err := validateServerCommandArgument(
		"kill-session", "Target", target, true,
	); err != nil {
		return err
	}
	result, err := s.literalCmd(ctx, "kill-session", "-t", target)
	return requireServerCommandNoStderr("kill-session", result, err)
}

// Kill destroys the receiver session and removes its winlinks. Ordinary
// attached clients detach; on tmux 3.6 or later, clients carrying
// no-detach-on-destroy move to another session when one exists. A window with
// no remaining links and all of that window's panes are also destroyed. The
// materialized receiver is not refreshed. Only stderr makes a completed
// command a [CommandError]; nonzero exits without stderr are ignored.
// Transport errors are delivery-ambiguous. Kill is equivalent to
// [Session.KillWith] with a zero [SessionKillRequest].
func (s Session) Kill(ctx context.Context) error {
	return s.KillWith(ctx, SessionKillRequest{})
}

// KillWith applies one kill-session mode without refreshing the materialized
// receiver. The zero request destroys the receiver; AllExcept destroys every
// other session while preserving the receiver and its current window;
// ClearAlerts only clears alerts in windows linked to the receiver and leaves
// sessions, winlinks, panes, client attachments, and current-window selections
// unchanged. Destroying a session handles clients as [Session.Kill] describes
// and removes its winlinks; windows left without links and their panes are
// also destroyed. Group destroys the receiver's group and requires tmux 3.7;
// on older versions it follows [UnsupportedPolicy].
//
// The three modes are mutually exclusive. Only stderr makes a completed command
// a [CommandError]; nonzero exits without stderr are ignored. Transport errors
// are delivery-ambiguous.
func (s Session) KillWith(ctx context.Context, request SessionKillRequest) error {
	modes := 0
	if request.AllExcept {
		modes++
	}
	if request.ClearAlerts {
		modes++
	}
	if request.Group {
		modes++
	}
	if modes > 1 {
		return invalidLifecycleRequest(
			"AllExcept, ClearAlerts, and Group are mutually exclusive",
		)
	}
	if err := validateTypedTarget(
		"kill-session", "Target", "session", s.sessionID.String(),
	); err != nil {
		return err
	}
	arguments := []string{"kill-session"}
	if request.AllExcept {
		arguments = append(arguments, "-a")
	}
	if request.ClearAlerts {
		arguments = append(arguments, "-C")
	}
	if request.Group {
		required := Version{raw: "3.7", major: 3, minor: 7}
		current, err := s.server.Version(ctx)
		if err != nil {
			return err
		}
		if current.AtLeast(required) {
			arguments = append(arguments, "-g")
		} else if err := s.server.unsupportedFeature(
			"kill-session", "group", current, required,
		); err != nil {
			return err
		}
	}
	result, err := s.literalCmd(ctx, arguments...)
	return requireServerCommandNoStderr("kill-session", result, err)
}

// KillWindow destroys one stable window. When Target and Index are nil it
// selects the receiver session's current window, and Index selects a winlink
// in that session. A nonnil Target is forwarded as unrestricted tmux target
// syntax and may select a window in another session. The selected stable
// window is removed from every session and its panes are destroyed. Affected
// sessions preserve their current selection unless this window was current,
// in which case they select another. A session left without windows is
// destroyed; [Session.Kill] describes how tmux handles its clients.
//
// Target and Index are mutually exclusive. The receiver is not refreshed. Only
// stderr makes a completed command a [CommandError]; nonzero exits without
// stderr are ignored. Transport errors are delivery-ambiguous.
func (s Session) KillWindow(ctx context.Context, request KillWindowRequest) error {
	if request.Target != nil && request.Index != nil {
		return invalidLifecycleRequest("Target and Index are mutually exclusive")
	}

	var target string
	if request.Target != nil {
		target = *request.Target
		if err := validateServerCommandArgument(
			"kill-window", "Target", target, true,
		); err != nil {
			return err
		}
	} else {
		if err := validateTypedTarget(
			"kill-window", "Target", "session", s.sessionID.String(),
		); err != nil {
			return err
		}
		target = s.sessionID.String()
		if request.Index != nil {
			target += ":" + strconv.Itoa(*request.Index)
		}
	}

	result, err := s.server.literalCmd(ctx, "kill-window", "-t", target)
	return requireServerCommandNoStderr("kill-window", result, err)
}

// Kill destroys the stable window selected by the receiver's WindowID,
// removes all of its winlinks, and destroys its panes. Affected sessions
// preserve their current selection unless this window was current, in which
// case they select another. A session left without windows is destroyed;
// [Session.Kill] describes how tmux handles its clients. The receiver is not
// refreshed. Only stderr makes a completed command a [CommandError]; nonzero
// exits without stderr are ignored.
func (w Window) Kill(ctx context.Context) error {
	result, err := w.literalCmd(ctx, "kill-window")
	return requireServerCommandNoStderr("kill-window", result, err)
}

// KillOthers destroys every other stable window selected through the
// receiver's exact session and leaves the receiver as that session's current
// and only window. Links in other sessions are not selected merely because
// they share the receiver's [WindowID], but every selected stable window is
// removed from all sessions. Other affected sessions preserve their current
// selection unless a destroyed window was current, in which case they select
// another. A session left without windows is destroyed; [Session.Kill]
// describes how tmux handles its clients. The receiver is not refreshed. Only
// stderr makes a completed command a [CommandError]; nonzero exits without
// stderr are ignored.
func (w Window) KillOthers(ctx context.Context) error {
	target, err := exactWindowTarget(w)
	if err != nil {
		return err
	}
	result, err := w.server.literalCmd(ctx, "kill-window", "-t", target, "-a")
	return requireServerCommandNoStderr("kill-window", result, err)
}

// Kill destroys the receiver pane through its exact linked-pane target. If
// panes remain and the receiver was active, tmux selects another active pane.
// If this was the last pane, tmux also destroys the window and removes all of
// its winlinks. Affected sessions preserve their current selection unless the
// destroyed window was current, in which case they select another. A session
// left without windows is destroyed; [Session.Kill] describes how tmux handles
// its clients. The receiver is not refreshed. Only stderr makes a completed
// command a [CommandError]; nonzero exits without stderr are ignored.
func (p Pane) Kill(ctx context.Context) error {
	result, err := p.literalCmd(ctx, "kill-pane")
	return requireServerCommandNoStderr("kill-pane", result, err)
}

// KillOthers destroys every other pane in the receiver's stable window and
// leaves the receiver as its sole active pane. It does not select the exact
// winlink as its session's current window or promise client focus, and it does
// not destroy a window or session. The receiver is not refreshed. Only stderr
// makes a completed command a [CommandError]; nonzero exits without stderr are ignored.
func (p Pane) KillOthers(ctx context.Context) error {
	result, err := p.literalCmd(ctx, "kill-pane", "-a")
	return requireServerCommandNoStderr("kill-pane", result, err)
}

