package tmux

import (
	"context"
	"errors"
)

// Session performs a canonical live lookup of id and returns a newly
// materialized record. Use [Session.Refresh] when beginning from a record.
func (s Server) Session(ctx context.Context, id SessionID) (Session, error) {
	values, version, identity, err := s.livePoint(ctx, "session", "session_id", id.String(), "list-sessions", false)
	if err != nil {
		return Session{}, err
	}
	snapshot, err := newSnapshotWithIdentity(s, version, snapshotRecords{
		sessions: []formatValues{values},
	}, listedSessions, &identity)
	if err != nil {
		return Session{}, err
	}
	return snapshot.SessionByID(id)
}

// SessionByName performs a live lookup of the session tmux knows by name and
// returns a newly materialized record. A name no session holds reports
// [ErrNotFound].
//
// tmux keeps session names unique, so a name identifies one session for as
// long as it keeps it. A [SessionID] does not change, which is why the records
// this package hands back carry one and [Server.Session] takes one; a name is
// what a person types and what a workspace file records.
func (s Server) SessionByName(ctx context.Context, name string) (Session, error) {
	if err := validateLifecycleSessionName("name", name); err != nil {
		return Session{}, err
	}
	snapshot, err := s.searchSnapshot(
		ctx,
		"list-sessions",
		nil,
		nil,
		searchSessions,
		searchRowMatch{field: "session_name", value: name},
	)
	if err != nil {
		return Session{}, err
	}
	sessions := snapshot.Sessions()
	if len(sessions) != 1 {
		return Session{}, &SnapshotLookupError{
			Object:     "session",
			Identifier: name,
			Matches:    len(sessions),
		}
	}
	return sessions[0], nil
}

// Window performs a canonical live lookup of id using tmux's canonical session
// and returns a newly materialized record. It does not preserve a linked-session
// view; use [Window.ResolveSession] for that exact relationship.
func (s Server) Window(ctx context.Context, id WindowID) (Window, error) {
	values, version, identity, err := s.livePoint(ctx, "window", "window_id", id.String(), "list-windows", true)
	if err != nil {
		return Window{}, err
	}
	snapshot, err := newSnapshotWithIdentity(s, version, snapshotRecords{
		windows: []formatValues{values},
	}, listedWindows, &identity)
	if err != nil {
		return Window{}, err
	}
	return snapshot.WindowByID(id)
}

// Pane performs a canonical live lookup of id using tmux's canonical session
// and returns a newly materialized record. It does not preserve a linked-session
// view; use [Pane.ResolveWindow] for that exact relationship.
func (s Server) Pane(ctx context.Context, id PaneID) (Pane, error) {
	values, version, identity, err := s.livePoint(ctx, "pane", "pane_id", id.String(), "list-panes", true)
	if err != nil {
		return Pane{}, err
	}
	snapshot, err := newSnapshotWithIdentity(s, version, snapshotRecords{
		panes: []formatValues{values},
	}, listedPanes, &identity)
	if err != nil {
		return Pane{}, err
	}
	return snapshot.PaneByID(id)
}

// Client performs a canonical live lookup of name and returns a new record.
func (s Server) Client(ctx context.Context, name ClientName) (Client, error) {
	values, version, identity, err := s.livePoint(ctx, "client", "client_name", name.String(), "list-clients", false)
	if err != nil {
		return Client{}, err
	}
	snapshot, err := newSnapshotWithIdentity(s, version, snapshotRecords{
		clients: []formatValues{values},
	}, listedClients, &identity)
	if err != nil {
		return Client{}, err
	}
	return snapshot.ClientByName(name)
}

// Refresh performs a canonical live lookup without mutating the receiver.
func (s Session) Refresh(ctx context.Context) (Session, error) {
	return s.server.Session(ctx, s.sessionID)
}

// Refresh performs a canonical live lookup for the window's stable ID and
// returns a new record without mutating the receiver. It does not preserve a
// linked-session view; use [Window.ResolveSession] for exact relationships.
func (w Window) Refresh(ctx context.Context) (Window, error) {
	return w.server.Window(ctx, w.windowID)
}

// Refresh performs a canonical live lookup for the pane's stable ID and
// returns a new record without mutating the receiver. It does not preserve a
// linked-session view; use [Pane.ResolveWindow] for exact relationships.
func (p Pane) Refresh(ctx context.Context) (Pane, error) {
	return p.server.Pane(ctx, p.paneID)
}

// Refresh performs a canonical live lookup without mutating the receiver.
func (c Client) Refresh(ctx context.Context) (Client, error) {
	return c.server.Client(ctx, c.clientName)
}

func (s Server) livePoint(
	ctx context.Context,
	object string,
	identityField string,
	identifier string,
	command string,
	targeted bool,
) (formatValues, Version, snapshotServerIdentity, error) {
	return s.livePointWithTargetValidation(
		ctx,
		object,
		identityField,
		identifier,
		command,
		targeted,
		true,
	)
}

func (s Server) livePaneFromEnvironment(
	ctx context.Context,
	identifier string,
) (formatValues, Version, snapshotServerIdentity, error) {
	return s.livePointWithTargetValidation(
		ctx,
		"pane",
		"pane_id",
		identifier,
		"list-panes",
		true,
		false,
	)
}

func (s Server) livePointWithTargetValidation(
	ctx context.Context,
	object string,
	identityField string,
	identifier string,
	command string,
	targeted bool,
	validateTarget bool,
) (formatValues, Version, snapshotServerIdentity, error) {
	if validateTarget {
		if err := validateTypedTarget(command, identityField, object, identifier); err != nil {
			return formatValues{}, Version{}, snapshotServerIdentity{}, err
		}
	}
	identity, err := s.probeSnapshotIdentity(ctx)
	if err != nil {
		return formatValues{}, Version{}, snapshotServerIdentity{}, err
	}
	minimum, err := ParseVersion(MinimumSupportedVersion)
	if err != nil {
		return formatValues{}, Version{}, snapshotServerIdentity{}, err
	}
	if !identity.version.meetsMinimum(minimum) {
		return formatValues{}, Version{}, snapshotServerIdentity{}, &VersionTooLowError{
			Current: identity.version,
			Minimum: minimum,
		}
	}

	extra := make([]string, 0, 2)
	if targeted {
		extra = append(extra, "-t", identifier)
	}
	rows, err := s.snapshotListing(ctx, command, extra, identity.version)
	if err != nil {
		if targeted && targetNotFoundCommand(err) {
			return formatValues{}, Version{}, snapshotServerIdentity{}, s.liveLookupAbsence(
				ctx,
				identity,
				object,
				identifier,
				err,
			)
		}
		// An untargeted listing that named an object is describing something
		// other than the absence of the one asked for, which is why it is not
		// allowed to read as that absence.
		return formatValues{}, Version{}, snapshotServerIdentity{}, withoutAbsenceClaim(err)
	}

	matches := make([]formatValues, 0, 1)
	for _, row := range rows {
		if value, ok := row.get(identityField); ok && value == identifier {
			matches = append(matches, row)
		}
	}
	selected, err := selectLivePoint(matches, object, identifier, targeted)
	if err != nil {
		if errors.Is(err, ErrNotFound) {
			err = s.liveLookupAbsence(ctx, identity, object, identifier, nil)
		}
		return formatValues{}, Version{}, snapshotServerIdentity{}, err
	}
	closing, err := s.probeClosingIdentity(ctx, identity)
	if err != nil {
		return formatValues{}, Version{}, snapshotServerIdentity{}, err
	}
	if !sameSnapshotIdentity(identity, closing) {
		return formatValues{}, Version{}, snapshotServerIdentity{}, snapshotIdentityChangeError(closing)
	}
	return selected, identity.version, identity, nil
}

func (s Server) liveLookupAbsence(
	ctx context.Context,
	opening snapshotServerIdentity,
	object string,
	identifier string,
	listingErr error,
) error {
	closing, err := s.probeClosingIdentity(ctx, opening)
	if err != nil {
		if contextError(err) {
			return err
		}
		// The closing probe only guards against a second tmux server having
		// answered the listing that proved this absence. A probe that cannot
		// run at all rules that out rather than leaving it open, because a
		// server that has gone did not replace the one that answered, so the
		// absence stands and the probe's own failure adds nothing to report.
		return liveLookupError(object, identifier, 0)
	}
	if !sameSnapshotIdentity(opening, closing) {
		changeErr := snapshotIdentityChangeError(closing)
		if listingErr != nil {
			// A second daemon answered, so what the first one could not find
			// is no longer evidence that it is gone.
			return errors.Join(withoutAbsenceClaim(listingErr), changeErr)
		}
		return changeErr
	}
	return liveLookupError(object, identifier, 0)
}

func selectLivePoint(
	matches []formatValues,
	object string,
	identifier string,
	winlink bool,
) (formatValues, error) {
	if len(matches) == 0 {
		return formatValues{}, liveLookupError(object, identifier, 0)
	}
	if len(matches) == 1 {
		return matches[0], nil
	}
	if !winlink {
		return formatValues{}, liveLookupError(object, identifier, len(matches))
	}

	for _, row := range matches {
		if active, ok := row.get("window_active"); ok && active == "1" {
			return row, nil
		}
	}
	best := 0
	bestIndex, err := requiredSnapshotIndex(object, 0, matches[0], "window_index")
	if err != nil {
		return formatValues{}, err
	}
	for index := 1; index < len(matches); index++ {
		windowIndex, err := requiredSnapshotIndex(object, index, matches[index], "window_index")
		if err != nil {
			return formatValues{}, err
		}
		if windowIndex < bestIndex {
			best = index
			bestIndex = windowIndex
		}
	}
	return matches[best], nil
}

func targetNotFoundCommand(err error) bool {
	var commandError *CommandError
	return errors.As(err, &commandError) && commandError.targetNotFound
}

func liveLookupError(object, identifier string, matches int) *SnapshotLookupError {
	return &SnapshotLookupError{
		Object:     object,
		Identifier: identifier,
		Matches:    matches,
	}
}

func refreshExactActivePane(ctx context.Context, window Window) (Pane, error) {
	refreshed, err := refreshExactWindow(ctx, window)
	if err != nil {
		return Pane{}, err
	}
	pane, ok := refreshed.ActivePane()
	if !ok {
		return Pane{}, &SnapshotLookupError{
			Object: "active pane", Identifier: window.sessionID.String() + ":" + window.windowID.String(),
		}
	}
	return pane, nil
}

func refreshExactWindow(ctx context.Context, window Window) (Window, error) {
	snapshot, err := window.server.Snapshot(ctx)
	if err != nil {
		return Window{}, err
	}
	return exactWindowFromSnapshot(snapshot, window)
}

func refreshCreatedWindow(
	ctx context.Context,
	server Server,
	sessionID SessionID,
	windowID WindowID,
) (Window, error) {
	snapshot, err := server.Snapshot(ctx)
	if err != nil {
		return Window{}, err
	}
	return createdWindowFromSnapshot(snapshot, sessionID, windowID)
}

// refreshExactPane materializes the pane's own winlink view. It lists that
// one window's panes rather than taking a whole-server snapshot: the view
// wanted is the one in this window, which a point lookup would not promise
// for a linked window, and a snapshot's other listings answer nothing this
// asks.
func refreshExactPane(ctx context.Context, pane Pane) (Pane, error) {
	if _, err := validatePaneView(pane); err != nil {
		return Pane{}, err
	}
	target, err := exactPaneTarget(pane)
	if err != nil {
		return Pane{}, err
	}
	snapshot, err := pane.server.searchSnapshot(
		ctx,
		"list-panes",
		[]string{"-t", target},
		nil,
		searchPanes,
		searchRowMatch{field: "session_id", value: pane.sessionID.String()},
	)
	if err != nil {
		return Pane{}, err
	}
	return exactPaneFromSnapshot(snapshot, pane)
}

func refreshExactWindowSwap(
	ctx context.Context,
	result WindowSwapResult,
) (WindowSwapResult, error) {
	snapshot, err := result.Window.server.Snapshot(ctx)
	if err != nil {
		return WindowSwapResult{}, err
	}
	result.Window, err = exactWindowFromSnapshot(snapshot, result.Window)
	if err != nil {
		return WindowSwapResult{}, err
	}
	result.Target, err = exactWindowFromSnapshot(snapshot, result.Target)
	return result, err
}

func refreshExactPaneSwap(ctx context.Context, result PaneSwapResult) (PaneSwapResult, error) {
	snapshot, err := result.Pane.server.Snapshot(ctx)
	if err != nil {
		return PaneSwapResult{}, err
	}
	result.Pane, err = exactPaneFromSnapshot(snapshot, result.Pane)
	if err != nil || result.Target.paneID == "" {
		return result, err
	}
	result.Target, err = exactPaneFromSnapshot(snapshot, result.Target)
	return result, err
}

func exactWindowFromSnapshot(snapshot Snapshot, window Window) (Window, error) {
	identifier, err := validateWindowView(window)
	if err != nil {
		return Window{}, err
	}
	key := winlinkKey{
		sessionID: window.sessionID,
		windowID:  window.windowID,
		index:     window.windowIndex,
	}
	indexes := snapshot.state.windowsByWinlink[key]
	if len(indexes) == 0 {
		indexes = inSession(snapshot.state.windows, snapshot.state.windowsByID[window.windowID],
			window.sessionID, func(w Window) SessionID { return w.sessionID })
	}
	return lookupSnapshotValue(snapshot.state.windows, indexes, "window", identifier)
}

func exactPaneFromSnapshot(snapshot Snapshot, pane Pane) (Pane, error) {
	identifier, err := validatePaneView(pane)
	if err != nil {
		return Pane{}, err
	}
	key := paneViewKey{
		winlinkKey: winlinkKey{
			sessionID: pane.sessionID,
			windowID:  pane.windowID,
			index:     pane.windowIndex,
		},
		paneID: pane.paneID,
	}
	indexes := snapshot.state.panesByView[key]
	if len(indexes) == 0 {
		indexes = inSession(snapshot.state.panes, snapshot.state.panesByID[pane.paneID],
			pane.sessionID, func(p Pane) SessionID { return p.sessionID })
	}
	return lookupSnapshotValue(snapshot.state.panes, indexes, "pane", identifier)
}

// inSession narrows indexes to the views in session, for a record whose index
// or window moved after it was read: it is still the one view of that id in
// its session, unless the session links the window twice.
func inSession[T any](values []T, indexes []int, session SessionID, sessionOf func(T) SessionID) []int {
	var matches []int
	for _, index := range indexes {
		if sessionOf(values[index]) == session {
			matches = append(matches, index)
		}
	}
	return matches
}

func createdWindowFromSnapshot(
	snapshot Snapshot,
	sessionID SessionID,
	windowID WindowID,
) (Window, error) {
	matches := make([]Window, 0, 1)
	for _, window := range snapshot.WindowsByID(windowID) {
		if window.sessionID == sessionID {
			matches = append(matches, window)
		}
	}
	if len(matches) == 1 {
		return matches[0], nil
	}
	return Window{}, &SnapshotLookupError{
		Object:     "window",
		Identifier: sessionID.String() + ":" + windowID.String(),
		Matches:    len(matches),
	}
}

tmux/marshal.go.content:
package tmux

import (
	"encoding/json"
	"maps"
)

// marshalFormats renders format expansions as tmux returned them. A record
// materialized with no fields encodes an empty object rather than null, so a
// consumer can index it without a nil check.
func marshalFormats(values formatValues) map[string]string {
	if values.values == nil {
		return map[string]string{}
	}
	return maps.Clone(values.values)
}

// MarshalJSON encodes the format expansions as tmux returned them. Nothing
// decodes: [json.Unmarshal] into this type reports no error and changes
// nothing, because every field is unexported.
func (v FormatValues) MarshalJSON() ([]byte, error) {
	return json.Marshal(marshalFormats(v.values))
}

// MarshalJSON encodes the session's identity and the format expansions tmux
// returned for it, under "formats". Nothing decodes: a decoded record would
// carry no [Server], so it could name a session it could never act on, and
// [json.Unmarshal] into this type reports no error and changes nothing.
func (s Session) MarshalJSON() ([]byte, error) {
	return json.Marshal(struct {
		ID      SessionID         `json:"id"`
		Formats map[string]string `json:"formats"`
	}{ID: s.sessionID, Formats: marshalFormats(s.formats)})
}

// MarshalJSON encodes the window's identity, its place in the hierarchy, and
// the format expansions tmux returned for it. Nothing decodes; see
// [Session.MarshalJSON].
func (w Window) MarshalJSON() ([]byte, error) {
	return json.Marshal(struct {
		ID          WindowID          `json:"id"`
		SessionID   SessionID         `json:"sessionId"`
		WindowIndex int               `json:"windowIndex"`
		Formats     map[string]string `json:"formats"`
	}{
		ID:          w.windowID,
		SessionID:   w.sessionID,
		WindowIndex: w.windowIndex,
		Formats:     marshalFormats(w.formats),
	})
}

// MarshalJSON encodes the pane's identity, its place in the hierarchy, and the
// format expansions tmux returned for it. Nothing decodes; see
// [Session.MarshalJSON].
func (p Pane) MarshalJSON() ([]byte, error) {
	return json.Marshal(struct {
		ID          PaneID            `json:"id"`
		SessionID   SessionID         `json:"sessionId"`
		WindowID    WindowID          `json:"windowId"`
		WindowIndex int               `json:"windowIndex"`
		Index       int               `json:"index"`
		Formats     map[string]string `json:"formats"`
	}{
		ID:          p.paneID,
		SessionID:   p.sessionID,
		WindowID:    p.windowID,
		WindowIndex: p.windowIndex,
		Index:       p.paneIndex,
		Formats:     marshalFormats(p.formats),
	})
}

// MarshalJSON encodes the client's name and the format expansions tmux
// returned for it. Nothing decodes; see [Session.MarshalJSON].
func (c Client) MarshalJSON() ([]byte, error) {
	return json.Marshal(struct {
		Name    ClientName        `json:"name"`
		Formats map[string]string `json:"formats"`
	}{Name: c.clientName, Formats: marshalFormats(c.formats)})
}

// MarshalJSON encodes the snapshot's tmux version and the records it holds. A
// kind it listed encodes as an array, empty when tmux reported none; a kind it
// never listed is absent. Those are different answers, and one field cannot
// spell both, which is why the arrays are pointers here. Nothing decodes; see
// [Session.MarshalJSON].
func (s Snapshot) MarshalJSON() ([]byte, error) {
	encoded := struct {
		Version  string     `json:"version"`
		Sessions *[]Session `json:"sessions,omitempty"`
		Windows  *[]Window  `json:"windows,omitempty"`
		Panes    *[]Pane    `json:"panes,omitempty"`
		Clients  *[]Client  `json:"clients,omitempty"`
	}{Version: s.Version().String()}
	if s.state == nil {
		return json.Marshal(encoded)
	}
	if s.state.listed.holds(listedSessions) {
		listed := s.Sessions()
		encoded.Sessions = &listed
	}
	if s.state.listed.holds(listedWindows) {
		listed := s.Windows()
		encoded.Windows = &listed
	}
	if s.state.listed.holds(listedPanes) {
		listed := s.Panes()
		encoded.Panes = &listed
	}
	if s.state.listed.holds(listedClients) {
		listed := s.Clients()
		encoded.Clients = &listed
	}
	return json.Marshal(encoded)
}

