package tmux

// SessionID is tmux's stable session identifier, including its $ sigil. The
// zero value is not a usable tmux target.
type SessionID string

// String returns the tmux identifier verbatim.
func (id SessionID) String() string { return string(id) }

// WindowID is tmux's stable window identifier, including its @ sigil. It does
// not distinguish linked-session views; the zero value is not a usable target.
type WindowID string

// String returns the tmux identifier verbatim.
func (id WindowID) String() string { return string(id) }

// PaneID is tmux's stable pane identifier, including its % sigil. It does not
// distinguish linked-session views; the zero value is not a usable target.
type PaneID string

// String returns the tmux identifier verbatim.
func (id PaneID) String() string { return string(id) }

// ClientName is tmux's stable client name, normally its terminal path. The
// zero value is not a usable tmux target.
type ClientName string

// String returns the tmux client name verbatim.
func (name ClientName) String() string { return string(name) }

// Session is one materialized tmux session record. It is normally returned by
// [Server.Snapshot], [Server.Session], or [Session.Refresh]. A zero Session is
// not a usable tmux target.
type Session struct {
	formats   formatValues
	server    Server
	snapshot  *snapshotState
	sessionID SessionID
}

// ID returns the stable tmux identity of this session.
func (s Session) ID() SessionID { return s.sessionID }

// Server returns the immutable configured handle that produced the session.
func (s Session) Server() Server { return s.server }

func (s Session) withServer(server Server) Session {
	s.server = server
	return s
}

// Windows returns newly allocated shallow copies of this snapshot record's
// winlink views, and reports whether the receiver carries relations at all.
//
// It never queries tmux. [Server.Snapshot] and the resolvers carry relations; a
// targeted lookup, refresh, or creation reports false rather than an empty
// relation. Use [Session.SearchWindows] for current live windows.
func (s Session) Windows() ([]Window, bool) {
	if s.snapshot == nil || !s.snapshot.listed.holds(listedWindows) {
		return nil, false
	}
	return boundTo(
		valuesAt(s.snapshot.windows, s.snapshot.windowsBySession[s.sessionID]),
		Window.withServer,
		s.server,
	), true
}

// Panes returns newly allocated shallow copies of this snapshot record's pane
// views, and reports whether the receiver carries relations at all.
//
// It never queries tmux. [Server.Snapshot] and the resolvers carry relations; a
// targeted lookup, refresh, or creation reports false rather than an empty
// relation. Use [Session.SearchPanes] for current live panes.
func (s Session) Panes() ([]Pane, bool) {
	if s.snapshot == nil || !s.snapshot.listed.holds(listedPanes) {
		return nil, false
	}
	return boundTo(
		valuesAt(s.snapshot.panes, s.snapshot.panesBySession[s.sessionID]),
		Pane.withServer,
		s.server,
	), true
}

// Window is one materialized (session, index, window) winlink record. It is
// normally returned by [Server.Snapshot], [Server.Window], or [Window.Refresh].
// A zero Window is not a usable tmux target.
type Window struct {
	formats     formatValues
	server      Server
	snapshot    *snapshotState
	sessionID   SessionID
	windowID    WindowID
	windowIndex int
}

// SessionID returns the linked session containing this view.
func (w Window) SessionID() SessionID { return w.sessionID }

// ID returns the underlying stable tmux window identity.
func (w Window) ID() WindowID { return w.windowID }

// Index returns this window's index in its linked session. It returns -1 for
// a partial Window whose exact winlink has not been materialized.
func (w Window) Index() int { return w.windowIndex }

// Server returns the configured handle that produced the window.
func (w Window) Server() Server { return w.server }

func (w Window) withServer(server Server) Window {
	w.server = server
	return w
}

// Session returns this view's parent record when it remains in the same
// snapshot. It never queries tmux.
func (w Window) Session() (Session, bool) {
	if w.snapshot == nil {
		return Session{}, false
	}
	session, ok := oneAt(w.snapshot.sessions, w.snapshot.sessionsByID[w.sessionID])
	if !ok {
		return Session{}, false
	}
	return session.withServer(w.server), true
}

// Panes returns newly allocated shallow copies of panes for this exact winlink,
// and reports whether the receiver carries relations at all.
//
// It never queries tmux. [Server.Snapshot], the resolvers, and
// [Session.NewWindow] carry relations; a targeted lookup or refresh reports
// false instead. Use [Window.SearchPanes] for current live panes.
func (w Window) Panes() ([]Pane, bool) {
	if w.snapshot == nil || !w.snapshot.listed.holds(listedPanes) {
		return nil, false
	}
	key := winlinkKey{sessionID: w.sessionID, windowID: w.windowID, index: w.windowIndex}
	return boundTo(
		valuesAt(w.snapshot.panes, w.snapshot.panesByWinlink[key]),
		Pane.withServer,
		w.server,
	), true
}

// Pane is one materialized pane record within a specific winlink. It is
// normally returned by [Server.Snapshot], [Server.Pane], or [Pane.Refresh].
// A zero Pane is not a usable tmux target.
type Pane struct {
	formats     formatValues
	server      Server
	snapshot    *snapshotState
	sessionID   SessionID
	windowID    WindowID
	windowIndex int
	paneID      PaneID
	paneIndex   int
}

// SessionID returns the linked session containing this pane view.
func (p Pane) SessionID() SessionID { return p.sessionID }

// WindowID returns the underlying stable tmux window identity.
func (p Pane) WindowID() WindowID { return p.windowID }

// WindowIndex returns this pane view's window index in its linked session.
func (p Pane) WindowIndex() int { return p.windowIndex }

// ID returns the stable tmux pane identity.
func (p Pane) ID() PaneID { return p.paneID }

// Index returns the pane's index in its exact window view. Unlike the
// materialized format accessors it sits beside, it returns a plain int, because
// a pane record always carries the index tmux placed it at.
func (p Pane) Index() int { return p.paneIndex }

// Server returns the configured handle that produced the pane.
func (p Pane) Server() Server { return p.server }

func (p Pane) withServer(server Server) Pane {
	p.server = server
	return p
}

// Session returns this view's parent record when it remains in the same
// snapshot. It never queries tmux.
func (p Pane) Session() (Session, bool) {
	if p.snapshot == nil {
		return Session{}, false
	}
	session, ok := oneAt(p.snapshot.sessions, p.snapshot.sessionsByID[p.sessionID])
	if !ok {
		return Session{}, false
	}
	return session.withServer(p.server), true
}

// Window returns this pane's exact winlink record when it remains in the same
// snapshot. It never queries tmux.
func (p Pane) Window() (Window, bool) {
	if p.snapshot == nil {
		return Window{}, false
	}
	key := winlinkKey{sessionID: p.sessionID, windowID: p.windowID, index: p.windowIndex}
	window, ok := oneAt(p.snapshot.windows, p.snapshot.windowsByWinlink[key])
	if !ok {
		return Window{}, false
	}
	return window.withServer(p.server), true
}

// Client is one materialized tmux client record. It is normally returned by
// [Server.Snapshot], [Server.Client], or [Client.Refresh]. A zero Client is not
// a usable tmux target.
type Client struct {
	formats    formatValues
	server     Server
	snapshot   *snapshotState
	clientName ClientName
	attachment clientAttachment
}

type clientAttachment struct {
	sessionID   SessionID
	windowID    WindowID
	windowIndex int
	paneID      PaneID
	hasSession  bool
	hasWindow   bool
	hasPane     bool
}

// Server returns the configured handle that produced the client.
func (c Client) Server() Server { return c.server }

// Name returns the stable tmux name of this client.
func (c Client) Name() ClientName { return c.clientName }

// AttachedSession returns the materialized attached session, if present in the
// same snapshot. It never queries tmux.
func (c Client) AttachedSession() (Session, bool) {
	if c.snapshot == nil || !c.attachment.hasSession {
		return Session{}, false
	}
	session, ok := oneAt(c.snapshot.sessions, c.snapshot.sessionsByID[c.attachment.sessionID])
	if !ok {
		return Session{}, false
	}
	return session.withServer(c.server), true
}

// AttachedWindow returns the client's exact materialized winlink, if present
// in the same snapshot. It never queries tmux.
func (c Client) AttachedWindow() (Window, bool) {
	if c.snapshot == nil || !c.attachment.hasWindow {
		return Window{}, false
	}
	key := winlinkKey{
		sessionID: c.attachment.sessionID,
		windowID:  c.attachment.windowID,
		index:     c.attachment.windowIndex,
	}
	window, ok := oneAt(c.snapshot.windows, c.snapshot.windowsByWinlink[key])
	if !ok {
		return Window{}, false
	}
	return window.withServer(c.server), true
}

// AttachedPane returns the client's exact materialized pane view, if present
// in the same snapshot. It never queries tmux.
func (c Client) AttachedPane() (Pane, bool) {
	if c.snapshot == nil || !c.attachment.hasPane {
		return Pane{}, false
	}
	key := paneViewKey{
		winlinkKey: winlinkKey{
			sessionID: c.attachment.sessionID,
			windowID:  c.attachment.windowID,
			index:     c.attachment.windowIndex,
		},
		paneID: c.attachment.paneID,
	}
	pane, ok := oneAt(c.snapshot.panes, c.snapshot.panesByView[key])
	if !ok {
		return Pane{}, false
	}
	return pane.withServer(c.server), true
}

// boundTo keeps relations on the server handle selected by the parent record.
func boundTo[T any](values []T, bind func(T, Server) T, server Server) []T {
	for index := range values {
		values[index] = bind(values[index], server)
	}
	return values
}

func valuesAt[T any](values []T, indexes []int) []T {
	result := make([]T, len(indexes))
	for index, source := range indexes {
		result[index] = values[source]
	}
	return result
}

func oneAt[T any](values []T, indexes []int) (T, bool) {
	if len(indexes) != 1 {
		var zero T
		return zero, false
	}
	return values[indexes[0]], true
}

tmux/notification_stream.go.content:
package tmux

import (
	"context"
	"errors"
	"iter"
	"strconv"
	"strings"
	"time"
)

// NotificationStream owns one observation-only control client attached to a
// session. It yields tmux notifications in wire order and must be closed.
// Before tmux 3.6, destroying the attached session follows that session's
// detach-on-destroy policy and may end the stream.
//
// A stream ends in one of three ways, and none can be resumed. A stream is one
// tmux client, so a new one is a new client: it starts at tmux's present, with
// no subscriptions armed, no pane held by PauseAfter, and none of what the old
// stream had queued or tmux sent in the gap. To recover, close the old stream,
// read whatever state matters from tmux directly, open another with
// [Server.OpenNotifications] or [Session.OpenNotifications], and Subscribe
// again. [ControlClient.Reconnect] is not offered here because it would have to
// choose between dropping the subscriptions silently and replaying commands,
// which the package never does.
//
//   - The caller closed it: reads return an error matching [ErrControlClosed]
//     and [os.ErrClosed].
//   - tmux ended it, because the server exited or the client fell too far
//     behind: reads return an error matching [ErrControlClosed] and
//     [ErrControlStreamLost], after the notifications queued before the end.
//   - Its backlog filled: reads return a [ControlNotificationOverflowError]
//     matching [ErrControlNotificationOverflow] after the queued prefix. The
//     process is still running and tmux keeps sending, but everything after
//     the overflow is dropped; close the stream.
type NotificationStream struct {
	client *ControlClient
}

// NotificationOptions configures which notifications a stream receives. The
// zero value retains notifications other than pane output.
type NotificationOptions struct {
	// IncludePaneOutput includes output and extended-output notifications.
	IncludePaneOutput bool
	// PauseAfter asks tmux to hold a pane's output once this stream is that
	// far behind on it, and to say so with a pause notification. Zero leaves
	// tmux's own behavior, which ends a stream that falls five minutes behind
	// rather than pausing it. tmux resolves this to whole seconds, and it
	// governs pane output, so it requires IncludePaneOutput.
	PauseAfter time.Duration
	// BacklogBytes bounds the notifications this stream holds while the caller
	// is not reading, counting each notification's text and a small fixed
	// overhead. Zero means 16 MiB. Once a notification would cross the bound,
	// reads return the queued prefix and then
	// ErrControlNotificationOverflow. A larger bound trades memory for
	// headroom on a chatty pane; a smaller one makes a slow reader fail sooner.
	// It may not be below 64 KiB.
	BacklogBytes int
}

// minNotificationBacklog is the smallest bound BacklogBytes accepts, well above
// the largest single notification tmux sends.
const minNotificationBacklog = 64 << 10

func (o NotificationOptions) backlog() int {
	if o.BacklogBytes == 0 {
		return defaultControlNotificationLimit
	}
	return o.BacklogBytes
}

func (o NotificationOptions) validate() error {
	if o.BacklogBytes != 0 && o.BacklogBytes < minNotificationBacklog {
		return invalidServerCommandRequest(
			"refresh-client", "BacklogBytes", strconv.Itoa(o.BacklogBytes),
			"is below the 65536 byte minimum; zero selects the default",
		)
	}
	if o.PauseAfter == 0 {
		return nil
	}
	if o.PauseAfter < time.Second {
		return invalidServerCommandRequest(
			"refresh-client", "PauseAfter", o.PauseAfter.String(),
			"is below the whole second tmux resolves this flag to",
		)
	}
	if !o.IncludePaneOutput {
		return invalidServerCommandRequest(
			"refresh-client", "PauseAfter", o.PauseAfter.String(),
			"holds pane output, which this stream does not receive without IncludePaneOutput",
		)
	}
	return nil
}

// OpenNotifications starts an owned observation-only stream attached to
// session. Session must belong to the same configured server selector. A
// connection-bound server returns [ErrConnectionRequiresProcess].
//
// The stream starts at tmux's present and holds nothing from before it opened.
// When it ends or overflows it cannot be resumed; open another, as described
// on [NotificationStream], and arm its subscriptions again.
func (s Server) OpenNotifications(
	ctx context.Context,
	session Session,
	options NotificationOptions,
) (*NotificationStream, error) {
	profile := controlNotificationsNoPaneOutput
	if options.IncludePaneOutput {
		profile = controlNotificationsFull
	}
	if err := options.validate(); err != nil {
		return nil, err
	}
	client, err := s.openControlWithBacklog(ctx, session, profile, options.backlog())
	if err != nil {
		return nil, err
	}
	stream := &NotificationStream{client: client}
	if options.PauseAfter > 0 {
		if err := stream.armPause(ctx, options.PauseAfter); err != nil {
			return nil, errors.Join(err, client.CloseContext(ctx))
		}
	}
	return stream, nil
}

// armPause arms tmux's per-pane hold for this stream's own client.
func (s *NotificationStream) armPause(ctx context.Context, after time.Duration) error {
	_, err := s.client.Cmd(ctx, "refresh-client", "-f",
		"pause-after="+strconv.Itoa(int(after/time.Second)))
	return err
}

// ContinuePane resumes pane output tmux held after this stream fell behind on
// it. tmux does not replay what it held, so read the pane to recover that span
// rather than waiting for it. Resuming a pane tmux never paused does nothing
// and reports nothing, because tmux answers neither.
func (s *NotificationStream) ContinuePane(ctx context.Context, pane PaneID) error {
	if s == nil || s.client == nil {
		return ErrControlClosed
	}
	// tmux discards a resume argument it cannot parse without reporting it, so
	// an unusable identifier would leave the pane held with nothing to show why.
	if !resumablePaneID(pane) {
		return invalidServerCommandRequest(
			"refresh-client", "Pane", pane.String(),
			"is not a pane identifier tmux will resume, such as %1",
		)
	}
	_, err := s.client.Cmd(ctx, "refresh-client", "-A", pane.String()+":continue")
	return err
}

// SubscriptionRequest names a format for tmux to evaluate and report on this
// stream whenever its value changes. Its zero value is invalid because Name and
// Format are required. At most one of Window and Pane scopes the evaluation;
// neither evaluates against the stream's attached session, which tmux
// always uses for a session-scoped subscription and which cannot be selected.
//
// tmux stops evaluating a pane-scoped subscription once that pane's process has
// exited, so a subscription that must observe pane death is scoped to the
// window and reads the pane from the change it reports.
type SubscriptionRequest struct {
	// Name identifies the subscription in each change and to Unsubscribe. It
	// may not contain a colon or a space.
	Name string
	// Format is the tmux format to evaluate, such as #{pane_current_command}.
	Format string
	// Window scopes evaluation to one window.
	Window WindowID
	// Pane scopes evaluation to one pane.
	Pane PaneID
}

func (r SubscriptionRequest) validate() error {
	if r.Name == "" {
		return invalidServerCommandRequest("refresh-client", "Name", "", "is required")
	}
	if strings.ContainsAny(r.Name, ": ") {
		return invalidServerCommandRequest(
			"refresh-client", "Name", r.Name,
			"may not contain a colon or a space, which tmux reads as the scope",
		)
	}
	if err := validateServerCommandArgument("refresh-client", "Name", r.Name, true); err != nil {
		return err
	}
	if r.Format == "" {
		return invalidServerCommandRequest("refresh-client", "Format", "", "is required")
	}
	if err := validateServerCommandArgument("refresh-client", "Format", r.Format, true); err != nil {
		return err
	}
	if r.Window != "" && r.Pane != "" {
		return invalidServerCommandRequest(
			"refresh-client", "Scope", "", "selects both Window and Pane",
		)
	}
	return nil
}

// scope renders the target segment of refresh-client -B's
// name:target:format grammar. Session scope has no target of its own - tmux
// always evaluates it against the control client's attached session - so it
// renders empty, like the unscoped default. tmux 3.8 tightened that grammar
// to require target be exactly empty for session scope; anything else that is
// not a pane or window form, including a literal session ID, is now a parse
// failure that silently drops the subscription (monitor_parse in monitor.c).
// Earlier tmux was permissive there, so this also matches every older,
// supported version.
func (r SubscriptionRequest) scope() string {
	switch {
	case r.Window != "":
		return r.Window.String()
	case r.Pane != "":
		return r.Pane.String()
	}
	return ""
}

// Subscribe asks tmux to evaluate request's format and report it on this
// stream as a subscription-changed notification, read with
// [ControlNotification.Subscription]. tmux reports the value at its next
// evaluation, about a second later, and then each time it changes. Arming a
// name already armed replaces its format.
func (s *NotificationStream) Subscribe(ctx context.Context, request SubscriptionRequest) error {
	if s == nil || s.client == nil {
		return ErrControlClosed
	}
	if err := request.validate(); err != nil {
		return err
	}
	_, err := s.client.Cmd(ctx, "refresh-client", "-B",
		request.Name+":"+request.scope()+":"+request.Format)
	return err
}

// Unsubscribe stops the subscription armed under name. Stopping a name that
// was never armed does nothing and reports nothing, because tmux answers
// neither.
func (s *NotificationStream) Unsubscribe(ctx context.Context, name string) error {
	if s == nil || s.client == nil {
		return ErrControlClosed
	}
	if name == "" || strings.ContainsAny(name, ": ") {
		return invalidServerCommandRequest(
			"refresh-client", "Name", name, "is not a subscription name",
		)
	}
	if err := validateServerCommandArgument("refresh-client", "Name", name, true); err != nil {
		return err
	}
	_, err := s.client.Cmd(ctx, "refresh-client", "-B", name)
	return err
}

// resumablePaneID reports whether tmux's resume parser accepts id, which needs
// a per cent sign and then digits.
func resumablePaneID(id PaneID) bool {
	digits, ok := strings.CutPrefix(string(id), "%")
	if !ok || digits == "" {
		return false
	}
	return !strings.ContainsFunc(digits, func(r rune) bool { return r < '0' || r > '9' })
}

// OpenNotifications starts an owned notification stream attached to the
// receiver. It does not change the receiver's transport or expose control
// commands. A connection-bound receiver returns [ErrConnectionRequiresProcess].
func (s Session) OpenNotifications(
	ctx context.Context,
	options NotificationOptions,
) (*NotificationStream, error) {
	return s.server.OpenNotifications(ctx, s, options)
}

// Next returns the next ordered control-mode notification. Concurrent calls are
// serialized: each notification goes to exactly one call, and a call waiting
// its turn returns when ctx ends.
//
// A stream that has ended reports why: see [NotificationStream] for the errors
// to match. A caller that wants to treat every end alike writes
// errors.Is(err, [ErrControlClosed]).
func (s *NotificationStream) Next(
	ctx context.Context,
) (ControlNotification, error) {
	if s == nil || s.client == nil {
		return ControlNotification{}, ErrControlClosed
	}
	return s.client.NextNotification(ctx)
}

// Notifications returns [NotificationStream.Next] as a range loop; reads from
// several iterators or direct calls are serialized. Malformed notifications yield
// their error and iteration continues; every other error ends the loop after
// being yielded.
func (s *NotificationStream) Notifications(
	ctx context.Context,
) iter.Seq2[ControlNotification, error] {
	return notificationSeq(ctx, s.Next)
}

// CloseContext starts idempotent stream shutdown and waits within ctx. The
// context bounds only the wait; a later call may resume waiting for shutdown.
func (s *NotificationStream) CloseContext(ctx context.Context) error {
	if s == nil || s.client == nil {
		return ErrControlClosed
	}
	return s.client.CloseContext(ctx)
}

// Close stops the notification stream. It is safe to call concurrently and
// more than once.
func (s *NotificationStream) Close() error {
	if s == nil || s.client == nil {
		return ErrControlClosed
	}
	return s.client.Close()
}

tmux/observer.go.content:
package tmux

import (
	"fmt"
	"time"
)

// CommandTransport names how one tmux command reached tmux.
type CommandTransport uint8

const (
	// CommandTransportProcess ran the command as its own tmux process.
	CommandTransportProcess CommandTransport = iota
	// CommandTransportConnection carried the command over a control-mode
	// connection opened earlier.
	CommandTransportConnection
)

// String implements fmt.Stringer.
func (t CommandTransport) String() string {
	switch t {
	case CommandTransportProcess:
		return "process"
	case CommandTransportConnection:
		return "connection"
	default:
		return fmt.Sprintf("CommandTransport(%d)", uint8(t))
	}
}

// CommandTrace records one completed attempt to run a tmux command. It carries
// neither the argument vector nor tmux's output, both of which may hold
// passwords, tokens, or pane contents; [CommandError] is where a caller that
// accepts that reads them.
type CommandTrace struct {
	// Subcommand is the tmux subcommand, such as "list-sessions". A raw
	// command list reports its first subcommand.
	Subcommand string
	// Transport names how the command reached tmux.
	Transport CommandTransport
	// Duration is how long the attempt took.
	Duration time.Duration
	// ExitCode is tmux's exit code, or -1 when no tmux command ran.
	ExitCode int
	// Err is the transport or validation failure, if any. A completed tmux
	// command that failed leaves this nil and reports through ExitCode.
	Err error
}

// String implements fmt.Stringer.
func (t CommandTrace) String() string {
	if t.Err != nil {
		return fmt.Sprintf("tmux %s over %s failed after %s: %v",
			t.Subcommand, t.Transport, t.Duration, t.Err)
	}
	return fmt.Sprintf("tmux %s over %s exited %d after %s",
		t.Subcommand, t.Transport, t.ExitCode, t.Duration)
}

// CommandObserver receives one [CommandTrace] per tmux command a [Server] and
// the values derived from it run:
//
//	server, err := tmux.NewServer(tmux.ServerOptions{
//		CommandObserver: func(trace tmux.CommandTrace) {
//			slog.Info("tmux", "command", trace.Subcommand,
//				"transport", trace.Transport.String(),
//				"duration", trace.Duration, "exit", trace.ExitCode)
//		},
//	})
//	if err != nil {
//		log.Fatal(err)
//	}
//
// It is called synchronously on the goroutine that ran the command, after the
// command finishes and before its result is returned, so a slow observer slows
// every command. Operations may invoke it concurrently; synchronize shared
// state. A nil observer costs nothing, not even the clock reads.
//
// It sees the version probes this package runs on its own behalf, and the
// identity probe a daemon guard runs to decide whether a failure was a
// replaced daemon, so one call can produce more than one trace.
type CommandObserver func(CommandTrace)

// observeCommand reports one finished command. subcommand is read from the
// arguments the caller asked for rather than the ones sent, so a daemon guard
// wrapping them does not become the reported command.
func observeCommand(
	observer CommandObserver,
	args []string,
	started time.Time,
	transport CommandTransport,
	exitCode int,
	err error,
) {
	subcommand := ""
	if len(args) > 0 {
		subcommand = args[0]
	}
	observer(CommandTrace{
		Subcommand: subcommand,
		Transport:  transport,
		Duration:   time.Since(started),
		ExitCode:   exitCode,
		Err:        err,
	})
}

// commandObserver returns the observer this server reports to, or nil.
func (s Server) commandObserver() CommandObserver {
	if s.state == nil {
		return nil
	}
	return s.state.config.commandObserver
}

// commandTransport names how this server's own commands reach tmux.
func (s Server) commandTransport() CommandTransport {
	if s.connection != nil {
		return CommandTransportConnection
	}
	return CommandTransportProcess
}

tmux/option_decode.go.content:
package tmux

import (
	"bytes"
	"cmp"
	"errors"
	"fmt"
	"slices"
	"strconv"
	"strings"

	"github.com/libtmux/libtmux-go/tmux/internal/tmuxcmd"
)

// ErrMalformedOptionOutput classifies [OptionDecodeError] through errors.Is.
var (
	// ErrMalformedOptionOutput identifies a recognized option or hook record
	// that cannot be decoded without ambiguity. It is matched by errors.Is for
	// OptionDecodeError.
	ErrMalformedOptionOutput         = errors.New("tmux: malformed option output")
	errMalformedArgsEscapedValue     = errors.New("tmux: malformed args_escape value")
	errMalformedTargetedOptionOutput = errors.New(
		"tmux: malformed targeted option output",
	)
)

// OptionDecodeError reports a malformed recognized record without retaining
// its value. It matches [ErrMalformedOptionOutput] through errors.Is; callers
// can recover Record and Reason with errors.As. Record is the zero-based
// physical output line.
type OptionDecodeError struct {
	// Record is the zero-based physical output line.
	Record int
	// Reason describes the malformed record without retaining its value.
	Reason string
}

// Error implements error.
func (e *OptionDecodeError) Error() string {
	return fmt.Sprintf("%v: record %d: %s", ErrMalformedOptionOutput, e.Record, e.Reason)
}

// Unwrap makes OptionDecodeError compatible with ErrMalformedOptionOutput.
func (e *OptionDecodeError) Unwrap() error { return ErrMalformedOptionOutput }

type optionVersionBoundaryError struct {
	kind error
}

func (e *optionVersionBoundaryError) Error() string {
	return fmt.Sprintf("%v: tmux version boundary is malformed", ErrMalformedOptionOutput)
}

func (e *optionVersionBoundaryError) Unwrap() []error {
	return []error{ErrMalformedOptionOutput, e.kind}
}

type decodedOptionValue struct {
	name              string
	origin            OptionOrigin
	boolValue         bool
	int64Value        int64
	stringValue       string
	sparseStringValue SparseArray[string]
}

type decodedOptionAccumulator struct {
	definition generatedOptionDefinition
	ordinal    int
	record     int
	origin     OptionOrigin
	value      decodedOptionValue
	entries    []SparseEntry[string]
	bare       bool
	seen       bool
}

type decodedOptionKey struct {
	base      string
	index     int
	indexed   bool
	inherited bool
	valid     bool
}

// optionValueDecodeError omits serialized option data because values may be secret.
type optionValueDecodeError struct {
	kind   error
	offset int
	reason string
}

func (e *optionValueDecodeError) Error() string {
	return fmt.Sprintf("%v at byte %d: %s", e.kind, e.offset, e.reason)
}

func (e *optionValueDecodeError) Unwrap() error {
	return e.kind
}

func decodeArgsEscapedValue(serialized []byte) (string, error) {
	decoded, err := decodeArgsEscapedBytes(serialized)
	if err != nil {
		return "", err
	}
	return tmuxcmd.DecodeBackslashReplace(decoded), nil
}

func decodeArgsEscapedBytes(serialized []byte) ([]byte, error) {
	if len(serialized) == 0 {
		return nil, newOptionValueDecodeError(
			errMalformedArgsEscapedValue,
			0,
			"missing serialized value",
		)
	}

	body := serialized
	bodyOffset := 0
	quote := byte(0)
	if serialized[0] == '\'' || serialized[0] == '"' {
		quote = serialized[0]
		if len(serialized) < 2 || serialized[len(serialized)-1] != quote {
			return nil, newOptionValueDecodeError(
				errMalformedArgsEscapedValue,
				0,
				"unmatched outer quote",
			)
		}
		body = serialized[1 : len(serialized)-1]
		bodyOffset = 1
	}

	decoded := make([]byte, 0, len(body))
	for index := 0; index < len(body); index++ {
		current := body[index]
		if current == '\'' || current == '"' {
			if quote == 0 || current == quote {
				return nil, newOptionValueDecodeError(
					errMalformedArgsEscapedValue,
					bodyOffset+index,
					"unexpected unescaped quote",
				)
			}
		}
		if current != '\\' {
			decoded = append(decoded, current)
			continue
		}

		if index+1 >= len(body) {
			return nil, newOptionValueDecodeError(
				errMalformedArgsEscapedValue,
				bodyOffset+index,
				"dangling escape",
			)
		}
		escaped := body[index+1]
		if isOctalDigit(escaped) {
			if index+3 >= len(body) ||
				!isOctalDigit(body[index+2]) ||
				!isOctalDigit(body[index+3]) {
				return nil, newOptionValueDecodeError(
					errMalformedArgsEscapedValue,
					bodyOffset+index,
					"octal escape must contain exactly three digits",
				)
			}
			value := (int(escaped-'0') << 6) |
				(int(body[index+2]-'0') << 3) |
				int(body[index+3]-'0')
			if value > 0xff {
				return nil, newOptionValueDecodeError(
					errMalformedArgsEscapedValue,
					bodyOffset+index,
					"octal escape exceeds one byte",
				)
			}
			decoded = append(decoded, byte(value))
			index += 3
			continue
		}

		decoded = append(decoded, decodeArgsCStyleEscape(escaped))
		index++
	}
	return decoded, nil
}

func decodeArgsCStyleEscape(value byte) byte {
	switch value {
	case 'a':
		return '\a'
	case 'b':
		return '\b'
	case 'f':
		return '\f'
	case 'n':
		return '\n'
	case 'r':
		return '\r'
	case 's':
		return ' '
	case 't':
		return '\t'
	case 'v':
		return '\v'
	case 'E':
		return 0x1b
	default:
		return value
	}
}

func isOctalDigit(value byte) bool {
	return value >= '0' && value <= '7'
}

func decodeTargetedOptionOutput(raw []byte) (string, error) {
	if len(raw) == 0 || raw[len(raw)-1] != '\n' {
		return "", newOptionValueDecodeError(
			errMalformedTargetedOptionOutput,
			len(raw),
			"missing terminal line feed",
		)
	}
	return tmuxcmd.DecodeBackslashReplace(raw[:len(raw)-1]), nil
}

func newOptionValueDecodeError(kind error, offset int, reason string) *optionValueDecodeError {
	return &optionValueDecodeError{kind: kind, offset: offset, reason: reason}
}

func decodeOptionOutput(
	raw []byte,
	definitions []generatedOptionDefinition,
	scope generatedOptionScope,
	hooks bool,
	version *Version,
) ([]decodedOptionValue, error) {
	if len(raw) == 0 {
		return make([]decodedOptionValue, 0), nil
	}
	if raw[len(raw)-1] != '\n' {
		return nil, &OptionDecodeError{
			Record: bytes.Count(raw, []byte{'\n'}),
			Reason: "missing terminal line feed",
		}
	}

	type catalogEntry struct {
		definition generatedOptionDefinition
		ordinal    int
	}
	catalog := make(map[string]catalogEntry, len(definitions))
	for ordinal, definition := range definitions {
		if generatedDefinitionSupportsScope(definition, scope) {
			catalog[definition.name] = catalogEntry{definition: definition, ordinal: ordinal}
		}
	}

	lines := bytes.Split(raw[:len(raw)-1], []byte{'\n'})
	values := make([]decodedOptionValue, 0, len(catalog))
	seenDefinitions := make(map[int]struct{}, len(catalog))
	var current *decodedOptionAccumulator
	for record, line := range lines {
		keyBytes, serialized, hasValue := bytes.Cut(line, []byte{' '})
		key := parseDecodedOptionKey(string(keyBytes))
		entry, known := catalog[key.base]
		if !known {
			continue
		}
		if !key.valid {
			return nil, newBulkOptionDecodeError(record, "recognized record has malformed key")
		}
		if generatedDefinitionScopeVariesByVersion(entry.definition, scope) {
			if version == nil {
				return nil, newBulkOptionDecodeError(record, "recognized record requires a tmux version boundary")
			}
			if !generatedDefinitionSupportsVersionScope(entry.definition, *version, scope) {
				return nil, newBulkOptionDecodeError(record, "recognized record is unsupported at this tmux version and scope")
			}
		}

		if current == nil || entry.ordinal != current.ordinal {
			if _, seen := seenDefinitions[entry.ordinal]; seen {
				return nil, newBulkOptionDecodeError(record, "recognized records are not contiguous")
			}
			if current != nil {
				value, err := finishDecodedOption(*current)
				if err != nil {
					return nil, err
				}
				values = append(values, value)
			}
			seenDefinitions[entry.ordinal] = struct{}{}
			current = &decodedOptionAccumulator{
				definition: entry.definition,
				ordinal:    entry.ordinal,
				record:     record,
				origin:     OptionOriginLocal,
				value:      decodedOptionValue{name: entry.definition.name},
				entries:    make([]SparseEntry[string], 0),
			}
		}

		origin := OptionOriginLocal
		if key.inherited {
			origin = OptionOriginInherited
		}
		if current.seen && current.origin != origin {
			return nil, newBulkOptionDecodeError(record, "recognized array records mix origins")
		}
		current.origin = origin

		if !entry.definition.array {
			if current.seen {
				return nil, newBulkOptionDecodeError(record, "recognized scalar is repeated")
			}
			if key.indexed {
				return nil, newBulkOptionDecodeError(record, "recognized scalar has an array index")
			}
			if !hasValue {
				return nil, newBulkOptionDecodeError(record, "recognized scalar is missing its value")
			}
			if err := decodeScalarOptionValue(&current.value, entry.definition, serialized); err != nil {
				return nil, newBulkOptionDecodeError(record, "recognized scalar value is malformed")
			}
			current.seen = true
			continue
		}

		if !key.indexed {
			if current.seen {
				return nil, newBulkOptionDecodeError(record, "recognized array mixes bare and indexed records")
			}
			empty, err := decodeArrayOptionElement(serialized, hasValue, hooks, true)
			if err != nil || empty != "" {
				return nil, newBulkOptionDecodeError(record, "recognized bare array is not empty")
			}
			current.bare = true
			current.seen = true
			continue
		}
		if current.bare {
			return nil, newBulkOptionDecodeError(record, "recognized array mixes bare and indexed records")
		}
		if !hasValue {
			return nil, newBulkOptionDecodeError(record, "recognized indexed array value is missing")
		}
		if len(current.entries) != 0 && key.index <= current.entries[len(current.entries)-1].Index {
			return nil, newBulkOptionDecodeError(record, "recognized array indices are not unique and ascending")
		}
		value, err := decodeArrayOptionElement(serialized, true, hooks, false)
		if err != nil {
			return nil, newBulkOptionDecodeError(record, "recognized array value is malformed")
		}
		current.entries = append(current.entries, SparseEntry[string]{Index: key.index, Value: value})
		current.seen = true
	}

	if current != nil {
		value, err := finishDecodedOption(*current)
		if err != nil {
			return nil, err
		}
		values = append(values, value)
	}
	slices.SortFunc(values, func(left, right decodedOptionValue) int {
		return cmp.Compare(catalog[left.name].ordinal, catalog[right.name].ordinal)
	})
	return values, nil
}

func parseDecodedOptionKey(raw string) decodedOptionKey {
	key := decodedOptionKey{valid: true}
	if strings.HasSuffix(raw, "*") {
		key.inherited = true
		raw = strings.TrimSuffix(raw, "*")
	}
	if open := strings.LastIndexByte(raw, '['); open >= 0 {
		key.base = raw[:open]
		if open == 0 || !strings.HasSuffix(raw, "]") || strings.ContainsAny(raw[:open], "[]*") {
			key.valid = false
			return key
		}
		indexText := raw[open+1 : len(raw)-1]
		index, err := strconv.Atoi(indexText)
		if err != nil || index < 0 {
			key.valid = false
			return key
		}
		key.index = index
		key.indexed = true
		return key
	}
	key.base = raw
	if raw == "" || strings.ContainsAny(raw, "]*") {
		key.valid = false
	}
	return key
}

func generatedDefinitionSupportsScope(
	definition generatedOptionDefinition,
	scope generatedOptionScope,
) bool {
	for _, variant := range definition.variants {
		if variant.scopes&scope != 0 {
			return true
		}
	}
	return false
}

// generatedDefinitionScopeNames names the scopes a definition does carry, so a
// refusal can say where the option lives rather than only that it is not here.
func generatedDefinitionScopeNames(definition generatedOptionDefinition) string {
	var scopes generatedOptionScope
	for _, variant := range definition.variants {
		scopes |= variant.scopes
	}
	names := make([]string, 0, 4)
	for _, candidate := range []struct {
		scope generatedOptionScope
		name  string
	}{
		{generatedOptionScopeServer, "server"},
		{generatedOptionScopeSession, "session"},
		{generatedOptionScopeWindow, "window"},
		{generatedOptionScopePane, "pane"},
	} {
		if scopes&candidate.scope != 0 {
			names = append(names, candidate.name)
		}
	}
	switch len(names) {
	case 0:
		return ""
	case 1:
		return names[0] + " options"
	default:
		return strings.Join(names[:len(names)-1], ", ") +
			" and " + names[len(names)-1] + " options"
	}
}

func generatedDefinitionSupportsVersionScope(
	definition generatedOptionDefinition,
	version Version,
	scope generatedOptionScope,
) bool {
	var active *generatedOptionVariant
	for index := range definition.variants {
		variant := &definition.variants[index]
		if !version.AtLeast(variant.minimum) {
			break
		}
		active = variant
	}
	return active != nil && active.scopes&scope != 0
}

func generatedDefinitionScopeVariesByVersion(
	definition generatedOptionDefinition,
	scope generatedOptionScope,
) bool {
	baseline := generatedDefinitionSupportsVersionScope(
		definition,
		generatedOptionFeatureFloor,
		scope,
	)
	if !baseline {
		return true
	}
	for _, variant := range definition.variants {
		if variant.minimum.Compare(generatedOptionFeatureFloor) <= 0 {
			continue
		}
		if variant.scopes&scope == 0 {
			return true
		}
	}
	return false
}

func optionOutputRequiresVersion(
	raw []byte,
	definitions []generatedOptionDefinition,
	scope generatedOptionScope,
) bool {
	versioned := make(map[string]struct{})
	for _, definition := range definitions {
		if generatedDefinitionSupportsScope(definition, scope) &&
			generatedDefinitionScopeVariesByVersion(definition, scope) {
			versioned[definition.name] = struct{}{}
		}
	}
	for line := range bytes.SplitSeq(raw, []byte{'\n'}) {
		keyBytes, _, _ := bytes.Cut(line, []byte{' '})
		key := parseDecodedOptionKey(string(keyBytes))
		if _, ok := versioned[key.base]; ok {
			return true
		}
	}
	return false
}

func decodeScalarOptionValue(
	destination *decodedOptionValue,
	definition generatedOptionDefinition,
	serialized []byte,
) error {
	switch definition.valueKind {
	case generatedOptionValueKindBool:
		switch string(serialized) {
		case "on":
			destination.boolValue = true
		case "off":
			destination.boolValue = false
		default:
			return errors.New("invalid flag")
		}
	case generatedOptionValueKindInt64:
		value, err := strconv.ParseInt(string(serialized), 10, 64)
		if err != nil {
			return err
		}
		destination.int64Value = value
	case generatedOptionValueKindString:
		value, err := decodeArgsEscapedValue(serialized)
		if err != nil {
			return err
		}
		destination.stringValue = value
	case generatedOptionValueKindSparseString:
		return errors.New("invalid scalar kind")
	default:
		return errors.New("invalid scalar kind")
	}
	return nil
}

func decodeArrayOptionElement(
	serialized []byte,
	hasValue bool,
	hooks bool,
	bare bool,
) (string, error) {
	if bare && !hasValue {
		return "", nil
	}
	if hooks {
		if !hasValue {
			if bare {
				return "", nil
			}
			return "", errors.New("missing hook value")
		}
		return tmuxcmd.DecodeBackslashReplace(serialized), nil
	}
	if !hasValue {
		return "", errors.New("missing serialized value")
	}
	return decodeArgsEscapedValue(serialized)
}

func finishDecodedOption(current decodedOptionAccumulator) (decodedOptionValue, error) {
	if !current.seen {
		return decodedOptionValue{}, newBulkOptionDecodeError(current.record, "recognized record is incomplete")
	}
	current.value.origin = current.origin
	if current.definition.array {
		array, err := NewSparseArray(current.entries...)
		if err != nil {
			return decodedOptionValue{}, newBulkOptionDecodeError(current.record, "recognized array indices are invalid")
		}
		current.value.sparseStringValue = array
	}
	return current.value, nil
}

func optionValueFromDecoded[T any](value T, origin OptionOrigin) OptionValue[T] {
	if origin == OptionOriginInherited {
		return newInheritedOptionValue(value)
	}
	return newLocalOptionValue(value)
}

func newBulkOptionDecodeError(record int, reason string) *OptionDecodeError {
	return &OptionDecodeError{Record: record, Reason: reason}
}

