			result.copyCommand = optionValueFromDecoded(value.stringValue, value.origin)
		case "default-client-command":
			result.defaultClientCommand = optionValueFromDecoded(value.stringValue, value.origin)
		case "default-terminal":
			result.defaultTerminal = optionValueFromDecoded(value.stringValue, value.origin)
		case "editor":
			result.editor = optionValueFromDecoded(value.stringValue, value.origin)
		case "escape-time":
			result.escapeTime = optionValueFromDecoded(time.Duration(value.int64Value)*time.Millisecond, value.origin)
		case "exit-empty":
			result.exitEmpty = optionValueFromDecoded(value.boolValue, value.origin)
		case "exit-unattached":
			result.exitUnattached = optionValueFromDecoded(value.boolValue, value.origin)
		case "extended-keys":
			result.extendedKeys = optionValueFromDecoded(ExtendedKeys(value.stringValue), value.origin)
		case "extended-keys-format":
			result.extendedKeysFormat = optionValueFromDecoded(ExtendedKeysFormat(value.stringValue), value.origin)
		case "focus-events":
			result.focusEvents = optionValueFromDecoded(value.boolValue, value.origin)
		case "get-clipboard":
			result.getClipboard = optionValueFromDecoded(GetClipboard(value.stringValue), value.origin)
		case "history-file":
			result.historyFile = optionValueFromDecoded(value.stringValue, value.origin)
		case "input-buffer-size":
			result.inputBufferSize = optionValueFromDecoded(value.int64Value, value.origin)
		case "message-limit":
			result.messageLimit = optionValueFromDecoded(value.int64Value, value.origin)
		case "prefix-timeout":
