			result.wordSeparators = optionValueFromDecoded(value.stringValue, value.origin)
		}
	}
	return result
}

// WindowOptionValues is an immutable materialized view of known window option values; its zero value is empty and it does not refresh.
// Obtain it with [Window.Options] or [GlobalWindowScope.Options]. [OptionValue.Get] reports presence and [OptionValue.Origin] reports inheritance.
// Use [Window.RawOption] or [GlobalWindowScope.RawOption] for caller-named or undecoded values.
type WindowOptionValues struct {
	aggressiveResize               OptionValue[bool]
	allowPassthrough               OptionValue[AllowPassthrough]
	allowRename                    OptionValue[bool]
	allowSetTitle                  OptionValue[bool]
	alternateScreen                OptionValue[bool]
	automaticRename                OptionValue[bool]
	automaticRenameFormat          OptionValue[string]
	clockModeColour                OptionValue[string]
	clockModeStyle                 OptionValue[ClockModeStyle]
	copyModeCurrentLineNumberStyle OptionValue[string]
	copyModeCurrentMatchStyle      OptionValue[string]
	copyModeLineNumberStyle        OptionValue[string]
	copyModeLineNumbers            OptionValue[CopyModeLineNumbers]
	copyModeMarkStyle              OptionValue[string]
	copyModeMatchStyle             OptionValue[string]
	copyModePositionFormat         OptionValue[string]
	copyModePositionStyle          OptionValue[string]
	copyModeSelectionStyle         OptionValue[string]
	cursorColour                   OptionValue[string]
	cursorStyle                    OptionValue[CursorStyle]
	fillCharacter                  OptionValue[string]
	mainPaneHeight                 OptionValue[string]
	mainPaneWidth                  OptionValue[string]
	menuBorderLines                OptionValue[MenuBorderLines]
	menuBorderStyle                OptionValue[string]
	menuSelectedStyle              OptionValue[string]
	menuStyle                      OptionValue[string]
	modeKeys                       OptionValue[ModeKeys]
	modeStyle                      OptionValue[string]
	monitorActivity                OptionValue[bool]
	monitorBell                    OptionValue[bool]
	monitorSilence                 OptionValue[int64]
	otherPaneHeight                OptionValue[string]
	otherPaneWidth                 OptionValue[string]
	paneActiveBorderStyle          OptionValue[string]
	paneBaseIndex                  OptionValue[int64]
