package tmux

import (
	"bytes"
	"context"
	"errors"
)

// Options returns a freshly decoded, caller-owned view of known server options,
// including inherited values. A read or transport failure is returned rather
// than answered with zero values; context errors propagate.
// Each returned accessor names the setter that writes it, so
// [ServerOptionValues.BufferLimit] pairs with [Server.SetBufferLimit].
func (s Server) Options(ctx context.Context) (ServerOptionValues, error) {
	values, err := readTypedOptionValues(
		ctx,
		s,
		[]string{"-s"},
		generatedOptionDefinitions[:],
		generatedOptionScopeServer,
		false,
	)
	if err != nil {
		return ServerOptionValues{}, err
	}
	return newServerOptionValues(values), nil
}

// Options returns a freshly decoded, caller-owned view of known global session
// options, including defaults. A read failure is returned rather than answered
// with zero values; context errors propagate.
// Each returned accessor names the setter that writes it, so
// [SessionOptionValues.Status] pairs with [GlobalSessionScope.SetStatus].
func (s GlobalSessionScope) Options(ctx context.Context) (SessionOptionValues, error) {
	values, err := readTypedOptionValues(
		ctx,
		s.server,
		[]string{"-g"},
		generatedOptionDefinitions[:],
		generatedOptionScopeSession,
		false,
	)
	if err != nil {
		return SessionOptionValues{}, err
	}
	return newSessionOptionValues(values), nil
}

// Options returns a freshly decoded, caller-owned view of known global window
// options, including defaults. A read failure is returned rather than answered
// with zero values; context errors propagate.
// Each returned accessor names the setter that writes it, so
// [WindowOptionValues.MainPaneWidth] pairs with
// [GlobalWindowScope.SetMainPaneWidth].
func (s GlobalWindowScope) Options(ctx context.Context) (WindowOptionValues, error) {
	values, err := readTypedOptionValues(
		ctx,
		s.server,
		[]string{"-g", "-w"},
		generatedOptionDefinitions[:],
		generatedOptionScopeWindow,
		false,
	)
	if err != nil {
		return WindowOptionValues{}, err
	}
	return newWindowOptionValues(values), nil
}

// Options returns a freshly decoded, caller-owned view of known options at this
// stable session target, including inherited values. A read failure is returned
// rather than answered with zero values; context errors propagate.
// Each returned accessor names the setter that writes it, so
// [SessionOptionValues.Mouse] pairs with [Session.SetMouse].
func (s Session) Options(ctx context.Context) (SessionOptionValues, error) {
	server, scope, err := sessionOptionRuntimeScope(s)
	if err != nil {
		return SessionOptionValues{}, err
	}
	values, err := readTypedOptionValues(
		ctx,
		server,
		scope,
		generatedOptionDefinitions[:],
		generatedOptionScopeSession,
		false,
	)
	if err != nil {
		return SessionOptionValues{}, err
	}
	return newSessionOptionValues(values), nil
}

// Options returns a freshly decoded, caller-owned view of known options at this
// exact window target, including inherited values. The receiver's exact linked
// session context controls tmux format evaluation. A read failure is returned
// rather than answered with zero values.
// Each returned accessor names the setter that writes it, so
// [WindowOptionValues.MainPaneWidth] pairs with [Window.SetMainPaneWidth].
func (w Window) Options(ctx context.Context) (WindowOptionValues, error) {
	server, scope, err := windowOptionRuntimeScope(w)
	if err != nil {
		return WindowOptionValues{}, err
	}
	values, err := readTypedOptionValues(
		ctx,
		server,
		scope,
		generatedOptionDefinitions[:],
		generatedOptionScopeWindow,
		false,
	)
	if err != nil {
		return WindowOptionValues{}, err
	}
	return newWindowOptionValues(values), nil
}

// Options returns a freshly decoded, caller-owned view of known options at this
// exact pane target, including inherited values. The receiver's exact linked
// session context controls tmux format evaluation. A read failure is returned
// rather than answered with zero values.
// Each returned accessor names the setter that writes it, so
// [PaneOptionValues.WindowStyle] pairs with [Pane.SetWindowStyle].
func (p Pane) Options(ctx context.Context) (PaneOptionValues, error) {
	server, scope, err := paneOptionRuntimeScope(p)
	if err != nil {
		return PaneOptionValues{}, err
	}
	values, err := readTypedOptionValues(
		ctx,
		server,
		scope,
		generatedOptionDefinitions[:],
		generatedOptionScopePane,
		false,
	)
	if err != nil {
		return PaneOptionValues{}, err
	}
	return newPaneOptionValues(values), nil
}

// RawOption returns one exact server-scope option value. A successful string is
// caller-owned; ok reports presence. Targeted reads do not use list leniency,
// and completed failures return a secret-safe option error.
// An unindexed empty array is indistinguishable from an empty scalar; use
// Options for typed array presence.
func (s Server) RawOption(ctx context.Context, name string) (string, bool, error) {
	return rawOption(ctx, s, []string{"-s"}, name, false)
}

// RawOption returns one exact global session-option value. A
// successful string is caller-owned, and ok reports presence.
// An unindexed empty array is indistinguishable from an empty scalar; use
// Options for typed array presence.
func (s GlobalSessionScope) RawOption(
	ctx context.Context,
	name string,
) (string, bool, error) {
	return rawOption(ctx, s.server, []string{"-g"}, name, false)
}

// RawOption returns one exact global window-option value. A
// successful string is caller-owned, and ok reports presence.
// An unindexed empty array is indistinguishable from an empty scalar; use
// Options for typed array presence.
func (s GlobalWindowScope) RawOption(
	ctx context.Context,
	name string,
) (string, bool, error) {
	return rawOption(ctx, s.server, []string{"-g", "-w"}, name, false)
}

// RawOption returns one exact session option value at this stable session
// target. A successful string is caller-owned; ok reports presence, and a
// completed failure is returned rather than normalized.
// An unindexed empty array is indistinguishable from an empty scalar; use
// Options for typed array presence.
func (s Session) RawOption(ctx context.Context, name string) (string, bool, error) {
	server, scope, err := sessionOptionRuntimeScope(s)
	if err != nil {
		return "", false, err
	}
	return rawOption(ctx, server, scope, name, false)
}

// RawOption returns one exact window option value at this exact window target.
// A successful string is caller-owned; the receiver's exact linked session
// context controls tmux format evaluation, and a completed failure is returned.
func (w Window) RawOption(ctx context.Context, name string) (string, bool, error) {
	server, scope, err := windowOptionRuntimeScope(w)
	if err != nil {
		return "", false, err
	}
	return rawOption(ctx, server, scope, name, false)
}

// RawOption returns one exact pane option value at this exact pane target. A
// successful string is caller-owned; the receiver's exact linked session
// context controls tmux format evaluation, and a completed failure is returned.
func (p Pane) RawOption(ctx context.Context, name string) (string, bool, error) {
	server, scope, err := paneOptionRuntimeScope(p)
	if err != nil {
		return "", false, err
	}
	return rawOption(ctx, server, scope, name, false)
}

func readTypedOptionValues(
	ctx context.Context,
	server Server,
	scope []string,
	definitions []generatedOptionDefinition,
	generatedScope generatedOptionScope,
	hooks bool,
) ([]decodedOptionValue, error) {
	arguments := make([]string, 0, len(scope)+3)
	arguments = append(arguments, "show-options")
	arguments = append(arguments, scope...)
	arguments = append(arguments, "-A")
	if hooks {
		arguments = append(arguments, "-H")
	}
	result, raw, err := server.literalCmdWithRaw(ctx, arguments...)
	if err != nil {
		return nil, err
	}
	if result.ExitCode != 0 || len(result.Stderr) != 0 {
		return nil, newOptionError("show-options", "", result)
	}
	var version *Version
	if optionOutputRequiresVersion(raw, definitions, generatedScope) {
		current, versionErr := server.Version(ctx)
		if versionErr != nil {
			if isContextOperationError(ctx, versionErr) {
				return nil, versionErr
			}
			_, classified := classifyOptionVersionBoundaryError(versionErr)
			return nil, classified
		}
		version = &current
	}
	return decodeOptionOutput(raw, definitions, generatedScope, hooks, version)
}

func classifyOptionVersionBoundaryError(err error) (bool, error) {
	if _, ok := errors.AsType[*versionTransportError](err); ok {
		return true, err
	}
	if query, ok := errors.AsType[*VersionQueryError](err); ok {
		if query.failedCommand() {
			return true, err
		}
		return false, &optionVersionBoundaryError{kind: ErrVersionQuery}
	}
	if errors.Is(err, ErrInvalidVersion) {
		return false, &optionVersionBoundaryError{kind: ErrInvalidVersion}
	}
	return false, err
}

func rawOption(
	ctx context.Context,
	server Server,
	scope []string,
	name string,
	hooks bool,
) (string, bool, error) {
	if err := validateServerCommandArgument(
		"show-options", "Name", name, true,
	); err != nil {
		return "", false, err
	}
	arguments := make([]string, 0, len(scope)+6)
	arguments = append(arguments, "show-options")
	arguments = append(arguments, scope...)
	if hooks {
		arguments = append(arguments, "-H")
	}
	arguments = append(arguments, "-q", "-v", "--", name)
	result, raw, err := server.literalCmdWithRaw(ctx, arguments...)
	if err != nil {
		return "", false, err
	}
	if len(raw) == 0 && len(result.Stderr) == 0 {
		return "", false, nil
	}
	if result.ExitCode != 0 || len(result.Stderr) != 0 {
		return "", false, newOptionError("show-options", name, result)
	}
	value, err := decodeTargetedOptionOutput(raw)
	if err != nil {
		return "", false, err
	}
	if len(raw) != 1 || raw[0] != '\n' {
		return value, true, nil
	}

	base, index, indexed := splitIndexedOptionName(name)
	if !indexed {
		return "", true, nil
	}
	present, err := queryIndexedOptionPresence(ctx, server, scope, name, base, index, hooks)
	if err != nil {
		return "", false, err
	}
	return "", present, nil
}

func queryIndexedOptionPresence(
	ctx context.Context,
	server Server,
	scope []string,
	name string,
	base string,
	index int,
	hooks bool,
) (bool, error) {
	arguments := make([]string, 0, len(scope)+5)
	arguments = append(arguments, "show-options")
	arguments = append(arguments, scope...)
	if hooks {
		arguments = append(arguments, "-H")
	}
	arguments = append(arguments, "-q", "--", base)
	result, raw, err := server.literalCmdWithRaw(ctx, arguments...)
	if err != nil {
		return false, err
	}
	if len(raw) == 0 && len(result.Stderr) == 0 {
		return false, nil
	}
	if result.ExitCode != 0 || len(result.Stderr) != 0 {
		return false, newOptionError("show-options", name, result)
	}
	return indexedOptionPresent(raw, base, index)
}

func indexedOptionPresent(raw []byte, base string, wanted int) (bool, error) {
	if len(raw) == 0 {
		return false, nil
	}
	if raw[len(raw)-1] != '\n' {
		return false, newBulkOptionDecodeError(
			bytes.Count(raw, []byte{'\n'}),
			"indexed base listing is missing its terminal line feed",
		)
	}
	last := -1
	present := false
	bare := false
	for record, line := range bytes.Split(raw[:len(raw)-1], []byte{'\n'}) {
		keyBytes, serialized, hasValue := bytes.Cut(line, []byte{' '})
		key := parseDecodedOptionKey(string(keyBytes))
		if !key.valid {
			return false, newBulkOptionDecodeError(record, "indexed base listing has a malformed key")
		}
		if key.base != base {
			return false, newBulkOptionDecodeError(record, "indexed base listing has an unexpected key")
		}
		if !key.indexed {
			if hasValue && len(serialized) != 0 {
				return false, newBulkOptionDecodeError(record, "indexed base listing has a nonempty bare value")
			}
			if last >= 0 {
				return false, newBulkOptionDecodeError(record, "indexed base listing mixes bare and indexed records")
			}
			bare = true
			continue
		}
		if bare {
			return false, newBulkOptionDecodeError(record, "indexed base listing mixes bare and indexed records")
		}
		if !hasValue {
			return false, newBulkOptionDecodeError(record, "indexed base listing value is missing")
		}
		if key.index <= last {
			return false, newBulkOptionDecodeError(record, "indexed base listing indices are not unique and ascending")
		}
		last = key.index
		if key.index == wanted {
			present = true
		}
	}
	return present, nil
}

func splitIndexedOptionName(name string) (string, int, bool) {
	key := parseDecodedOptionKey(name)
	if !key.valid || key.inherited || !key.indexed {
		return "", 0, false
	}
	return key.base, key.index, true
}

func isContextOperationError(ctx context.Context, err error) bool {
	return ctx.Err() != nil ||
		errors.Is(err, context.Canceled) ||
		errors.Is(err, context.DeadlineExceeded)
}

tmux/option_runtime.go.content:
package tmux

import (
	"context"
	"fmt"
	"math"
	"slices"
	"strconv"
	"time"
)

func encodeTypedOptionBool(value bool) string {
	if value {
		return "on"
	}
	return "off"
}

func encodeTypedOptionInt64(value int64) string {
	return strconv.FormatInt(value, 10)
}

// SetArrayResult reports confirmed progress from a typed sparse-array
// replacement. AppliedIndices is caller-owned and is non-nil whenever mutation
// was attempted.
type SetArrayResult struct {
	// Replaced reports whether tmux confirmed the base replacement.
	Replaced bool
	// AppliedIndices lists confirmed indexed writes in ascending order.
	AppliedIndices []int
}

func setTypedOption(
	ctx context.Context,
	server Server,
	scope []string,
	generatedScope generatedOptionScope,
	name string,
	value string,
	choice bool,
) error {
	if err := validateServerCommandArgument("set-option", "Name", name, true); err != nil {
		return err
	}
	if err := validateServerCommandArgument("set-option", "Value", value, true); err != nil {
		return err
	}
	if choice {
		definition := generatedOptionDefinitionByName(name)
		if definition == nil || !generatedChoiceValueValid(*definition, value) {
			return &OptionValueError{Name: name}
		}
		if generatedChoiceDomainVariesByVersion(*definition, generatedScope) {
			version, err := server.Version(ctx)
			if err != nil {
				return err
			}
			variant := generatedActiveOptionVariant(*definition, version)
			if variant != nil && variant.scopes&generatedScope != 0 &&
				!generatedVariantChoiceValid(*variant, value) {
				return &OptionValueError{Name: name}
			}
		}
	}
	return changeOption(
		ctx, server, scope, generatedScope, name, value, SetOptionOptions{}, false,
	)
}

func setTypedOptionArray(
	ctx context.Context,
	server Server,
	scope []string,
	generatedScope generatedOptionScope,
	name string,
	value SparseArray[string],
) (SetArrayResult, error) {
	entries := value.Entries()
	slices.SortFunc(entries, func(left, right SparseEntry[string]) int {
		switch {
		case left.Index < right.Index:
			return -1
		case left.Index > right.Index:
			return 1
		default:
			return 0
		}
	})
	if err := validateServerCommandArgument("set-option", "Name", name, true); err != nil {
		return SetArrayResult{}, err
	}
	for index, entry := range entries {
		if entry.Index < 0 || entry.Index > math.MaxInt32 {
			return SetArrayResult{}, fmt.Errorf("%w: %d", ErrInvalidSparseIndex, entry.Index)
		}
		if index != 0 && entries[index-1].Index == entry.Index {
			return SetArrayResult{}, fmt.Errorf("%w: %d", ErrDuplicateSparseIndex, entry.Index)
		}
		if err := validateServerCommandArgument(
			"set-option", "Value", entry.Value, true,
		); err != nil {
			return SetArrayResult{}, err
		}
	}
	if err := preflightGeneratedMutation(
		ctx,
		server,
		"set-option",
		name,
		generatedOptionDefinitions[:],
		generatedOptionAliases[:],
		generatedScope,
		true,
	); err != nil {
		return SetArrayResult{}, err
	}

	result := SetArrayResult{AppliedIndices: make([]int, 0, len(entries))}
	if err := runTypedArrayOptionMutation(ctx, server, scope, name, ""); err != nil {
		return result, err
	}
	result.Replaced = true
	for _, entry := range entries {
		indexedName := name + "[" + strconv.Itoa(entry.Index) + "]"
		if err := runTypedArrayOptionMutation(ctx, server, scope, indexedName, entry.Value); err != nil {
			return result, err
		}
		result.AppliedIndices = append(result.AppliedIndices, entry.Index)
	}
	return result, nil
}

func runTypedArrayOptionMutation(
	ctx context.Context,
	server Server,
	scope []string,
	name string,
	value string,
) error {
	arguments := make([]string, 0, len(scope)+4)
	arguments = append(arguments, "set-option")
	arguments = append(arguments, scope...)
	arguments = append(arguments, "--", name, value)
	return runOptionMutation(ctx, server, arguments, name, false)
}

func generatedOptionDefinitionByName(name string) *generatedOptionDefinition {
	for index := range generatedOptionDefinitions {
		if generatedOptionDefinitions[index].name == name {
			return &generatedOptionDefinitions[index]
		}
	}
	return nil
}

func generatedChoiceValueValid(definition generatedOptionDefinition, value string) bool {
	for _, variant := range definition.variants {
		if generatedVariantChoiceValid(variant, value) {
			return true
		}
	}
	return false
}

func generatedVariantChoiceValid(variant generatedOptionVariant, value string) bool {
	if variant.kind == generatedOptionKindFlag {
		return value == "off" || value == "on"
	}
	return slices.Contains(variant.choices, value)
}

func generatedChoiceDomainVariesByVersion(
	definition generatedOptionDefinition,
	scope generatedOptionScope,
) bool {
	var baseline []string
	for _, variant := range definition.variants {
		if variant.scopes&scope == 0 {
			continue
		}
		domain := variant.choices
		if variant.kind == generatedOptionKindFlag {
			domain = []string{"off", "on"}
		}
		if baseline == nil {
			baseline = domain
			continue
		}
		if !slices.Equal(baseline, domain) {
			return true
		}
	}
	return false
}

func generatedActiveOptionVariant(
	definition generatedOptionDefinition,
	version Version,
) *generatedOptionVariant {
	var active *generatedOptionVariant
	for index := range definition.variants {
		if !version.AtLeast(definition.variants[index].minimum) {
			break
		}
		active = &definition.variants[index]
	}
	return active
}

// encodeTypedOptionDuration renders value as the whole number of unit tmux
// stores this option as. A duration tmux cannot hold is refused before the
// command rather than truncated into one it can: an escape-time of 1500µs is
// a caller meaning something this option cannot express.
func encodeTypedOptionDuration(name string, value, unit time.Duration) (string, error) {
	if value < 0 || value%unit != 0 || value/unit > math.MaxInt32 {
		return "", invalidServerCommandRequest(
			"set-option", name, value.String(),
			"must be a whole number of "+unitName(unit)+" from 0 through 2147483647",
		)
	}
	return strconv.FormatInt(int64(value/unit), 10), nil
}

// unitName names a unit the way tmux's own options table does.
func unitName(unit time.Duration) string {
	if unit == time.Second {
		return "seconds"
	}
	return "milliseconds"
}

tmux/option_scope.go.content:
package tmux

// GlobalSessionScope is an immutable handle for global session options and
// hooks. Its zero value is invalid because it contains a zero [Server].
type GlobalSessionScope struct {
	server Server
}

// GlobalWindowScope is an immutable handle for global window options and
// hooks. Its zero value is invalid because it contains a zero [Server].
type GlobalWindowScope struct {
	server Server
}

// GlobalSessionScope returns a handle that preserves s and its error policy.
func (s Server) GlobalSessionScope() GlobalSessionScope {
	return GlobalSessionScope{server: s}
}

// GlobalWindowScope returns a handle that preserves s and its error policy.
func (s Server) GlobalWindowScope() GlobalWindowScope {
	return GlobalWindowScope{server: s}
}

func sessionOptionRuntimeScope(session Session) (Server, []string, error) {
	target := session.sessionID.String()
	if err := validateServerCommandArgument(
		"show-options", "Target", target, true,
	); err != nil {
		return Server{}, nil, err
	}
	if err := validateTypedTarget("show-options", "Target", "session", target); err != nil {
		return Server{}, nil, err
	}
	return session.server, []string{"-t", target}, nil
}

// windowOptionRuntimeScope names the window by id alone: options and hooks
// belong to the window, not to one of its links, and a session in the target
// would let tmux set a missing window's option on that session's current one.
func windowOptionRuntimeScope(window Window) (Server, []string, error) {
	if _, err := validateWindowView(window); err != nil {
		return Server{}, nil, err
	}
	return window.server, []string{"-t", window.windowID.String(), "-w"}, nil
}

// windowFormatScope keeps the session a linked window is viewed from, for the
// operations whose formats tmux expands in that session.
func windowFormatScope(window Window) (Server, []string, error) {
	target, err := exactWindowTarget(window)
	if err != nil {
		return Server{}, nil, err
	}
	return window.server, []string{"-t", target, "-w"}, nil
}

func paneOptionRuntimeScope(pane Pane) (Server, []string, error) {
	target, err := exactPaneTarget(pane)
	if err != nil {
		return Server{}, nil, err
	}
	return pane.server, []string{"-t", target, "-p"}, nil
}

tmux/option_value.go.content:
package tmux

//go:generate go run ./internal/generate/options -spec internal/generate/options/spec.json -output option_generated.go

// OptionOrigin identifies where a present option value was resolved.
// The declared values form the complete set of valid origins.
type OptionOrigin uint8

// String returns the origin's tmux vocabulary, so an origin prints as a word
// beside the generated option values, which all carry String.
func (o OptionOrigin) String() string {
	switch o {
	case OptionOriginLocal:
		return "local"
	case OptionOriginInherited:
		return "inherited"
	default:
		return "unset"
	}
}

const (
	// OptionOriginLocal identifies a value set directly at the queried scope.
	OptionOriginLocal OptionOrigin = iota + 1
	// OptionOriginInherited identifies a value inherited from a parent scope.
	OptionOriginInherited
)

// OptionValue preserves option presence and resolution origin.
// Its zero value is absent. Copies of reference-bearing T values are shallow.
type OptionValue[T any] struct {
	value  T
	origin OptionOrigin
}

// Get returns the option value and reports whether it is present.
func (v OptionValue[T]) Get() (T, bool) {
	if !v.present() {
		var zero T
		return zero, false
	}
	return v.value, true
}

// Origin returns the resolution origin and reports whether the option is present.
func (v OptionValue[T]) Origin() (OptionOrigin, bool) {
	if !v.present() {
		return 0, false
	}
	return v.origin, true
}

func newLocalOptionValue[T any](value T) OptionValue[T] {
	return OptionValue[T]{value: value, origin: OptionOriginLocal}
}

func newInheritedOptionValue[T any](value T) OptionValue[T] {
	return OptionValue[T]{value: value, origin: OptionOriginInherited}
}

func (v OptionValue[T]) present() bool {
	return v.origin == OptionOriginLocal || v.origin == OptionOriginInherited
}

tmux/pane_capture.go.content:
package tmux

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"
	"sync/atomic"

	"github.com/libtmux/libtmux-go/tmux/internal/tmuxcmd"
)

var (
	// ErrInvalidCaptureRequest identifies a capture request that cannot be
	// represented safely as tmux arguments.
	ErrInvalidCaptureRequest = errors.New("tmux: invalid capture request")

	captureVersion34 = Version{raw: "3.4", major: 3, minor: 4}
	captureVersion36 = Version{raw: "3.6", major: 3, minor: 6}
	captureVersion37 = Version{raw: "3.7", major: 3, minor: 7}
)

// CaptureRequestError reports a [CapturePaneRequest] field that cannot be
// represented as a tmux capture-pane argument. It matches
// [ErrInvalidCaptureRequest] through [errors.Is] and is available through
// [errors.As].
type CaptureRequestError struct {
	// Field names the invalid request field.
	Field string
	// Value is the rejected field value. It may be empty when absence is the
	// error.
	Value string
	// Reason describes the violated request constraint without promising a
	// stable complete error string.
	Reason string
}

// Error implements error.
func (e *CaptureRequestError) Error() string {
	return fmt.Sprintf("%v: %s %q %s", ErrInvalidCaptureRequest, e.Field, e.Value, e.Reason)
}

// Unwrap makes CaptureRequestError compatible with ErrInvalidCaptureRequest.
func (e *CaptureRequestError) Unwrap() error {
	return ErrInvalidCaptureRequest
}

// CapturePosition selects a line relative to tmux's visible pane or history.
// Its zero value omits the boundary and lets tmux use the visible-screen
// default. Construct numeric positions with [CaptureLine].
type CapturePosition string

const (
	// CaptureBoundary selects the start of history when used as Start and the
	// end of the visible pane when used as End.
	CaptureBoundary CapturePosition = "-"
)

// CaptureLine returns the canonical tmux representation of a capture line.
// Zero is the first visible line; negative values address history.
func CaptureLine(line int) CapturePosition {
	return CapturePosition(strconv.Itoa(line))
}

// CapturePaneRequest configures pane capture. Its zero value captures the
// visible screen with tmux's default text handling. Version-gated flags follow
// [UnsupportedPolicy]. [CaptureBoundary] selects the start of history for Start
// and the end of the visible pane for End.
type CapturePaneRequest struct {
	// Start selects the first captured line. Empty uses tmux's visible-screen
	// default; CaptureBoundary selects the start of history.
	Start CapturePosition
	// End selects the last captured line. Empty uses tmux's visible-screen
	// default; CaptureBoundary selects the end of the visible pane.
	End CapturePosition

	// EscapeSequences includes terminal attribute escape sequences.
	EscapeSequences bool
	// EscapeNonPrintable renders non-printable characters as octal escapes.
	EscapeNonPrintable bool
	// JoinWrapped joins wrapped lines, preserves their trailing spaces, and
	// implies tmux trimming independently of TrimTrailing.
	JoinWrapped bool
	// PreserveTrailing preserves trailing spaces at each line end.
	PreserveTrailing bool
	// TrimTrailing omits trailing positions without characters. It requires
	// tmux 3.4; see UnsupportedPolicy.
	TrimTrailing bool
	// AlternateScreen captures the alternate screen without history.
	AlternateScreen bool
	// Quiet suppresses tmux's error when AlternateScreen is requested but no
	// alternate screen exists.
	Quiet bool
	// ModeScreen captures the active mode screen. It requires tmux 3.6; see
	// UnsupportedPolicy.
	ModeScreen bool
	// Pending captures only the beginning of an incomplete escape sequence.
	Pending bool
	// Hyperlinks captures hyperlink metadata for the selected lines. It requires
	// tmux 3.7; see UnsupportedPolicy.
	Hyperlinks bool
	// LineNumbers prefixes each line with its tmux line number. It requires
	// tmux 3.7; see UnsupportedPolicy.
	LineNumbers bool
	// LineFlags prefixes each line with tmux line metadata flags. It requires
	// tmux 3.7; see UnsupportedPolicy.
	LineFlags bool
}

// Capture captures printed content from the receiver's exact linked pane.
// It returns a caller-owned slice. A completed nonzero exit or stderr becomes
// a [CommandError]; any stdout tmux still printed is returned alongside it.
//
// This is a point-in-time capture rather than a stream; the zero request reads
// the visible screen. It may include a shell's echo of [Pane.SendKeys] input.
// Compare whole lines when polling; use [ControlClient.NextNotification] or
// [Server.WaitFor] when the application exposes a stream or explicit signal.
//
// Invalid positions fail before execution. Transport and context failures return
// any partial stdout with the error.
func (p Pane) Capture(
	ctx context.Context,
	request CapturePaneRequest,
) ([]string, error) {
	result, err := p.capturePane(ctx, "", false, request)
	return result.Stdout, err
}

// CaptureBytes captures printed content from the receiver's exact linked pane
// as caller-owned stdout bytes. It preserves tmux's output delimiters and
// trailing newlines after tmux has interpreted the pane's terminal contents.
//
// Its validation and failure behavior match [Pane.Capture], including returning
// partial bytes with transport or context errors.
func (p Pane) CaptureBytes(
	ctx context.Context,
	request CapturePaneRequest,
) ([]byte, error) {
	result, err := p.capturePane(ctx, "", false, request)
	return result.RawStdout, err
}

// CaptureToBuffer captures content from the receiver's exact linked pane
// into the nonempty named tmux buffer. The buffer is owned by tmux and no
// printed output is returned. A completed nonzero exit or stderr becomes a
// [CommandError].
//
// Invalid requests fail before execution. Transport and context errors are
// delivery-ambiguous: the buffer may already have changed.
func (p Pane) CaptureToBuffer(
	ctx context.Context,
	buffer string,
	request CapturePaneRequest,
) error {
	_, err := p.capturePane(ctx, buffer, true, request)
	return err
}

// captureFileSequence names one call's scratch buffer apart from every other
// call's. Two captures of one pane can ask for different lines, so a buffer
// name shared between them would let one call save the other's screen.
var captureFileSequence atomic.Uint64

// CaptureToFile captures the receiver's exact linked pane through a tmux buffer
// and the file at path, returning the same lines [Pane.Capture] returns.
//
// Printed captures cannot safely cross a control connection, so [Pane.Capture]
// and [Pane.CaptureBytes] use a subprocess or reject a connection. CaptureToFile
// stages through a scratch buffer so capture, save, and cleanup can all use the
// connection's command lanes.
//
// path must name a file the tmux server can write and this process can read.
// It is replaced and left for the caller. Concurrent calls must use distinct
// paths. The scratch tmux buffer is deleted before return when possible.
//
// Validation and version gating match [Pane.Capture]. Capture, save, and
// file-read failures return an error with no lines; buffer cleanup is best effort.
func (p Pane) CaptureToFile(
	ctx context.Context,
	path string,
	request CapturePaneRequest,
) ([]string, error) {
	expanded, err := expandBufferPath("save-buffer", "Pane.CaptureTo", path)
	if err != nil {
		return nil, err
	}
	buffer := fmt.Sprintf(
		"libtmux-go-capture-%d-%d",
		os.Getpid(),
		captureFileSequence.Add(1),
	)
	if err := p.CaptureToBuffer(ctx, buffer, request); err != nil {
		return nil, err
	}
	// The buffer is deleted whichever way this returns: tmux's most recent
	// buffer is what an interactive paste reaches, so leaving a pane's screen
	// there would change what the user's own prefix-] does.
	defer func() { _ = p.server.DeleteBuffer(ctx, &buffer) }()
	if err := p.server.SaveBuffer(ctx, SaveBufferRequest{
		Path: expanded,
		Name: &buffer,
	}); err != nil {
		return nil, err
	}
	contents, err := os.ReadFile(expanded)
	if err != nil {
		return nil, err
	}
	// tmux writes the buffer to the file exactly as it would have printed it, so
	// the same decoder produces the same lines Pane.Capture reports.
	return tmuxcmd.SplitStdout(contents), nil
}

func (p Pane) capturePane(
	ctx context.Context,
	buffer string,
	toBuffer bool,
	request CapturePaneRequest,
) (CommandResult, error) {
	arguments, err := p.captureArguments(ctx, buffer, toBuffer, request)
	if err != nil {
		return CommandResult{ExitCode: -1}, err
	}
	if !toBuffer {
		// Control mode does not escape command stdout. Pane content matching a
		// closing guard could truncate the reply and desynchronize later commands,
		// so printed captures always use a subprocess.
		p.server = p.server.requireProcess()
	}
	result, err := p.literalCmd(ctx, arguments...)
	return result, requireServerCommandNoStderr("capture-pane", result, err)
}

// captureArguments validates request and builds its capture-pane argument
// vector; it does not select a transport or run the command.
func (p Pane) captureArguments(
	ctx context.Context,
	buffer string,
	toBuffer bool,
	request CapturePaneRequest,
) ([]string, error) {
	if err := validateServerCommandArguments(
		"capture-pane",
		serverCommandArgument{field: "Buffer", value: buffer},
		serverCommandArgument{field: "Start", value: string(request.Start)},
		serverCommandArgument{field: "End", value: string(request.End)},
		serverCommandArgument{field: "Pane", value: p.paneID.String()},
	); err != nil {
		return nil, err
	}
	if toBuffer && buffer == "" {
		return nil, &CaptureRequestError{
			Field:  "Buffer",
			Reason: "must not be empty",
		}
	}
	if err := validateCapturePosition("Start", request.Start); err != nil {
		return nil, err
	}
	if err := validateCapturePosition("End", request.End); err != nil {
		return nil, err
	}
	if err := validateTypedTarget(
		"capture-pane", "Pane", "pane", p.paneID.String(),
	); err != nil {
		return nil, err
	}

	var current Version
	if captureNeedsVersion(request) {
		var err error
		current, err = p.server.Version(ctx)
		if err != nil {
			return nil, err
		}
	}

	arguments := make([]string, 0, 22)
	var err error
	arguments = append(arguments, "capture-pane")
	if toBuffer {
		arguments = append(arguments, "-b", buffer)
	} else {
		arguments = append(arguments, "-p")
	}
	if request.Start != "" {
		arguments = append(arguments, "-S", string(request.Start))
	}
	if request.End != "" {
		arguments = append(arguments, "-E", string(request.End))
	}
	if request.EscapeSequences {
		arguments = append(arguments, "-e")
	}
	if request.EscapeNonPrintable {
		arguments = append(arguments, "-C")
	}
	if request.JoinWrapped {
		arguments = append(arguments, "-J")
	}
	if request.PreserveTrailing {
		arguments = append(arguments, "-N")
	}
	arguments, err = p.appendCaptureFeature(
		arguments,
		request.TrimTrailing,
		"-T",
		"trim_trailing",
		current,
		captureVersion34,
	)
	if err != nil {
		return nil, err
	}
	if request.AlternateScreen {
		arguments = append(arguments, "-a")
	}
	if request.Quiet {
		arguments = append(arguments, "-q")
	}
	arguments, err = p.appendCaptureFeature(
		arguments,
		request.ModeScreen,
		"-M",
		"mode_screen",
		current,
		captureVersion36,
	)
	if err != nil {
		return nil, err
	}
	if request.Pending {
		arguments = append(arguments, "-P")
	}
	arguments, err = p.appendCaptureFeature(
		arguments,
		request.Hyperlinks,
		"-H",
		"hyperlinks",
		current,
		captureVersion37,
	)
	if err != nil {
		return nil, err
	}
	arguments, err = p.appendCaptureFeature(
		arguments,
		request.LineNumbers,
		"-L",
		"line_numbers",
		current,
		captureVersion37,
	)
	if err != nil {
		return nil, err
	}
	arguments, err = p.appendCaptureFeature(
		arguments,
		request.LineFlags,
		"-F",
		"line_flags",
		current,
		captureVersion37,
	)
	if err != nil {
		return nil, err
	}
	return arguments, nil
}

// CaptureTo streams printed content from the receiver's exact linked pane into
// destination without holding a screen in memory, which is what makes a long
// scrollback affordable to write straight to a file or a compressor. Like
// [Pane.Capture] it reads the screen at one point in time rather than
// following it; the zero request reads the visible screen and version-gated
// fields follow [UnsupportedPolicy].
//
// A completed nonzero exit becomes a redacted command error, because CaptureTo
// returns no bytes for the caller to inspect. Cancellation does not prove
// destination received the complete screen, and a copy failure takes
// precedence over a completed command's exit status because it means
// destination never saw everything tmux sent. Printed captures always use a
// subprocess, so a [Connection]-bound Pane returns
// [ErrConnectionRequiresProcess]; [Pane.CaptureToFile] stages through a tmux
// buffer and runs over a connection.
func (p Pane) CaptureTo(
	ctx context.Context,
	destination io.Writer,
	request CapturePaneRequest,
) error {
	if destination == nil {
		return &CaptureRequestError{Field: "destination", Reason: "must not be nil"}
	}
	arguments, err := p.captureArguments(ctx, "", false, request)
	if err != nil {
		return err
	}
	result, err := p.streamOut(ctx, destination, arguments)
	return requireRedactedServerCommandNoStderr("capture-pane", result, err)
}

func validateCapturePosition(field string, position CapturePosition) error {
	value := string(position)
	if value == "" || position == CaptureBoundary {
		return nil
	}
	line, err := strconv.Atoi(value)
	if err == nil && strconv.Itoa(line) == value {
		return nil
	}
	return &CaptureRequestError{
		Field:  field,
		Value:  value,
		Reason: "must be empty, CaptureBoundary, or a canonical base-10 integer",
	}
}

func captureNeedsVersion(request CapturePaneRequest) bool {
	return request.TrimTrailing || request.ModeScreen || request.Hyperlinks ||
		request.LineNumbers || request.LineFlags
}

func (p Pane) appendCaptureFeature(
	arguments []string,
	requested bool,
	flag string,
	feature string,
	current Version,
	required Version,
) ([]string, error) {
	if !requested {
		return arguments, nil
	}
	if current.AtLeast(required) {
		return append(arguments, flag), nil
	}
	if err := p.server.unsupportedFeature("capture-pane", feature, current, required); err != nil {
		return nil, err
	}
	return arguments, nil
}

tmux/pane_create.go.content:
package tmux

import (
	"context"
	"maps"
	"strconv"
)

var newPaneVersion37 = Version{raw: "3.7", major: 3, minor: 7}

// NewPaneRequest configures a floating pane and requires tmux 3.7 or later.
// Its zero value creates a detached floating pane with tmux's default size,
// position, styles, and command. Nil pointer fields omit their options;
// nonnil pointers are explicit, including empty style or message strings.
// Width and Height must be nonnegative. Empty and Command are mutually
// exclusive. Unsupported tmux versions return [VersionTooLowError] rather than
// omitting fields.
//
// Methods copy pointers and Environment before I/O; concurrent mutation during
// the copy is unsafe.
type NewPaneRequest struct {
	// Attach lets the created pane become active in the exact target winlink;
	// false preserves its active pane.
	Attach bool
	// StartDirectory expands ~ and ~/... for the current user. Named-user
	// forms such as ~other are rejected; empty inherits tmux's default.
	// A directory that does not exist is not an error: tmux starts the
	// process in the home directory instead, or in / without one.
	StartDirectory string
	// Command starts the pane with this shell command; empty uses tmux's default.
	Command string
	// Environment is emitted in lexically sorted key order. The map is not
	// retained; nil and an empty map both add no entries.
	Environment map[string]string
	// Width sets a nonnegative pane width; nil lets tmux choose.
	Width *int
	// Height sets a nonnegative pane height; nil lets tmux choose.
	Height *int
	// X sets the horizontal position; nil lets tmux choose.
	X *int
	// Y sets the vertical position; nil lets tmux choose.
	Y *int
	// Zoom preserves the target window's zoomed state.
	Zoom bool
	// Empty creates a pane without starting a command.
	Empty bool
	// Style sets the pane style; nil omits it.
	Style *string
	// ActiveBorderStyle sets the active border style; nil omits it.
	ActiveBorderStyle *string
	// InactiveBorderStyle sets the inactive border style; nil omits it.
	InactiveBorderStyle *string
	// Message sets the pane message; nil omits it.
	Message *string
	// Keep preserves the pane after its command exits.
	Keep bool
}

// SplitPaneRequest configures tiled pane creation on tmux 3.3a or later. Its
// zero value creates a detached pane below the exact target with tmux's
// default size and command. Nil pointer fields omit their options; nonnil
// pointers are explicit, including empty style or message strings. Size and
// Percentage are mutually exclusive. Invalid values are rejected before tmux
// is mutated.
//
// Methods copy pointer and map values before I/O; concurrent mutation is unsafe.
// Empty, styles, Message, and Keep require tmux 3.7 and follow
// [UnsupportedPolicy]. Empty and Command conflict only when Empty is supported.
type SplitPaneRequest struct {
	// Attach lets the created pane become active in the exact target winlink;
	// false preserves its active pane.
	Attach bool
	// Direction selects the side of the target; zero means below.
	Direction PaneDirection
	// Size selects a nonnegative absolute pane size; nil omits it.
	Size *int
	// Percentage selects a size from 0 through 100; nil omits it. It is sent
	// as tmux's "-l N%", which every supported version accepts; the older -p
	// spelling is rejected by tmux 3.4.
	Percentage *int
	// StartDirectory expands ~ and ~/... for the current user. Named-user
	// forms such as ~other are rejected; empty inherits tmux's default.
	// A directory that does not exist is not an error: tmux starts the
	// process in the home directory instead, or in / without one.
	StartDirectory string
	// Command starts the pane with this shell command; empty uses tmux's default.
	Command string
	// FullWindow lets the new pane span the full window size.
	FullWindow bool
	// Zoom preserves the window's zoomed state after the split.
	Zoom bool
	// Environment is emitted in lexically sorted key order and is not retained;
	// nil and an empty map both add no entries.
	Environment map[string]string
	// Empty requests an empty pane on tmux 3.7 or later.
	Empty bool
	// Style sets the pane style on tmux 3.7 or later; nil omits it.
	Style *string
	// ActiveBorderStyle sets the active border style on tmux 3.7 or later; nil
	// omits it.
	ActiveBorderStyle *string
	// InactiveBorderStyle sets the inactive border style on tmux 3.7 or later;
	// nil omits it.
	InactiveBorderStyle *string
	// Message sets the pane message on tmux 3.7 or later; nil omits it.
	Message *string
	// Keep preserves the pane after its command exits on tmux 3.7 or later.
	Keep bool
}

// NewPane creates a floating pane in the receiver's exact winlink. Attach
// makes the new pane active in that session and winlink; it is not a global
// client-focus guarantee. The returned [Pane] is freshly materialized in the
// receiver SessionID and WindowID rather than by canonical ID-only refresh.
//
// If tmux reports a [PaneID] before a transport or refresh failure, the partial
// result includes the receiver SessionID and WindowID. Other failures return
// zero; creation is not rolled back.
func (w Window) NewPane(ctx context.Context, request NewPaneRequest) (Pane, error) {
	request = captureNewPaneRequest(request)
	target, err := exactWindowTarget(w)
	if err != nil {
		return Pane{}, err
	}
	return newPane(ctx, w.server, w.sessionID, w.windowID, w.windowIndex, target, request)
}

// NewPane creates a floating pane relative to the receiver's exact
// linked-pane view. Attach makes the new pane active in that session and
// winlink; it is not a global client-focus guarantee. The returned [Pane] is
// freshly materialized in the receiver SessionID and WindowID.
//
// If tmux reports a [PaneID] before a transport or refresh failure, the partial
// result includes the receiver SessionID and WindowID. Other failures return
// zero; creation is not rolled back.
func (p Pane) NewPane(ctx context.Context, request NewPaneRequest) (Pane, error) {
	request = captureNewPaneRequest(request)
	target, err := exactPaneTarget(p)
	if err != nil {
		return Pane{}, err
	}
	return newPane(ctx, p.server, p.sessionID, p.windowID, p.windowIndex, target, request)
}

func newPane(
	ctx context.Context,
	server Server,
	sessionID SessionID,
	windowID WindowID,
	windowIndex int,
	target string,
	request NewPaneRequest,
) (Pane, error) {
	if err := validateNewPaneRequest(target, request); err != nil {
		return Pane{}, err
	}
	environment, err := lifecycleEnvironmentArguments(request.Environment)
	if err != nil {
		return Pane{}, err
	}
	startDirectory, err := expandLifecycleDirectory(request.StartDirectory)
	if err != nil {
		return Pane{}, err
	}
	if err := server.RequireVersion(ctx, newPaneVersion37); err != nil {
		return Pane{}, err
	}

	arguments := []string{"new-pane", "-t", target}
	for _, option := range []struct {
		flag  string
		value *int
	}{
		{flag: "-x", value: request.Width},
		{flag: "-y", value: request.Height},
		{flag: "-X", value: request.X},
		{flag: "-Y", value: request.Y},
	} {
		if option.value != nil {
			arguments = append(arguments, option.flag+strconv.Itoa(*option.value))
		}
	}
	if request.Zoom {
		arguments = append(arguments, "-Z")
	}
	for _, option := range []struct {
		flag  string
		value *string
	}{
		{flag: "-s", value: request.Style},
		{flag: "-S", value: request.ActiveBorderStyle},
		{flag: "-R", value: request.InactiveBorderStyle},
		{flag: "-m", value: request.Message},
	} {
		if option.value != nil {
			arguments = append(arguments, option.flag, *option.value)
		}
	}
	if request.Keep {
		arguments = append(arguments, "-k")
	}
	arguments = append(arguments, "-P", "-F#{pane_id}")
	if startDirectory != "" {
		arguments = append(arguments, "-c"+startDirectory)
	}
	if !request.Attach {
		arguments = append(arguments, "-d")
	}
	arguments = append(arguments, environment...)
	if request.Empty {
		arguments = append(arguments, "-E")
	}
	if request.Command != "" {
		arguments = append(arguments, "--", request.Command)
	}

	result, err := server.literalCmd(ctx, arguments...)
	if err != nil {
		if identity, identityErr := lifecycleStableIdentity("pane", result.Stdout); identityErr == nil {
			return Pane{
				server: server, sessionID: sessionID,
				windowID: windowID, windowIndex: windowIndex, paneID: PaneID(identity),
			}, err
		}
		return Pane{}, err
	}
	result, err = requireRedactedLifecycleSuccess("new-pane", result, nil)
	if err != nil {
		return Pane{}, err
	}
	identity, err := lifecycleStableIdentity("pane", result.Stdout)
	if err != nil {
		return Pane{}, err
	}
	predicted := Pane{
		server: server, sessionID: sessionID,
		windowID: windowID, windowIndex: windowIndex, paneID: PaneID(identity),
	}
	refreshed, err := refreshExactPane(ctx, predicted)
	if err != nil {
		return predicted, err
	}
	return refreshed, nil
}

func validateNewPaneRequest(target string, request NewPaneRequest) error {
	if err := validateServerCommandArguments(
		"new-pane",
		serverCommandArgument{field: "StartDirectory", value: request.StartDirectory},
		serverCommandArgument{field: "Command", value: request.Command},
		serverCommandArgument{field: "Target", value: target},
	); err != nil {
		return err
	}
	if request.Width != nil && *request.Width < 0 {
		return invalidLifecycleRequest("Width must be nonnegative")
	}
	if request.Height != nil && *request.Height < 0 {
		return invalidLifecycleRequest("Height must be nonnegative")
	}
	if request.Empty && request.Command != "" {
		return invalidLifecycleRequest("Empty and Command are mutually exclusive")
	}
	for _, field := range []struct {
		name  string
		value *string
	}{
		{name: "Style", value: request.Style},
		{name: "ActiveBorderStyle", value: request.ActiveBorderStyle},
		{name: "InactiveBorderStyle", value: request.InactiveBorderStyle},
		{name: "Message", value: request.Message},
	} {
		if field.value != nil {
			if err := validateServerCommandArgument("new-pane", field.name, *field.value, true); err != nil {
				return err
			}
		}
	}
	_, err := lifecycleEnvironmentArguments(request.Environment)
	return err
}

func captureNewPaneRequest(request NewPaneRequest) NewPaneRequest {
	request.Width = copyOptionalInt(request.Width)
	request.Height = copyOptionalInt(request.Height)
	request.X = copyOptionalInt(request.X)
	request.Y = copyOptionalInt(request.Y)
	request.Style = copyOptionalString(request.Style)
	request.ActiveBorderStyle = copyOptionalString(request.ActiveBorderStyle)
	request.InactiveBorderStyle = copyOptionalString(request.InactiveBorderStyle)
	request.Message = copyOptionalString(request.Message)
	request.Environment = maps.Clone(request.Environment)
	return request
}

// SplitPane creates a tiled pane in the receiver's exact winlink. Attach makes
// the new pane active in that session and winlink; it is not a global
// client-focus guarantee. The returned [Pane] is freshly materialized in the
// receiver SessionID and WindowID rather than by canonical ID-only refresh.
// [Pane.Split] is the equivalent operation relative to an existing pane
// rather than its window.
//
// If tmux reports a [PaneID] before a transport or refresh failure, the partial
// result also contains the receiver SessionID and WindowID. Other failures
// return zero; creation is not rolled back.
func (w Window) SplitPane(ctx context.Context, request SplitPaneRequest) (Pane, error) {
	request = captureSplitPaneRequest(request)
	target, err := exactWindowTarget(w)
	if err != nil {
		return Pane{}, err
	}
	return splitPane(ctx, w.server, w.sessionID, w.windowID, w.windowIndex, target, request)
}

// Split creates a tiled pane relative to the receiver's exact linked-pane
// view. Attach makes the new pane active in that session and winlink; it is not
// a global client-focus guarantee. The returned [Pane] is freshly materialized
// in the receiver SessionID and WindowID. Named Split rather than SplitPane to
// avoid repeating Pane; [Window.SplitPane] is the equivalent operation
// relative to a window.
//
// If tmux reports a [PaneID] before a transport or refresh failure, the partial
// result also contains the receiver SessionID and WindowID. Other failures
// return zero; creation is not rolled back.
func (p Pane) Split(ctx context.Context, request SplitPaneRequest) (Pane, error) {
	request = captureSplitPaneRequest(request)
	target, err := exactPaneTarget(p)
	if err != nil {
		return Pane{}, err
	}
	return splitPane(ctx, p.server, p.sessionID, p.windowID, p.windowIndex, target, request)
}

func splitPane(
	ctx context.Context,
	server Server,
	sessionID SessionID,
	windowID WindowID,
	windowIndex int,
	target string,
	request SplitPaneRequest,
) (Pane, error) {
	var version Version
	if splitPaneRequiresVersion(request) {
		probed, err := server.Version(ctx)
		if err != nil {
			return Pane{}, err
		}
		version = probed
	}
	arguments, warnings, err := splitPaneArguments(target, request, version)
	if err != nil {
		return Pane{}, err
	}
	if err := server.reportUnsupported(warnings); err != nil {
		return Pane{}, err
	}
	result, err := server.literalCmd(ctx, arguments...)
	return splitPaneResult(ctx, server, sessionID, windowID, windowIndex, result, err)
}

// splitPaneRequiresVersion reports whether a request asks for a flag this
// package gates on the tmux version, and so cannot be rendered without probing
// it. Nearly every split asks for none, which is why the probe is conditional:
// it costs a tmux process of its own the first time.
func splitPaneRequiresVersion(request SplitPaneRequest) bool {
	return request.Empty || splitPaneStylingRequested(request)
}

// splitPaneArguments renders a split's argument vector and the warnings that
// rendering it produced. It performs no I/O, so a [Plan] can render a split it
// has not run and a caller can read what would be sent.
//
// version is consulted only for the flags [splitPaneRequiresVersion] reports,
// so a caller that skipped the probe may pass the zero Version.
func splitPaneArguments(
	target string,
	request SplitPaneRequest,
	version Version,
) ([]string, []Warning, error) {
	if err := validateServerCommandArguments(
		"split-window",
		serverCommandArgument{field: "StartDirectory", value: request.StartDirectory},
		serverCommandArgument{field: "Command", value: request.Command},
		serverCommandArgument{field: "Target", value: target},
	); err != nil {
		return nil, nil, err
	}
	if err := validateSplitPaneRequest(request); err != nil {
		return nil, nil, err
	}
	environment, err := lifecycleEnvironmentArguments(request.Environment)
	if err != nil {
		return nil, nil, err
	}
	startDirectory, err := expandLifecycleDirectory(request.StartDirectory)
	if err != nil {
		return nil, nil, err
	}
	var warnings []Warning
	useEmpty, useStyling := request.Empty, splitPaneStylingRequested(request)
	if useEmpty || useStyling {
		required := Version{raw: "3.7", major: 3, minor: 7}
		if !version.AtLeast(required) {
			if useEmpty {
				warnings = append(warnings, newUnsupportedFeatureWarning(
					"split-window", "empty", version, required,
				))
				useEmpty = false
			}
			if useStyling {
				warnings = append(warnings, newUnsupportedFeatureWarning(
					"split-window", "style/border/message/keep", version, required,
				))
				useStyling = false
			}
		}
	}
	if useEmpty && request.Command != "" {
		return nil, warnings, invalidLifecycleRequest(
			"Empty and Command are mutually exclusive",
		)
	}

	arguments := []string{"split-window", "-t", target}
	switch request.Direction {
	case PaneDirectionBelow:
		arguments = append(arguments, "-v")
	case PaneDirectionAbove:
		arguments = append(arguments, "-v", "-b")
	case PaneDirectionRight:
		arguments = append(arguments, "-h")
	case PaneDirectionLeft:
		arguments = append(arguments, "-h", "-b")
	}
	if request.Size != nil {
		arguments = append(arguments, "-l"+strconv.Itoa(*request.Size))
	}
	if request.Percentage != nil {
		// "-l N%" rather than "-p N". tmux deprecated -p in 3.1 when -l
		// learned percentages, and 3.4 stopped accepting it outright: a
		// percentage split there fails with "size missing". The percentage
		// form of -l works across the supported range,
		// so there is nothing to gate on.
		arguments = append(arguments, "-l"+strconv.Itoa(*request.Percentage)+"%")
	}
	if request.FullWindow {
		arguments = append(arguments, "-f")
	}
	if request.Zoom {
		arguments = append(arguments, "-Z")
	}
	arguments = append(arguments, "-P", "-F#{pane_id}")
	if startDirectory != "" {
		arguments = append(arguments, "-c"+startDirectory)
	}
	if !request.Attach {
		arguments = append(arguments, "-d")
	}
	arguments = append(arguments, environment...)
	if useEmpty {
		arguments = append(arguments, "-E")
	}
	if useStyling {
		for _, option := range []struct {
			flag  string
			value *string
		}{
			{flag: "-s", value: request.Style},
			{flag: "-S", value: request.ActiveBorderStyle},
			{flag: "-R", value: request.InactiveBorderStyle},
			{flag: "-m", value: request.Message},
		} {
			if option.value != nil {
				arguments = append(arguments, option.flag, *option.value)
			}
		}
		if request.Keep {
			arguments = append(arguments, "-k")
		}
	}
	if request.Command != "" {
		arguments = append(arguments, "--", request.Command)
	}
	return arguments, warnings, nil
}

// splitPaneResult materializes the pane a split produced.
func splitPaneResult(
	ctx context.Context,
	server Server,
	sessionID SessionID,
	windowID WindowID,
	windowIndex int,
	result CommandResult,
	err error,
) (Pane, error) {
	if err != nil {
		if identity, identityErr := lifecycleStableIdentity("pane", result.Stdout); identityErr == nil {
			return Pane{
				server: server, sessionID: sessionID,
				windowID: windowID, windowIndex: windowIndex, paneID: PaneID(identity),
			}, err
		}
		return Pane{}, err
	}
	result, err = requireRedactedLifecycleSuccess("split-window", result, nil)
	if err != nil {
		return Pane{}, err
	}
	identity, err := lifecycleStableIdentity("pane", result.Stdout)
	if err != nil {
		return Pane{}, err
	}
	predicted := Pane{
		server: server, sessionID: sessionID,
		windowID: windowID, windowIndex: windowIndex, paneID: PaneID(identity),
	}
	pane, err := refreshExactPane(ctx, predicted)
	if err != nil {
		return predicted, err
	}
	return pane, nil
}

func validateSplitPaneRequest(request SplitPaneRequest) error {
	if request.Direction > PaneDirectionLeft {
		return invalidLifecycleRequest("unsupported pane direction")
	}
	if request.Size != nil && request.Percentage != nil {
		return invalidLifecycleRequest("Size and Percentage are mutually exclusive")
	}
	if request.Size != nil && *request.Size < 0 {
		return invalidLifecycleRequest("Size must be nonnegative")
	}
	if request.Percentage != nil && (*request.Percentage < 0 || *request.Percentage > 100) {
		return invalidLifecycleRequest("Percentage must be between 0 and 100")
	}
	for _, field := range []struct {
		name  string
		value *string
	}{
		{name: "Style", value: request.Style},
		{name: "ActiveBorderStyle", value: request.ActiveBorderStyle},
		{name: "InactiveBorderStyle", value: request.InactiveBorderStyle},
		{name: "Message", value: request.Message},
	} {
		if field.value != nil {
			if err := validateServerCommandArgument(
				"split-window", field.name, *field.value, true,
			); err != nil {
				return err
			}
		}
	}
	return nil
}

func captureSplitPaneRequest(request SplitPaneRequest) SplitPaneRequest {
	request.Size = copyOptionalInt(request.Size)
	request.Percentage = copyOptionalInt(request.Percentage)
	request.Style = copyOptionalString(request.Style)
	request.ActiveBorderStyle = copyOptionalString(request.ActiveBorderStyle)
	request.InactiveBorderStyle = copyOptionalString(request.InactiveBorderStyle)
	request.Message = copyOptionalString(request.Message)
	request.Environment = maps.Clone(request.Environment)
	return request
}

func splitPaneStylingRequested(request SplitPaneRequest) bool {
	return request.Style != nil ||
		request.ActiveBorderStyle != nil ||
		request.InactiveBorderStyle != nil ||
		request.Message != nil ||
		request.Keep
}

tmux/pane_geometry.go.content:
package tmux

import (
	"context"
	"strconv"
)

// PaneResizeDirection selects a directional [Pane.Resize]. Its zero value
// selects no directional adjustment.
type PaneResizeDirection uint8

const (
	// PaneResizeDirectionNone omits a directional resize.
	PaneResizeDirectionNone PaneResizeDirection = iota
	// PaneResizeDirectionUp selects tmux's upward adjustment.
	PaneResizeDirectionUp
	// PaneResizeDirectionDown selects tmux's downward adjustment.
	PaneResizeDirectionDown
	// PaneResizeDirectionLeft selects tmux's leftward adjustment.
	PaneResizeDirectionLeft
	// PaneResizeDirectionRight selects tmux's rightward adjustment.
	PaneResizeDirectionRight
)

type paneSizeKind uint8

const (
	paneSizeUnset paneSizeKind = iota
	paneSizeCells
	paneSizePercent
)

// PaneSize is an opaque absolute cell count or percentage for [Pane.Resize].
// Its zero value omits the dimension. [PaneCells](0) and [PanePercent](0) are
// explicit sizes, not zero PaneSize values.
type PaneSize struct {
	kind  paneSizeKind
	value int
}

// PaneCells returns an explicit pane size measured in cells. Resize validates
// that cells is nonnegative; zero remains an explicit request.
func PaneCells(cells int) PaneSize {
	return PaneSize{kind: paneSizeCells, value: cells}
}

// PanePercent returns an explicit percentage of the window size. Resize
// validates that percent is between 0 and 100 inclusive; zero remains an
// explicit request.
func PanePercent(percent int) PaneSize {
	return PaneSize{kind: paneSizePercent, value: percent}
}

// ResizePaneRequest selects one resize mode. Direction with Adjustment,
// dimensions, Zoom, Mouse, and TrimBelow are mutually exclusive modes; Height
// and Width may be set together. Its zero value sends a bare tmux resize-pane
// command rather than selecting a mode. When Direction is
// [PaneResizeDirectionNone], Adjustment must be zero.
type ResizePaneRequest struct {
	// Direction selects a directional resize and requires Adjustment.
	Direction PaneResizeDirection
	// Adjustment is the positive number of cells moved in Direction. It must
	// be zero when Direction is PaneResizeDirectionNone.
	Adjustment int
	// Height sets an absolute or percentage height. A zero PaneSize omits it.
	Height PaneSize
	// Width sets an absolute or percentage width. A zero PaneSize omits it.
	Width PaneSize
	// Zoom toggles the pane between its normal layout and full-window zoom.
	Zoom bool
	// Mouse begins tmux mouse resizing and is meaningful from a mouse binding.
	Mouse bool
	// TrimBelow removes lines below the cursor and refills from history.
	TrimBelow bool
}

// Resize runs tmux resize-pane against the receiver's exact linked
// session-window-pane target, then refreshes by PaneID. The returned canonical
// [Pane] may therefore carry a different linked-session or winlink context.
// If the resize is accepted but refresh fails, Resize returns the original
// receiver with that error.
//
// Invalid requests fail before execution. A completed command produces a
// redacted [CommandError] only for stderr; nonzero exits without stderr are
// followed by refresh. Transport errors return zero and are delivery-ambiguous.
func (p Pane) Resize(ctx context.Context, request ResizePaneRequest) (Pane, error) {
	if err := validateTypedTarget(
		"resize-pane", "Pane", "pane", p.paneID.String(),
	); err != nil {
		return Pane{}, err
	}
	target, err := exactPaneTarget(p)
	if err != nil {
		return Pane{}, err
	}
	arguments, err := resizePaneArguments(target, request)
	if err != nil {
		return Pane{}, err
	}

	result, err := p.server.literalCmd(ctx, arguments...)
	if err := requireRedactedServerCommandNoStderr("resize-pane", result, err); err != nil {
		return Pane{}, err
	}
	refreshed, err := p.Refresh(ctx)
	if err != nil {
		return p, err
	}
	return refreshed, nil
}

// resizePaneArguments renders a resize for a [Plan] without I/O.
func resizePaneArguments(
	target string,
	request ResizePaneRequest,
) ([]string, error) {
	if err := validateServerCommandArgument(
		"resize-pane", "Target", target, true,
	); err != nil {
		return nil, err
	}
	if err := validateResizePaneRequest(request); err != nil {
		return nil, err
	}

	arguments := []string{"resize-pane", "-t", target}
	switch {
	case request.Direction != PaneResizeDirectionNone:
		arguments = append(
			arguments,
			paneResizeDirectionFlag(request.Direction),
			strconv.Itoa(request.Adjustment),
		)
	case request.Height.kind != paneSizeUnset || request.Width.kind != paneSizeUnset:
		if request.Height.kind != paneSizeUnset {
			arguments = append(arguments, "-y"+paneSizeArgument(request.Height))
		}
		if request.Width.kind != paneSizeUnset {
			arguments = append(arguments, "-x"+paneSizeArgument(request.Width))
		}
	case request.Zoom:
		arguments = append(arguments, "-Z")
	case request.Mouse:
		arguments = append(arguments, "-M")
	case request.TrimBelow:
		arguments = append(arguments, "-T")
	}
	return arguments, nil
}

// SetWidth resizes the pane to a nonnegative absolute width in cells. Zero is
// an explicit width. Targeting, refresh, and error semantics match [Pane.Resize].
func (p Pane) SetWidth(ctx context.Context, width int) (Pane, error) {
	return p.Resize(ctx, ResizePaneRequest{Width: PaneCells(width)})
}

// SetHeight resizes the pane to a nonnegative absolute height in cells. Zero
// is an explicit height. Targeting, refresh, and error semantics match
// [Pane.Resize].
func (p Pane) SetHeight(ctx context.Context, height int) (Pane, error) {
	return p.Resize(ctx, ResizePaneRequest{Height: PaneCells(height)})
}

// SetTitle sets the title of the receiver's exact linked pane. tmux expands
// format expressions in title; the value is not a shell command. SetTitle then
// refreshes by PaneID, so the returned canonical [Pane] may carry a different
// linked-session or winlink context. If the mutation is accepted but refresh
// fails, SetTitle returns the original receiver with that error.
//
// Completed stderr produces a redacted [CommandError]; nonzero exits without
// stderr are followed by refresh. Transport errors return zero and are
// delivery-ambiguous.
func (p Pane) SetTitle(ctx context.Context, title string) (Pane, error) {
	result, err := p.literalCmd(ctx, "select-pane", "-T", title)
	if err := requireRedactedServerCommandNoStderr("select-pane", result, err); err != nil {
		return Pane{}, err
	}
	refreshed, err := p.Refresh(ctx)
	if err != nil {
		return p, err
	}
	return refreshed, nil
}

func validateResizePaneRequest(request ResizePaneRequest) error {
	if request.Direction > PaneResizeDirectionRight {
		return invalidServerCommandRequest(
			"resize-pane",
			"Direction",
			strconv.FormatUint(uint64(request.Direction), 10),
			"is unsupported",
		)
	}
	hasDirection := request.Direction != PaneResizeDirectionNone
	hasAdjustment := request.Adjustment != 0
	if hasDirection != hasAdjustment {
		return invalidServerCommandRequest(
			"resize-pane",
			"Adjustment",
			"",
			"Direction and Adjustment must be set together",
		)
	}
	if request.Adjustment < 0 {
		return invalidServerCommandRequest(
			"resize-pane",
			"Adjustment",
			strconv.Itoa(request.Adjustment),
			"must be positive",
		)
	}
	if err := validatePaneSize("Height", request.Height); err != nil {
		return err
	}
	if err := validatePaneSize("Width", request.Width); err != nil {
		return err
	}

	modes := 0
	if hasDirection {
		modes++
	}
	if request.Height.kind != paneSizeUnset || request.Width.kind != paneSizeUnset {
		modes++
	}
	if request.Zoom {
		modes++
	}
	if request.Mouse {
		modes++
	}
	if request.TrimBelow {
		modes++
	}
	if modes > 1 {
		return invalidServerCommandRequest(
			"resize-pane",
			"Mode",
			"",
			"adjustment, dimensions, Zoom, Mouse, and TrimBelow are mutually exclusive",
		)
	}
	return nil
}

func validatePaneSize(field string, size PaneSize) error {
	switch size.kind {
	case paneSizeUnset:
		return nil
	case paneSizeCells:
		if size.value < 0 {
			return invalidServerCommandRequest(
				"resize-pane", field, strconv.Itoa(size.value), "must not be negative",
			)
		}
	case paneSizePercent:
		if size.value < 0 || size.value > 100 {
			return invalidServerCommandRequest(
				"resize-pane", field, strconv.Itoa(size.value), "must be between 0 and 100",
			)
		}
	default:
		return invalidServerCommandRequest(
			"resize-pane", field, "", "has an unsupported size kind",
		)
	}
	return nil
}

func paneSizeArgument(size PaneSize) string {
	value := strconv.Itoa(size.value)
	if size.kind == paneSizePercent {
		return value + "%"
	}
	return value
}

func paneResizeDirectionFlag(direction PaneResizeDirection) string {
	switch direction {
	case PaneResizeDirectionNone:
		return ""
	case PaneResizeDirectionUp:
		return "-U"
	case PaneResizeDirectionDown:
		return "-D"
	case PaneResizeDirectionLeft:
		return "-L"
	case PaneResizeDirectionRight:
		return "-R"
	default:
		return ""
	}
}

tmux/pane_input.go.content:
package tmux

import (
	"context"
	"io"
	"slices"
	"strconv"
	"strings"
)

var paneInputVersion34 = Version{raw: "3.4", major: 3, minor: 4}

// SendKeysRequest configures tmux key input. Pointer values are copied before
// I/O and must not be mutated concurrently.
//
// Command must be nonnil unless Reset, Repeat, or CopyModeCommand is set. A
// nonnil empty Command is an explicit key operand and is followed by Enter
// unless SkipEnter is set. CopyModeCommand takes precedence over Command and
// suppresses Enter. HexKeys takes precedence over Literal when both are set.
type SendKeysRequest struct {
	// Command is one tmux key operand. Nil selects a flag-only invocation;
	// nonnil, including an empty string, supplies the operand.
	Command *string
	// SkipEnter prevents the separate Enter key sent after Command.
	SkipEnter bool
	// SuppressHistory prefixes Command with one space. Whether that excludes
	// the text from history depends on the application or shell in the pane.
	SuppressHistory bool
	// Literal disables tmux key-name lookup and treats Command as literal UTF-8.
	// It does not bypass interpretation by the pane's application or shell.
	Literal bool
	// Reset asks tmux to reset terminal state before processing key input.
	Reset bool
	// CopyModeCommand sends a tmux copy-mode command instead of Command. A
	// nonnil empty string remains an explicit operand.
	CopyModeCommand *string
	// Repeat repeats the key input a positive number of times. Zero omits the
	// repeat count.
	Repeat int
	// ExpandFormats asks tmux to expand format expressions in key operands.
	ExpandFormats bool
	// HexKeys interprets key operands as hexadecimal ASCII values and takes
	// precedence over Literal.
	HexKeys bool
	// TargetClient selects the client used by KeyName. Zero leaves client
	// selection to tmux; without KeyName it does not redirect pane input.
	TargetClient ClientName
	// KeyName routes keys through the selected client's key table rather than
	// delivering them to the pane.
	KeyName bool
}

// SendKeySequenceRequest configures ordered pane key delivery. Keys must
// contain at least one nonempty operand. SendKeySequence copies Keys before
// I/O; callers must not mutate it concurrently with the call.
type SendKeySequenceRequest struct {
	// Keys are tmux key names sent in order.
	Keys []string
	// Literal treats every key as literal UTF-8 instead of a tmux key name.
	Literal bool
}

// SendKeySequence sends the requested keys to the receiver's exact linked
// pane in one tmux command. It does not append Enter. Literal changes tmux key
// parsing but does not bypass interpretation by the pane's application.
//
// A returned error does not establish how many keys tmux delivered.
func (p Pane) SendKeySequence(ctx context.Context, request SendKeySequenceRequest) error {
	request.Keys = slices.Clone(request.Keys)
	if err := validateSendKeySequenceRequest(p, request); err != nil {
		return err
	}
	target, err := exactPaneTarget(p)
	if err != nil {
		return err
	}
	arguments, err := sendKeySequenceArguments(target, request)
	if err != nil {
		return err
	}
	result, err := p.server.literalCmd(ctx, arguments...)
	return requireRedactedServerCommandNoStderr("send-keys", result, err)
}

func sendKeySequenceArguments(
	target string,
	request SendKeySequenceRequest,
) ([]string, error) {
	if err := validateServerCommandArgument(
		"send-keys", "Target", target, true,
	); err != nil {
		return nil, err
	}
	arguments := []string{"send-keys", "-t", target}
	if request.Literal {
		arguments = append(arguments, "-l")
	}
	arguments = append(arguments, "--")
	return append(arguments, request.Keys...), nil
}

func validateSendKeySequenceRequest(p Pane, request SendKeySequenceRequest) error {
	if err := validateTypedTarget(
		"send-keys", "Pane", "pane", p.paneID.String(),
	); err != nil {
		return err
	}
	if len(request.Keys) == 0 {
		return invalidServerCommandRequest(
			"send-keys", "Keys", "", "must contain at least one key",
		)
	}
	for index, key := range request.Keys {
		field := "Keys[" + strconv.Itoa(index) + "]"
		if key == "" {
			return invalidServerCommandRequest(
				"send-keys", field, "", "must not be empty",
			)
		}
		if err := validateServerCommandArgument("send-keys", field, key, true); err != nil {
			return err
		}
	}
	return nil
}

// SendKeys invokes tmux send-keys with the receiver's exact linked
// session-window-pane target. This is tmux key input, not shell execution:
// Literal only changes tmux key parsing, and any delivered text may still be
// interpreted by the pane's application. KeyName routes through a client's key
// table instead of delivering to the pane.
//
// KeyName and TargetClient require tmux 3.4 and follow [UnsupportedPolicy].
//
// A completed nonzero exit or stderr, from either the Command send or the
// separate Enter, becomes a redacted [CommandError]: Command may carry a
// caller's secret, so only tmux's exit code is retained. Transport and
// context errors are delivery-ambiguous, including between Command and Enter.
func (p Pane) SendKeys(ctx context.Context, request SendKeysRequest) error {
	request = captureSendKeysRequest(request)
	if err := validateSendKeysRequest(p, request); err != nil {
		return err
	}

	var current Version
	if sendKeysRequiresVersion(request) {
		var err error
		current, err = p.server.Version(ctx)
		if err != nil {
			return err
		}
	}
	target, err := exactPaneTarget(p)
	if err != nil {
		return err
	}
	arguments, warnings, err := sendKeysArguments(target, request, current)
	if err != nil {
		return err
	}
	if err := p.server.reportUnsupported(warnings); err != nil {
		return err
	}
	result, err := p.server.literalCmd(ctx, arguments...)
	if err := requireRedactedServerCommandNoStderr("send-keys", result, err); err != nil {
		return err
	}
	if !sendKeysNeedsEnter(request) {
		return nil
	}
	return p.Enter(ctx)
}

// sendKeysRequiresVersion avoids a probe for requests with no gated flags.
func sendKeysRequiresVersion(request SendKeysRequest) bool {
	return request.KeyName || request.TargetClient != ""
}

// sendKeysNeedsEnter reports whether the request's text is followed by Enter.
//
// It is sent as a second tmux command rather than appended to the first: tmux
// reads a command list by re-parsing its arguments, which turns a backslash
// escape in a caller's text into what it escapes - a typed printf 'x\n'
// reaching the pane as two lines - and reads a trailing semicolon as the
// list's own separator. Enter is a separate command and therefore a separate
// [Plan] step.
func sendKeysNeedsEnter(request SendKeysRequest) bool {
	return request.CopyModeCommand == nil && request.Command != nil && !request.SkipEnter
}

// sendKeysArguments renders without I/O and returns compatibility warnings.
func sendKeysArguments(
	target string,
	request SendKeysRequest,
	version Version,
) ([]string, []Warning, error) {
	if err := validateServerCommandArgument(
		"send-keys", "Target", target, true,
	); err != nil {
		return nil, nil, err
	}
	var warnings []Warning
	arguments := []string{"send-keys", "-t", target}
	if request.Reset {
		arguments = append(arguments, "-R")
	}
	if request.ExpandFormats {
		arguments = append(arguments, "-F")
	}
	if request.HexKeys {
		arguments = append(arguments, "-H")
	}
	if request.KeyName {
		if version.AtLeast(paneInputVersion34) {
			arguments = append(arguments, "-K")
		} else {
			warnings = append(warnings, newUnsupportedFeatureWarning(
				"send-keys", "key_name", version, paneInputVersion34,
			))
		}
	}
	if request.Literal {
		arguments = append(arguments, "-l")
	}
	if request.Repeat != 0 {
		arguments = append(arguments, "-N", strconv.Itoa(request.Repeat))
	}
	if request.TargetClient != "" {
		if version.AtLeast(paneInputVersion34) {
			arguments = append(arguments, "-c", request.TargetClient.String())
		} else {
			warnings = append(warnings, newUnsupportedFeatureWarning(
				"send-keys", "target_client", version, paneInputVersion34,
			))
		}
	}

	if request.CopyModeCommand != nil {
		return append(arguments, "-X", "--", *request.CopyModeCommand), warnings, nil
	}
	if request.Command == nil {
		return arguments, warnings, nil
	}
	command := *request.Command
	if request.SuppressHistory {
		command = " " + command
	}
	return append(arguments, "--", command), warnings, nil
}

// Writer returns the pane's keyboard as an [io.Writer]. Bytes written to it
// are typed into the pane literally, and each newline is the Enter key, so
// [fmt.Fprintln] submits a line as a person at the keyboard would. Text with
// no trailing newline is typed and left on the line.
//
// A write returns once tmux has taken the keys, before the pane's program has
// read them; the program interprets what arrives. A line with a trailing
// newline costs two tmux commands, the text and a separate Enter; buffering
// whole lines still costs far less than writing bytes one at a time.
//
// A write of any size is typed whole, so [io.Copy] works: a line longer than
// tmux takes in one command is sent in pieces.
func (p Pane) Writer(ctx context.Context) io.Writer {
	return paneWriter{ctx: ctx, pane: p}
}

// paneWriterPiece bounds the text in one send-keys. tmux takes at most 16 KiB
// in one command, and a pane that checks its server's identity before each
// command spells every byte outside printable ASCII in four. A piece may end
// inside a UTF-8 character: tmux passes the bytes on, and the pane's program
// reads them whole.
const paneWriterPiece = 3 << 10

type paneWriter struct {
	ctx  context.Context
	pane Pane
}

func (w paneWriter) Write(data []byte) (int, error) {
	rest := string(data)
	for rest != "" {
		line, more, found := strings.Cut(rest, "\n")
		if typed, err := w.typeLine(line, found); err != nil {
			return len(data) - len(rest) + typed, err
		}
		rest = more
	}
	return len(data), nil
}

// typeLine types line in pieces tmux accepts, then presses Enter when enter is
// set. On an error it returns how many bytes of line tmux had already taken,
// so a caller resuming after them types nothing twice.
func (w paneWriter) typeLine(line string, enter bool) (int, error) {
	typed := 0
	for len(line)-typed > paneWriterPiece {
		piece := line[typed : typed+paneWriterPiece]
		if err := w.pane.SendKeys(w.ctx, SendKeysRequest{
			Command: &piece, Literal: true, SkipEnter: true,
		}); err != nil {
			return typed, err
		}
		typed += paneWriterPiece
	}
	if last := line[typed:]; last != "" {
		if err := w.pane.SendKeys(w.ctx, SendKeysRequest{
			Command: &last, Literal: true, SkipEnter: true,
		}); err != nil {
			return typed, err
		}
		typed += len(last)
	}
	if !enter {
		return typed, nil
	}
	return typed, w.pane.Enter(w.ctx)
}

// Enter sends the Enter key to the receiver's exact linked pane. A completed
// nonzero exit or stderr becomes a redacted [CommandError]; transport errors
// are delivery-ambiguous.
func (p Pane) Enter(ctx context.Context) error {
	result, err := p.literalCmd(ctx, "send-keys", "--", "Enter")
	return requireRedactedServerCommandNoStderr("send-keys", result, err)
}

// enterArguments renders [Pane.Enter] for a [Plan] without I/O.
func enterArguments(target string) ([]string, error) {
	if err := validateServerCommandArgument(
		"send-keys", "Target", target, true,
	); err != nil {
		return nil, err
	}
	return []string{"send-keys", "-t", target, "--", "Enter"}, nil
}

// sendPrefixArguments renders a prefix for a [Plan] without I/O.
func sendPrefixArguments(target string, key PrefixKey) ([]string, error) {
	arguments, err := targetedArguments("send-prefix", target)
	if err != nil {
		return nil, err
	}
	switch key {
	case PrefixPrimary:
		return arguments, nil
	case PrefixSecondary:
		return append(arguments, "-2"), nil
	default:
		return nil, invalidServerCommandRequest(
			"send-prefix", "Key", strconv.FormatUint(uint64(key), 10), "is unsupported",
		)
	}
}

// PrefixKey selects the primary or secondary tmux prefix key. Its zero value
// selects the primary prefix.
type PrefixKey uint8

const (
	// PrefixPrimary selects tmux's primary prefix key.
	PrefixPrimary PrefixKey = iota
	// PrefixSecondary selects tmux's secondary prefix key.
	PrefixSecondary
)

// SendPrefix sends a tmux prefix key to the receiver's exact linked pane.
// Unsupported PrefixKey values fail before execution. A completed command
// produces a [CommandError] only when tmux writes stderr; the library-created
// error retains only the exit code. Nonzero exits without stderr are ignored;
// transport errors are delivery-ambiguous.
func (p Pane) SendPrefix(ctx context.Context, key PrefixKey) error {
	if err := validateTypedTarget(
		"send-prefix", "Pane", "pane", p.paneID.String(),
	); err != nil {
		return err
	}
	target, err := exactPaneTarget(p)
	if err != nil {
		return err
	}
	arguments, err := sendPrefixArguments(target, key)
	if err != nil {
		return err
	}
	result, err := p.server.literalCmd(ctx, arguments...)
	return requireRedactedServerCommandNoStderr("send-prefix", result, err)
}

// ClearHistoryRequest configures pane history clearing. Its zero value clears
// scrollback without requesting hyperlink cleanup.
type ClearHistoryRequest struct {
	// ResetHyperlinks also removes hyperlinks. It requires tmux 3.4; see
	// UnsupportedPolicy.
	ResetHyperlinks bool
}

// ClearHistory removes scrollback from the receiver's exact linked pane.
// ResetHyperlinks triggers a version probe before mutation. A completed
// command produces a redacted [CommandError] only for stderr; nonzero exits
// without stderr are ignored. Accepted changes are not rolled back.
func (p Pane) ClearHistory(ctx context.Context, request ClearHistoryRequest) error {
	if err := validateTypedTarget(
		"clear-history", "Pane", "pane", p.paneID.String(),
	); err != nil {
		return err
	}
	var current Version
	if request.ResetHyperlinks {
		probed, err := p.server.Version(ctx)
		if err != nil {
			return err
		}
		current = probed
	}
	target, err := exactPaneTarget(p)
	if err != nil {
		return err
	}
	arguments, warnings, err := clearHistoryArguments(target, request, current)
	if err != nil {
		return err
	}
	if err := p.server.reportUnsupported(warnings); err != nil {
		return err
	}
	result, err := p.server.literalCmd(ctx, arguments...)
	return requireRedactedServerCommandNoStderr("clear-history", result, err)
}

// clearHistoryArguments renders without I/O and returns compatibility warnings.
func clearHistoryArguments(
	target string,
	request ClearHistoryRequest,
	version Version,
) ([]string, []Warning, error) {
	arguments, err := targetedArguments("clear-history", target)
	if err != nil {
		return nil, nil, err
	}
	var warnings []Warning
	if request.ResetHyperlinks {
		if version.AtLeast(paneInputVersion34) {
			arguments = append(arguments, "-H")
		} else {
			warnings = append(warnings, newUnsupportedFeatureWarning(
				"clear-history", "reset_hyperlinks", version, paneInputVersion34,
			))
		}
	}
	return arguments, warnings, nil
}

// Clear types the text "reset" and then Enter into the receiver's exact linked
// pane, the way a person at the keyboard would. Whatever is running reads it:
// a shell runs reset(1), and an editor receives the word. Use [Pane.Reset] or
// [Pane.ClearHistory] to act on the pane itself rather than on its program.
// A transport error may leave the text delivered without Enter.
func (p Pane) Clear(ctx context.Context) error {
	command := "reset"
	return p.SendKeys(ctx, SendKeysRequest{Command: &command})
}

// Reset submits one tmux command list that resets terminal state and then
// clears history for the exact linked pane. The mutations are not atomic and
// may be partial. Only stderr makes a completed command a [CommandError];
// nonzero exits without stderr are ignored. Transport errors are
// delivery-ambiguous.
func (p Pane) Reset(ctx context.Context) error {
	target, err := exactPaneTarget(p)
	if err != nil {
		return err
	}
	result, err := p.server.Cmd(
		ctx,
		"send-keys", "-t", target, "-R",
		";",
		"clear-history", "-t", target,
	)
	// tmux runs a list until one command fails and merges their output, so the
	// label names the list rather than guessing which half stderr came from.
	return requireServerCommandNoStderr("send-keys; clear-history", result, err)
}

func captureSendKeysRequest(request SendKeysRequest) SendKeysRequest {
	if request.Command != nil {
		value := *request.Command
		request.Command = &value
	}
	if request.CopyModeCommand != nil {
		value := *request.CopyModeCommand
		request.CopyModeCommand = &value
	}
	return request
}

func validateSendKeysRequest(p Pane, request SendKeysRequest) error {
	if err := validateTypedTarget(
		"send-keys", "Pane", "pane", p.paneID.String(),
	); err != nil {
		return err
	}
	arguments := []serverCommandArgument{{field: "Pane", value: p.paneID.String()}}
	if request.Command != nil {
		arguments = append(arguments, serverCommandArgument{field: "Command", value: *request.Command})
	}
	if request.CopyModeCommand != nil {
		arguments = append(
			arguments,
			serverCommandArgument{field: "CopyModeCommand", value: *request.CopyModeCommand},
		)
	}
	if request.TargetClient != "" {
		arguments = append(
			arguments,
			serverCommandArgument{field: "TargetClient", value: request.TargetClient.String()},
		)
	}
	if err := validateServerCommandArguments("send-keys", arguments...); err != nil {
		return err
	}
	if request.Repeat < 0 {
		return invalidServerCommandRequest(
			"send-keys", "Repeat", strconv.Itoa(request.Repeat), "must be positive",
		)
	}
	if request.Command == nil && request.CopyModeCommand == nil && !request.Reset && request.Repeat == 0 {
		return invalidServerCommandRequest(
			"send-keys",
			"Command",
			"",
			"must be set unless Reset, Repeat, or CopyModeCommand is set",
		)
	}
	return nil
}

tmux/pane_modes.go.content:
package tmux

import (
	"context"
	"strconv"
)

var paneModesVersion35 = Version{raw: "3.5", major: 3, minor: 5}

// CopyModeRequest configures tmux copy mode. Its zero value enters copy mode
// on the receiver without scrolling. Fields may be combined. tmux resolves the
// receiver and optional SourcePane before processing Cancel, so a stale target
// can prevent reset. After resolution, Cancel takes precedence over other actions,
// though SourcePane validation and the PageDown version probe still occur first.
type CopyModeRequest struct {
	// ScrollUp enters copy mode one page above the current position.
	ScrollUp bool
	// ExitOnBottom makes copy mode exit after scrolling back to the visible
	// screen, until another non-scrolling key disables that behavior.
	ExitOnBottom bool
	// MouseDrag begins a copy-mode mouse drag and is meaningful from a mouse
	// binding.
	MouseDrag bool
	// PageDown enters copy mode one page below the current position. It requires
	// tmux 3.5 and follows UnsupportedPolicy. Its version probe still occurs
	// when Cancel is set.
	PageDown bool
	// SourcePane selects a stable pane whose content is copied while the
	// receiver remains the pane placed in copy mode. Zero uses the receiver. A
	// nonzero value is validated by the library and resolved by tmux even when
	// Cancel is set; a stale or nonexistent pane can prevent cancellation.
	SourcePane PaneID
	// Cancel exits copy mode and any other active pane mode after tmux resolves
	// the receiver and optional SourcePane. A resolution failure prevents the
	// reset; after successful resolution, tmux ignores the other action fields.
	Cancel bool
}

// TreeSortOrder selects one initial tmux choose-tree ordering. Its zero value
// leaves tmux's configured ordering unchanged.
type TreeSortOrder uint8

const (
	// TreeSortDefault leaves the configured choose-tree ordering unchanged.
	TreeSortDefault TreeSortOrder = iota
	// TreeSortIndex orders tree entries by index.
	TreeSortIndex
	// TreeSortName orders tree entries by name.
	TreeSortName
	// TreeSortTime orders tree entries by activity time.
	TreeSortTime
	// TreeSortSize orders tree entries by size.
	TreeSortSize
)

// ChooseTreeRequest configures the interactive session and window chooser. Its
// zero value uses tmux defaults. Format and Filter are copied before execution
// and must not be mutated concurrently.
type ChooseTreeRequest struct {
	// SessionsCollapsed starts with session nodes collapsed.
	SessionsCollapsed bool
	// WindowsCollapsed starts with window nodes collapsed.
	WindowsCollapsed bool
	// Format is a tmux format expression evaluated for each tree item. Nil
	// leaves the configured format; nonnil empty remains an explicit format.
	Format *string
	// Filter is a tmux format expression whose truth value selects tree items.
	// Nil omits filtering; nonnil empty remains an explicit expression.
	Filter *TmuxFilter
	// Sort selects the initial ordering. Unknown values are rejected before
	// execution.
	Sort TreeSortOrder
	// Reverse reverses the initial tree ordering.
	Reverse bool
	// Zoom zooms the chooser pane while tree mode is active.
	Zoom bool
}

// FindWindowRequest configures the interactive window search chooser. Match is
// a tmux search operand, not a shell command. The zero value searches with an
// empty glob using tmux's default name, title, and visible-content scopes.
type FindWindowRequest struct {
	// Match is the glob pattern, or regular expression when Regex is true.
	Match string
	// MatchContent restricts matching to visible window content, not history.
	MatchContent bool
	// CaseInsensitive makes matching ignore case.
	CaseInsensitive bool
	// MatchName restricts matching to window names.
	MatchName bool
	// Regex interprets Match as a regular expression instead of a glob.
	Regex bool
	// MatchTitle restricts matching to window titles.
	MatchTitle bool
}

// DisplayPanesRequest configures pane-number display for tmux's current client
// and does not inherit the Pane target. Duration is read during the call, not
// retained, and must not be mutated concurrently.
type DisplayPanesRequest struct {
	// Duration is the display time in milliseconds. Nil uses tmux's
	// display-panes-time option; zero waits for a key press. Negative values are
	// rejected before execution.
	Duration *int
	// NoSelect prevents number keys from selecting a pane, so the display
	// closes only after its duration. With Duration set to zero, it may remain
	// until the context is canceled.
	NoSelect bool
}

// CopyMode enters or cancels copy mode using the receiver's exact linked
// session-window-pane target. PageDown requires tmux 3.5 and follows
// [UnsupportedPolicy]. A version-probe error stops the operation. tmux resolves
// the receiver and optional SourcePane before
// processing Cancel; a stale target can therefore fail without resetting the
// current mode. Cancel then takes precedence over other actions.
//
// Only stderr produces a redacted [CommandError]; nonzero exits without stderr
// are ignored. Accepted mode changes are not rolled back.
func (p Pane) CopyMode(ctx context.Context, request CopyModeRequest) error {
	arguments, err := exactPaneCommandArguments(p, "copy-mode")
	if err != nil {
		return err
	}

	var sourcePane string
	if request.SourcePane != "" {
		sourcePane = request.SourcePane.String()
		if err := validateTypedTarget(
			"copy-mode", "SourcePane", "pane", sourcePane,
		); err != nil {
			return err
		}
	}

	var current Version
	if request.PageDown {
		current, err = p.server.Version(ctx)
		if err != nil {
			return err
		}
	}
	if request.ScrollUp {
		arguments = append(arguments, "-u")
	}
	if request.ExitOnBottom {
		arguments = append(arguments, "-e")
	}
	if request.MouseDrag {
		arguments = append(arguments, "-M")
	}
	if request.PageDown {
		if current.AtLeast(paneModesVersion35) {
			arguments = append(arguments, "-d")
		} else if err := p.server.unsupportedFeature(
			"copy-mode", "page_down", current, paneModesVersion35,
		); err != nil {
			return err
		}
	}
	if sourcePane != "" {
		arguments = append(arguments, "-s", sourcePane)
	}
	if request.Cancel {
		arguments = append(arguments, "-q")
	}
	return runRedactedPaneModeCommand(ctx, p.server, "copy-mode", arguments)
}

// ClockMode enters clock mode using the receiver's exact linked target.
func (p Pane) ClockMode(ctx context.Context) error {
	return p.runSimplePaneMode(ctx, "clock-mode")
}

// ChooseBuffer enters tmux's interactive buffer chooser using the receiver's
// exact linked target. It requires an attached client.
func (p Pane) ChooseBuffer(ctx context.Context) error {
	return p.runSimplePaneMode(ctx, "choose-buffer")
}

// ChooseClient enters tmux's interactive client chooser using the receiver's
// exact linked target. It requires an attached client.
func (p Pane) ChooseClient(ctx context.Context) error {
	return p.runSimplePaneMode(ctx, "choose-client")
}

// CustomizeMode enters tmux's interactive option browser using the receiver's
// exact linked target. It requires an attached client.
func (p Pane) CustomizeMode(ctx context.Context) error {
	return p.runSimplePaneMode(ctx, "customize-mode")
}

// ChooseTree enters tmux's interactive session, window, and pane chooser using
// the receiver's exact linked target. It requires an attached client. Format
// and Filter are tmux expressions; neither is interpreted by a shell.
// Unsupported sort values fail before execution. Only stderr produces a
// redacted [CommandError]; transport errors may leave tree mode active.
func (p Pane) ChooseTree(ctx context.Context, request ChooseTreeRequest) error {
	arguments, err := exactPaneCommandArguments(p, "choose-tree")
	if err != nil {
		return err
	}
	format := copyOptionalString(request.Format)
	var filter *TmuxFilter
	if request.Filter != nil {
		value := *request.Filter
		filter = &value
	}
	if format != nil {
		if err := validateServerCommandArgument("choose-tree", "Format", *format, true); err != nil {
			return err
		}
	}
	if filter != nil {
		if err := validateServerCommandArgument(
			"choose-tree", "Filter", string(*filter), true,
		); err != nil {
			return err
		}
	}
	sortOrder, err := treeSortArgument(request.Sort)
	if err != nil {
		return err
	}

	if request.SessionsCollapsed {
		arguments = append(arguments, "-s")
	}
	if request.WindowsCollapsed {
		arguments = append(arguments, "-w")
	}
	if request.Zoom {
		arguments = append(arguments, "-Z")
	}
	if request.Reverse {
		arguments = append(arguments, "-r")
	}
	if format != nil {
		arguments = append(arguments, "-F", *format)
	}
	if filter != nil {
		arguments = append(arguments, "-f", string(*filter))
	}
	if sortOrder != "" {
		arguments = append(arguments, "-O", sortOrder)
	}
	return runRedactedPaneModeCommand(ctx, p.server, "choose-tree", arguments)
}

// FindWindow opens a tree chooser filtered by Match using the receiver's exact
// linked target. It requires an attached client. Match is passed as one tmux
// search operand and protected from leading-dash option parsing; it is not a
// tmux format or shell command. Only stderr produces a redacted [CommandError];
// transport errors may leave the chooser open.
func (p Pane) FindWindow(ctx context.Context, request FindWindowRequest) error {
	arguments, err := exactPaneCommandArguments(p, "find-window")
	if err != nil {
		return err
	}
	if err := validateServerCommandArgument(
		"find-window", "Match", request.Match, true,
	); err != nil {
		return err
	}
	if request.MatchContent {
		arguments = append(arguments, "-C")
	}
	if request.CaseInsensitive {
		arguments = append(arguments, "-i")
	}
	if request.MatchName {
		arguments = append(arguments, "-N")
	}
	if request.Regex {
		arguments = append(arguments, "-r")
	}
	if request.MatchTitle {
		arguments = append(arguments, "-T")
	}
	arguments = append(arguments, "--", request.Match)
	return runRedactedPaneModeCommand(ctx, p.server, "find-window", arguments)
}

// DisplayPanes displays pane numbers for tmux's current client and waits for
// the indicator to close. It is client-scoped: the receiver supplies only the
// server connection and no pane target. A zero request uses tmux's configured
// duration and permits number-key selection.
//
// Only stderr produces a redacted [CommandError]; nonzero exits without stderr
// are ignored. Cancellation cannot revoke an accepted display.
func (p Pane) DisplayPanes(ctx context.Context, request DisplayPanesRequest) error {
	arguments := []string{"display-panes"}
	if request.Duration != nil {
		duration := *request.Duration
		if duration < 0 {
			return invalidServerCommandRequest(
				"display-panes", "Duration", strconv.Itoa(duration), "must be nonnegative",
			)
		}
		arguments = append(arguments, "-d", strconv.Itoa(duration))
	}
	if request.NoSelect {
		arguments = append(arguments, "-N")
	}
	result, err := p.server.literalCmd(ctx, arguments...)
	return requireRedactedServerCommandNoStderr("display-panes", result, err)
}

func (p Pane) runSimplePaneMode(ctx context.Context, subcommand string) error {
	arguments, err := exactPaneCommandArguments(p, subcommand)
	if err != nil {
		return err
	}
	return runRedactedPaneModeCommand(ctx, p.server, subcommand, arguments)
}

func exactPaneCommandArguments(pane Pane, subcommand string) ([]string, error) {
	target, err := exactPaneTarget(pane)
	if err != nil {
		return nil, err
	}
	return []string{subcommand, "-t", target}, nil
}

func runRedactedPaneModeCommand(
	ctx context.Context,
	server Server,
	subcommand string,
	arguments []string,
) error {
	result, err := server.literalCmd(ctx, arguments...)
	return requireRedactedServerCommandNoStderr(subcommand, result, err)
}

func treeSortArgument(order TreeSortOrder) (string, error) {
	switch order {
	case TreeSortDefault:
		return "", nil
	case TreeSortIndex:
		return "index", nil
	case TreeSortName:
		return "name", nil
	case TreeSortTime:
		return "time", nil
	case TreeSortSize:
		return "size", nil
	default:
		return "", invalidServerCommandRequest(
			"choose-tree",
			"Sort",
			strconv.FormatUint(uint64(order), 10),
			"is unsupported",
		)
	}
}

tmux/pane_popup.go.content:
package tmux

import (
	"context"
	"maps"
	"slices"
)

var (
	panePopupVersion36 = Version{raw: "3.6", major: 3, minor: 6}
	// panePopupVersion39 is where tmux made display-popup create a floating
	// pane. No popup exists to modify, so -N, which only clears the
	// automatic-close flags of an existing one, is no longer accepted.
	panePopupVersion39 = Version{raw: "next-3.9", major: 3, minor: 9, development: -1}
	// panePopupVersion38 is where tmux added an explicit refusal for a
	// control-mode target client: cmd_display_popup_exec gained
	// "if (tc->flags & CLIENT_CONTROL) return (CMD_RETURN_NORMAL);"
	// (cmd-display-menu.c, 3.7c to 3.8-rc2, the earliest build measured),
	// matching tmux's own regress/control-client-popup.sh ("Popups require a
	// tty overlay and cannot be displayed by a control client"). tmux answers CMD_RETURN_NORMAL
	// either way, so nothing distinguishes the refusal from success on the
	// wire; a caller only learns the popup never ran, if they later look.
	panePopupVersion38 = Version{raw: "3.8-rc2", major: 3, minor: 8, candidate: 3}
)

// DisplayPopupRequest configures a popup overlay. Pointer and map values are
// copied before I/O and must not be mutated concurrently.
// Pointer fields distinguish omission from an explicit empty value, with the
// Command and StartDirectory behavior documented on those fields.
//
// CloseOnExit and CloseOnSuccess are mutually exclusive. CloseExisting asks
// tmux only to close the existing overlay, so the remaining fields do not
// create a replacement. NoBorder makes BorderLines ineffective. When modifying
// an existing popup, NoKeys clears its configured automatic-close flags before
// tmux applies CloseOnExit, CloseOnSuccess, and CloseOnAnyKey from this request.
// NoKeys does not disable keyboard input.
type DisplayPopupRequest struct {
	// Command is interpreted by tmux as a shell command. Nil lets tmux use
	// default-command and then its default shell; nonnil empty is passed
	// explicitly and tmux resolves it directly to the default shell.
	Command *string
	// CloseOnExit closes the overlay whenever Command exits.
	CloseOnExit bool
	// CloseOnSuccess closes the overlay only when Command exits successfully.
	CloseOnSuccess bool
	// CloseExisting closes the selected client's existing overlay and prevents
	// this request from creating a replacement.
	CloseExisting bool
	// TargetClient selects the client that receives the overlay; zero lets tmux
	// choose. tmux 3.8 and later refuses to host a popup on a control-mode
	// client, which cannot render an overlay, so an explicit control-mode
	// TargetClient is rejected on those versions rather than left as the
	// silent no-op tmux itself returns.
	TargetClient ClientName
	// Width is an explicit cell count or percentage and may contain tmux format
	// expressions. Nil lets tmux choose the default width.
	Width *string
	// Height is an explicit cell count or percentage and may contain tmux
	// format expressions. Nil lets tmux choose the default height.
	Height *string
	// X is a tmux popup position expression and may contain tmux formats. Nil
	// lets tmux choose the horizontal position.
	X *string
	// Y is a tmux popup position expression and may contain tmux formats. Nil
	// lets tmux choose the vertical position.
	Y *string
	// StartDirectory selects the popup working directory. Nil omits the option;
	// nonnil empty is normalized to ".". The library expands a leading local ~
	// before tmux expands formats in the resulting value.
	// A directory that does not exist is not an error: tmux starts the
	// process in the home directory instead, or in / without one.
	StartDirectory *string
	// Title is the popup title format. Nil leaves the tmux default.
	Title *string
	// BorderLines selects tmux's border-line style. NoBorder makes it
	// ineffective.
	BorderLines *string
	// Style selects the tmux style for the popup interior.
	Style *string
	// BorderStyle selects the tmux style for the popup border.
	BorderStyle *string
	// Environment adds validated popup environment entries. Nil and an empty
	// map add none; entries are sent in lexical key order.
	Environment map[string]string
	// NoBorder removes the popup border and makes BorderLines ineffective.
	NoBorder bool
	// CloseOnAnyKey lets a nonmouse, nonpaste key dismiss the popup after its
	// command has exited. It does not dismiss the popup while the job is active;
	// tmux continues to send keys to that job.
	CloseOnAnyKey bool
	// NoKeys clears automatic-close flags previously configured on an existing
	// popup. Same-request close flags are then applied, and key input remains
	// enabled.
	NoKeys bool
}

type displayPopupValues struct {
	command        *string
	targetClient   string
	width          *string
	height         *string
	x              *string
	y              *string
	startDirectory *string
	title          *string
	borderLines    *string
	style          *string
	borderStyle    *string
	environment    []string
	closeOnExit    bool
	closeOnSuccess bool
	closeExisting  bool
	noBorder       bool
	closeOnAnyKey  bool
	noKeys         bool
}

// DisplayPopup displays an overlay on the selected client and waits until it
// closes after command exit or user dismissal. A zero request starts tmux's
// default command or default shell and may wait indefinitely. The API exposes
// no popup process handle, stdout, or child exit status.
//
// The command carries the receiver's exact linked session-window-pane target,
// which supplies format and working-directory context. TargetClient selects
// the overlay client; it does not turn the operation into pane delivery. tmux
// interprets Command as a shell command; outer-parser escaping does not quote
// or neutralize that inner command.
//
// CloseOnAnyKey and NoKeys require tmux 3.6. Unsupported fields follow
// [UnsupportedPolicy]. NoKeys is omitted from tmux 3.9, whose popups are
// floating panes with no earlier popup to modify. On tmux 3.8 and later, an
// explicit TargetClient that resolves to a control-mode client returns
// [ErrInvalidServerCommandRequest] unless CloseExisting is set: tmux itself answers that combination exactly
// as it answers success, so nothing on the wire would otherwise say the
// popup never ran. CloseExisting is exempt because tmux handles it before
// that refusal on every version, clearing whatever overlay the target has -
// nothing, for a control-mode client - without creating anything either way.
//
// Invalid fields fail before display. Only stderr produces a redacted
// [CommandError]; nonzero exits without stderr are ignored. Cancellation cannot
// dismiss an accepted popup, which may remain visible.
func (p Pane) DisplayPopup(ctx context.Context, request DisplayPopupRequest) error {
	arguments, err := exactPaneCommandArguments(p, "display-popup")
	if err != nil {
		return err
	}
	values, err := captureDisplayPopupRequest(request)
	if err != nil {
		return err
	}

	var current Version
	if values.needsVersion() || values.targetClient != "" {
		current, err = p.server.Version(ctx)
		if err != nil {
			return err
		}
	}
	// CloseExisting is exempt: cmd_display_popup_exec handles -C before the
	// CLIENT_CONTROL refusal (cmd-display-menu.c), clearing whatever overlay
	// the target has - nothing for a control-mode client, which never had
	// one - and returns without creating anything, on every version. That
	// path was never broken, so it is not this check's problem.
	if values.targetClient != "" && !values.closeExisting && current.AtLeast(panePopupVersion38) {
		if err := requireDisplayPopupTargetSupportsOverlay(ctx, p.server, values.targetClient); err != nil {
			return err
		}
	}
	if values.closeExisting {
		arguments = append(arguments, "-C")
	}
	if values.targetClient != "" {
		arguments = append(arguments, "-c", values.targetClient)
	}
	if values.closeOnExit {
		arguments = append(arguments, "-E")
	}
	if values.closeOnSuccess {
		arguments = append(arguments, "-E", "-E")
	}
	if values.width != nil {
		arguments = append(arguments, "-w", *values.width)
	}
	if values.height != nil {
		arguments = append(arguments, "-h", *values.height)
	}
	if values.x != nil {
		arguments = append(arguments, "-x", *values.x)
	}
	if values.y != nil {
		arguments = append(arguments, "-y", *values.y)
	}
	if values.startDirectory != nil {
		arguments = append(arguments, "-d", *values.startDirectory)
	}
	arguments = appendPopupStyleArguments(arguments, values)
	arguments, err = appendPopupVersion36Arguments(p.server, arguments, values, current)
	if err != nil {
		return err
	}
	if values.command != nil {
		arguments = append(arguments, "--", *values.command)
	}
	result, err := p.server.literalCmd(ctx, arguments...)
	return requireRedactedServerCommandNoStderr("display-popup", result, err)
}

func captureDisplayPopupRequest(request DisplayPopupRequest) (displayPopupValues, error) {
	if request.CloseOnExit && request.CloseOnSuccess {
		return displayPopupValues{}, invalidServerCommandRequest(
			"display-popup",
			"CloseOnExit",
			"true",
			"is mutually exclusive with CloseOnSuccess",
		)
	}
	values := displayPopupValues{
		command:        copyOptionalString(request.Command),
		width:          copyOptionalString(request.Width),
		height:         copyOptionalString(request.Height),
		x:              copyOptionalString(request.X),
		y:              copyOptionalString(request.Y),
		title:          copyOptionalString(request.Title),
		borderLines:    copyOptionalString(request.BorderLines),
		style:          copyOptionalString(request.Style),
		borderStyle:    copyOptionalString(request.BorderStyle),
		closeOnExit:    request.CloseOnExit,
		closeOnSuccess: request.CloseOnSuccess,
		closeExisting:  request.CloseExisting,
		noBorder:       request.NoBorder,
		closeOnAnyKey:  request.CloseOnAnyKey,
		noKeys:         request.NoKeys,
	}
	if request.TargetClient != "" {
		client := request.TargetClient.String()
		if client == "" {
			return displayPopupValues{}, invalidServerCommandRequest(
				"display-popup", "TargetClient", "", "must not be empty",
			)
		}
		if err := validateServerCommandArgument(
			"display-popup", "TargetClient", client, true,
		); err != nil {
			return displayPopupValues{}, err
		}
		values.targetClient = client
	}
	if request.StartDirectory != nil {
		directory, err := expandCommandPath("display-popup", *request.StartDirectory)
		if err != nil {
			return displayPopupValues{}, err
		}
		values.startDirectory = &directory
	}
	for _, field := range []struct {
		name  string
		value *string
	}{
		{name: "Command", value: values.command},
		{name: "Width", value: values.width},
		{name: "Height", value: values.height},
		{name: "X", value: values.x},
		{name: "Y", value: values.y},
		{name: "Title", value: values.title},
		{name: "BorderLines", value: values.borderLines},
		{name: "Style", value: values.style},
		{name: "BorderStyle", value: values.borderStyle},
	} {
		if field.value == nil {
			continue
		}
		if err := validateServerCommandArgument(
			"display-popup", field.name, *field.value, true,
		); err != nil {
			return displayPopupValues{}, err
		}
	}

	keys := slices.Sorted(maps.Keys(request.Environment))
	values.environment = make([]string, 0, len(keys))
	for _, key := range keys {
		if err := validateEnvironmentName(key); err != nil {
			return displayPopupValues{}, err
		}
		value := request.Environment[key]
		if err := validateEnvironmentValue(value); err != nil {
			return displayPopupValues{}, err
		}
		values.environment = append(values.environment, key+"="+value)
	}
	return values, nil
}

// requireDisplayPopupTargetSupportsOverlay rejects a target client tmux 3.8+
// would otherwise silently refuse. tmux answers that refusal exactly as it
// answers success, so nothing on the wire tells a caller the popup never
// ran; this catches it before that happens, while it can still be reported.
// A target lookup failure is not this check's problem: it falls through to
// the request tmux would have received anyway, which fails or succeeds on
// its own terms.
func requireDisplayPopupTargetSupportsOverlay(
	ctx context.Context,
	server Server,
	targetClient string,
) error {
	// A lookup failure is deliberately not surfaced here: it is not this
	// check's problem, and falls through to the request tmux would have
	// received anyway.
	target, lookupErr := server.Client(ctx, ClientName(targetClient))
	if lookupErr == nil {
		if controlMode, ok := target.ControlMode(); ok && controlMode {
			return invalidServerCommandRequest(
				"display-popup", "TargetClient", targetClient,
				"is a control-mode client; tmux 3.8 and later cannot host a popup on "+
					"one and silently ignores the command instead of returning an error",
			)
		}
	}
	return nil
}

func (values displayPopupValues) needsVersion() bool {
	return values.closeOnAnyKey || values.noKeys
}

func appendPopupStyleArguments(arguments []string, values displayPopupValues) []string {
	for _, field := range []struct {
		flag  string
		value *string
	}{
		{flag: "-T", value: values.title},
		{flag: "-b", value: values.borderLines},
		{flag: "-s", value: values.style},
		{flag: "-S", value: values.borderStyle},
	} {
		if field.value != nil {
			arguments = append(arguments, field.flag, *field.value)
		}
	}
	for _, variable := range values.environment {
		arguments = append(arguments, "-e"+variable)
	}
	if values.noBorder {
		arguments = append(arguments, "-B")
	}
	return arguments
}

func appendPopupVersion36Arguments(
	server Server,
	arguments []string,
	values displayPopupValues,
	current Version,
) ([]string, error) {
	if values.closeOnAnyKey {
		if current.AtLeast(panePopupVersion36) {
			arguments = append(arguments, "-k")
		} else if err := server.unsupportedFeature(
			"display-popup", "close_on_any_key", current, panePopupVersion36,
		); err != nil {
			return nil, err
		}
	}
	if values.noKeys {
		if current.AtLeast(panePopupVersion39) {
			// Nothing to clear: a new floating pane carries no configured flags.
			return arguments, nil
		}
		if current.AtLeast(panePopupVersion36) {
			arguments = append(arguments, "-N")
		} else if err := server.unsupportedFeature(
			"display-popup", "no_keys", current, panePopupVersion36,
		); err != nil {
			return nil, err
		}
	}
	return arguments, nil
}

