// RenameWindow records a new name for the window target names.
func (p *Plan) RenameWindow(target Ref, name string) {
	p.add(Op{
		name:   "rename-window",
		target: target,
		build: func(resolved, _ string, _ planRenderContext) ([]string, error) {
