package tmux

import (
	"context"
	"strconv"
)

// PromptType selects one closed tmux prompt-history class. The zero value
// selects all prompt types.
type PromptType uint8

// Supported tmux prompt-history classes.
const (
	// PromptTypeAll selects every prompt-history class and omits -T.
	PromptTypeAll PromptType = iota
	// PromptTypeCommand selects command-prompt history.
	PromptTypeCommand
	// PromptTypeSearch selects search-prompt history.
	PromptTypeSearch
	// PromptTypeTarget selects target-prompt history.
	PromptTypeTarget
	// PromptTypeWindowTarget selects window-target-prompt history.
	PromptTypeWindowTarget
)

// PromptHistoryRequest selects one prompt-history class. A zero request
// selects every class.
type PromptHistoryRequest struct {
	// Type selects a prompt-history class; zero selects all classes.
	Type PromptType
}

// ShowPromptHistory returns an owned snapshot of tmux prompt-history lines.
// It is available on every supported tmux. A tmux command or transport failure is returned rather than answered
// with no history.
func (s Server) ShowPromptHistory(
	ctx context.Context,
	request PromptHistoryRequest,
) ([]string, error) {
	promptType, hasPromptType, err := promptHistoryType("show-prompt-history", request.Type)
	if err != nil {
		return nil, err
	}
	arguments := []string{"show-prompt-history"}
	if hasPromptType {
		arguments = append(arguments, "-T", promptType)
	}
	return runServerListCommand(ctx, s, arguments)
}

// ClearPromptHistory clears all tmux prompt history or one selected class.
// Version, transport, and completed-stderr failures are returned. It is
// available on every supported tmux.
func (s Server) ClearPromptHistory(
	ctx context.Context,
	request PromptHistoryRequest,
) error {
	promptType, hasPromptType, err := promptHistoryType("clear-prompt-history", request.Type)
	if err != nil {
		return err
	}
	arguments := []string{"clear-prompt-history"}
	if hasPromptType {
		arguments = append(arguments, "-T", promptType)
	}
	result, err := s.literalCmd(ctx, arguments...)
	return requireServerCommandNoStderr("clear-prompt-history", result, err)
}

func promptHistoryType(subcommand string, promptType PromptType) (string, bool, error) {
	switch promptType {
	case PromptTypeAll:
		return "", false, nil
	case PromptTypeCommand:
		return "command", true, nil
	case PromptTypeSearch:
		return "search", true, nil
	case PromptTypeTarget:
		return "target", true, nil
	case PromptTypeWindowTarget:
		return "window-target", true, nil
	default:
		return "", false, invalidServerCommandRequest(
			subcommand,
			"Type",
			strconv.FormatUint(uint64(promptType), 10),
			"is unsupported",
		)
	}
}

tmux/relations.go.content:
package tmux

import (
	"context"
	"strconv"
)

// ActiveWindow returns this session's sole active winlink from the materialized
// snapshot. It never queries tmux; use [Session.ResolveActiveWindow] for live
// state.
func (s Session) ActiveWindow() (Window, bool) {
	var active Window
	found := false
	windows, ok := s.Windows()
	if !ok {
		return Window{}, false
	}
	for _, window := range windows {
		value, queried := window.Active()
		if !queried || !value {
			continue
		}
		if found {
			return Window{}, false
		}
		active = window
		found = true
	}
	return active, found
}

// ActivePane returns the active pane in this session's materialized active
// window. It never queries tmux; use [Session.ResolveActivePane] for live state.
func (s Session) ActivePane() (Pane, bool) {
	window, ok := s.ActiveWindow()
	if !ok {
		return Pane{}, false
	}
	return window.ActivePane()
}

// ActivePane returns the first active pane in this materialized winlink view.
// It never queries tmux; use [Window.ResolveActivePane] for live state.
func (w Window) ActivePane() (Pane, bool) {
	panes, ok := w.Panes()
	if !ok {
		return Pane{}, false
	}
	for _, pane := range panes {
		value, queried := pane.Active()
		if queried && value {
			return pane, true
		}
	}
	return Pane{}, false
}

// LinkedSessions returns newly allocated shallow copies of materialized
// sessions containing this window, and reports whether the receiver carries
// relations at all. It never queries tmux.
func (w Window) LinkedSessions() ([]Session, bool) {
	if w.snapshot == nil || !w.snapshot.listed.holds(listedSessions|listedWindows) {
		return nil, false
	}
	result := make([]Session, 0)
	seen := make(map[SessionID]struct{})
	for _, index := range w.snapshot.windowsByID[w.windowID] {
		sessionID := w.snapshot.windows[index].sessionID
		if _, exists := seen[sessionID]; exists {
			continue
		}
		seen[sessionID] = struct{}{}
		session, ok := oneAt(w.snapshot.sessions, w.snapshot.sessionsByID[sessionID])
		if ok {
			result = append(result, session.withServer(w.server))
		}
	}
	return result, true
}

// ResolveActiveWindow snapshots live tmux state and returns this session's sole
// exact active winlink. It returns [SnapshotLookupError] cardinality errors.
func (s Session) ResolveActiveWindow(ctx context.Context) (Window, error) {
	live, err := s.resolveLive(ctx)
	if err != nil {
		return Window{}, err
	}
	return requiredActiveWindow(live)
}

// ResolveActivePane returns the active pane in this session's active window,
// read live. It lists that session's panes rather than taking a whole-server
// snapshot, because a pane row already carries which window is active. It
// returns [SnapshotLookupError] cardinality errors, which match [ErrNotFound]
// when nothing was found.
func (s Session) ResolveActivePane(ctx context.Context) (Pane, error) {
	identifier := s.sessionID.String()
	if err := validateTypedTarget(
		"list-panes", "SessionID", "session", identifier,
	); err != nil {
		return Pane{}, err
	}
	snapshot, err := s.server.hierarchyFromPanes(
		ctx,
		[]string{"-s", "-t", identifier},
		searchRowMatch{field: "session_id", value: identifier},
	)
	if err != nil {
		return Pane{}, err
	}
	return activePaneOf(snapshot.Panes(), "session", identifier, true)
}

// activePaneOf returns the first active pane among rows, as
// [Window.ActivePane] does for a materialized view. With activeWindow set it
// also requires the pane's window to be the active one, which is what picks a
// session's current pane out of every pane it holds.
func activePaneOf(panes []Pane, object, identifier string, activeWindow bool) (Pane, error) {
	for _, pane := range panes {
		if active, ok := pane.Active(); !ok || !active {
			continue
		}
		if activeWindow {
			if active, ok := pane.formats.getBool("window_active"); !ok || !active {
				continue
			}
		}
		return pane, nil
	}
	return Pane{}, &SnapshotLookupError{
		Object:     "active pane",
		Identifier: object + " " + identifier,
		Matches:    0,
	}
}

// ResolveSession snapshots live tmux state and returns this exact winlink's
// parent session. It returns [SnapshotLookupError] cardinality errors.
func (w Window) ResolveSession(ctx context.Context) (Session, error) {
	live, err := w.resolveLive(ctx)
	if err != nil {
		return Session{}, err
	}
	return lookupSnapshotValue(
		live.snapshot.sessions,
		live.snapshot.sessionsByID[live.sessionID],
		"session",
		live.sessionID.String(),
	)
}

// ResolveActivePane returns the active pane in this exact winlink view, read
// live. It lists that window's panes rather than taking a whole-server
// snapshot. It returns [SnapshotLookupError] cardinality errors, which match
// [ErrNotFound] when nothing was found.
func (w Window) ResolveActivePane(ctx context.Context) (Pane, error) {
	target, err := exactWindowTarget(w)
	if err != nil {
		return Pane{}, err
	}
	snapshot, err := w.server.hierarchyFromPanes(
		ctx,
		[]string{"-t", target},
		searchRowMatch{field: "session_id", value: w.sessionID.String()},
		searchRowMatch{field: "window_id", value: w.windowID.String()},
	)
	if err != nil {
		return Pane{}, err
	}
	return activePaneOf(snapshot.Panes(), "window", w.windowID.String(), false)
}

// ResolveWindow snapshots live tmux state and returns the exact winlink
// containing this pane view. It returns [SnapshotLookupError] cardinality errors.
func (p Pane) ResolveWindow(ctx context.Context) (Window, error) {
	live, err := p.resolveLive(ctx)
	if err != nil {
		return Window{}, err
	}
	return live.resolveSnapshotWindow()
}

// ResolveSession snapshots live tmux state and returns the parent session of
// this pane's exact winlink. It returns [SnapshotLookupError] cardinality errors.
func (p Pane) ResolveSession(ctx context.Context) (Session, error) {
	live, err := p.resolveLive(ctx)
	if err != nil {
		return Session{}, err
	}
	window, err := live.resolveSnapshotWindow()
	if err != nil {
		return Session{}, err
	}
	return lookupSnapshotValue(
		live.snapshot.sessions,
		live.snapshot.sessionsByID[window.sessionID],
		"session",
		window.sessionID.String(),
	)
}

func (s Session) resolveLive(ctx context.Context) (Session, error) {
	if err := validateTypedTarget(
		"resolve-session", "SessionID", "session", s.sessionID.String(),
	); err != nil {
		return Session{}, err
	}
	snapshot, err := s.server.Snapshot(ctx)
	if err != nil {
		return Session{}, err
	}
	return snapshot.SessionByID(s.sessionID)
}

func (w Window) resolveLive(ctx context.Context) (Window, error) {
	identifier, err := validateWindowView(w)
	if err != nil {
		return Window{}, err
	}
	snapshot, err := w.server.Snapshot(ctx)
	if err != nil {
		return Window{}, err
	}
	return lookupSnapshotValue(
		snapshot.state.windows,
		snapshot.state.windowsByWinlink[winlinkKey{
			sessionID: w.sessionID,
			windowID:  w.windowID,
			index:     w.windowIndex,
		}],
		"window",
		identifier,
	)
}

func (p Pane) resolveLive(ctx context.Context) (Pane, error) {
	identifier, err := validatePaneView(p)
	if err != nil {
		return Pane{}, err
	}
	snapshot, err := p.server.Snapshot(ctx)
	if err != nil {
		return Pane{}, err
	}
	return lookupSnapshotValue(
		snapshot.state.panes,
		snapshot.state.panesByView[paneViewKey{
			winlinkKey: winlinkKey{
				sessionID: p.sessionID,
				windowID:  p.windowID,
				index:     p.windowIndex,
			},
			paneID: p.paneID,
		}],
		"pane",
		identifier,
	)
}

func (p Pane) resolveSnapshotWindow() (Window, error) {
	identifier := windowViewIdentifier(p.sessionID, p.windowID, p.windowIndex)
	key := winlinkKey{
		sessionID: p.sessionID,
		windowID:  p.windowID,
		index:     p.windowIndex,
	}
	return lookupSnapshotValue(
		p.snapshot.windows,
		p.snapshot.windowsByWinlink[key],
		"window",
		identifier,
	)
}

func requiredActiveWindow(session Session) (Window, error) {
	window, ok, err := attachmentActiveWindow(session)
	if err != nil {
		return Window{}, err
	}
	if !ok {
		return Window{}, &SnapshotLookupError{
			Object:     "active window",
			Identifier: session.sessionID.String(),
			Matches:    0,
		}
	}
	return window, nil
}

func validateWindowView(window Window) (string, error) {
	// A Window's own identity is its window id: check it first so an
	// all-zero value (a relation accessor's discarded ok, or a created value
	// with no relations) is reported as a missing window, not a missing
	// session - the wrong kind sends a caller to a resolver that needs the
	// very window id this handle also lacks.
	if err := validateTypedTarget(
		"resolve-window", "WindowID", "window", window.windowID.String(),
	); err != nil {
		return "", err
	}
	if err := validateTypedTarget(
		"resolve-window", "SessionID", "session", window.sessionID.String(),
	); err != nil {
		return "", err
	}
	if window.windowIndex < 0 {
		return "", invalidServerCommandRequest(
			"resolve-window",
			"WindowIndex",
			strconv.Itoa(window.windowIndex),
			"must be nonnegative",
		)
	}
	return windowViewIdentifier(window.sessionID, window.windowID, window.windowIndex), nil
}

func validatePaneView(pane Pane) (string, error) {
	if _, err := validateWindowView(Window{
		sessionID: pane.sessionID, windowID: pane.windowID, windowIndex: pane.windowIndex,
	}); err != nil {
		return "", err
	}
	if err := validateTypedTarget(
		"resolve-pane", "PaneID", "pane", pane.paneID.String(),
	); err != nil {
		return "", err
	}
	return paneViewIdentifier(pane), nil
}

func windowViewIdentifier(sessionID SessionID, windowID WindowID, index int) string {
	return sessionID.String() + ":" + strconv.Itoa(index) + ":" + windowID.String()
}

func paneViewIdentifier(pane Pane) string {
	return windowViewIdentifier(pane.sessionID, pane.windowID, pane.windowIndex) + "." + pane.paneID.String()
}

tmux/scoped_command.go.content:
package tmux

import (
	"context"
	"errors"
)

// ErrMissingSubcommand identifies an object command with no tmux subcommand.
var ErrMissingSubcommand = errors.New("tmux: subcommand is required")

// Cmd executes a tmux subcommand targeted to the session's stable ID.
func (s Session) Cmd(ctx context.Context, args ...string) (CommandResult, error) {
	return scopedCommand(ctx, s.server, "session", s.sessionID.String(), args)
}

// Cmd executes a tmux subcommand targeted to the window's stable ID.
func (w Window) Cmd(ctx context.Context, args ...string) (CommandResult, error) {
	return scopedCommand(ctx, w.server, "window", w.windowID.String(), args)
}

// Cmd executes a tmux subcommand targeted to the pane's stable ID.
func (p Pane) Cmd(ctx context.Context, args ...string) (CommandResult, error) {
	return scopedCommand(ctx, p.server, "pane", p.paneID.String(), args)
}

func (s Session) literalCmd(ctx context.Context, args ...string) (CommandResult, error) {
	return literalScopedCommand(ctx, s.server, "session", s.sessionID.String(), args)
}

func (w Window) literalCmd(ctx context.Context, args ...string) (CommandResult, error) {
	return literalScopedCommand(ctx, w.server, "window", w.windowID.String(), args)
}

func (p Pane) literalCmd(ctx context.Context, args ...string) (CommandResult, error) {
	return literalPaneCommand(ctx, p, args)
}

func scopedCommand(
	ctx context.Context,
	server Server,
	object string,
	target string,
	args []string,
) (CommandResult, error) {
	if len(args) == 0 {
		return CommandResult{ExitCode: -1}, ErrMissingSubcommand
	}
	if err := validateTypedTarget(args[0], "Target", object, target); err != nil {
		return CommandResult{ExitCode: -1}, err
	}
	arguments := make([]string, 0, len(args)+2)
	arguments = append(arguments, args[0], "-t", target)
	arguments = append(arguments, args[1:]...)
	return server.Cmd(ctx, arguments...)
}

func literalScopedCommand(
	ctx context.Context,
	server Server,
	object string,
	target string,
	args []string,
) (CommandResult, error) {
	if len(args) == 0 {
		return CommandResult{ExitCode: -1}, ErrMissingSubcommand
	}
	if err := validateServerCommandArgument(
		"command", "Target", target, true,
	); err != nil {
		return CommandResult{ExitCode: -1}, err
	}
	for _, argument := range args {
		if err := validateServerCommandArgument(
			"command", "Arguments", argument, true,
		); err != nil {
			return CommandResult{ExitCode: -1}, err
		}
	}
	if err := validateTypedTarget(args[0], "Target", object, target); err != nil {
		return CommandResult{ExitCode: -1}, err
	}
	arguments := make([]string, 0, len(args)+2)
	arguments = append(arguments, args[0], "-t", target)
	arguments = append(arguments, args[1:]...)
	return server.literalCmd(ctx, arguments...)
}

tmux/search.go.content:
package tmux

import "context"

var searchClientsFilterVersion34 = Version{raw: "3.4", major: 3, minor: 4}

type searchCollection uint8

type searchRowMatch struct {
	field string
	value string
}

const (
	searchSessions searchCollection = iota
	searchWindows
	searchPanes
	searchClients
)

// SearchSessions returns a newly materialized snapshot projection of sessions
// selected by tmux's live -f expression. A nil filter omits -f; a nonnil empty
// filter remains an explicit empty expression.
func (s Server) SearchSessions(
	ctx context.Context,
	filter *TmuxFilter,
) ([]Session, error) {
	snapshot, err := s.searchSnapshot(
		ctx, "list-sessions", nil, filter, searchSessions,
	)
	if err != nil {
		return nil, err
	}
	return snapshot.Sessions(), nil
}

// SearchClients returns a newly materialized snapshot projection of clients
// selected by tmux's live -f expression. A nil filter omits -f and requests the
// unfiltered listing on every supported tmux version. A nonnil filter,
// including an empty expression, requires tmux 3.4 or newer and otherwise
// returns [VersionTooLowError].
func (s Server) SearchClients(
	ctx context.Context,
	filter *TmuxFilter,
) ([]Client, error) {
	snapshot, err := s.searchSnapshot(
		ctx, "list-clients", nil, filter, searchClients,
	)
	if err != nil {
		return nil, err
	}
	return snapshot.Clients(), nil
}

// SearchWindows returns a newly materialized snapshot projection of winlinks
// selected by tmux's live -f expression. A nil filter omits -f and a nonnil
// empty filter sends an explicit expression.
func (s Server) SearchWindows(
	ctx context.Context,
	filter *TmuxFilter,
) ([]Window, error) {
	snapshot, err := s.searchSnapshot(
		ctx, "list-windows", []string{"-a"}, filter, searchWindows,
	)
	if err != nil {
		return nil, err
	}
	return snapshot.Windows(), nil
}

// SearchPanes returns a newly materialized snapshot projection of pane views
// selected by tmux's live -f expression. A nil filter omits -f and a nonnil
// empty filter sends an explicit expression.
func (s Server) SearchPanes(
	ctx context.Context,
	filter *TmuxFilter,
) ([]Pane, error) {
	snapshot, err := s.searchSnapshot(
		ctx, "list-panes", []string{"-a"}, filter, searchPanes,
	)
	if err != nil {
		return nil, err
	}
	return snapshot.Panes(), nil
}

// SearchWindows returns this session's winlinks selected by tmux's live -f
// expression. A nil filter omits -f and a nonnil empty filter sends an
// explicit expression. The session's stable identity limits the projection.
func (s Session) SearchWindows(
	ctx context.Context,
	filter *TmuxFilter,
) ([]Window, error) {
	identifier := s.sessionID.String()
	if err := validateTypedTarget(
		"list-windows", "SessionID", "session", identifier,
	); err != nil {
		return nil, err
	}
	snapshot, err := s.server.searchSnapshot(
		ctx,
		"list-windows",
		[]string{"-t", identifier},
		filter,
		searchWindows,
		searchRowMatch{field: "session_id", value: identifier},
	)
	if err != nil {
		return nil, err
	}
	return snapshot.Windows(), nil
}

// SearchPanes returns this session's pane views selected by tmux's live -f
// expression. A nil filter omits -f and a nonnil empty filter sends an
// explicit expression. The session's stable identity limits the projection.
func (s Session) SearchPanes(
	ctx context.Context,
	filter *TmuxFilter,
) ([]Pane, error) {
	identifier := s.sessionID.String()
	if err := validateTypedTarget(
		"list-panes", "SessionID", "session", identifier,
	); err != nil {
		return nil, err
	}
	snapshot, err := s.server.searchSnapshot(
		ctx,
		"list-panes",
		[]string{"-s", "-t", identifier},
		filter,
		searchPanes,
		searchRowMatch{field: "session_id", value: identifier},
	)
	if err != nil {
		return nil, err
	}
	return snapshot.Panes(), nil
}

// SearchPanes returns this window's pane views selected by tmux's live -f
// expression. A nil filter omits -f and a nonnil empty filter sends an
// explicit expression. Stable session and window identities limit the projection.
func (w Window) SearchPanes(
	ctx context.Context,
	filter *TmuxFilter,
) ([]Pane, error) {
	target, err := exactWindowTarget(w)
	if err != nil {
		return nil, err
	}
	snapshot, err := w.server.searchSnapshot(
		ctx,
		"list-panes",
		[]string{"-t", target},
		filter,
		searchPanes,
		searchRowMatch{field: "session_id", value: w.sessionID.String()},
		searchRowMatch{field: "window_id", value: w.windowID.String()},
	)
	if err != nil {
		return nil, err
	}
	return snapshot.Panes(), nil
}

func (s Server) searchSnapshot(
	ctx context.Context,
	command string,
	extra []string,
	filter *TmuxFilter,
	collection searchCollection,
	matches ...searchRowMatch,
) (Snapshot, error) {
	return s.searchSnapshotProjected(ctx, command, extra, filter, collection, false, matches...)
}

// searchSnapshotProjected is searchSnapshot with hierarchy reporting whether
// each row also materializes the session and window it names.
func (s Server) searchSnapshotProjected(
	ctx context.Context,
	command string,
	extra []string,
	filter *TmuxFilter,
	collection searchCollection,
	hierarchy bool,
	matches ...searchRowMatch,
) (Snapshot, error) {
	filterArguments, err := captureSearchFilter(command, filter)
	if err != nil {
		return Snapshot{}, err
	}
	extra = append(append([]string(nil), extra...), filterArguments...)

	identity, err := s.probeSnapshotIdentity(ctx)
	if err != nil {
		return Snapshot{}, err
	}
	minimum, err := ParseVersion(MinimumSupportedVersion)
	if err != nil {
		return Snapshot{}, err
	}
	if !identity.version.meetsMinimum(minimum) {
		return Snapshot{}, &VersionTooLowError{Current: identity.version, Minimum: minimum}
	}
	if collection == searchClients && filter != nil &&
		!identity.version.AtLeast(searchClientsFilterVersion34) {
		return Snapshot{}, &VersionTooLowError{
			Current: identity.version,
			Minimum: searchClientsFilterVersion34,
		}
	}

	rows, listErr := s.snapshotListing(ctx, command, extra, identity.version)
	if listErr != nil {
		if snapshotCollectionError(listErr) {
			return s.snapshotAfterListingFailure(ctx, identity, listErr)
		}
		return Snapshot{}, listErr
	}
	if len(matches) != 0 {
		rows = matchingSearchRows(rows, matches)
	}

	closing, err := s.probeClosingIdentity(ctx, identity)
	if err != nil {
		return Snapshot{}, err
	}
	if !sameSnapshotIdentity(identity, closing) {
		return Snapshot{}, snapshotIdentityChangeError(closing)
	}
	records, listed := searchSnapshotRecords(collection, rows), searchListedCollection(collection)
	if hierarchy {
		records = paneRowHierarchy(rows)
		listed = listedSessions | listedWindows | listedPanes
	}
	return newSnapshotWithIdentity(s, identity.version, records, listed, &identity)
}

// paneRowHierarchy reads the sessions and windows holding rows out of the rows
// themselves, which carry every session- and window-scope field. Each is kept
// once: a window's panes each name it, and a record that appeared twice would
// be as ambiguous to a relation lookup as two different windows.
func paneRowHierarchy(rows []formatValues) snapshotRecords {
	records := snapshotRecords{panes: rows}
	sessions := make(map[string]struct{}, len(rows))
	windows := make(map[winlinkKey]struct{}, len(rows))
	for _, row := range rows {
		sessionID, _ := row.get("session_id")
		if _, seen := sessions[sessionID]; !seen {
			sessions[sessionID] = struct{}{}
			records.sessions = append(records.sessions, row)
		}
		windowID, _ := row.get("window_id")
		index, _ := row.getInt("window_index")
		key := winlinkKey{
			sessionID: SessionID(sessionID),
			windowID:  WindowID(windowID),
			index:     index,
		}
		if _, seen := windows[key]; !seen {
			windows[key] = struct{}{}
			records.windows = append(records.windows, row)
		}
	}
	return records
}

func captureSearchFilter(command string, filter *TmuxFilter) ([]string, error) {
	if filter == nil {
		return nil, nil
	}
	value := string(*filter)
	if err := validateServerCommandArgument(command, "Filter", value, true); err != nil {
		return nil, err
	}
	return []string{"-f", value}, nil
}

func matchingSearchRows(rows []formatValues, matches []searchRowMatch) []formatValues {
	matching := make([]formatValues, 0, len(rows))
	for _, row := range rows {
		matched := true
		for _, match := range matches {
			current, ok := row.get(match.field)
			if !ok || current != match.value {
				matched = false
				break
			}
		}
		if matched {
			matching = append(matching, row)
		}
	}
	return matching
}

func searchListedCollection(collection searchCollection) snapshotCollections {
	switch collection {
	case searchSessions:
		return listedSessions
	case searchWindows:
		return listedWindows
	case searchPanes:
		return listedPanes
	case searchClients:
		return listedClients
	}
	return 0
}

// hierarchyFromPanes lists panes and reads the sessions and windows holding
// them out of the same rows, which carry every session- and window-scope
// field. One listing therefore materializes the graph those panes sit in,
// where listing each kind separately costs a command apiece and asks tmux for
// the same values again.
func (s Server) hierarchyFromPanes(
	ctx context.Context,
	extra []string,
	matches ...searchRowMatch,
) (Snapshot, error) {
	return s.searchSnapshotProjected(
		ctx, "list-panes", extra, nil, searchPanes, true, matches...,
	)
}

func searchSnapshotRecords(collection searchCollection, rows []formatValues) snapshotRecords {
	switch collection {
	case searchSessions:
		return snapshotRecords{sessions: rows}
	case searchWindows:
		return snapshotRecords{windows: rows}
	case searchPanes:
		return snapshotRecords{panes: rows}
	case searchClients:
		return snapshotRecords{clients: rows}
	default:
		panic("unknown search collection")
	}
}

tmux/server_attach.go.content:
package tmux

import (
	"context"
	"os"
	"slices"
	"strconv"
	"strings"

	"github.com/libtmux/libtmux-go/tmux/internal/tmuxcmd"
)

// AttachSessionOptions configures terminal ownership and attach behavior
// shared by server- and session-scoped attachment. Nil StartDirectory omits
// its flag and a nonnil empty string is explicit; ClientFlags is copied. The
// Stdin, Stdout, and Stderr pointers are retained for the attach call and are
// never owned or closed by this package.
type AttachSessionOptions struct {
	// DetachOthers disconnects other clients attached to the target session.
	DetachOthers bool
	// DetachParent detaches the invoking client from its parent session first.
	DetachParent bool
	// NoUpdateEnvironment preserves the invoking client's environment.
	NoUpdateEnvironment bool
	// ReadOnly attaches the client with read-only permissions.
	ReadOnly bool
	// StartDirectory selects the attached client's initial directory.
	StartDirectory *string
	// ClientFlags are comma-joined client flags copied before attachment starts.
	ClientFlags []string
	// Stdin is the attached tmux client's input stream; nil inherits process stdin.
	Stdin *os.File
	// Stdout is the attached tmux client's output stream; nil inherits process stdout.
	Stdout *os.File
	// Stderr is the attached tmux client's error stream; nil inherits process stderr.
	Stderr *os.File
}

// AttachSessionRequest selects a session name or tmux target pattern and
// configures a blocking terminal attachment. An empty Target lets tmux choose.
type AttachSessionRequest struct {
	// Target is a session name or tmux target pattern; empty leaves selection to tmux.
	Target string
	// AttachSessionOptions supplies terminal streams and attach flags.
	AttachSessionOptions
}

type attachSessionValues struct {
	target              string
	startDirectory      string
	clientFlags         []string
	stdin               *os.File
	stdout              *os.File
	stderr              *os.File
	detachOthers        bool
	detachParent        bool
	noUpdateEnvironment bool
	readOnly            bool
	hasStartDirectory   bool
}

// Start starts the configured tmux server. It is idempotent when that
// server is already running. Completed stderr is an error; cancellation does
// not prove that a daemon was not started.
//
// With tmux's exit-empty default, a server holding no sessions may exit before
// the next command even though Start succeeded. Create a session or disable
// exit-empty in [ServerOptions.ConfigFile] before startup. Use [Server.IsAlive]
// or [Server.CheckAlive] to check it.
func (s Server) Start(ctx context.Context) error {
	result, err := s.literalCmd(ctx, "start-server")
	return requireServerCommandNoStderr("start-server", result, err)
}

// AttachSession attaches the caller's terminal to a matching session and
// blocks until detach or context cancellation. Nil standard streams inherit
// the process streams; each stream must be a concrete terminal descriptor.
// The call retains caller-supplied files while attached and never owns or
// closes them. A completed nonzero exit returns [CommandError]; cancellation
// can end waiting but does not prove that attachment or detachment did not occur.
// On Unix, cancellation requests a tmux disconnect before bounded forced
// cleanup. If the daemon cannot respond, callers may need to restore their
// terminal state after the call returns.
//
// Alone among this package's operations, it leaves tmux's own locale detection
// alone, because what tmux writes here reaches the caller's terminal rather
// than this package. See [Session.Attach] for the session-scoped form.
func (s Server) AttachSession(ctx context.Context, request AttachSessionRequest) error {
	values, err := captureAttachSessionRequest(request.Target, request.AttachSessionOptions)
	if err != nil {
		return err
	}
	return s.attachSession(ctx, values)
}

// Attach attaches the caller's terminal to this session's stable identifier
// and blocks until detach or context cancellation. It validates the receiver's
// stable SessionID, retains but never closes caller-supplied streams, and
// returns [CommandError] for a completed nonzero exit. Cancellation does not
// prove attachment or detachment did not occur. See [Server.AttachSession]
// for locale handling and terminal recovery after forced cancellation.
func (s Session) Attach(ctx context.Context, options AttachSessionOptions) error {
	target := s.sessionID.String()
	if err := validateTypedTarget(
		"attach-session", "Target", "session", target,
	); err != nil {
		return err
	}
	values, err := captureAttachSessionRequest(target, options)
	if err != nil {
		return err
	}
	return s.server.attachSession(ctx, values)
}

func (s Server) attachSession(ctx context.Context, values attachSessionValues) error {
	arguments := []string{"attach-session"}
	if values.detachOthers {
		arguments = append(arguments, "-d")
	}
	if values.detachParent {
		arguments = append(arguments, "-x")
	}
	if values.noUpdateEnvironment {
		arguments = append(arguments, "-E")
	}
	if values.readOnly {
		arguments = append(arguments, "-r")
	}
	if values.hasStartDirectory {
		arguments = append(arguments, "-c", values.startDirectory)
	}
	if len(values.clientFlags) != 0 {
		arguments = append(arguments, "-f", strings.Join(values.clientFlags, ","))
	}
	if values.target != "" {
		arguments = append(arguments, "-t", values.target)
	}
	result, err := s.inheritLocale().streamingLiteralCmd(
		ctx,
		tmuxcmd.Stdio{Stdin: values.stdin, Stdout: values.stdout, Stderr: values.stderr, AttachSession: true},
		arguments...,
	)
	if err != nil {
		return err
	}
	if result.ExitCode != 0 {
		return newRedactedCommandError("attach-session", result)
	}
	return nil
}

func (s Server) streamingLiteralCmd(
	ctx context.Context,
	stdio tmuxcmd.Stdio,
	args ...string,
) (CommandResult, error) {
	if err := validateLiteralCommandArguments(args); err != nil {
		return CommandResult{ExitCode: -1}, err
	}
	result, err := s.runCommand(ctx, commandProcess, args, &stdio, false)
	commandResult := CommandResult{
		Command:  slices.Clone(result.Command),
		ExitCode: result.ExitCode,
	}
	if err != nil {
		return commandResult, commandTransportFailure(err)
	}
	return commandResult, nil
}

func captureAttachSessionRequest(
	target string,
	options AttachSessionOptions,
) (attachSessionValues, error) {
	values := attachSessionValues{
		target:              target,
		clientFlags:         slices.Clone(options.ClientFlags),
		stdin:               options.Stdin,
		stdout:              options.Stdout,
		stderr:              options.Stderr,
		detachOthers:        options.DetachOthers,
		detachParent:        options.DetachParent,
		noUpdateEnvironment: options.NoUpdateEnvironment,
		readOnly:            options.ReadOnly,
	}
	if err := validateServerCommandArgument(
		"attach-session", "Target", values.target, true,
	); err != nil {
		return attachSessionValues{}, err
	}
	if options.StartDirectory != nil {
		values.startDirectory = *options.StartDirectory
		values.hasStartDirectory = true
		if err := validateServerCommandArgument(
			"attach-session", "StartDirectory", values.startDirectory, true,
		); err != nil {
			return attachSessionValues{}, err
		}
	}
	for index, flag := range values.clientFlags {
		if err := validateServerCommandArgument(
			"attach-session",
			"ClientFlags["+strconv.Itoa(index)+"]",
			flag,
			true,
		); err != nil {
			return attachSessionValues{}, err
		}
	}
	return values, nil
}

tmux/server_buffers.go.content:
package tmux

import (
	"context"
	"io"
	"slices"
	"strings"
)

// TmuxFilter is a raw tmux -f format expression. It is distinct from the
// generated local filter structs and is evaluated only by tmux. A nil filter
// omits -f; a nonnil empty filter sends an explicit empty expression.
//
// The expression is tmux's own, so it is written the way tmux's FORMATS
// section describes rather than built from Go values:
//
//	active := tmux.TmuxFilter("#{==:#{window_active},1}")
//	windows, err := session.SearchWindows(ctx, &active)
//
// tmux evaluates this while listing. Generated model filters run in Go after
// materialization.
//
//revive:disable-next-line:exported TmuxFilter preserves tmux vocabulary beside local model filters.
type TmuxFilter string

// SetBufferRequest configures storing data in a tmux paste buffer. Its zero
// value writes an empty most-recent buffer; nil Name selects that buffer while
// a pointer to an empty name is explicit.
type SetBufferRequest struct {
	// Data is the exact buffer data to store or append.
	Data string
	// Name selects a named buffer, or nil for tmux's most-recent buffer.
	Name *string
	// Append appends Data instead of replacing the selected buffer.
	Append bool
}

// SaveBufferRequest configures writing a tmux paste buffer to a file. Its zero
// value is invalid because Path is required; nil Name selects the most-recent
// buffer and a pointer to an empty name is explicit.
type SaveBufferRequest struct {
	// Path is the required output file path.
	Path string
	// Name selects a named buffer, or nil for tmux's most-recent buffer.
	Name *string
	// Append appends buffer data to Path instead of replacing its contents.
	Append bool
}

// LoadBufferRequest configures loading a file into a tmux paste buffer. Its
// zero value is invalid because Path is required; nil Name lets tmux allocate
// a buffer and a pointer to an empty name is explicit.
type LoadBufferRequest struct {
	// Path is the required input file path.
	Path string
	// Name selects the destination buffer, or nil for tmux's allocation behavior.
	Name *string
}

// LoadBufferFromOptions configures streaming data into a tmux paste buffer.
// Its zero value lets tmux allocate a buffer; nil Name selects that
// allocation and a pointer to an empty name is explicit.
type LoadBufferFromOptions struct {
	// Name selects the destination buffer, or nil for tmux's allocation behavior.
	Name *string
}

// SaveBufferToOptions configures streaming a tmux paste buffer's contents
// out. Its zero value selects tmux's most-recent buffer; a pointer to an
// empty name is explicit.
type SaveBufferToOptions struct {
	// Name selects a named buffer, or nil for tmux's most-recent buffer.
	Name *string
}

// ListBuffersRequest configures tmux's live paste-buffer listing. Its zero
// value requests tmux's default output; nil Format and Filter omit their flags,
// whereas pointers to empty strings are explicit expressions.
type ListBuffersRequest struct {
	// Format selects tmux's output format.
	Format *string
	// Filter is a raw tmux filter expression evaluated by tmux.
	Filter *TmuxFilter
}

// SetBuffer stores or appends exact string data without refreshing models. It
// mutates the selected paste buffer; completed stderr is reported as a
// redacted command error because Data may be secret. Cancellation does not
// prove that tmux did not store data.
func (s Server) SetBuffer(ctx context.Context, request SetBufferRequest) error {
	if err := validateBufferName("set-buffer", request.Name); err != nil {
		return err
	}
	if err := validateServerCommandArgument("set-buffer", "Data", request.Data, true); err != nil {
		return err
	}
	arguments := []string{"set-buffer"}
	if request.Append {
		arguments = append(arguments, "-a")
	}
	if request.Name != nil {
		arguments = append(arguments, "-b", *request.Name)
	}
	arguments = append(arguments, "--", request.Data)
	result, err := s.literalCmd(ctx, arguments...)
	if err != nil {
		return err
	}
	if len(result.Stderr) != 0 {
		return newRedactedCommandError("set-buffer", result)
	}
	return nil
}

// ShowBuffer returns one buffer using Python-compatible line reconstruction.
// The returned string is owned by the caller; nil Name selects tmux's most
// recent buffer. Completed stderr is an error.
func (s Server) ShowBuffer(ctx context.Context, name *string) (string, error) {
	result, err := s.showBuffer(ctx, name)
	if err != nil {
		return "", err
	}
	return strings.Join(result.Stdout, "\n"), nil
}

// ShowBufferBytes returns one buffer as exact caller-owned tmux stdout bytes.
// Unlike [Server.ShowBuffer], it preserves invalid UTF-8, delimiters, and
// trailing newlines. Nil Name selects tmux's most recent buffer. Completed
// stderr returns a redacted command error and a nil byte slice.
func (s Server) ShowBufferBytes(ctx context.Context, name *string) ([]byte, error) {
	result, err := s.showBuffer(ctx, name)
	if err != nil {
		return nil, err
	}
	return result.RawStdout, nil
}

func (s Server) showBuffer(ctx context.Context, name *string) (CommandResult, error) {
	if err := validateBufferName("show-buffer", name); err != nil {
		return CommandResult{ExitCode: -1}, err
	}
	arguments := []string{"show-buffer"}
	if name != nil {
		arguments = append(arguments, "-b", *name)
	}
	// show-buffer's result is tmux's own stdout, which [Server.ShowBufferBytes]
	// returns byte for byte, so this read requires a tmux process.
	result, err := s.requireProcess().literalCmd(ctx, arguments...)
	if err := requireRedactedServerCommandNoStderr("show-buffer", result, err); err != nil {
		return result, err
	}
	return result, nil
}

// DeleteBuffer deletes a named buffer, or the most recent buffer when name is nil.
// Cancellation does not prove that tmux did not delete the buffer.
func (s Server) DeleteBuffer(ctx context.Context, name *string) error {
	if err := validateBufferName("delete-buffer", name); err != nil {
		return err
	}
	arguments := []string{"delete-buffer"}
	if name != nil {
		arguments = append(arguments, "-b", *name)
	}
	result, err := s.literalCmd(ctx, arguments...)
	return requireServerCommandNoStderr("delete-buffer", result, err)
}

// SaveBuffer writes a named or most-recent buffer to a file. Path follows
// [Server.SourceFile]'s current-user expansion and lexical normalization. It
// changes that file. Exact "-" is rejected because it names tmux's stdout
// rather than a path; [Server.SaveBufferTo] streams to an [io.Writer], and
// this method is the one that runs over a [Connection].
func (s Server) SaveBuffer(ctx context.Context, request SaveBufferRequest) error {
	if err := validateBufferName("save-buffer", request.Name); err != nil {
		return err
	}
	path, err := expandBufferPath("save-buffer", "Server.SaveBufferTo", request.Path)
	if err != nil {
		return err
	}
	arguments := []string{"save-buffer"}
	if request.Append {
		arguments = append(arguments, "-a")
	}
	if request.Name != nil {
		arguments = append(arguments, "-b", *request.Name)
	}
	arguments = append(arguments, "--", path)
	result, err := s.literalCmd(ctx, arguments...)
	return requireServerCommandNoStderr("save-buffer", result, err)
}

// LoadBuffer reads a file into a named or newly allocated buffer. Path follows
// [Server.SourceFile]'s current-user expansion and lexical normalization. It
// mutates tmux's destination buffer. Exact "-" is rejected because it names
// tmux's stdin rather than a path; [Server.LoadBufferFrom] streams from an
// [io.Reader], and this method is the one that runs over a [Connection].
func (s Server) LoadBuffer(ctx context.Context, request LoadBufferRequest) error {
	if err := validateBufferName("load-buffer", request.Name); err != nil {
		return err
	}
	path, err := expandBufferPath("load-buffer", "Server.LoadBufferFrom", request.Path)
	if err != nil {
		return err
	}
	arguments := []string{"load-buffer"}
	if request.Name != nil {
		arguments = append(arguments, "-b", *request.Name)
	}
	arguments = append(arguments, "--", path)
	result, err := s.literalCmd(ctx, arguments...)
	return requireServerCommandNoStderr("load-buffer", result, err)
}

// LoadBufferFrom streams source into a named or newly allocated tmux paste
// buffer, reading it to completion without holding its contents in memory. It
// carries any bytes, including NUL, and is bounded by neither argv nor tmux's
// command-message limit, which is what [Server.SetBuffer] is bounded by.
//
// A copy failure after tmux exits zero means the buffer holds only the prefix
// that reached tmux, and cancellation does not prove tmux stored nothing. A
// source that blocks regardless of cancellation does not hold the call, and is
// still being read when it returns. A [Connection]-bound Server returns
// [ErrConnectionRequiresProcess]: tmux offers no stdin to a control client, so
// use [Server.LoadBuffer] and a path over a connection.
func (s Server) LoadBufferFrom(
	ctx context.Context,
	source io.Reader,
	options LoadBufferFromOptions,
) error {
	if source == nil {
		return invalidServerCommandRequest("load-buffer", "source", "", "must not be nil")
	}
	if err := validateBufferName("load-buffer", options.Name); err != nil {
		return err
	}
	arguments := []string{"load-buffer"}
	if options.Name != nil {
		arguments = append(arguments, "-b", *options.Name)
	}
	arguments = append(arguments, "--", "-")
	result, err := s.streamIn(ctx, source, arguments)
	return requireRedactedServerCommandNoStderr("load-buffer", result, err)
}

// SaveBufferTo streams a named or most-recent tmux paste buffer into
// destination without holding its contents in memory. It writes any bytes,
// including NUL, and preserves them exactly where [Server.ShowBuffer]
// reconstructs lines.
//
// Cancellation does not prove destination received a complete buffer, and a
// copy failure takes precedence over a completed command's exit status because
// it means destination never saw everything tmux sent. A destination that
// blocks regardless of cancellation does not hold the call. A
// [Connection]-bound Server returns [ErrConnectionRequiresProcess]: tmux
// offers no stdout to a control client, so use [Server.SaveBuffer] and a path
// over a connection.
func (s Server) SaveBufferTo(
	ctx context.Context,
	destination io.Writer,
	options SaveBufferToOptions,
) error {
	if destination == nil {
		return invalidServerCommandRequest("save-buffer", "destination", "", "must not be nil")
	}
	if err := validateBufferName("save-buffer", options.Name); err != nil {
		return err
	}
	arguments := []string{"save-buffer"}
	if options.Name != nil {
		arguments = append(arguments, "-b", *options.Name)
	}
	arguments = append(arguments, "--", "-")
	result, err := s.streamOut(ctx, destination, arguments)
	return requireRedactedServerCommandNoStderr("save-buffer", result, err)
}

// ListBuffers returns an owned snapshot of live tmux buffer rows. A command or
// transport failure is returned rather than answered with no rows; context
// cancellation still returns its context error. The result is not a live
// collection.
func (s Server) ListBuffers(
	ctx context.Context,
	request ListBuffersRequest,
) ([]string, error) {
	if request.Format != nil {
		if err := validateServerCommandArgument(
			"list-buffers", "Format", *request.Format, true,
		); err != nil {
			return nil, err
		}
	}
	if request.Filter != nil {
		if err := validateServerCommandArgument(
			"list-buffers", "Filter", string(*request.Filter), true,
		); err != nil {
			return nil, err
		}
	}
	arguments := []string{"list-buffers"}
	if request.Format != nil {
		arguments = append(arguments, "-F", *request.Format)
	}
	if request.Filter != nil {
		arguments = append(arguments, "-f", string(*request.Filter))
	}
	return runRedactedServerListCommand(ctx, s, arguments)
}

func validateBufferName(subcommand string, name *string) error {
	if name == nil {
		return nil
	}
	return validateServerCommandArgument(subcommand, "Name", *name, true)
}

func expandBufferPath(subcommand string, streaming string, path string) (string, error) {
	if path == "" {
		return "", invalidServerCommandRequest(
			subcommand,
			"Path",
			path,
			"must not be empty",
		)
	}
	if path == "-" {
		return "", invalidServerCommandRequest(
			subcommand,
			"Path",
			path,
			"is tmux's stdio operand rather than a path; use "+streaming,
		)
	}
	expanded, err := expandCommandPath(subcommand, path)
	if err != nil {
		return "", err
	}
	return expanded, nil
}

func runServerListCommand(
	ctx context.Context,
	server Server,
	arguments []string,
) ([]string, error) {
	return runServerListCommandWithError(ctx, server, arguments, newCommandError)
}

func runRedactedServerListCommand(
	ctx context.Context,
	server Server,
	arguments []string,
) ([]string, error) {
	return runServerListCommandWithError(ctx, server, arguments, newRedactedCommandError)
}

func runServerListCommandWithError(
	ctx context.Context,
	server Server,
	arguments []string,
	newError func(string, CommandResult) *CommandError,
) ([]string, error) {
	result, err := server.literalCmd(ctx, arguments...)
	if err != nil {
		return nil, err
	}
	if result.ExitCode != 0 || len(result.Stderr) != 0 {
		return nil, newError(arguments[0], result)
	}
	return slices.Clone(result.Stdout), nil
}

tmux/server_clients.go.content:
package tmux

import "context"

// serverClientsClipboardVersion is where refresh-client -l becomes safe to
// send. tmux has accepted the flag since before the supported range, but 3.3a
// ends the server on it for a client with a terminal, so the flag is withheld
// below this rather than gated on the kind of client a caller happens to
// target.
var serverClientsClipboardVersion = Version{raw: "3.4", major: 3, minor: 4}

// ServerAccessRequest configures tmux server access control. Its zero value is
// invalid: List or exactly one nonempty Allow or Deny is required. Allow and
// Deny, and ReadOnly and Write, are mutually exclusive; nil pointers omit
// their selectors while explicit empty users are rejected. List selects the
// returned-list path, but compatible selector and mode flags are still sent to
// tmux rather than ignored.
type ServerAccessRequest struct {
	// Allow grants the named user access.
	Allow *string
	// Deny revokes the named user's access.
	Deny *string
	// List returns the configured access entries instead of mutating them.
	List bool
	// ReadOnly grants read-only access to the selected user.
	ReadOnly bool
	// Write grants write access to the selected user.
	Write bool
}

// RefreshClientRequest configures refreshing one tmux client. Its zero value
// refreshes tmux's current client; a zero TargetClient omits -t.
type RefreshClientRequest struct {
	// TargetClient selects a stable client; zero selects tmux's current client.
	TargetClient ClientName
	// RequestClipboard requests clipboard data and requires tmux 3.4; older tmux
	// versions may exit when given the flag, so it follows UnsupportedPolicy.
	RequestClipboard bool
}

// DetachClientRequest configures detaching one tmux client. Its zero value
// detaches tmux's current client; nil fields omit their flags while an empty
// ShellCommand pointer is explicit.
type DetachClientRequest struct {
	// TargetClient selects a stable client; zero selects tmux's current client.
	TargetClient ClientName
	// ShellCommand is run after detaching when nonnil.
	ShellCommand *string
}

// DetachAllClientsRequest configures detaching every client except one. Its
// zero value keeps tmux's current client; nil fields omit their flags.
type DetachAllClientsRequest struct {
	// KeepClient selects the stable client to retain; zero keeps tmux's current client.
	KeepClient ClientName
	// ShellCommand is run after detaching when nonnil.
	ShellCommand *string
}

// ServerAccess changes or lists the server access-control entries. It is available
// on every supported tmux. List returns an
// owned snapshot, and reports a completed or transport failure rather than
// answering with no entries; mutation completed stderr is an error.
func (s Server) ServerAccess(
	ctx context.Context,
	request ServerAccessRequest,
) ([]string, error) {
	allow, hasAllow := optionalClientString(request.Allow)
	deny, hasDeny := optionalClientString(request.Deny)
	if hasAllow && allow == "" {
		return nil, invalidServerCommandRequest(
			"server-access", "Allow", allow, "must not be empty",
		)
	}
	if hasDeny && deny == "" {
		return nil, invalidServerCommandRequest(
			"server-access", "Deny", deny, "must not be empty",
		)
	}
	if hasAllow {
		if err := validateServerCommandArgument(
			"server-access", "Allow", allow, true,
		); err != nil {
			return nil, err
		}
	}
	if hasDeny {
		if err := validateServerCommandArgument(
			"server-access", "Deny", deny, true,
		); err != nil {
			return nil, err
		}
	}
	if hasAllow && hasDeny {
		return nil, invalidServerCommandRequest(
			"server-access", "Allow", allow, "is mutually exclusive with Deny",
		)
	}
	if request.ReadOnly && request.Write {
		return nil, invalidServerCommandRequest(
			"server-access", "ReadOnly", "true", "is mutually exclusive with Write",
		)
	}
	if !request.List && !hasAllow && !hasDeny {
		return nil, invalidServerCommandRequest(
			"server-access", "User", "", "is required unless List is set",
		)
	}

	arguments := []string{"server-access"}
	user := ""
	if hasAllow {
		arguments = append(arguments, "-a")
		user = allow
	}
	if hasDeny {
		arguments = append(arguments, "-d")
		user = deny
	}
	if request.List {
		arguments = append(arguments, "-l")
	}
	if request.ReadOnly {
		arguments = append(arguments, "-r")
	}
	if request.Write {
		arguments = append(arguments, "-w")
	}
	if user != "" {
		arguments = append(arguments, "--", user)
	}
	if request.List {
		return runServerListCommand(ctx, s, arguments)
	}
	return nil, runClientCommand(ctx, s, "server-access", arguments)
}

// LockServer locks every attached client on the tmux server. Cancellation does
// not prove the server did not lock a client.
func (s Server) LockServer(ctx context.Context) error {
	return runClientCommand(ctx, s, "lock-server", []string{"lock-server"})
}

// RefreshClient redraws a client, or tmux's current client when no target is set.
// RequestClipboard requires tmux 3.4 and follows [UnsupportedPolicy].
func (s Server) RefreshClient(ctx context.Context, request RefreshClientRequest) error {
	targetClient, hasTargetClient, err := requestClientTarget(request.TargetClient)
	if err != nil {
		return err
	}
	requestClipboard := false
	if request.RequestClipboard {
		current, versionErr := s.Version(ctx)
		if versionErr != nil {
			return versionErr
		}
		if current.AtLeast(serverClientsClipboardVersion) {
			requestClipboard = true
		} else if err := s.unsupportedFeature(
			"refresh-client",
			"request_clipboard",
			current,
			serverClientsClipboardVersion,
		); err != nil {
			return err
		}
	}
	arguments := []string{"refresh-client"}
	if hasTargetClient {
		arguments = append(arguments, "-t", targetClient)
	}
	if requestClipboard {
		arguments = append(arguments, "-l")
	}
	return runClientCommand(ctx, s, "refresh-client", arguments)
}

// LockClient locks a client, or tmux's current client when targetClient is nil.
// Cancellation does not prove the target client was not locked.
func (s Server) LockClient(ctx context.Context, targetClient *ClientName) error {
	target, hasTarget, err := clientTarget(targetClient)
	if err != nil {
		return err
	}
	arguments := []string{"lock-client"}
	if hasTarget {
		arguments = append(arguments, "-t", target)
	}
	return runClientCommand(ctx, s, "lock-client", arguments)
}

// SuspendClient suspends a client, or tmux's current client when targetClient is nil.
// Cancellation does not prove suspension did not occur.
func (s Server) SuspendClient(ctx context.Context, targetClient *ClientName) error {
	target, hasTarget, err := clientTarget(targetClient)
	if err != nil {
		return err
	}
	arguments := []string{"suspend-client"}
	if hasTarget {
		arguments = append(arguments, "-t", target)
	}
	return runClientCommand(ctx, s, "suspend-client", arguments)
}

// DetachClient detaches one client, or tmux's current client when no target is set.
// A completed stderr result is an error; cancellation does not prove delivery
// or detachment did not occur.
func (s Server) DetachClient(ctx context.Context, request DetachClientRequest) error {
	targetClient, hasTargetClient, err := requestClientTarget(request.TargetClient)
	if err != nil {
		return err
	}
	shellCommand, hasShellCommand := optionalClientString(request.ShellCommand)
	if hasShellCommand {
		if err := validateServerCommandArgument(
			"detach-client", "ShellCommand", shellCommand, true,
		); err != nil {
			return err
		}
	}
	arguments := []string{"detach-client"}
	if hasShellCommand {
		arguments = append(arguments, "-E", shellCommand)
	}
	if hasTargetClient {
		arguments = append(arguments, "-t", targetClient)
	}
	return runClientCommand(ctx, s, "detach-client", arguments)
}

// DetachAllClients detaches every client except KeepClient or tmux's current client.
// Cancellation does not prove every client was detached.
func (s Server) DetachAllClients(
	ctx context.Context,
	request DetachAllClientsRequest,
) error {
	keepClient, hasKeepClient, err := requestClientTarget(request.KeepClient)
	if err != nil {
		return err
	}
	shellCommand, hasShellCommand := optionalClientString(request.ShellCommand)
	if hasShellCommand {
		if err := validateServerCommandArgument(
			"detach-client", "ShellCommand", shellCommand, true,
		); err != nil {
			return err
		}
	}
	arguments := []string{"detach-client", "-a"}
	if hasShellCommand {
		arguments = append(arguments, "-E", shellCommand)
	}
	if hasKeepClient {
		arguments = append(arguments, "-t", keepClient)
	}
	return runClientCommand(ctx, s, "detach-client", arguments)
}

// SwitchClient switches tmux's current client to targetSession. TargetSession
// is a validated session name rather than a stable identity; cancellation does
// not prove the switch did not occur.
//
// The target is sent anchored with tmux's "=" exact-match prefix: an
// unanchored "-t name" resolves by prefix, so a name that matches no session
// exactly but starts a different one's name would otherwise switch there
// silently instead of failing. The anchor is safe here because
// validateLifecycleSessionName has already refused the period or colon that
// would make "=name" misread the target itself.
func (s Server) SwitchClient(ctx context.Context, targetSession string) error {
	if err := validateLifecycleSessionName("target session", targetSession); err != nil {
		return err
	}
	return runClientCommand(
		ctx,
		s,
		"switch-client",
		[]string{"switch-client", "-t", "=" + targetSession},
	)
}

// Lock locks every client attached to the session identified by this handle's
// stable ID. Cancellation does not prove that tmux did not lock a client.
func (s Session) Lock(ctx context.Context) error {
	if err := validateServerCommandArgument(
		"lock-session", "Target", s.sessionID.String(), true,
	); err != nil {
		return err
	}
	if err := validateTypedTarget(
		"lock-session", "Target", "session", s.sessionID.String(),
	); err != nil {
		return err
	}
	return runClientCommand(
		ctx,
		s.server,
		"lock-session",
		[]string{"lock-session", "-t", s.sessionID.String()},
	)
}

// DetachClients detaches every client attached to the session identified by
// this handle's stable ID. A nonnil ShellCommand is run after detaching.
func (s Session) DetachClients(ctx context.Context, shellCommand *string) error {
	if err := validateServerCommandArgument(
		"detach-client", "Target", s.sessionID.String(), true,
	); err != nil {
		return err
	}
	if err := validateTypedTarget(
		"detach-client", "Target", "session", s.sessionID.String(),
	); err != nil {
		return err
	}
	command, hasCommand := optionalClientString(shellCommand)
	if hasCommand {
		if err := validateServerCommandArgument(
			"detach-client", "ShellCommand", command, true,
		); err != nil {
			return err
		}
	}
	arguments := []string{"detach-client"}
	if hasCommand {
		arguments = append(arguments, "-E", command)
	}
	arguments = append(arguments, "-s", s.sessionID.String())
	return runClientCommand(ctx, s.server, "detach-client", arguments)
}

// SwitchClient switches tmux's current client to the session identified by
// this handle's stable ID.
func (s Session) SwitchClient(ctx context.Context) error {
	if err := validateServerCommandArgument(
		"switch-client", "Target", s.sessionID.String(), true,
	); err != nil {
		return err
	}
	if err := validateTypedTarget(
		"switch-client", "Target", "session", s.sessionID.String(),
	); err != nil {
		return err
	}
	return runClientCommand(
		ctx,
		s.server,
		"switch-client",
		[]string{"switch-client", "-t", s.sessionID.String()},
	)
}

func runClientCommand(
	ctx context.Context,
	server Server,
	subcommand string,
	arguments []string,
) error {
	result, err := server.literalCmd(ctx, arguments...)
	return requireServerCommandNoStderr(subcommand, result, err)
}

func clientTarget(target *ClientName) (string, bool, error) {
	if target == nil {
		return "", false, nil
	}
	value := target.String()
	if err := validateServerCommandArgument(
		"client", "TargetClient", value, true,
	); err != nil {
		return "", false, err
	}
	if err := validateTypedTarget("client", "TargetClient", "client", value); err != nil {
		return "", false, err
	}
	return value, true, nil
}

func requestClientTarget(target ClientName) (string, bool, error) {
	if target == "" {
		return "", false, nil
	}
	value := target.String()
	if err := validateServerCommandArgument(
		"client", "TargetClient", value, true,
	); err != nil {
		return "", false, err
	}
	if err := validateTypedTarget("client", "TargetClient", "client", value); err != nil {
		return "", false, err
	}
	return value, true, nil
}

func optionalClientString(value *string) (string, bool) {
	if value == nil {
		return "", false
	}
	return *value, true
}

