package tmux

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"slices"
	"strconv"
	"strings"
)

var (
	// ErrInvalidServerCommandRequest identifies a server command request that
	// cannot be represented safely as tmux arguments.
	ErrInvalidServerCommandRequest = errors.New("tmux: invalid server command request")

	serverExecVersion34 = Version{raw: "3.4", major: 3, minor: 4}
	serverExecVersion36 = Version{raw: "3.6", major: 3, minor: 6}
	serverExecVersion37 = Version{raw: "3.7", major: 3, minor: 7}
)

// ServerCommandRequestError reports a locally rejected server command request
// field. Callers can use [errors.Is] with [ErrInvalidServerCommandRequest] or
// [errors.As] to inspect it. Value is redacted only when that field's
// validator requests redaction.
type ServerCommandRequestError struct {
	// Subcommand is the tmux command whose request was rejected.
	Subcommand string
	// Field is the request field that was rejected.
	Field string
	// Value is the rejected value, or "[redacted]" for a secret-sensitive field.
	Value string
	// Reason describes the validation failure without changing the sentinel error.
	Reason string
}

// Error implements error.
func (e *ServerCommandRequestError) Error() string {
	return fmt.Sprintf(
		"%v: %s %s %q %s",
		ErrInvalidServerCommandRequest,
		e.Subcommand,
		e.Field,
		e.Value,
		e.Reason,
	)
}

// Unwrap makes ServerCommandRequestError compatible with
// ErrInvalidServerCommandRequest.
func (e *ServerCommandRequestError) Unwrap() error {
	return ErrInvalidServerCommandRequest
}

// RunShellRequest configures a command executed by tmux's run-shell command.
// Its zero value is invalid because Command is required. Pointer fields
// distinguish omitted flags from explicit empty arguments; RunShell copies
// Delay, StartDirectory, and Args before invoking tmux.
type RunShellRequest struct {
	// Command is the required shell or tmux command to run.
	Command string
	// Background returns after tmux accepts the job instead of waiting for stdout.
	Background bool
	// Delay supplies run-shell's optional delay; nil omits it and an empty value is explicit.
	Delay *string
	// AsTmuxCommand asks tmux to interpret Command as tmux command syntax.
	AsTmuxCommand bool
	// TargetPane selects a stable pane target; its zero value leaves target selection to tmux.
	TargetPane PaneID
	// StartDirectory selects the job directory; nil omits it. It requires tmux
	// 3.4; see UnsupportedPolicy.
	// A directory that does not exist is not an error: tmux starts the
	// process in the home directory instead, or in / without one.
	StartDirectory *string
	// ShowStderr requests job stderr and requires tmux 3.6; see
	// UnsupportedPolicy.
	ShowStderr bool
	// Args are extra job arguments copied before tmux runs. They require tmux
	// 3.7; see UnsupportedPolicy.
	Args []string
}

// WaitForMode selects one wait-for operation. The zero value waits until the
// channel is signaled.
type WaitForMode uint8

// Supported wait-for operations.
const (
	// WaitForModeWait waits until another client signals Channel.
	WaitForModeWait WaitForMode = iota
	// WaitForModeSignal signals Channel and wakes waiters.
	WaitForModeSignal
	// WaitForModeLock acquires Channel's tmux mutex, queuing behind another
	// locker if it is already held.
	//
	// Before tmux 3.8, a cancelled or timed-out ctx while queued costs Channel
	// one unlock: tmux hands the mutex to the next queued client whether or
	// not it is still there, and the one that has gone cannot pass it on
	// (cmd-wait-for.c cmd_wait_for_unlock). Unlocking again hands it to the
	// next real locker, so a channel is not lost, but a program that abandons
	// lock waits and counts its unlocks will deadlock on its own arithmetic.
	// tmux 3.8 drops the wait of a client that has gone (tmux issue 5614), so
	// there an abandoned wait costs nothing and an extra unlock fails.
	WaitForModeLock
	// WaitForModeUnlock releases Channel's tmux mutex.
	WaitForModeUnlock
)

// WaitForRequest configures a wait, signal, lock, or unlock operation. Its
// zero value waits on the required nonempty Channel.
type WaitForRequest struct {
	// Channel names the tmux wait-for channel or mutex.
	Channel string
	// Mode selects the channel action; zero waits.
	Mode WaitForMode
}

// IfShellRequest configures conditional execution of a tmux command. Its zero
// value is invalid because ShellCommand and ThenCommand are required; nil
// ElseCommand omits the failure branch while a pointer to an empty string is
// explicit.
type IfShellRequest struct {
	// ShellCommand is the required shell condition executed by tmux.
	ShellCommand string
	// ThenCommand is the required tmux command executed when ShellCommand succeeds.
	ThenCommand string
	// ElseCommand is the optional tmux command executed when ShellCommand fails.
	ElseCommand *string
	// Background makes tmux schedule the conditional command without waiting.
	Background bool
	// TargetPane selects a stable pane target; its zero value omits -t.
	TargetPane PaneID
}

// SourceFileRequest configures loading or parsing a tmux configuration file.
// Its zero value is invalid because Path is required; SourceFile expands only
// the current user's ~ forms and copies no caller-owned mutable input.
type SourceFileRequest struct {
	// Path is the required configuration path; exact "-" is rejected because no stdin is provided.
	Path string
	// Quiet suppresses tmux diagnostics for missing source files.
	Quiet bool
	// ParseOnly validates the file without applying its commands.
	ParseOnly bool
	// Verbose requests tmux parsing diagnostics.
	Verbose bool
}

// RunShell executes a shell command through tmux and returns an owned stdout
// slice. A background request returns nil after tmux accepts the job. tmux 3.3
// and 3.4 hand a foreground command's output to no client, so the slice is
// empty there whatever the command printed.
// Unsupported optional flags follow [UnsupportedPolicy]. A completed stderr
// result is an error; context cancellation can be observed with [errors.Is] but
// does not establish that tmux did not start the job.
//
// On a [Connection]-bound server a foreground request runs on a control client
// opened for that call and closed when it ends, as [Server.WaitFor] does, so a
// slow or canceled command leaves every lane free. tmux sends that client the
// command's output as lines outside any reply frame, so the client takes every
// line before its own fence as output, whatever the line looks like. The one
// exception is a line that is a well-formed control notification, such as
// "%window-add @1", which a connection cannot tell from tmux's own and drops.
//
// A foreground command that tmux ends with success is checked against the
// server, as in [Server.WaitFor], and returns an error matching [ErrNoServer]
// when the server exited under it.
func (s Server) RunShell(ctx context.Context, request RunShellRequest) ([]string, error) {
	request.Delay = copyOptionalString(request.Delay)
	request.StartDirectory = copyOptionalString(request.StartDirectory)
	request.Args = slices.Clone(request.Args)
	if err := validateRunShellArguments(request); err != nil {
		return nil, err
	}
	if request.Command == "" {
		return nil, invalidServerCommandRequest("run-shell", "Command", "", "must not be empty")
	}
	targetPane := request.TargetPane.String()
	if targetPane != "" {
		if err := validateTypedTarget(
			"run-shell", "TargetPane", "pane", targetPane,
		); err != nil {
			return nil, err
		}
	}

	extraArguments := request.Args
	var current Version
	if request.StartDirectory != nil || request.ShowStderr || len(extraArguments) != 0 {
		var err error
		current, err = s.Version(ctx)
		if err != nil {
			return nil, err
		}
	}

	arguments := make([]string, 0, 13+len(extraArguments))
	arguments = append(arguments, "run-shell")
	if request.Background {
		arguments = append(arguments, "-b")
	}
	if request.Delay != nil {
		arguments = append(arguments, "-d", *request.Delay)
	}
	if request.AsTmuxCommand {
		arguments = append(arguments, "-C")
	}
	if targetPane != "" {
		arguments = append(arguments, "-t", targetPane)
	}
	if request.StartDirectory != nil {
		if current.AtLeast(serverExecVersion34) {
			arguments = append(arguments, "-c", *request.StartDirectory)
		} else if err := s.unsupportedFeature(
			"run-shell",
			"start_directory",
			current,
			serverExecVersion34,
		); err != nil {
			return nil, err
		}
	}
	if request.ShowStderr {
		if current.AtLeast(serverExecVersion36) {
			arguments = append(arguments, "-E")
		} else if err := s.unsupportedFeature(
			"run-shell",
			"show_stderr",
			current,
			serverExecVersion36,
		); err != nil {
			return nil, err
		}
	}
	arguments = append(arguments, "--", request.Command)
	if len(extraArguments) != 0 {
		if current.AtLeast(serverExecVersion37) {
			arguments = append(arguments, extraArguments...)
		} else if err := s.unsupportedFeature(
			"run-shell",
			"args",
			current,
			serverExecVersion37,
		); err != nil {
			return nil, err
		}
	}

	// Without -C, tmux prints the shell command's stdout; with it, tmux runs
	// that output as commands, which answer in frames of their own.
	result, err := s.literalCmdAs(
		ctx, shellCommandKind(request.Background, !request.AsTmuxCommand), arguments...,
	)
	err = s.blockingFailure(ctx, "run-shell", err)
	if err := requireRedactedServerCommandNoStderr("run-shell", result, err); err != nil {
		return nil, err
	}
	if request.Background {
		return nil, nil
	}
	if err := s.requireServerSurvived(ctx, "run-shell"); err != nil {
		return nil, err
	}
	return result.Stdout, nil
}

// WaitFor waits for, signals, locks, or unlocks a named tmux channel. It
// changes only that server-side channel state; cancellation can interrupt the
// client wait but cannot prove a preceding signal or lock did not take
// effect. See [WaitForModeLock]: before tmux 3.8, abandoning a lock wait costs
// that channel one unlock.
//
// On a [Connection]-bound server a wait or lock runs on a control client opened
// for that call and closed when it ends, so canceling it, or a peer never
// signaling, leaves every lane free. Closing the connection ends a parked call
// with [ErrControlClosed].
//
// tmux ends a waiting client with success when the server exits, which reads
// as a signal. A wait or lock that tmux ends that way is checked against the
// server and returns an error matching [ErrNoServer] when the server is gone.
// A signal followed at once by the server exiting reads the same way.
func (s Server) WaitFor(ctx context.Context, request WaitForRequest) error {
	if err := validateServerCommandArgument(
		"wait-for", "Channel", request.Channel, true,
	); err != nil {
		return err
	}
	if request.Channel == "" {
		return invalidServerCommandRequest("wait-for", "Channel", "", "must not be empty")
	}
	arguments := []string{"wait-for"}
	switch request.Mode {
	case WaitForModeWait:
	case WaitForModeSignal:
		arguments = append(arguments, "-S")
	case WaitForModeLock:
		arguments = append(arguments, "-L")
	case WaitForModeUnlock:
		arguments = append(arguments, "-U")
	default:
		return invalidServerCommandRequest(
			"wait-for",
			"Mode",
			strconv.FormatUint(uint64(request.Mode), 10),
			"is unsupported",
		)
	}
	arguments = append(arguments, "--", request.Channel)
	// A wait or lock can hold its client until another client acts, and tmux
	// cannot cancel a command already sent, so a connection runs it on a
	// client of its own rather than on a shared lane.
	kind := commandServer
	if request.Mode == WaitForModeWait || request.Mode == WaitForModeLock {
		kind = commandBlocking
	}
	result, err := s.literalCmdAs(ctx, kind, arguments...)
	err = s.blockingFailure(ctx, "wait-for", err)
	if err := requireRedactedServerCommandNoStderr("wait-for", result, err); err != nil {
		return err
	}
	if kind == commandBlocking {
		return s.requireServerSurvived(ctx, "wait-for")
	}
	return nil
}

// requireServerSurvived follows a blocking command tmux ended with success.
// tmux's client exits 0 when the server exits under it, with no output that
// tells that from a real completion, so only the server can say. It returns an
// error matching [ErrNoServer] when the server is gone; a failed look is no
// evidence either way, and the command itself did complete.
func (s Server) requireServerSurvived(ctx context.Context, subcommand string) error {
	if s.serverGone(ctx) {
		return fmt.Errorf("%s: the tmux server exited during the command: %w", subcommand, ErrNoServer)
	}
	return nil
}

// blockingFailure follows a blocking command that failed on a connection's
// client. The server exiting ends that client's stream, which reads as a lost
// client rather than a gone server, so a lost client is checked against the
// server and reports [ErrNoServer] when it is gone. Any other failure,
// including the caller's own cancellation, passes through.
func (s Server) blockingFailure(ctx context.Context, subcommand string, err error) error {
	if err == nil || s.connection == nil || ctx.Err() != nil ||
		(!errors.Is(err, ErrControlClosed) && !errors.Is(err, ErrOutcomeUnknown)) {
		return err
	}
	if !s.serverGone(ctx) {
		return err
	}
	return fmt.Errorf("%s: the tmux server exited during the command: %w (%w)", subcommand, ErrNoServer, err)
}

// serverGone reports whether the server answers that it is gone. A bound
// server asks through its connection first; once the server has exited that
// connection fails with something other than [ErrNoServer], so a failed look
// asks again through a process of its own. A look that fails both ways is no
// evidence, which keeps a Connection closed while the server is healthy from
// reading as a gone server.
func (s Server) serverGone(ctx context.Context) bool {
	alive, err := s.IsAlive(ctx)
	if (err == nil && !alive) || errors.Is(err, ErrNoServer) {
		return true
	}
	if err == nil || s.connection == nil || ctx.Err() != nil {
		return false
	}
	process := s
	process.connection = nil
	alive, err = process.IsAlive(ctx)
	return (err == nil && !alive) || errors.Is(err, ErrNoServer) || errors.Is(err, ErrDaemonReplaced)
}

// IfShell executes ThenCommand when ShellCommand succeeds and ElseCommand, if
// present, when it fails. A completed stderr result is an error; cancellation
// can interrupt delivery without proving that tmux did not execute a branch.
//
// On a [Connection]-bound server a foreground request runs on a control client
// of its own, as [Server.RunShell] does, and a server that exited under it is
// reported the same way.
func (s Server) IfShell(ctx context.Context, request IfShellRequest) error {
	if err := validateIfShellArguments(request); err != nil {
		return err
	}
	if request.ShellCommand == "" {
		return invalidServerCommandRequest("if-shell", "ShellCommand", "", "must not be empty")
	}
	if request.ThenCommand == "" {
		return invalidServerCommandRequest("if-shell", "ThenCommand", "", "must not be empty")
	}
	targetPane := request.TargetPane.String()
	if targetPane != "" {
		if err := validateTypedTarget(
			"if-shell", "TargetPane", "pane", targetPane,
		); err != nil {
			return err
		}
	}
	arguments := []string{"if-shell"}
	if request.Background {
		arguments = append(arguments, "-b")
	}
	if targetPane != "" {
		arguments = append(arguments, "-t", targetPane)
	}
	arguments = append(arguments, "--", request.ShellCommand, request.ThenCommand)
	if request.ElseCommand != nil {
		arguments = append(arguments, *request.ElseCommand)
	}
	result, err := s.literalCmdAs(ctx, shellCommandKind(request.Background, false), arguments...)
	err = s.blockingFailure(ctx, "if-shell", err)
	if err := requireRedactedServerCommandNoStderr("if-shell", result, err); err != nil {
		return err
	}
	if !request.Background {
		return s.requireServerSurvived(ctx, "if-shell")
	}
	return nil
}

// shellCommandKind says how run-shell and if-shell occupy a client. tmux
// holds a client's queue through a foreground one until its shell command has
// finished, so it can hold a client as long as that command runs; a background
// one is answered at once. prints says the command's stdout reaches a control
// client as lines after the reply.
func shellCommandKind(background, prints bool) commandKind {
	switch {
	case background:
		return commandServer
	case prints:
		return commandBlockingOutput
	}
	return commandBlocking
}

// SourceFile loads or parses one tmux configuration file. The path expands ~
// and ~/... for the current user and normalizes redundant separators and dot
// components without collapsing parent components. Named-user forms are
// rejected. Exact "-" is rejected because it requires process stdin; a
// relative path naming a file called "-" remains file data. It can mutate
// tmux configuration; completed stderr is an error, and cancellation does not
// prove that parsing or sourcing did not occur.
func (s Server) SourceFile(ctx context.Context, request SourceFileRequest) error {
	arguments, err := sourceFileArguments(request)
	if err != nil {
		return err
	}
	result, err := s.literalCmd(ctx, arguments...)
	return requireRedactedServerCommandNoStderr("source-file", result, err)
}

// sourceFileArguments renders one source-file argument vector. It performs no
// tmux I/O, so a [Plan] can render a load it has not run. It does resolve the
// path against the filesystem, which is what expanding ~ means.
func sourceFileArguments(request SourceFileRequest) ([]string, error) {
	if request.Path == "" {
		return nil, invalidServerCommandRequest(
			"source-file", "Path", "", "must not be empty")
	}
	if request.Path == "-" {
		return nil, invalidServerCommandRequest(
			"source-file",
			"Path",
			request.Path,
			"requires stdin, which this runner does not provide",
		)
	}
	path, err := expandServerCommandPath(request.Path)
	if err != nil {
		return nil, err
	}
	arguments := []string{"source-file"}
	if request.Quiet {
		arguments = append(arguments, "-q")
	}
	if request.ParseOnly {
		arguments = append(arguments, "-n")
	}
	if request.Verbose {
		arguments = append(arguments, "-v")
	}
	return append(arguments, "--", path), nil
}

func invalidServerCommandRequest(
	subcommand string,
	field string,
	value string,
	reason string,
) error {
	return &ServerCommandRequestError{
		Subcommand: subcommand,
		Field:      field,
		Value:      value,
		Reason:     reason,
	}
}

func expandServerCommandPath(path string) (string, error) {
	return expandCommandPath("source-file", path)
}

func validateRunShellArguments(request RunShellRequest) error {
	values := []serverCommandArgument{
		{field: "Command", value: request.Command},
		{field: "TargetPane", value: request.TargetPane.String()},
	}
	if request.Delay != nil {
		values = append(values, serverCommandArgument{field: "Delay", value: *request.Delay})
	}
	if request.StartDirectory != nil {
		values = append(
			values,
			serverCommandArgument{field: "StartDirectory", value: *request.StartDirectory},
		)
	}
	for _, argument := range request.Args {
		values = append(values, serverCommandArgument{field: "Args", value: argument})
	}
	return validateServerCommandArguments("run-shell", values...)
}

func validateIfShellArguments(request IfShellRequest) error {
	values := []serverCommandArgument{
		{field: "ShellCommand", value: request.ShellCommand},
		{field: "ThenCommand", value: request.ThenCommand},
		{field: "TargetPane", value: request.TargetPane.String()},
	}
	if request.ElseCommand != nil {
		values = append(
			values,
			serverCommandArgument{field: "ElseCommand", value: *request.ElseCommand},
		)
	}
	return validateServerCommandArguments("if-shell", values...)
}

func expandCommandPath(subcommand string, path string) (string, error) {
	if err := validateServerCommandArgument(subcommand, "Path", path, true); err != nil {
		return "", err
	}
	if !strings.HasPrefix(path, "~") {
		return normalizeCommandPath(path), nil
	}
	if path != "~" && !strings.HasPrefix(path, "~/") {
		return "", invalidServerCommandRequest(
			subcommand,
			"Path",
			path,
			"does not support named-user expansion",
		)
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", invalidServerCommandRequest(
			subcommand,
			"Path",
			path,
			"cannot expand the current user home: "+err.Error(),
		)
	}
	if home == "" {
		return "", invalidServerCommandRequest(
			subcommand,
			"Path",
			path,
			"cannot expand an empty current user home",
		)
	}
	if path == "~" {
		return normalizeCommandPath(home), nil
	}
	expanded := home
	if !os.IsPathSeparator(home[len(home)-1]) {
		expanded += string(os.PathSeparator)
	}
	expanded += filepath.FromSlash(strings.TrimPrefix(path, "~/"))
	return normalizeCommandPath(expanded), nil
}

// normalizeCommandPath mirrors pathlib's harmless lexical normalization while
// retaining parent components whose kernel resolution may cross symlinks.
func normalizeCommandPath(path string) string {
	volume := filepath.VolumeName(path)
	remainder := path[len(volume):]
	leadingSeparators := 0
	for leadingSeparators < len(remainder) && os.IsPathSeparator(remainder[leadingSeparators]) {
		leadingSeparators++
	}

	parts := strings.FieldsFunc(remainder[leadingSeparators:], func(character rune) bool {
		return character == '/' || character == rune(os.PathSeparator)
	})
	normalized := parts[:0]
	for _, part := range parts {
		if part != "." {
			normalized = append(normalized, part)
		}
	}

	separator := string(os.PathSeparator)
	prefix := volume
	if leadingSeparators != 0 {
		prefix += separator
		if volume == "" && os.PathSeparator == '/' && leadingSeparators == 2 {
			prefix += separator
		}
	}
	joined := strings.Join(normalized, separator)
	// Keep a relative file named "-" distinct from tmux's stdio sentinel.
	if prefix == "" && joined == "-" && path != "-" {
		return "." + separator + "-"
	}
	if prefix != "" {
		return prefix + joined
	}
	if joined == "" {
		return "."
	}
	return joined
}

func validateServerCommandArgument(
	subcommand string,
	field string,
	value string,
	redact bool,
) error {
	if !strings.ContainsRune(value, '\x00') {
		return nil
	}
	if redact {
		value = "[redacted]"
	}
	return invalidServerCommandRequest(
		subcommand,
		field,
		value,
		"contains NUL, which cannot cross process argv",
	)
}

func requireServerCommandNoStderr(
	subcommand string,
	result CommandResult,
	err error,
) error {
	if err != nil {
		return err
	}
	if len(result.Stderr) != 0 {
		return newCommandError(subcommand, result)
	}
	return nil
}

func requireRedactedServerCommandNoStderr(
	subcommand string,
	result CommandResult,
	err error,
) error {
	if err != nil {
		return err
	}
	if len(result.Stderr) != 0 {
		return newRedactedCommandError(subcommand, result)
	}
	return nil
}

tmux/server_interactive.go.content:
package tmux

import (
	"context"
	"strconv"
)

var (
	serverInteractiveVersion34 = Version{raw: "3.4", major: 3, minor: 4}
	serverInteractiveVersion35 = Version{raw: "3.5", major: 3, minor: 5}
	serverInteractiveVersion36 = Version{raw: "3.6", major: 3, minor: 6}
	serverInteractiveVersion37 = Version{raw: "3.7", major: 3, minor: 7}
)

// ConfirmBeforeRequest configures a background tmux confirmation prompt. Its
// zero value is invalid because Command is required. Nil pointer fields omit
// their flags while explicit empty strings are passed to tmux; ConfirmKey must
// be one printable ASCII character.
type ConfirmBeforeRequest struct {
	// Command is the required tmux command shown for confirmation.
	Command string
	// Prompt replaces tmux's prompt when nonnil.
	Prompt *string
	// ConfirmKey selects the affirmative key and requires tmux 3.4; see
	// UnsupportedPolicy.
	ConfirmKey *string
	// DefaultYes selects yes by default and requires tmux 3.4; see
	// UnsupportedPolicy.
	DefaultYes bool
	// TargetClient selects the stable client that displays the prompt.
	TargetClient ClientName
}

// CommandPromptRequest configures a background tmux command prompt. Its zero
// value is invalid because Template is required; nil pointer fields omit flags
// while explicit empty values are passed to tmux.
type CommandPromptRequest struct {
	// Template is the required tmux command template submitted by the prompt.
	Template string
	// Prompt replaces tmux's prompt text when nonnil.
	Prompt *string
	// Inputs supplies initial prompt inputs when nonnil.
	Inputs *string
	// TargetClient selects the stable client that displays the prompt.
	TargetClient ClientName
	// OneKey accepts one key rather than a line.
	OneKey bool
	// KeyOnly limits accepted input to keys.
	KeyOnly bool
	// OnInputChange runs Template after each input change.
	OnInputChange bool
	// Numeric restricts accepted input to a number.
	Numeric bool
	// Type selects the associated prompt-history class; zero omits -T.
	Type PromptType
	// ExpandFormat expands formats in the prompt result.
	ExpandFormat bool
	// Literal disables key-name parsing and requires tmux 3.6; see
	// UnsupportedPolicy.
	Literal bool
	// BackspaceExit exits on backspace and requires tmux 3.7; see
	// UnsupportedPolicy.
	BackspaceExit bool
	// NoFreeze leaves the pane unfrozen and requires tmux 3.7; see
	// UnsupportedPolicy.
	NoFreeze bool
}

// MenuItem is one display-menu entry. Its zero value is a separator. A named
// item always contributes its name, key, and command to tmux, including empty
// key or command strings.
type MenuItem struct {
	// Name is the visible item name; an empty name makes this item a separator.
	Name string
	// Key is the optional shortcut for a named item.
	Key string
	// Command is the tmux command for a named item.
	Command string
}

// DisplayMenuRequest configures one tmux popup menu. Position and style
// strings retain tmux's format and symbolic-position languages verbatim. Its
// zero value is invalid because Items is required. All pointer fields omit
// their flags when nil and retain explicit empty strings; DisplayMenu copies
// Items before calling tmux. TargetPane and TargetClient are independent but
// must be stable identities when present.
type DisplayMenuRequest struct {
	// Items are menu rows; a zero MenuItem is a separator.
	Items []MenuItem
	// Title is the optional menu title.
	Title *string
	// TargetPane supplies pane context for format expansion.
	TargetPane PaneID
	// TargetClient selects the client that renders the menu.
	TargetClient ClientName
	// X is tmux's horizontal position expression.
	X *string
	// Y is tmux's vertical position expression.
	Y *string
	// StartingChoice selects the initial item and requires tmux 3.4; see
	// UnsupportedPolicy.
	StartingChoice *string
	// BorderLines selects border glyphs and requires tmux 3.4; see
	// UnsupportedPolicy.
	BorderLines *string
	// Style selects menu style and requires tmux 3.4; see UnsupportedPolicy.
	Style *string
	// BorderStyle selects border style and requires tmux 3.4; see
	// UnsupportedPolicy.
	BorderStyle *string
	// SelectedStyle selects highlighted-item style and requires tmux 3.4; see
	// UnsupportedPolicy.
	SelectedStyle *string
	// Mouse enables mouse selection and requires tmux 3.5; see UnsupportedPolicy.
	Mouse bool
	// StayOpen keeps the menu visible after selecting an item.
	StayOpen bool
}

type confirmBeforeValues struct {
	command      string
	prompt       string
	confirmKey   string
	targetClient string
	defaultYes   bool
	hasPrompt    bool
	hasKey       bool
	hasClient    bool
}

type commandPromptValues struct {
	template      string
	prompt        string
	inputs        string
	targetClient  string
	promptType    string
	oneKey        bool
	keyOnly       bool
	onInputChange bool
	numeric       bool
	expandFormat  bool
	literal       bool
	backspaceExit bool
	noFreeze      bool
	hasPrompt     bool
	hasInputs     bool
	hasClient     bool
	hasPromptType bool
}

type displayMenuValues struct {
	items          []MenuItem
	title          string
	targetPane     string
	targetClient   string
	x              string
	y              string
	startingChoice string
	borderLines    string
	style          string
	borderStyle    string
	selectedStyle  string
	mouse          bool
	stayOpen       bool
	hasTitle       bool
	hasPane        bool
	hasClient      bool
	hasX           bool
	hasY           bool
	hasChoice      bool
	hasBorderLines bool
	hasStyle       bool
	hasBorderStyle bool
	hasSelected    bool
}

// ConfirmBefore asks tmux to display a background confirmation prompt and
// returns after tmux accepts it, not after the user answers or Command runs.
// It is available on every supported tmux. ConfirmKey and DefaultYes require tmux 3.4 and follow
// [UnsupportedPolicy]. Completed stderr is an error; cancellation does not
// prove prompt delivery or later command execution did not occur.
func (s Server) ConfirmBefore(ctx context.Context, request ConfirmBeforeRequest) error {
	values, err := captureConfirmBeforeRequest(request)
	if err != nil {
		return err
	}
	current, err := s.Version(ctx)
	if err != nil {
		return err
	}

	arguments := []string{"confirm-before", "-b"}
	if values.hasPrompt {
		arguments = append(arguments, "-p", values.prompt)
	}
	if values.hasKey {
		if current.AtLeast(serverInteractiveVersion34) {
			arguments = append(arguments, "-c", values.confirmKey)
		} else if err := s.unsupportedFeature(
			"confirm-before", "confirm_key", current, serverInteractiveVersion34,
		); err != nil {
			return err
		}
	}
	if values.defaultYes {
		if current.AtLeast(serverInteractiveVersion34) {
			arguments = append(arguments, "-y")
		} else if err := s.unsupportedFeature(
			"confirm-before", "default_yes", current, serverInteractiveVersion34,
		); err != nil {
			return err
		}
	}
	if values.hasClient {
		arguments = append(arguments, "-t", values.targetClient)
	}
	arguments = append(arguments, "--", values.command)

	result, err := s.literalCmd(ctx, arguments...)
	return requireRedactedServerCommandNoStderr("confirm-before", result, err)
}

// CommandPrompt asks tmux to display a background command prompt and returns
// after tmux accepts it, not after input is submitted or Template runs. It
// is available on every supported tmux. Later flags follow [UnsupportedPolicy]. Completed stderr
// is an error; cancellation does not prove prompt delivery or later execution.
func (s Server) CommandPrompt(ctx context.Context, request CommandPromptRequest) error {
	values, err := captureCommandPromptRequest(request)
	if err != nil {
		return err
	}
	current, err := s.Version(ctx)
	if err != nil {
		return err
	}

	arguments := []string{"command-prompt", "-b"}
	if values.oneKey {
		arguments = append(arguments, "-1")
	}
	if values.keyOnly {
		arguments = append(arguments, "-k")
	}
	if values.onInputChange {
		arguments = append(arguments, "-i")
	}
	if values.numeric {
		arguments = append(arguments, "-N")
	}
	if values.expandFormat {
		arguments = append(arguments, "-F")
	}
	if values.literal {
		if current.AtLeast(serverInteractiveVersion36) {
			arguments = append(arguments, "-l")
		} else if err := s.unsupportedFeature(
			"command-prompt", "literal", current, serverInteractiveVersion36,
		); err != nil {
			return err
		}
	}
	if values.backspaceExit {
		if current.AtLeast(serverInteractiveVersion37) {
			arguments = append(arguments, "-e")
		} else if err := s.unsupportedFeature(
			"command-prompt", "bspace_exit", current, serverInteractiveVersion37,
		); err != nil {
			return err
		}
	}
	if values.noFreeze {
		if current.AtLeast(serverInteractiveVersion37) {
			arguments = append(arguments, "-C")
		} else if err := s.unsupportedFeature(
			"command-prompt", "no_freeze", current, serverInteractiveVersion37,
		); err != nil {
			return err
		}
	}
	if values.hasPrompt {
		arguments = append(arguments, "-p", values.prompt)
	}
	if values.hasInputs {
		arguments = append(arguments, "-I", values.inputs)
	}
	if values.hasPromptType {
		arguments = append(arguments, "-T", values.promptType)
	}
	if values.hasClient {
		arguments = append(arguments, "-t", values.targetClient)
	}
	arguments = append(arguments, "--", values.template)

	result, err := s.literalCmd(ctx, arguments...)
	return requireRedactedServerCommandNoStderr("command-prompt", result, err)
}

// DisplayMenu displays a menu and waits until tmux closes it. The target
// client must own a TTY; control-mode clients cannot render menu overlays.
// It returns no selected value and does not establish whether an item command
// ran. Unsupported optional flags follow [UnsupportedPolicy]. Completed stderr
// is an error, and cancellation does not prove menu delivery or a selected
// command's effect.
func (s Server) DisplayMenu(ctx context.Context, request DisplayMenuRequest) error {
	values, err := captureDisplayMenuRequest(request)
	if err != nil {
		return err
	}

	needsVersion := values.hasChoice || values.hasBorderLines || values.hasStyle ||
		values.hasBorderStyle || values.hasSelected || values.mouse
	var current Version
	if needsVersion {
		current, err = s.Version(ctx)
		if err != nil {
			return err
		}
	}

	arguments := []string{"display-menu"}
	if values.hasTitle {
		arguments = append(arguments, "-T", values.title)
	}
	if values.hasClient {
		arguments = append(arguments, "-c", values.targetClient)
	}
	if values.hasPane {
		arguments = append(arguments, "-t", values.targetPane)
	}
	if values.hasX {
		arguments = append(arguments, "-x", values.x)
	}
	if values.hasY {
		arguments = append(arguments, "-y", values.y)
	}
	if values.hasChoice {
		if current.AtLeast(serverInteractiveVersion34) {
			arguments = append(arguments, "-C", values.startingChoice)
		} else if err := s.unsupportedFeature(
			"display-menu", "starting_choice", current, serverInteractiveVersion34,
		); err != nil {
			return err
		}
	}
	if values.hasBorderLines {
		if current.AtLeast(serverInteractiveVersion34) {
			arguments = append(arguments, "-b", values.borderLines)
		} else if err := s.unsupportedFeature(
			"display-menu", "border_lines", current, serverInteractiveVersion34,
		); err != nil {
			return err
		}
	}
	if values.hasStyle {
		if current.AtLeast(serverInteractiveVersion34) {
			arguments = append(arguments, "-s", values.style)
		} else if err := s.unsupportedFeature(
			"display-menu", "style", current, serverInteractiveVersion34,
		); err != nil {
			return err
		}
	}
	if values.hasBorderStyle {
		if current.AtLeast(serverInteractiveVersion34) {
			arguments = append(arguments, "-S", values.borderStyle)
		} else if err := s.unsupportedFeature(
			"display-menu", "border_style", current, serverInteractiveVersion34,
		); err != nil {
			return err
		}
	}
	if values.hasSelected {
		if current.AtLeast(serverInteractiveVersion34) {
			arguments = append(arguments, "-H", values.selectedStyle)
		} else if err := s.unsupportedFeature(
			"display-menu", "selected_style", current, serverInteractiveVersion34,
		); err != nil {
			return err
		}
	}
	if values.mouse {
		if current.AtLeast(serverInteractiveVersion35) {
			arguments = append(arguments, "-M")
		} else if err := s.unsupportedFeature(
			"display-menu", "mouse", current, serverInteractiveVersion35,
		); err != nil {
			return err
		}
	}
	if values.stayOpen {
		arguments = append(arguments, "-O")
	}
	arguments = append(arguments, "--")
	for _, menuItem := range values.items {
		arguments = append(arguments, menuItem.Name)
		if menuItem.Name != "" {
			arguments = append(arguments, menuItem.Key, menuItem.Command)
		}
	}

	result, err := s.literalCmd(ctx, arguments...)
	return requireRedactedServerCommandNoStderr("display-menu", result, err)
}

func captureConfirmBeforeRequest(request ConfirmBeforeRequest) (confirmBeforeValues, error) {
	values := confirmBeforeValues{command: request.Command, defaultYes: request.DefaultYes}
	if values.command == "" {
		return confirmBeforeValues{}, invalidServerCommandRequest(
			"confirm-before", "Command", "", "must not be empty",
		)
	}
	if err := validateServerCommandArgument(
		"confirm-before", "Command", values.command, true,
	); err != nil {
		return confirmBeforeValues{}, err
	}
	if request.Prompt != nil {
		values.prompt = *request.Prompt
		values.hasPrompt = true
		if err := validateServerCommandArgument(
			"confirm-before", "Prompt", values.prompt, false,
		); err != nil {
			return confirmBeforeValues{}, err
		}
	}
	if request.ConfirmKey != nil {
		values.confirmKey = *request.ConfirmKey
		values.hasKey = true
		if len(values.confirmKey) != 1 || values.confirmKey[0] < 32 ||
			values.confirmKey[0] > 126 {
			return confirmBeforeValues{}, invalidServerCommandRequest(
				"confirm-before", "ConfirmKey", values.confirmKey,
				"must be one printable ASCII character",
			)
		}
	}
	if request.TargetClient != "" {
		values.targetClient = request.TargetClient.String()
		values.hasClient = true
		if err := validateServerCommandArgument(
			"confirm-before", "TargetClient", values.targetClient, true,
		); err != nil {
			return confirmBeforeValues{}, err
		}
		if err := validateTypedTarget(
			"confirm-before", "TargetClient", "client", values.targetClient,
		); err != nil {
			return confirmBeforeValues{}, err
		}
	}
	return values, nil
}

func captureCommandPromptRequest(request CommandPromptRequest) (commandPromptValues, error) {
	values := commandPromptValues{
		template:      request.Template,
		oneKey:        request.OneKey,
		keyOnly:       request.KeyOnly,
		onInputChange: request.OnInputChange,
		numeric:       request.Numeric,
		expandFormat:  request.ExpandFormat,
		literal:       request.Literal,
		backspaceExit: request.BackspaceExit,
		noFreeze:      request.NoFreeze,
	}
	if values.template == "" {
		return commandPromptValues{}, invalidServerCommandRequest(
			"command-prompt", "Template", "", "must not be empty",
		)
	}
	if err := validateServerCommandArgument(
		"command-prompt", "Template", values.template, true,
	); err != nil {
		return commandPromptValues{}, err
	}
	promptType, hasPromptType, err := promptHistoryType("command-prompt", request.Type)
	if err != nil {
		return commandPromptValues{}, err
	}
	values.promptType = promptType
	values.hasPromptType = hasPromptType
	if request.Prompt != nil {
		values.prompt = *request.Prompt
		values.hasPrompt = true
		if err := validateServerCommandArgument(
			"command-prompt", "Prompt", values.prompt, false,
		); err != nil {
			return commandPromptValues{}, err
		}
	}
	if request.Inputs != nil {
		values.inputs = *request.Inputs
		values.hasInputs = true
		if err := validateServerCommandArgument(
			"command-prompt", "Inputs", values.inputs, true,
		); err != nil {
			return commandPromptValues{}, err
		}
	}
	if request.TargetClient != "" {
		values.targetClient = request.TargetClient.String()
		values.hasClient = true
		if err := validateServerCommandArgument(
			"command-prompt", "TargetClient", values.targetClient, true,
		); err != nil {
			return commandPromptValues{}, err
		}
		if err := validateTypedTarget(
			"command-prompt", "TargetClient", "client", values.targetClient,
		); err != nil {
			return commandPromptValues{}, err
		}
	}
	return values, nil
}

func captureDisplayMenuRequest(request DisplayMenuRequest) (displayMenuValues, error) {
	if len(request.Items) == 0 {
		return displayMenuValues{}, invalidServerCommandRequest(
			"display-menu", "Items", "0", "must contain at least one entry",
		)
	}
	values := displayMenuValues{
		items:    make([]MenuItem, len(request.Items)),
		mouse:    request.Mouse,
		stayOpen: request.StayOpen,
	}
	copy(values.items, request.Items)
	for index, item := range values.items {
		if item.Name == "" && (item.Key != "" || item.Command != "") {
			return displayMenuValues{}, invalidServerCommandRequest(
				"display-menu", "Items["+strconv.Itoa(index)+"]", "",
				"a separator cannot have a key or command",
			)
		}
		if err := validateServerCommandArgument(
			"display-menu", "Items["+strconv.Itoa(index)+"].Name", item.Name, false,
		); err != nil {
			return displayMenuValues{}, err
		}
		if err := validateServerCommandArgument(
			"display-menu", "Items["+strconv.Itoa(index)+"].Key", item.Key, false,
		); err != nil {
			return displayMenuValues{}, err
		}
		if err := validateServerCommandArgument(
			"display-menu", "Items["+strconv.Itoa(index)+"].Command", item.Command, true,
		); err != nil {
			return displayMenuValues{}, err
		}
	}

	var err error
	if request.Title != nil {
		values.title, values.hasTitle = *request.Title, true
		err = validateServerCommandArgument("display-menu", "Title", values.title, false)
		if err != nil {
			return displayMenuValues{}, err
		}
	}
	if request.TargetPane != "" {
		values.targetPane, values.hasPane = request.TargetPane.String(), true
		if err = validateServerCommandArgument(
			"display-menu", "TargetPane", values.targetPane, true,
		); err != nil {
			return displayMenuValues{}, err
		}
		if err = validateTypedTarget(
			"display-menu", "TargetPane", "pane", values.targetPane,
		); err != nil {
			return displayMenuValues{}, err
		}
	}
	if request.TargetClient != "" {
		values.targetClient, values.hasClient = request.TargetClient.String(), true
		if err = validateServerCommandArgument(
			"display-menu", "TargetClient", values.targetClient, true,
		); err != nil {
			return displayMenuValues{}, err
		}
		if err = validateTypedTarget(
			"display-menu", "TargetClient", "client", values.targetClient,
		); err != nil {
			return displayMenuValues{}, err
		}
	}
	if request.X != nil {
		values.x, values.hasX = *request.X, true
		if err = validateServerCommandArgument("display-menu", "X", values.x, false); err != nil {
			return displayMenuValues{}, err
		}
	}
	if request.Y != nil {
		values.y, values.hasY = *request.Y, true
		if err = validateServerCommandArgument("display-menu", "Y", values.y, false); err != nil {
			return displayMenuValues{}, err
		}
	}
	if request.StartingChoice != nil {
		values.startingChoice, values.hasChoice = *request.StartingChoice, true
		if err = validateServerCommandArgument(
			"display-menu", "StartingChoice", values.startingChoice, false,
		); err != nil {
			return displayMenuValues{}, err
		}
	}
	if request.BorderLines != nil {
		values.borderLines, values.hasBorderLines = *request.BorderLines, true
		if err = validateServerCommandArgument(
			"display-menu", "BorderLines", values.borderLines, false,
		); err != nil {
			return displayMenuValues{}, err
		}
	}
	if request.Style != nil {
		values.style, values.hasStyle = *request.Style, true
		if err = validateServerCommandArgument("display-menu", "Style", values.style, false); err != nil {
			return displayMenuValues{}, err
		}
	}
	if request.BorderStyle != nil {
		values.borderStyle, values.hasBorderStyle = *request.BorderStyle, true
		if err = validateServerCommandArgument(
			"display-menu", "BorderStyle", values.borderStyle, false,
		); err != nil {
			return displayMenuValues{}, err
		}
	}
	if request.SelectedStyle != nil {
		values.selectedStyle, values.hasSelected = *request.SelectedStyle, true
		if err = validateServerCommandArgument(
			"display-menu", "SelectedStyle", values.selectedStyle, false,
		); err != nil {
			return displayMenuValues{}, err
		}
	}
	return values, nil
}

tmux/server_keys.go.content:
package tmux

import (
	"context"
)

var serverKeysVersion37 = Version{raw: "3.7", major: 3, minor: 7}

// BindKeyRequest configures one tmux key binding. Its zero value is invalid
// because Key is required; nil KeyTable and Note omit their flags while
// pointers to empty strings are explicit.
type BindKeyRequest struct {
	// Key is the required tmux key notation to bind.
	Key string
	// Command is the tmux command; an empty command is a no-op binding on tmux 3.3+.
	Command string
	// KeyTable selects a table, or nil for tmux's default table.
	KeyTable *string
	// Note supplies tmux's optional binding note.
	Note *string
	// Repeat makes the binding repeatable.
	Repeat bool
}

// UnbindKeyRequest selects one key or an entire key table to unbind. Exactly
// one of Key and AllKeys must be set.
type UnbindKeyRequest struct {
	// Key selects one binding; it is mutually exclusive with AllKeys.
	Key *string
	// KeyTable limits removal to one table; nil selects tmux's default table.
	KeyTable *string
	// AllKeys removes every binding in KeyTable and is mutually exclusive with Key.
	AllKeys bool
	// Quiet suppresses tmux's missing-binding diagnostic.
	Quiet bool
}

// ListKeysRequest configures raw key-binding output. Its zero value selects
// tmux's default table and format; nil fields omit flags while explicit empty
// pointers are passed to tmux.
type ListKeysRequest struct {
	// KeyTable limits output to one key table.
	KeyTable *string
	// Format selects output format and requires tmux 3.7; see
	// UnsupportedPolicy.
	Format *string
}

// ListCommandsRequest optionally limits output to one tmux command or alias.
// Nil CommandName lists all commands; a pointer to an empty name is explicit.
type ListCommandsRequest struct {
	// CommandName optionally selects one command or alias.
	CommandName *string
}

// ShowMessagesRequest selects the target and server information to print.
// Terminals and Jobs are independent and may both be enabled.
type ShowMessagesRequest struct {
	// TargetClient selects a stable client; zero selects tmux's current client.
	TargetClient ClientName
	// Terminals includes terminal capability information.
	Terminals bool
	// Jobs includes job status information.
	Jobs bool
}

// BindKey binds Key to Command in a tmux key table. An empty Command creates
// a no-op binding.
// It mutates the table; cancellation does not prove that tmux did not bind Key.
func (s Server) BindKey(ctx context.Context, request BindKeyRequest) error {
	keyTable, hasKeyTable := serverKeyOptionalString(request.KeyTable)
	note, hasNote := serverKeyOptionalString(request.Note)
	if err := validateServerKeyArguments(
		"bind-key",
		serverCommandArgument{field: "Key", value: request.Key},
		serverCommandArgument{field: "Command", value: request.Command},
		serverCommandArgument{field: "KeyTable", value: keyTable},
		serverCommandArgument{field: "Note", value: note},
	); err != nil {
		return err
	}
	if request.Key == "" {
		return invalidServerCommandRequest("bind-key", "Key", "", "must not be empty")
	}

	arguments := []string{"bind-key"}
	if request.Repeat {
		arguments = append(arguments, "-r")
	}
	if hasNote {
		arguments = append(arguments, "-N", note)
	}
	if hasKeyTable {
		arguments = append(arguments, "-T", keyTable)
	}
	arguments = append(arguments, "--", request.Key, request.Command)
	return runServerKeyCommand(ctx, s, "bind-key", arguments)
}

// UnbindKey removes one key binding or every binding in a key table. Key and
// AllKeys must select exactly one target; cancellation does not prove removal
// did not occur.
func (s Server) UnbindKey(ctx context.Context, request UnbindKeyRequest) error {
	key, hasKey := serverKeyOptionalString(request.Key)
	keyTable, hasKeyTable := serverKeyOptionalString(request.KeyTable)
	if err := validateServerKeyArguments(
		"unbind-key",
		serverCommandArgument{field: "Key", value: key},
		serverCommandArgument{field: "KeyTable", value: keyTable},
	); err != nil {
		return err
	}
	if hasKey == request.AllKeys {
		return invalidServerCommandRequest(
			"unbind-key",
			"Key",
			key,
			"must select exactly one of Key or AllKeys",
		)
	}
	if hasKey && key == "" {
		return invalidServerCommandRequest("unbind-key", "Key", "", "must not be empty")
	}

	arguments := []string{"unbind-key"}
	if request.AllKeys {
		arguments = append(arguments, "-a")
	}
	if request.Quiet {
		arguments = append(arguments, "-q")
	}
	if hasKeyTable {
		arguments = append(arguments, "-T", keyTable)
	}
	if hasKey {
		arguments = append(arguments, "--", key)
	}
	return runServerKeyCommand(ctx, s, "unbind-key", arguments)
}

// ListKeys returns an owned snapshot of raw tmux key-binding lines. Format
// requires tmux 3.7 and follows [UnsupportedPolicy]. tmux 3.7 through 3.7c send
// a table's sole matching binding to client status and leave stdout empty; this
// method preserves that upstream and Python behavior. Listing failures remain
// errors.
//
// On an unused socket, tmux starts an empty server to answer. With the default
// exit-empty setting, that server exits at once and leaves its socket file.
func (s Server) ListKeys(
	ctx context.Context,
	request ListKeysRequest,
) ([]string, error) {
	keyTable, hasKeyTable := serverKeyOptionalString(request.KeyTable)
	format, hasFormat := serverKeyOptionalString(request.Format)
	if err := validateServerKeyArguments(
		"list-keys",
		serverCommandArgument{field: "KeyTable", value: keyTable},
		serverCommandArgument{field: "Format", value: format},
	); err != nil {
		return nil, err
	}

	arguments := []string{"list-keys"}
	if hasKeyTable {
		arguments = append(arguments, "-T", keyTable)
	}
	if hasFormat {
		current, err := s.Version(ctx)
		if err != nil {
			return nil, err
		}
		if current.AtLeast(serverKeysVersion37) {
			arguments = append(arguments, "-F", format)
		} else if err := s.unsupportedFeature(
			"list-keys",
			"format",
			current,
			serverKeysVersion37,
		); err != nil {
			return nil, err
		}
	}
	return runServerListCommand(ctx, s, arguments)
}

// ListCommands returns an owned snapshot of raw tmux command-description lines.
// A list failure is returned rather than answered with no rows. Like
// [Server.ListKeys], it answers on a socket holding no server.
func (s Server) ListCommands(
	ctx context.Context,
	request ListCommandsRequest,
) ([]string, error) {
	commandName, hasCommandName := serverKeyOptionalString(request.CommandName)
	if err := validateServerKeyArguments(
		"list-commands",
		serverCommandArgument{field: "CommandName", value: commandName},
	); err != nil {
		return nil, err
	}
	arguments := []string{"list-commands"}
	if hasCommandName {
		arguments = append(arguments, "--", commandName)
	}
	return runServerListCommand(ctx, s, arguments)
}

// ListClients returns an owned snapshot of raw tmux client-description lines,
// the text tmux itself prints. A list failure is returned rather than answered
// with no rows. [Server.Clients] answers the same question as typed [Client]
// records and is what most callers want.
func (s Server) ListClients(ctx context.Context) ([]string, error) {
	return runServerListCommand(ctx, s, []string{"list-clients"})
}

// ShowMessages returns an owned snapshot of the tmux message log, terminal capabilities, job
// summary, or both terminal and job summaries. A zero TargetClient selects tmux's
// current client; a list failure is returned rather than answered with no rows.
func (s Server) ShowMessages(
	ctx context.Context,
	request ShowMessagesRequest,
) ([]string, error) {
	targetClient, hasTargetClient := string(request.TargetClient), request.TargetClient != ""
	if err := validateServerKeyArguments(
		"show-messages",
		serverCommandArgument{field: "TargetClient", value: targetClient},
	); err != nil {
		return nil, err
	}
	if hasTargetClient {
		if err := validateTypedTarget(
			"show-messages", "TargetClient", "client", targetClient,
		); err != nil {
			return nil, err
		}
	}

	arguments := []string{"show-messages"}
	if request.Terminals {
		arguments = append(arguments, "-T")
	}
	if request.Jobs {
		arguments = append(arguments, "-J")
	}
	if hasTargetClient {
		arguments = append(arguments, "-t", targetClient)
	}
	return runServerListCommand(ctx, s, arguments)
}

func runServerKeyCommand(
	ctx context.Context,
	server Server,
	subcommand string,
	arguments []string,
) error {
	result, err := server.literalCmd(ctx, arguments...)
	return requireRedactedServerCommandNoStderr(subcommand, result, err)
}

func serverKeyOptionalString[T ~string](value *T) (string, bool) {
	if value == nil {
		return "", false
	}
	return string(*value), true
}

func validateServerKeyArguments(
	subcommand string,
	arguments ...serverCommandArgument,
) error {
	return validateServerCommandArguments(subcommand, arguments...)
}

tmux/server_layout.go.content:
package tmux

import (
	"context"
	"iter"
	"strings"

	"github.com/libtmux/libtmux-go/tmux/internal/layout"
)

// ValidateLayouts checks every layout and its required pane count before any
// mutation. Nil and empty sequences succeed without I/O unless ctx is canceled.
// Empty layout strings are ignored. Other entries require at least one pane;
// classic trees must contain enough leaves. tmux validates JSON contents and
// geometry when applying the layout.
//
// Names accept unique abbreviations. Version-sensitive names query the selected
// daemon through this server's transport; only a cold endpoint without a captured
// daemon identity or control connection uses the configured binary's version.
// Permission, protocol, decode and cancellation errors are preserved.
// Validation errors match
// [ErrInvalidServerCommandRequest]; unavailable presets match [ErrVersionTooLow].
func (s Server) ValidateLayouts(ctx context.Context, layouts iter.Seq2[string, int]) error {
	_, err := s.validateLayouts(ctx, layouts)
	return err
}

func (s Server) validateLayouts(ctx context.Context, layouts iter.Seq2[string, int]) (Version, error) {
	if err := ctx.Err(); err != nil {
		return Version{}, err
	}
	var pending []string
	if layouts != nil {
		for value, panes := range layouts {
			if err := ctx.Err(); err != nil {
				return Version{}, err
			}
			if err := (SelectLayoutRequest{Layout: value}).Validate(); err != nil {
				return Version{}, err
			}
			if value == "" {
				continue
			}
			if panes < 1 {
				return Version{}, invalidServerCommandRequest("select-layout", "Panes", "",
					"must be positive")
			}
			if cells, custom := layout.Cells(value); custom && cells < panes {
				return Version{}, invalidServerCommandRequest("select-layout", "Layout", value,
					"contains fewer cells than the required panes")
			}
			if layoutNeedsVersion(value) {
				pending = append(pending, value)
			}
		}
	}
	if err := ctx.Err(); err != nil {
		return Version{}, err
	}
	if len(pending) == 0 {
		return Version{}, nil
	}
	version, err := s.layoutVersion(ctx)
	if err != nil {
		return Version{}, err
	}
	for _, value := range pending {
		if _, err := validateLayout(value, version); err != nil {
			return Version{}, err
		}
	}
	return version, nil
}

func (s Server) layoutVersion(ctx context.Context) (Version, error) {
	if s.connection != nil {
		// run-shell -C reports its refusal outside any reply block over
		// control, so a bound handle asks its daemon directly.
		return s.layoutVersionFromDisplay(ctx)
	}
	// run-shell has no after-hook, so reading the version does not fire a
	// user's after-display-message hook; tmux reports it in the refusal of the
	// marker word.
	marker := newIdentityProbeMarker()
	result, err := s.literalCmd(ctx, "run-shell", "-C", marker+"#{q:version}")
	if err != nil {
		return Version{}, err
	}
	if result.ExitCode == 1 && len(result.Stderr) == 1 {
		if token, ok := strings.CutPrefix(result.Stderr[0], "unknown command: "+marker); ok {
			if version, err := ParseVersion(token); err == nil {
				return version, nil
			}
			return Version{}, newVersionQueryError(result, "layout version query returned an invalid version")
		}
	}
	if s.daemon == nil && coldLayoutEndpoint(result) {
		return s.Version(ctx)
	}
	return Version{}, newCommandError("run-shell", result)
}

func (s Server) layoutVersionFromDisplay(ctx context.Context) (Version, error) {
	result, err := s.literalCmd(ctx, "display-message", "-p", "tmux #{version}")
	if err != nil {
		return Version{}, err
	}
	if result.ExitCode != 0 || len(result.Stderr) != 0 {
		if s.connection == nil && s.daemon == nil && coldLayoutEndpoint(result) {
			return s.Version(ctx)
		}
		return Version{}, newCommandError("display-message", result)
	}
	if len(result.Stdout) == 1 {
		if token, ok := strings.CutPrefix(result.Stdout[0], "tmux "); ok {
			version, err := ParseVersion(token)
			if err == nil {
				return version, nil
			}
		}
	}
	return Version{}, newVersionQueryError(result, "layout version query returned an invalid version")
}

func coldLayoutEndpoint(result CommandResult) bool {
	if result.ExitCode != 1 || len(result.Stderr) != 1 {
		return false
	}
	reason := result.Stderr[0]
	return strings.HasPrefix(reason, "no server running on ") ||
		(strings.HasPrefix(reason, "error connecting to ") &&
			strings.HasSuffix(reason, " (No such file or directory)"))
}

tmux/server_options.go.content:
package tmux

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"slices"

	"github.com/libtmux/libtmux-go/tmux/internal/tmuxcmd"
)

// ErrInvalidServer identifies an operation on an uninitialized [Server].
var ErrInvalidServer = errors.New("tmux: invalid server handle")

// ErrInvalidServerOptions identifies a value that fails [ServerOptions]
// validation. Executable lookup and working-directory failures retain their
// own error identities.
var ErrInvalidServerOptions = errors.New("tmux: invalid server options")

// ServerOptions configures a [Server] without starting tmux. [NewServer]
// snapshots the effective environment, working directory, and executable;
// callers retain ownership of every supplied value.
type ServerOptions struct {
	// Binary is the tmux executable name or path. Empty resolves tmux once
	// through the snapshotted PATH. Relative paths resolve against the
	// constructor's working directory. The resolved absolute path is shared by
	// subprocess and control-mode transports.
	Binary string
	// SocketName selects tmux's named socket. SocketPath takes precedence.
	SocketName string
	// SocketPath selects an explicit tmux socket path.
	SocketPath string
	// ConfigFile selects an exact tmux configuration file. Empty lets tmux read
	// its default configuration, so a program inherits whatever the user
	// running it has configured: a base-index other than zero, a prompt that
	// appears in captured pane text, hooks that fire on the sessions this
	// program creates. Point it at a file the program owns, which may be an
	// empty one, when the tmux it drives should not depend on that.
	ConfigFile string
	// Colors overrides tmux's terminal color capability.
	Colors ColorMode
	// ProcessEnvironment replaces the child process environment. Nil snapshots
	// the current process environment. A non-nil empty slice supplies no
	// caller-provided variables. Execution may add variables required by Go's
	// target platform and a canonical TMUX_TMPDIR that freezes named or default
	// socket selection. Duplicate names retain their last value. Entries
	// containing NUL are rejected except on Plan 9, where NUL separates path-list
	// elements. NewServer clones the slice.
	ProcessEnvironment []string
	// Unsupported selects what happens when a request needs an optional tmux
	// capability the running server does not have. The zero value refuses the
	// request; see UnsupportedPolicy.
	Unsupported UnsupportedPolicy
	// WarningHandler receives nonfatal compatibility warnings. Nil discards
	// warnings. See WarningHandler for delivery and concurrency semantics.
	WarningHandler WarningHandler
	// CommandObserver receives one record per tmux command run. Nil observes
	// nothing. See CommandObserver for delivery and concurrency semantics.
	CommandObserver CommandObserver
}

type serverConfig struct {
	executable                   string
	directory                    string
	socketName                   string
	socketPath                   string
	configFile                   string
	colors                       ColorMode
	processEnvironment           []string
	configuredProcessEnvironment []string
	socketSelection              SocketSelection
	unsupported                  UnsupportedPolicy
	warningHandler               WarningHandler
	commandObserver              CommandObserver
}

type serverDependencies struct {
	environ           func() []string
	getwd             func() (string, error)
	resolveExecutable func(string, []string, string) (string, error)
	executor          commandRunner
}

func defaultServerDependencies() serverDependencies {
	return serverDependencies{
		environ:           os.Environ,
		getwd:             os.Getwd,
		resolveExecutable: tmuxcmd.ResolveExecutable,
		executor:          tmuxcmd.Runner{},
	}
}

// NewServer validates and snapshots one tmux configuration without starting
// tmux. Empty socket selectors use the endpoint selected by the frozen
// environment.
func NewServer(options ServerOptions) (Server, error) {
	return newServer(options, defaultServerDependencies())
}

// WithSocketPath returns a server using path and the receiver's frozen
// executable, environment, working directory, and server-option policy. Empty
// clears explicit socket selectors and leaves endpoint selection to tmux. The
// result has fresh daemon-scoped coordination. A connection-bound receiver is
// rejected because its transport belongs to the original daemon.
func (s Server) WithSocketPath(path string) (Server, error) {
	state, err := s.stateForUse()
	if err != nil {
		return Server{}, err
	}
	if err := validateServerCommandArgument("tmux", "SocketPath", path, true); err != nil {
		return Server{}, invalidServerOptions(err)
	}
	if s.connection != nil {
		return Server{}, s.connection.terminalError(commandProcess)
	}
	config := state.config
	config.socketName = ""
	config.socketPath = path
	config.socketSelection.Path = selectedSocketPath(config, config.socketSelection.NamedDirectory)
	freezeNamedSocketEnvironment(&config)
	return Server{state: &serverState{
		config:   config,
		executor: state.executor,
		shared:   &serverShared{},
	}}, nil
}

// WithProcessEnvironmentValue returns a server whose tmux subprocesses receive
// name=value while preserving the receiver's frozen executable, configuration,
// and exact socket endpoint. It does not expose an inherited environment
// snapshot through [Server.ProcessEnvironment]. The result shares daemon-scoped
// coordination with the receiver. A connection-bound receiver is rejected.
func (s Server) WithProcessEnvironmentValue(name, value string) (Server, error) {
	state, err := s.stateForUse()
	if err != nil {
		return Server{}, err
	}
	if err := validateEnvironmentName(name); err != nil {
		return Server{}, invalidServerOptions(err)
	}
	if err := validateEnvironmentValue(value); err != nil {
		return Server{}, invalidServerOptions(err)
	}
	if s.connection != nil {
		return Server{}, s.connection.terminalError(commandProcess)
	}
	config := state.config
	config.processEnvironment = setProcessEnvironmentValue(
		config.processEnvironment,
		name,
		value,
	)
	if config.configuredProcessEnvironment != nil {
		config.configuredProcessEnvironment = setProcessEnvironmentValue(
			config.configuredProcessEnvironment,
			name,
			value,
		)
	}
	// Environment values such as TMUX_TMPDIR must not retarget the derived
	// handle. Pin the already-resolved endpoint as an explicit socket path.
	config.socketName = ""
	config.socketPath = state.config.socketSelection.Path
	return Server{
		state: &serverState{
			config:   config,
			executor: state.executor,
			shared:   state.shared,
		},
		daemon:          s.daemon,
		requiresProcess: s.requiresProcess,
	}, nil
}

func newServer(options ServerOptions, dependencies serverDependencies) (Server, error) {
	if err := validateColorMode(options.Colors); err != nil {
		return Server{}, invalidServerOptions(err)
	}
	if err := validateConnectionArguments(options); err != nil {
		return Server{}, invalidServerOptions(err)
	}
	if err := validateUnsupportedPolicy(options.Unsupported); err != nil {
		return Server{}, invalidServerOptions(err)
	}
	if err := validateServerCommandArgument("tmux", "Binary", options.Binary, true); err != nil {
		return Server{}, invalidServerOptions(err)
	}
	if dependencies.environ == nil || dependencies.getwd == nil ||
		dependencies.resolveExecutable == nil || dependencies.executor == nil {
		return Server{}, errors.New("tmux: incomplete constructor dependencies")
	}

	parentEnvironment := slices.Clone(dependencies.environ())
	configuredEnvironment := options.ProcessEnvironment != nil
	environment := options.ProcessEnvironment
	if environment == nil {
		environment = parentEnvironment
	} else {
		environment = slices.Clone(environment)
	}
	environment, err := normalizeProcessEnvironment(environment, parentEnvironment)
	if err != nil {
		return Server{}, err
	}
	cwd, err := dependencies.getwd()
	if err != nil {
		return Server{}, fmt.Errorf("snapshot working directory: %w", err)
	}
	if !filepath.IsAbs(cwd) {
		return Server{}, errors.New("snapshot working directory: path is not absolute")
	}
	binary := options.Binary
	if binary == "" {
		binary = "tmux"
	}
	executable, err := dependencies.resolveExecutable(binary, environment, cwd)
	if err != nil {
		return Server{}, fmt.Errorf("resolve tmux executable %q: %w", binary, err)
	}
	if !filepath.IsAbs(executable) {
		return Server{}, errors.New("resolve tmux executable: resolver returned a relative path")
	}

	config := serverConfig{
		executable:         filepath.Clean(executable),
		directory:          filepath.Clean(cwd),
		socketName:         options.SocketName,
		socketPath:         options.SocketPath,
		configFile:         options.ConfigFile,
		colors:             options.Colors,
		processEnvironment: environment,
		unsupported:        options.Unsupported,
		warningHandler:     options.WarningHandler,
		commandObserver:    options.CommandObserver,
	}
	if configuredEnvironment {
		config.configuredProcessEnvironment = slices.Clone(environment)
	}
	config.socketSelection = resolveSocketSelection(config)
	freezeNamedSocketEnvironment(&config)
	return Server{state: &serverState{
		config:   config,
		executor: dependencies.executor,
		shared:   &serverShared{},
	}}, nil
}

func invalidServerOptions(err error) error {
	if errors.Is(err, ErrInvalidServerOptions) {
		return err
	}
	return fmt.Errorf("%w: %w", ErrInvalidServerOptions, err)
}

func validateUnsupportedPolicy(policy UnsupportedPolicy) error {
	switch policy {
	case FailUnsupported, DegradeUnsupported:
		return nil
	default:
		return fmt.Errorf(
			"%w: invalid Unsupported policy %s",
			ErrInvalidServerOptions,
			policy,
		)
	}
}

tmux/server_version.go.content:
package tmux

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"sync"
	"sync/atomic"
)

// Version-probe sentinels classify [VersionQueryError] and
// [VersionTooLowError] through errors.Is.
var (
	// ErrVersionQuery identifies a tmux version probe that produced no usable
	// version. It is matched by errors.Is for VersionQueryError.
	ErrVersionQuery = errors.New("tmux: version query failed")
	// ErrVersionTooLow identifies a tmux version below a required feature level.
	// It is matched by errors.Is for VersionTooLowError.
	ErrVersionTooLow = errors.New("tmux: version too low")
)

// VersionQueryError reports an unsuccessful tmux version probe. It matches
// [ErrVersionQuery] through errors.Is; callers can recover its fields with
// errors.As. Library-created errors retain only the exit code; command
// arguments and output are omitted, although callers may construct values with
// other contents.
type VersionQueryError struct {
	// Result contains the library-created error's exit code and no diagnostics.
	Result CommandResult
	// Reason describes a malformed successful probe result, when applicable.
	Reason string

	commandFailure bool
}

// Error implements error.
func (e *VersionQueryError) Error() string {
	if e.Reason == "" {
		return ErrVersionQuery.Error()
	}
	return fmt.Sprintf("%v: %s", ErrVersionQuery, e.Reason)
}

// Unwrap makes VersionQueryError compatible with ErrVersionQuery.
func (e *VersionQueryError) Unwrap() error {
	return ErrVersionQuery
}

func (e *VersionQueryError) failedCommand() bool {
	return e.commandFailure || e.Result.ExitCode != 0 || len(e.Result.Stderr) != 0
}

func newVersionQueryError(result CommandResult, reason string) *VersionQueryError {
	commandFailure := result.ExitCode != 0 || len(result.Stderr) != 0
	if reason == "" && result.ExitCode != 0 {
		reason = fmt.Sprintf("tmux -V exited %d", result.ExitCode)
	} else if reason == "" && len(result.Stderr) != 0 {
		reason = "tmux -V returned stderr"
	}
	return &VersionQueryError{
		Result:         CommandResult{ExitCode: result.ExitCode},
		Reason:         reason,
		commandFailure: commandFailure,
	}
}

// VersionTooLowError reports the installed and required tmux feature levels.
// It matches [ErrVersionTooLow] through errors.Is; callers can recover its
// fields with errors.As.
//
// A version that names no release, such as a bare "master" or a distributor's
// suffix, is refused the same way, and its message says so instead of
// comparing it with the floor.
//
// Subcommand and Feature are set when one optional capability within a command
// was refused rather than the command itself, which is what
// [UnsupportedPolicy] governs.
type VersionTooLowError struct {
	// Current is the installed tmux feature level.
	Current Version
	// Minimum is the requested minimum feature level.
	Minimum Version
	// Subcommand names the tmux subcommand whose optional capability was
	// refused. Empty when the command itself is below its floor.
	Subcommand string
	// Feature names the refused optional capability. Empty when the command
	// itself is below its floor.
	Feature string

	unrecognized bool
}

// versionRemedy says what to do about a refused tmux.
const versionRemedy = "upgrade tmux and restart its server, or pin the previous libtmux release"

// Error implements error.
func (e *VersionTooLowError) Error() string {
	message := e.Reason()
	if e.Feature == "" && e.Minimum.raw == MinimumSupportedVersion {
		message += "; " + versionRemedy
	}
	return message
}

// Reason describes the refusal without saying what to do about it, for a
// caller that words its own remedy.
func (e *VersionTooLowError) Reason() string {
	if e.Feature != "" {
		return fmt.Sprintf(
			"%v: %s: %s requires %s or newer, installed %s",
			ErrVersionTooLow,
			e.Subcommand,
			e.Feature,
			e.Minimum,
			e.Current,
		)
	}
	if e.unrecognized {
		return fmt.Sprintf(
			"tmux: version unrecognized: %q names no tmux release, require %s or newer",
			e.Current.String(),
			e.Minimum,
		)
	}
	return fmt.Sprintf(
		"%v: installed %s, require %s or newer",
		ErrVersionTooLow,
		e.Current,
		e.Minimum,
	)
}

// Unwrap makes VersionTooLowError compatible with ErrVersionTooLow.
func (e *VersionTooLowError) Unwrap() error {
	return ErrVersionTooLow
}

type versionCache struct {
	mu       sync.Mutex
	value    Version
	valid    bool
	inFlight chan struct{}
}

type versionTransportError struct {
	err error
}

type openBSDCapability struct {
	major   int
	minor   int
	command string
	flag    byte
}

var (
	openBSDCapabilityProbeSequence atomic.Uint64
	openBSDCapabilityLadder        = [...]openBSDCapability{
		{major: 3, minor: 2, command: "display-popup"},
		{major: 3, minor: 3, command: "confirm-before", flag: 'b'},
		{major: 3, minor: 4, command: "confirm-before", flag: 'c'},
		{major: 3, minor: 5, command: "copy-mode", flag: 'd'},
		{major: 3, minor: 6, command: "capture-pane", flag: 'M'},
		{major: 3, minor: 7, command: "list-keys", flag: 'F'},
	}
)

func (e *versionTransportError) Error() string { return e.err.Error() }

func (e *versionTransportError) Unwrap() error { return e.err }

// Version returns a materialized handle's daemon version or an unbound handle's
// cached executable version. Failed probes are not cached. A waiting caller can
// abandon an in-flight shared probe when ctx ends without canceling its owner.
func (s Server) Version(ctx context.Context) (Version, error) {
	return s.loadVersion(ctx, false)
}

// RefreshVersion returns a materialized handle's daemon version or invalidates
// an unbound handle's executable cache and probes again. Canceling ctx stops this
// call's wait; it does not establish whether the executable received a probe.
func (s Server) RefreshVersion(ctx context.Context) (Version, error) {
	return s.loadVersion(ctx, true)
}

// RequireVersion returns a [VersionTooLowError] matching [ErrVersionTooLow]
// when the selected daemon, or an executable creating it, is older than minimum.
func (s Server) RequireVersion(ctx context.Context, minimum Version) error {
	checked, err := s.checkCore(ctx, false)
	if err != nil {
		return err
	}
	current, err := checked.Version(ctx)
	if err != nil {
		return err
	}
	if !current.meetsMinimum(minimum) {
		return refuseVersion(current, minimum)
	}
	return nil
}

func (s Server) loadVersion(ctx context.Context, refresh bool) (Version, error) {
	state, err := s.stateForUse()
	if err != nil {
		return Version{}, err
	}
	if s.daemon != nil {
		return s.daemon.version, nil
	}
	if s.startupVersion != nil {
		return *s.startupVersion, nil
	}
	cache := &state.shared.version
	for {
		cache.mu.Lock()
		if !refresh && cache.valid {
			version := cache.value
			cache.mu.Unlock()
			return version, nil
		}
		if cache.inFlight != nil {
			done := cache.inFlight
			cache.mu.Unlock()
			select {
			case <-done:
				continue
			case <-ctx.Done():
				return Version{}, ctx.Err()
			}
		}
		if refresh {
			cache.valid = false
		}
		done := make(chan struct{})
		cache.inFlight = done
		cache.mu.Unlock()

		version, err := s.queryVersion(ctx)

		cache.mu.Lock()
		if err == nil {
			cache.value = version
			cache.valid = true
		}
		cache.inFlight = nil
		close(done)
		cache.mu.Unlock()
		return version, err
	}
}

func (s Server) queryVersion(ctx context.Context) (Version, error) {
	return s.queryVersionForOS(ctx, runtime.GOOS)
}

func (s Server) queryVersionForOS(ctx context.Context, goos string) (Version, error) {
	version, err := s.queryExecutableVersion(ctx, goos)
	if err != nil || !isOpenBSDVersionToken(version.String()) {
		return version, err
	}
	return s.probeOpenBSDCapabilities(ctx, version.String())
}

// queryExecutableVersion reads only the current executable's report. The version check
// never shares a diagnostic cache or starts a capability-probe daemon.
func (s Server) queryExecutableVersion(ctx context.Context, goos string) (Version, error) {
	state, err := s.stateForUse()
	if err != nil {
		return Version{}, &versionTransportError{err: err}
	}
	result, err := s.runExactArgv(ctx, []string{"-V"})
	commandResult := cloneCommandResult(CommandResult{
		Command:  result.Command,
		Stdout:   result.Stdout,
		Stderr:   result.Stderr,
		ExitCode: result.ExitCode,
	})
	if err != nil {
		return Version{}, &versionTransportError{err: err}
	}
	// Prefix matching needs the original bytes; the public text decoder
	// escapes invalid UTF-8 in an otherwise valid executable basename.
	if len(result.RawStdout) != 0 {
		commandResult.Stdout = strings.Split(strings.TrimRight(string(result.RawStdout), "\n"), "\n")
	}
	// tmux 3.3a reports argv[0]'s basename; newer releases print "tmux".
	// Accept that exact configured name without loosening the version token.
	if len(commandResult.Stdout) == 1 {
		name := filepath.Base(state.config.executable)
		if token, ok := strings.CutPrefix(commandResult.Stdout[0], name+" "); ok {
			commandResult.Stdout[0] = "tmux " + token
		}
	}
	return parseQueriedVersion(commandResult, goos)
}

func parseQueriedVersion(result CommandResult, goos string) (Version, error) {
	if result.ExitCode != 0 || len(result.Stderr) != 0 {
		if goos == "openbsd" && len(result.Stderr) > 0 &&
			result.Stderr[0] == "tmux: unknown option -- V" {
			return Version{raw: "openbsd"}, nil
		}
		return Version{}, newVersionQueryError(result, "")
	}
	if len(result.Stdout) != 1 {
		return Version{}, newVersionQueryError(
			result, fmt.Sprintf("tmux -V returned %d lines", len(result.Stdout)),
		)
	}
	token, found := strings.CutPrefix(result.Stdout[0], "tmux ")
	if !found || token == "" {
		return Version{}, newVersionQueryError(result, "unexpected tmux -V output")
	}
	version, err := ParseVersion(token)
	if err != nil {
		return Version{}, newVersionQueryError(result, "tmux -V returned a malformed version token")
	}
	return version, nil
}

func (s Server) probeOpenBSDCapabilities(ctx context.Context, raw string) (Version, error) {
	socketName := fmt.Sprintf(
		"libtmux-capability-%d-%d",
		os.Getpid(),
		openBSDCapabilityProbeSequence.Add(1),
	)
	result, err := s.runExactArgv(ctx, []string{
		"-f" + os.DevNull,
		"-L" + socketName,
		"start-server",
		";",
		"list-commands",
	})
	commandResult := cloneCommandResult(CommandResult{
		Command:  result.Command,
		Stdout:   result.Stdout,
		Stderr:   result.Stderr,
		ExitCode: result.ExitCode,
	})
	if err != nil {
		return Version{}, &versionTransportError{err: err}
	}
	if result.ExitCode != 0 || len(result.Stderr) != 0 {
		reason := "tmux capability probe returned stderr"
		if result.ExitCode != 0 {
			reason = fmt.Sprintf("tmux capability probe exited %d", result.ExitCode)
		}
		return Version{}, newVersionQueryError(commandResult, reason)
	}
	if len(result.Stdout) == 0 {
		return Version{}, newVersionQueryError(
			commandResult,
			"tmux capability probe returned no commands",
		)
	}
	return openBSDCapabilityVersion(raw, result.Stdout), nil
}

func openBSDCapabilityVersion(raw string, lines []string) Version {
	version := Version{raw: raw}
	for _, capability := range openBSDCapabilityLadder {
		if !openBSDCommandSupports(lines, capability.command, capability.flag) {
			break
		}
		version.major = capability.major
		version.minor = capability.minor
	}
	return version
}

func isOpenBSDVersionToken(raw string) bool {
	return raw == "openbsd" || openBSDVersionPattern.MatchString(raw)
}

func openBSDCommandSupports(lines []string, command string, flag byte) bool {
	for _, line := range lines {
		fields := strings.Fields(line)
		if len(fields) == 0 || fields[0] != command {
			continue
		}
		if flag == 0 {
			return true
		}
		for _, field := range fields[1:] {
			if !strings.HasPrefix(field, "[-") {
				continue
			}
			flags := strings.TrimPrefix(field, "[-")
			if end := strings.IndexByte(flags, ']'); end >= 0 {
				flags = flags[:end]
			}
			if strings.IndexByte(flags, flag) >= 0 {
				return true
			}
		}
		return false
	}
	return false
}

tmux/server.go.content:
package tmux

import (
	"bytes"
	"context"
	"errors"
	"slices"
	"sync"

	"github.com/libtmux/libtmux-go/tmux/internal/tmuxcmd"
)

// Server is an immutable handle to one tmux configuration. Its zero value
// is invalid. Copying a configured Server preserves its configuration and
// shares version-cache coordination; only the documented concurrent operations
// are safe to share.
//
// [NewServer] resolves the executable, socket, and environment once and does
// not start tmux; creating the first session starts the daemon.
// A plain Server starts a tmux process for each command it sends, so
// discarding one leaves the daemon running; [Server.Kill] stops it.
// A Server from [Connection.Server] sends its commands over that connection's
// control lanes instead.
// Operations on the zero Server return [ErrInvalidServer].
//
// # What is on here
//
// Operations on one session, window, or pane live on [Session], [Window], and
// [Pane], such as [Session.NewWindow], [Window.SplitPane], [Pane.SendKeys], and
// [Pane.Capture].
// This type holds what belongs to the server as a whole, in the groups below.
//
// # Connecting
//
// [NewServer] validates one [ServerOptions] without starting tmux, and
// [NewServerFromEnv] reads the server this process is already inside from TMUX.
// [Server.IsAlive] answers whether anything is listening, and only an absent
// server reports false; [Server.CheckAlive] makes an absent server an error.
// [Server.Start] starts the daemon without a session, so with tmux's
// exit-empty default it can exit before the next command.
// [Server.Version] and [Server.RefreshVersion] report the configured tmux
// binary, and [Server.RequireVersion] fails with [ErrVersionTooLow] when it is
// older than a minimum.
//
// [Server.OpenControl] attaches a control-mode client to a session,
// [Server.OpenNotifications] opens an observation-only [NotificationStream] on
// one, and [Server.NewSessionConnection] creates a session together with a
// [Connection].
// [Server.ConnectionBound] reports whether a handle belongs to one.
//
// [Server.SocketPath], [Server.SocketSelection], [Server.ConfigFile],
// [Server.Executable], and [Server.ProcessEnvironment] report what the handle
// was built from.
// [Server.WithSocketPath] and [Server.WithProcessEnvironmentValue] return a
// copy that differs in that one setting.
// [Server.Equal] compares two handles by socket, and [Server.String] names the
// selector.
//
// # Finding one thing
//
// [Server.Session] and [Server.SessionByName] return one session,
// [Server.Window] and [Server.Pane] take tmux IDs,
// and [Server.Client] takes a client name.
// A lookup that finds nothing returns an error matching [ErrNotFound],
// or [ErrNoServer] when no server is running.
// [Server.HasSession] returns a bool instead,
// and a missing server counts as no session.
//
// # Listing everything
//
// [Server.Sessions], [Server.Windows], [Server.Panes], and [Server.Clients]
// list one kind of record each; [Server.Windows] returns one per window link.
// Failures, including [ErrNoServer], stay errors,
// so an outage does not read as an empty server.
// [Server.Snapshot] reads them together into a [Snapshot].
// [Server.ListClients] returns tmux's own client lines instead of records.
//
// # Querying things and getting around
//
// [Server.SearchSessions], [Server.SearchWindows], [Server.SearchPanes], and
// [Server.SearchClients] pass a [TmuxFilter] to tmux,
// which drops the rows that do not match before any record exists.
// [Session.SearchWindows], [Session.SearchPanes], and [Window.SearchPanes]
// search below one record the same way.
// To filter in Go instead, apply a [SessionFilter], [WindowFilter],
// [PaneFilter], or [ClientFilter] to a slice with tmuxq.Matching.
// tmuxq.Where, tmuxq.First, and tmuxq.ExactlyOne take a predicate function,
// and tmuxq.ExactlyOne fails unless exactly one value matches.
//
// A [Snapshot] answers further questions without another command:
// [Snapshot.SessionByID], [Snapshot.WindowByID], [Snapshot.PaneByID], and
// [Snapshot.ClientByName].
//
// Records from a snapshot, and from the listings above, know their neighbors.
// Go down with [Session.Windows], [Session.Panes], and [Window.Panes],
// up with [Pane.Window], [Pane.Session], and [Window.Session],
// and across to the focused child with [Session.ActiveWindow],
// [Session.ActivePane], and [Window.ActivePane].
// [Client.AttachedSession] reaches the session a client shows.
// None of them queries tmux, and each reports false on a record from a search,
// a lookup, or [Server.NewSession], which carries no relations.
//
// [Pane.ResolveWindow], [Pane.ResolveSession], [Window.ResolveSession],
// [Session.ResolveActiveWindow], [Session.ResolveActivePane], and
// [Window.ResolveActivePane] answer the same questions from live state,
// for any record.
//
// # Changing things
//
// [Server.NewSession] creates a detached session and returns its record.
// [Server.Kill] stops the daemon with everything in it,
// and [Server.KillSession] ends the session a tmux target selects.
//
// # Options and hooks
//
// [Server.Options] reads the server's options as a [ServerOptionValues].
// [Server.RawOption], [Server.SetOption], [Server.AppendOption], and
// [Server.UnsetOption] work by name, which reaches an option the typed setters
// do not cover.
// Known options also have typed setters, such as [Server.SetEscapeTime] and
// [Server.SetExitEmpty].
//
// [Server.GlobalSessionScope] and [Server.GlobalWindowScope] reach the defaults
// that sessions and windows inherit, and the global hooks,
// which are not methods of Server itself:
// [GlobalSessionScope.Hooks], [GlobalSessionScope.SetHook],
// [GlobalSessionScope.AppendHook], [GlobalSessionScope.UnsetHook], and
// [GlobalSessionScope.RunHook], with the same on [GlobalWindowScope].
//
// # Everything else tmux keeps
//
// Paste buffers ([Server.ListBuffers], [Server.ShowBuffer],
// [Server.ShowBufferBytes], [Server.SetBuffer], [Server.LoadBuffer],
// [Server.LoadBufferFrom], [Server.SaveBuffer], [Server.SaveBufferTo],
// [Server.DeleteBuffer]),
// key bindings ([Server.BindKey], [Server.UnbindKey], [Server.ListKeys]),
// the global environment ([Server.ShowEnvironment], [Server.GetEnvironment],
// [Server.SetEnvironment], [Server.UnsetEnvironment],
// [Server.RemoveEnvironment]),
// configuration ([Server.SourceFile]),
// shell commands ([Server.RunShell], [Server.IfShell]),
// wait-for channels, to wait, signal, lock, or unlock ([Server.WaitFor]),
// the message log ([Server.ShowMessages]),
// format expansion ([Server.DisplayMessage]),
// prompt history ([Server.ShowPromptHistory], [Server.ClearPromptHistory]),
// the commands tmux has ([Server.ListCommands]),
// access control ([Server.ServerAccess]),
// and layout checks ([Server.ValidateLayouts]).
//
// # Things that need a terminal
//
// [Server.DisplayMenu], [Server.CommandPrompt], and [Server.ConfirmBefore] draw
// on an attached client, and tmux refuses them without one.
// [Server.AttachSession] attaches the caller's own terminal and blocks until it
// detaches.
// [Server.SwitchClient], [Server.DetachClient], [Server.DetachAllClients],
// [Server.LockClient], [Server.SuspendClient], and [Server.RefreshClient] act
// on a client and fail without one;
// [Server.LockServer] locks every attached client.
//
// Anything tmux can do that is not here is reachable through [Server.Cmd],
// which runs raw tmux arguments and returns a [CommandResult];
// a completed nonzero exit is a result, not an error.
type Server struct {
	state          *serverState
	connection     *Connection
	daemon         *snapshotServerIdentity
	startupVersion *Version
	// probesIdentity marks the private identity bootstrap, which must never
	// start a daemon.
	probesIdentity bool
	// requiresProcess marks exact-output and interactive operations that cannot
	// cross a persistent control connection.
	requiresProcess bool
	// inheritsLocale marks an operation whose tmux output reaches the caller's
	// own terminal rather than this package, so tmux's locale detection
	// governs it instead of the UTF-8 commandArguments otherwise asks for.
	inheritsLocale bool
}

type serverState struct {
	config   serverConfig
	executor commandRunner
	shared   *serverShared
}

// serverShared coordinates version caching across handles that address the
// same daemon with different process environments.
type serverShared struct {
	version versionCache

	checkedMu sync.Mutex
	checked   *snapshotServerIdentity
}

// checkedDaemon returns the identity last checked at this endpoint.
func (s *serverShared) checkedDaemon() *snapshotServerIdentity {
	s.checkedMu.Lock()
	defer s.checkedMu.Unlock()
	return s.checked
}

// rememberChecked records a version-checked identity, or forgets it when nil. The
// if-shell fence on every dispatch is what proves the record still describes
// the live daemon.
func (s *serverShared) rememberChecked(identity *snapshotServerIdentity) {
	s.checkedMu.Lock()
	defer s.checkedMu.Unlock()
	s.checked = identity
}

// coordination returns the daemon-scoped shared state.
func (s *serverState) coordination() *serverShared {
	return s.shared
}

type commandRunner interface {
	Run(context.Context, tmuxcmd.Request) (tmuxcmd.Result, error)
}

// SocketPath returns the absolute socket path selected when the server was
// constructed. An invalid server returns an empty string.
func (s Server) SocketPath() string {
	if s.state == nil {
		return ""
	}
	return s.state.config.socketSelection.Path
}

// ConfigFile returns the configured tmux configuration path.
func (s Server) ConfigFile() string {
	if s.state == nil {
		return ""
	}
	return s.state.config.configFile
}

// ProcessEnvironment returns the normalized environment explicitly supplied
// through [ServerOptions]. Nil means the server inherited a private process
// snapshot. The returned slice is owned by the caller; an invalid server
// returns nil.
func (s Server) ProcessEnvironment() []string {
	if s.state == nil {
		return nil
	}
	return slices.Clone(s.state.config.configuredProcessEnvironment)
}

// Executable returns the absolute tmux executable path resolved when the
// server was constructed. An invalid server returns an empty string.
func (s Server) Executable() string {
	if s.state == nil {
		return ""
	}
	return s.state.config.executable
}

// Cmd executes raw tmux arguments and returns caller-owned result slices. A
// completed nonzero exit remains a result; validation and transport failures
// return errors. Cancellation cannot prove whether a mutation reached tmux.
//
// An argument that is exactly ";" separates two tmux commands, so one call can
// submit a command list. tmux runs a list until a command fails and drops the
// rest, and answers with one merged stdout, so a caller that needs to know
// which command produced which line submits them separately. A list means the
// same thing through either execution binding.
//
// Standalone -V and -h diagnose the configured executable without daemon version
// checks. They do not qualify a later daemon operation.
//
// Only a standalone ";" separates commands. Other semicolons follow the selected
// binding's parsing; typed operations keep values literal across bindings.
//
// On a [Connection]-bound server Cmd uses a lane, and tmux cannot cancel a
// command already sent, so a command that waits on something outside tmux,
// such as wait-for or a foreground run-shell, holds that lane until it
// finishes even after ctx ends. [Server.WaitFor], [Server.RunShell], and
// [Server.IfShell] take a client of their own instead.
func (s Server) Cmd(ctx context.Context, args ...string) (CommandResult, error) {
	if len(args) == 1 && (args[0] == "-V" || args[0] == "-h") {
		result, err := s.runExactArgv(ctx, args)
		return cloneCommandResult(CommandResult{
			Command: result.Command, Stdout: result.Stdout, RawStdout: result.RawStdout,
			Stderr: result.Stderr, ExitCode: result.ExitCode,
		}), err
	}
	result, _, err := s.dispatch(ctx, true, args...)
	return result, err
}

func (s Server) literalCmd(ctx context.Context, args ...string) (CommandResult, error) {
	result, _, err := s.literalCmdWithRaw(ctx, args...)
	return result, err
}

// literalCmdAs is literalCmd for a command whose kind the caller knows, which
// is how one that can hold its client keeps off a connection's shared lanes.
func (s Server) literalCmdAs(
	ctx context.Context,
	kind commandKind,
	args ...string,
) (CommandResult, error) {
	if err := validateLiteralCommandArguments(args); err != nil {
		return CommandResult{ExitCode: -1}, err
	}
	result, _, err := s.dispatchAs(ctx, kind, false, args...)
	return result, err
}

func (s Server) literalCmdWithRaw(
	ctx context.Context,
	args ...string,
) (CommandResult, []byte, error) {
	if err := validateLiteralCommandArguments(args); err != nil {
		return CommandResult{ExitCode: -1}, nil, err
	}
	return s.dispatch(ctx, false, args...)
}

// dispatch runs one tmux command. commandList reports whether a bare ";" in
// args separates two commands, which decides how each transport renders it.
func (s Server) dispatch(
	ctx context.Context,
	commandList bool,
	args ...string,
) (CommandResult, []byte, error) {
	return s.dispatchAs(ctx, commandServer, commandList, args...)
}

func (s Server) dispatchAs(
	ctx context.Context,
	kind commandKind,
	commandList bool,
	args ...string,
) (CommandResult, []byte, error) {
	result, err := s.runCommand(ctx, kind, args, nil, commandList)
	commandResult := cloneCommandResult(CommandResult{
		Command:   result.Command,
		Stdout:    result.Stdout,
		RawStdout: result.RawStdout,
		Stderr:    result.Stderr,
		ExitCode:  result.ExitCode,
	})
	if err != nil {
		return commandResult, bytes.Clone(result.RawStdout), commandTransportFailure(err)
	}
	return commandResult, bytes.Clone(result.RawStdout), nil
}

// IsAlive reports whether a tmux server answers on the configured socket.
// Only an absent server reports false without an error: a socket that exists
// but cannot be reached, such as one the process may not read, is a question
// that could not be answered and is returned as an error. Use
// [Server.CheckAlive] where an absent server is itself the failure.
func (s Server) IsAlive(ctx context.Context) (bool, error) {
	result, err := s.literalCmd(ctx, "list-sessions")
	if err != nil {
		return false, err
	}
	if result.ExitCode == 0 {
		return true, nil
	}
	commandErr := newCommandError("list-sessions", result)
	if errors.Is(commandErr, ErrNoServer) {
		return false, nil
	}
	return false, commandErr
}

// CheckAlive returns a [CommandError] when the configured server is not
// alive. Cancellation and transport failures are returned directly. Use
// [Server.IsAlive] where an absent server is an answer rather than a
// failure.
func (s Server) CheckAlive(ctx context.Context) error {
	result, err := s.literalCmd(ctx, "list-sessions")
	if err != nil {
		return err
	}
	if result.ExitCode != 0 {
		return newCommandError("list-sessions", result)
	}
	return nil
}

func (s Server) connectionState() *serverState {
	return s.state
}

func (s Server) stateForUse() (*serverState, error) {
	if s.state == nil || s.state.executor == nil || s.state.shared == nil ||
		s.state.config.executable == "" || s.state.config.directory == "" {
		return nil, ErrInvalidServer
	}
	return s.state, nil
}

func (s Server) commandArguments(args []string) []string {
	if s.state == nil {
		return slices.Clone(args)
	}
	config := s.state.config
	selectorFlag, selectorValue := effectiveSocketSelectorValues(
		config.socketPath,
		config.socketName,
	)
	globalCount := 1
	if config.colors != ColorDefault {
		globalCount++
	}
	if config.configFile != "" {
		globalCount++
	}
	if selectorValue != "" {
		globalCount++
	}

	command := make([]string, 0, globalCount+len(args))
	// tmux replaces every non-ASCII byte in a format it expands for a command
	// or control client whose locale does not name UTF-8, so a session named
	// café reads back as caf_ with no error. Captured bytes go out whole
	// either way; formats are what this is for. Go strings are UTF-8 and the environment
	// this package runs under is not its to choose, so it asks for UTF-8
	// rather than inheriting whatever the locale says.
	if !s.inheritsLocale {
		command = append(command, "-u")
	}
	if config.colors == Color256 {
		command = append(command, "-2")
	}
	// Global arguments are consumed before tmux's command-list parser. Their
	// values are already literal; a separator escape would become part of the
	// configured path or socket name.
	if config.configFile != "" {
		command = append(command, "-f"+config.configFile)
	}
	if selectorValue != "" {
		command = append(command, selectorFlag+selectorValue)
	}
	return append(command, args...)
}

func validateConnectionArguments(options ServerOptions) error {
	if options.ConfigFile != "" {
		if err := validateServerCommandArgument(
			"tmux", "ConfigFile", options.ConfigFile, true,
		); err != nil {
			return err
		}
	}
	selectorFlag, selectorValue := effectiveSocketSelector(options)
	if selectorValue == "" {
		return nil
	}
	field := "SocketName"
	if selectorFlag == "-S" {
		field = "SocketPath"
	}
	return validateServerCommandArgument("tmux", field, selectorValue, true)
}

func effectiveSocketSelector(options ServerOptions) (flag string, value string) {
	return effectiveSocketSelectorValues(options.SocketPath, options.SocketName)
}

func effectiveSocketSelectorValues(socketPath, socketName string) (flag string, value string) {
	if socketPath != "" {
		return "-S", socketPath
	}
	if socketName != "" {
		return "-L", socketName
	}
	return "", ""
}

func validateColorMode(mode ColorMode) error {
	switch mode {
	case ColorDefault, Color256:
		return nil
	default:
		return &ColorError{Mode: mode}
	}
}

tmux/session_lifecycle.go.content:
package tmux

import (
	"context"
	"errors"
	"fmt"
	"maps"
	"slices"
	"strconv"
	"strings"
	"unicode/utf8"
)

// ErrSessionExists identifies a named session that was not replaced.
var ErrSessionExists = errors.New("tmux: session already exists")

// HasSessionRequest selects exact or tmux-pattern session matching on every
// supported tmux. Its zero value is invalid because Target is required.
type HasSessionRequest struct {
	// Target is the required session name or tmux session pattern.
	Target string
	// Pattern lets tmux interpret Target as a pattern; false requires an exact
	// session name.
	Pattern bool
}

// NewSessionRequest configures session creation. [Server.NewSession] creates a
// detached session; [Server.NewSessionConnection] creates one attached to its
// first control-mode lane. Its zero value uses tmux defaults. Width and Height
// are either zero or 1 through 65535; KillExisting requires Name. KillExisting
// may remove a session before a later creation failure.
//
// [Server.NewSession] copies Environment before validation and retains no map
// storage; concurrent mutation during the copy is unsafe. Foreground-only tmux
// flags are not exposed.
type NewSessionRequest struct {
	// Name selects the new session name; empty lets tmux generate one.
	Name string
	// KillExisting removes an existing session named Name before creation.
	KillExisting bool
	// StartDirectory expands ~ and ~/... for the current user. Named-user
	// forms such as ~other are rejected; empty inherits tmux's default.
	// A directory that does not exist is not an error: tmux starts the
	// process in the home directory instead, or in / without one.
	StartDirectory string
	// WindowName names the initial window; empty lets tmux choose.
	WindowName string
	// Width sets the detached session width; zero lets tmux choose.
	Width int
	// Height sets the detached session height; zero lets tmux choose.
	Height int
	// Environment is emitted in lexically sorted key order. The map is not
	// retained; nil and an empty map both add no entries.
	Environment map[string]string
	// Command starts the initial pane with this shell command; empty uses tmux's
	// default command.
	Command string
}

// newSessionArguments renders one new-session argument vector. It performs no
// tmux I/O, so a [Plan] can render a session it has not created. The existence
// probe KillExisting needs is the caller's, not this.
func newSessionArguments(request NewSessionRequest) ([]string, error) {
	return renderNewSessionArguments(request, "#{session_id}", true, "")
}

func renderNewSessionArguments(
	request NewSessionRequest,
	format string,
	detached bool,
	clientFlags string,
) ([]string, error) {
	if request.Width < 0 || request.Width > 65535 {
		return nil, invalidLifecycleRequest("Width must be between 1 and 65535")
	}
	if request.Height < 0 || request.Height > 65535 {
		return nil, invalidLifecycleRequest("Height must be between 1 and 65535")
	}
	if request.Name != "" {
		if err := validateLifecycleSessionName("name", request.Name); err != nil {
			return nil, err
		}
	}
	environment, err := lifecycleEnvironmentArguments(request.Environment)
	if err != nil {
		return nil, err
	}
	startDirectory, err := expandLifecycleDirectory(request.StartDirectory)
	if err != nil {
		return nil, err
	}

	arguments := []string{"new-session", "-P", "-F" + format}
	if clientFlags != "" {
		arguments = append(arguments, "-f"+clientFlags)
	}
	if request.Name != "" {
		arguments = append(arguments, "-s"+request.Name)
	}
	if detached {
		arguments = append(arguments, "-d")
	}
	if startDirectory != "" {
		arguments = append(arguments, "-c", startDirectory)
	}
	if request.WindowName != "" {
		arguments = append(arguments, "-n", request.WindowName)
	}
	if request.Width != 0 {
		arguments = append(arguments, "-x", strconv.Itoa(request.Width))
	}
	if request.Height != 0 {
		arguments = append(arguments, "-y", strconv.Itoa(request.Height))
	}
	arguments = append(arguments, environment...)
	if request.Command != "" {
		arguments = append(arguments, "--", request.Command)
	}
	return arguments, nil
}

// HasSession reports whether Target selects a session. With Pattern false it
// compares session names exactly; with Pattern true, tmux may resolve IDs,
// client TTYs, unique prefixes, or globs. Pattern-mode completed nonzero exits
// are misses. Exact-name lookup treats [ErrNoServer] as a miss and returns
// other failures.
//
// Exact-name lookup lists sessions because tmux's exact-match marker still
// resolves identifiers and client TTYs.
func (s Server) HasSession(ctx context.Context, request HasSessionRequest) (bool, error) {
	if err := validateServerCommandArgument(
		"has-session", "Target", request.Target, true,
	); err != nil {
		return false, err
	}
	if err := validateLifecycleSessionName("target", request.Target); err != nil {
		return false, err
	}
	if !request.Pattern {
		identifier, err := s.sessionNamed(ctx, request.Target)
		return identifier != "", err
	}
	result, err := s.literalCmd(ctx, "has-session", "-t", request.Target)
	if err != nil {
		return false, err
	}
	return result.ExitCode == 0, nil
}

// sessionNamed returns the identifier of the session carrying exactly this
// name, or an empty identifier when no session does. A server that is not
// running holds no session by any name, which is a miss rather than a failure.
//
// The identifier leads the format so that the split point is unambiguous: a
// name may hold a space, and every identifier is one token.
func (s Server) sessionNamed(ctx context.Context, name string) (SessionID, error) {
	rows, err := s.literalCmd(ctx, "list-sessions", "-F", "#{session_id} #{session_name}")
	if err != nil {
		return "", err
	}
	if rows.ExitCode != 0 {
		commandErr := newCommandError("list-sessions", rows)
		if errors.Is(commandErr, ErrNoServer) {
			return "", nil
		}
		return "", commandErr
	}
	for _, row := range rows.Stdout {
		identifier, found, ok := strings.Cut(row, " ")
		if ok && found == name {
			return SessionID(identifier), nil
		}
	}
	return "", nil
}

// NewSession creates a detached session, then returns a newly materialized
// [Session]. It never changes client focus. KillExisting is not rolled back;
// transport and context failures may be delivery-ambiguous.
//
// The returned record has unmaterialized [Session.Windows] and [Session.Panes]
// relations. Use the resolvers or [Server.Snapshot] when relations are needed.
//
// If tmux reports an ID before a transport or refresh failure, the returned
// partial Session contains its [Server] and [SessionID]. Other failures return zero.
func (s Server) NewSession(ctx context.Context, request NewSessionRequest) (Session, error) {
	request = captureNewSessionRequest(request)
	if err := validateServerCommandArguments(
		"new-session",
		serverCommandArgument{field: "Name", value: request.Name},
		serverCommandArgument{field: "StartDirectory", value: request.StartDirectory},
		serverCommandArgument{field: "WindowName", value: request.WindowName},
		serverCommandArgument{field: "Command", value: request.Command},
	); err != nil {
		return Session{}, err
	}
	if request.KillExisting && request.Name == "" {
		return Session{}, invalidLifecycleRequest("KillExisting requires Name")
	}
	if request.Width < 0 || request.Width > 65535 {
		return Session{}, invalidLifecycleRequest("Width must be between 1 and 65535")
	}
	if request.Height < 0 || request.Height > 65535 {
		return Session{}, invalidLifecycleRequest("Height must be between 1 and 65535")
	}
	effective, err := newSessionCommandServer(s)
	if err != nil {
		return Session{}, err
	}
	if request.Name != "" {
		if err := validateLifecycleSessionName("name", request.Name); err != nil {
			return Session{}, err
		}
		// The session is killed by identifier rather than by the name that
		// found it, because tmux would resolve that name again through its own
		// ladder and can land on a different session.
		existing, err := effective.sessionNamed(ctx, request.Name)
		if err != nil {
			return Session{}, err
		}
		if existing != "" && !request.KillExisting {
			return Session{}, fmt.Errorf("%w: %q", ErrSessionExists, request.Name)
		}
		if existing != "" {
			result, err := effective.literalCmd(ctx, "kill-session", "-t", existing.String())
			if _, err = requireRedactedLifecycleSuccess("kill-session", result, err); err != nil {
				return Session{}, err
			}
		}
	}

	arguments, err := newSessionArguments(request)
	if err != nil {
		return Session{}, err
	}
	result, err := effective.literalCmd(ctx, arguments...)
	if err != nil {
		if identity, identityErr := lifecycleStableIdentity("session", result.Stdout); identityErr == nil {
			return Session{server: effective, sessionID: SessionID(identity)}, err
		}
		return Session{}, err
	}
	result, err = requireRedactedLifecycleSuccess("new-session", result, nil)
	if err != nil {
		return Session{}, err
	}
	identity, err := lifecycleStableIdentity("session", result.Stdout)
	if err != nil {
		return Session{}, err
	}
	session, err := effective.Session(ctx, SessionID(identity))
	if err != nil {
		return Session{server: effective, sessionID: SessionID(identity)}, err
	}
	return session, nil
}

// Rename changes the receiver session's name and returns a canonical freshly
// materialized [Session]. If the command succeeds but refresh fails, it
// returns the receiver with that error. A transport or context error can be
// delivery-ambiguous; no rollback is attempted. Invalid names are rejected
// before execution and match [ErrInvalidRequest].
func (s Session) Rename(ctx context.Context, name string) (Session, error) {
	if err := validateServerCommandArguments(
		"rename-session",
		serverCommandArgument{field: "Target", value: s.sessionID.String()},
		serverCommandArgument{field: "Name", value: name},
	); err != nil {
		return Session{}, err
	}
	if err := validateLifecycleSessionName("name", name); err != nil {
		return Session{}, err
	}
	result, err := s.literalCmd(ctx, "rename-session", "--", name)
	if _, err = requireLifecycleSuccess("rename-session", result, err); err != nil {
		return Session{}, err
	}
	refreshed, err := s.Refresh(ctx)
	if err != nil {
		return s, err
	}
	return refreshed, nil
}

func validateLifecycleSessionName(field, name string) error {
	if name == "" {
		return invalidLifecycleRequest(field + " must not be empty")
	}
	if strings.ContainsAny(name, ".:") {
		return invalidLifecycleRequest(field + " must not contain periods or colons")
	}
	// A control byte is refused for the same reason a delimiter is: to make one
	// name mean one thing on every supported release. tmux rejects these from
	// 3.7; before that it accepts them and stores the name visibility-encoded,
	// so a bell arrives as a backslash and an "a" and the session ends up under
	// a name nobody asked for.
	if !utf8.ValidString(name) {
		return invalidLifecycleRequest(field + " must be valid UTF-8")
	}
	for _, character := range name {
		if character < 0x20 || character == 0x7f {
			return invalidLifecycleRequest(
				field + " must not contain control characters")
		}
	}
	return nil
}

// ValidateSessionName reports whether name can be used as a tmux session
// name. Empty names, the target delimiters '.' and ':', control characters and
// invalid UTF-8 are rejected.
func ValidateSessionName(name string) error {
	return validateLifecycleSessionName("name", name)
}

func captureNewSessionRequest(request NewSessionRequest) NewSessionRequest {
	request.Environment = maps.Clone(request.Environment)
	return request
}

func newSessionCommandServer(server Server) (Server, error) {
	state, err := server.stateForUse()
	if err != nil {
		return Server{}, err
	}
	config := state.config
	if config.socketPath == "" && config.socketName == "" {
		if _, selectedByEnvironment := tmuxEnvironmentSocketPath(config); selectedByEnvironment {
			config.socketPath = config.socketSelection.Path
		}
	}
	environment := slices.Clone(config.processEnvironment)
	filtered := make([]string, 0, len(environment))
	for _, entry := range environment {
		name, _, _ := strings.Cut(entry, "=")
		if processEnvironmentKey(name) != processEnvironmentKey("TMUX") {
			filtered = append(filtered, entry)
		}
	}
	config.processEnvironment = filtered
	configured := slices.Clone(config.configuredProcessEnvironment)
	configured = slices.DeleteFunc(configured, func(entry string) bool {
		name, _, _ := strings.Cut(entry, "=")
		return processEnvironmentKey(name) == processEnvironmentKey("TMUX")
	})
	config.configuredProcessEnvironment = configured
	return Server{
		state: &serverState{
			config:   config,
			executor: state.executor,
			// Different options, the same tmux: the version it reports and the
			// pools open on it are properties of the server, not of whether
			// TMUX was removed from the environment reaching it.
			shared: state.shared,
		},
		connection:      server.connection,
		daemon:          server.daemon,
		requiresProcess: server.requiresProcess,
	}, nil
}

tmux/session_navigation.go.content:
package tmux

import (
	"context"
	"strconv"
)

// SelectWindowRequest selects one winlink in a [Session] on tmux 3.3a or
// later. Its zero value is invalid: exactly one of WindowID and Index is
// required. That mutual exclusion, stable-ID syntax, and a nonnegative Index
// are validated before execution. Index is read during the call and is not
// retained; nil omits it, a nonnil pointer is explicit, and callers must not
// mutate it concurrently.
type SelectWindowRequest struct {
	// WindowID selects a stable window linked into the receiver session.
	WindowID WindowID
	// Index selects a nonnegative winlink index in the receiver session.
	Index *int
}

// LastWindow makes the receiver session's previously selected winlink current
// and returns that freshly materialized session-specific [Window]. The
// selection is session-scoped; it does not promise focus for clients attached
// to other sessions. A transport or context error can be delivery-ambiguous
// and no rollback is attempted. Command or refresh failure returns a zero
// Window because this navigation operation cannot identify the selected view
// reliably without refresh.
func (s Session) LastWindow(ctx context.Context) (Window, error) {
	return s.navigateWindow(ctx, "last-window", s.sessionID.String())
}

// NextWindow makes the next winlink current in the receiver session and
// returns that freshly materialized session-specific [Window]. The selection
// is session-scoped; it does not promise focus for clients attached to other
// sessions. A transport or context error can be delivery-ambiguous and no
// rollback is attempted. Command or refresh failure returns a zero Window.
func (s Session) NextWindow(ctx context.Context) (Window, error) {
	return s.navigateWindow(ctx, "next-window", s.sessionID.String())
}

// PreviousWindow makes the previous winlink current in the receiver session
// and returns that freshly materialized session-specific [Window]. The
// selection is session-scoped; it does not promise focus for clients attached
// to other sessions. A transport or context error can be delivery-ambiguous
// and no rollback is attempted. Command or refresh failure returns a zero
// Window.
func (s Session) PreviousWindow(ctx context.Context) (Window, error) {
	return s.navigateWindow(ctx, "previous-window", s.sessionID.String())
}

// SelectWindow makes one winlink current in the receiver session and returns
// that freshly materialized session-specific [Window]. WindowID is combined
// with the receiver SessionID, because a WindowID alone does not distinguish
// linked views. The selection is session-scoped; it does not promise focus for
// clients attached to other sessions.
//
// Command or refresh failures return zero because the selected view cannot be
// identified without refresh. Transport errors are delivery-ambiguous.
func (s Session) SelectWindow(
	ctx context.Context,
	request SelectWindowRequest,
) (Window, error) {
	if err := validateTypedTarget(
		"select-window", "SessionID", "session", s.sessionID.String(),
	); err != nil {
		return Window{}, err
	}
	hasWindowID := request.WindowID != ""
	hasIndex := request.Index != nil
	if hasWindowID == hasIndex {
		return Window{}, invalidServerCommandRequest(
			"select-window",
			"Target",
			"",
			"requires exactly one of WindowID or Index",
		)
	}

	var selector string
	if hasWindowID {
		if err := validateTypedTarget(
			"select-window", "WindowID", "window", request.WindowID.String(),
		); err != nil {
			return Window{}, err
		}
		selector = request.WindowID.String()
	} else {
		if *request.Index < 0 {
			return Window{}, invalidServerCommandRequest(
				"select-window",
				"Index",
				strconv.Itoa(*request.Index),
				"must be nonnegative",
			)
		}
		selector = strconv.Itoa(*request.Index)
	}

	return s.navigateWindow(
		ctx,
		"select-window",
		s.sessionID.String()+":"+selector,
	)
}

func (s Session) navigateWindow(
	ctx context.Context,
	subcommand string,
	target string,
) (Window, error) {
	if err := validateTypedTarget(
		subcommand, "SessionID", "session", s.sessionID.String(),
	); err != nil {
		return Window{}, err
	}
	result, err := s.server.literalCmd(ctx, subcommand, "-t", target)
	if err := requireServerCommandNoStderr(subcommand, result, err); err != nil {
		return Window{}, err
	}

	refreshed, err := s.Refresh(ctx)
	if err != nil {
		return Window{}, err
	}
	return windowProjectedBySession(refreshed)
}

func windowProjectedBySession(session Session) (Window, error) {
	windowID, _ := session.Formats().WindowID()
	// One window projected out of a session's own row: only windows are listed,
	// so a relation reached from the result is unknown rather than empty.
	snapshot, err := newSnapshotWithIdentity(
		session.server,
		session.formats.tmuxVersion(),
		snapshotRecords{windows: []formatValues{session.formats}},
		listedWindows,
		nil,
	)
	if err != nil {
		return Window{}, err
	}
	return snapshot.WindowByID(windowID)
}

tmux/session_run.go.content:
package tmux

import (
	"context"
	"crypto/rand"
	"errors"
	"fmt"
	"io"
	"os"
	"slices"
	"strings"
	"sync"
	"sync/atomic"
	"time"
)

// RunOptions configures [Session.Run] and [Session.Start]. Its zero value
// runs the command in a window tmux names, in the session's default directory
// and environment, and removes that window once the command has finished.
type RunOptions struct {
	// WindowName names the window the command runs in; empty lets tmux choose.
	WindowName string
	// StartDirectory expands ~ and ~/... for the current user; empty inherits
	// the session's default.
	// A directory that does not exist is not an error: tmux starts the
	// process in the home directory instead, or in / without one.
	StartDirectory string
	// Environment is added to the command's environment. The map is not
	// retained.
	Environment map[string]string
	// Keep leaves the finished window in place, showing what the command
	// printed, instead of removing it.
	Keep bool
}

// ErrOutcomeUnrecorded reports that a command's pane is dead while tmux has
// not recorded how the command ended, which it does by reaping the command's
// process. tmux is known to leave a pane in that state indefinitely, so this
// is reported rather than waited out, and rather than passed off as a zero
// exit status that would call a failed command successful.
var ErrOutcomeUnrecorded = errors.New("tmux: command outcome was never recorded")

// RunResult reports how a command finished and what its terminal showed.
type RunResult struct {
	// Status is the command's exit status, or -1 when the command did not
	// exit on its own, as when a signal ended it, so zero always means it
	// succeeded. os.ProcessState.ExitCode reads the same way.
	Status int
	// Signal is the signal that ended the command, when one did, and nil
	// otherwise. Compare it with os.Kill or a syscall constant: tmux reports
	// a number on Linux and a name on macOS and the BSDs, and Signal holds
	// the same value on each.
	Signal os.Signal
	// Lines is what the terminal showed when the command finished, its
	// history included, without the blank lines tmux pads a screen with. A
	// line the window's width wrapped is joined back into one, and each line
	// ends at its last character that is not a space: a screen cannot tell
	// spaces a program wrote from the blank cells after them. tmux keeps at
	// most the session's history-limit lines above the screen, 2000 by
	// default, so the start of a longer output is gone.
	Lines []string
	// Pane is the pane the command ran in. It is live only when the run kept
	// its window.
	Pane PaneID
}

// clone returns result with an independently owned Lines, so a cached result
// handed to more than one caller cannot be corrupted by one of them.
func (result RunResult) clone() RunResult {
	result.Lines = slices.Clone(result.Lines)
	return result
}

// deadSignal turns tmux's pane_dead_signal into the signal it reports. A
// name this platform has no number for keeps tmux's spelling.
func deadSignal(reported string) os.Signal {
	if reported == "" {
		return nil
	}
	if signal, ok := platformSignal(reported); ok {
		return signal
	}
	return reportedSignal(reported)
}

// reportedSignal is a signal tmux named that this platform has no number for.
type reportedSignal string

func (s reportedSignal) String() string { return string(s) }

// Signal makes reportedSignal an [os.Signal].
func (reportedSignal) Signal() {}

// Run starts command in a new window of this session, waits for it to finish,
// and reports its exit status and what its terminal showed. It is [os/exec]
// for a program that needs a terminal: the command runs with a tty, so it
// sees isatty, colour, and a width, and what comes back is the screen tmux
// rendered rather than the bytes the program wrote. That screen holds a
// bounded history; see [RunResult.Lines]. For a large output, have the
// command write it to a file, or follow it with [Running.StreamTo].
//
// tmux runs command as default-shell -c command, so it is written in the
// language of the session's default-shell option, which tmux takes from
// $SHELL when it starts the server: under fish, echo $((1+2)) is an error.
// For one language on every machine, set default-shell, or write the
// command as sh -c '...'.
//
// A nonzero status is a result, not an error; the error reports what tmux
// could not do. The wait is tmux's own signal, backed by a liveness check that
// widens from a quarter second in case that signal is lost: it needs no tmux
// binary on the command's PATH and returns as the process exits. A command that never
// exits holds Run until ctx ends. On error, Run removes its window regardless
// of [RunOptions.Keep], since Run gives the caller no other chance to retry or
// clean up; a bare [Session.Start] followed by [Running.Wait] leaves that
// choice to the caller instead. [Server.RunShell] runs a command with no pane
// at all.
//
// On a session bound to a [Connection], Run works as it does elsewhere: the
// wait uses a control client of its own rather than a lane, so one lane is
// enough, and the final screen is read through a scratch tmux buffer and a
// temporary file that tmux writes and this process reads.
func (s Session) Run(ctx context.Context, command string, options RunOptions) (RunResult, error) {
	running, err := s.Start(ctx, command, options)
	if err != nil {
		return RunResult{}, err
	}
	result, err := running.Wait(ctx)
	if err != nil {
		cleanupCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 2*time.Second)
		defer cancel()
		_ = running.window.Kill(cleanupCtx)
	}
	return result, err
}

// Start runs command in a new window of this session and returns once it is
// under way, without waiting for it to finish. The returned [Running] reports
// the pane it runs in and blocks on demand: [Running.Wait] waits for the exit
// status and screen [Session.Run] would have returned, and [Running.Kill]
// stops the command. Options are exactly Run's.
//
// Before tmux 3.7, Start attempts to install an output pipe running cat
// unless the pane already has a pipe; a failed attempt only forfeits that
// compatibility help. [Running.Wait] stops a pipe Start installed once the
// outcome is read, whether or not Keep leaves the window itself in place.
//
// If Wait is never called, the window Start created is never removed.
//
// A session bound to a [Connection] can Start: [Running.Wait] holds a control
// client of its own, not a lane, so [Running.Kill] and every other command stay
// available while it waits.
func (s Session) Start(
	ctx context.Context,
	command string,
	options RunOptions,
) (running *Running, err error) {
	if command == "" {
		return nil, invalidServerCommandRequest("respawn-pane", "Command", "", "is required")
	}
	// The command's own exit would destroy the window before remain-on-exit
	// could be set on it, so the window starts with cat, which holds its
	// terminal until it is replaced once the pane is armed.
	request := NewWindowRequest{Command: "cat"}
	if options.WindowName != "" {
		request.Name = &options.WindowName
	}
	window, err := s.NewWindow(ctx, request)
	if err != nil {
		return nil, fmt.Errorf("start window: %w", err)
	}
	defer func() {
		if err == nil {
			return
		}
		cleanupCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 2*time.Second)
		defer cancel()
		_ = window.Kill(cleanupCtx)
	}()
	pane, err := window.ResolveActivePane(ctx)
	if err != nil {
		return nil, err
	}
	if err := pane.SetRemainOnExit(ctx, RemainOnExitOn); err != nil {
		return nil, err
	}
	// An empty notice keeps tmux's status text out of captured command output.
	if err := pane.SetRemainOnExitFormat(ctx, ""); err != nil {
		return nil, err
	}
	version, err := s.server.Version(ctx)
	if err != nil {
		return nil, err
	}
	// Before 3.7, tmux drains pending terminal bytes on exit only when a
	// pipe is open. Failing to install one only forfeits that compatibility
	// help, so it is tolerated rather than failing Start; installedPipe
	// records the attempt's own result so finish stops only the pipe it
	// opened, never one a caller's own hook installed.
	var installedPipe bool
	if piping, _ := pane.Piping(); !piping && !version.AtLeast(captureVersion37) {
		installedPipe = pane.Pipe(ctx, PipePaneRequest{Command: new("exec cat")}) == nil
	}
	// Channels are server-global, and tmux keeps a signal nobody is waiting
	// for until the next waiter takes it, so each run owns a fresh name.
	channel := "libtmux-go-run-" + rand.Text()
	if err := pane.SetHook(ctx, "pane-died", "wait-for -S "+channel); err != nil {
		return nil, err
	}
	respawn := RespawnRequest{Command: &command, Kill: true, Environment: options.Environment}
	if options.StartDirectory != "" {
		respawn.StartDirectory = &options.StartDirectory
	}
	respawned, err := pane.Respawn(ctx, respawn)
	if err != nil {
		return nil, fmt.Errorf("start command: %w", err)
	}
	return &Running{
		session:       s,
		window:        window,
		pane:          respawned,
		channel:       channel,
		keep:          options.Keep,
		installedPipe: installedPipe,
	}, nil
}

// Running is a command started by [Session.Start]: a real process, already
// under way, in a pane of its own. [Running.Pane] exposes that pane so its
// output can be streamed with [Pane.OpenObservation] or typed into with
// [Pane.Writer] while the command runs; [Running.Wait] and [Running.Kill]
// wait for and stop it. A line printed with nothing separating it from the
// command's own exit can race tmux's control-mode notification of it and
// never reach [PaneObservation.Reader]; [RunResult.Lines] from Wait, a plain
// screen capture rather than that notification stream, always has it.
type Running struct {
	session       Session
	window        Window
	pane          Pane
	channel       string
	keep          bool
	installedPipe bool
	// settle answers how long to let tmux catch up before reporting that it
	// never recorded an outcome. Nil uses settleLimit; a test supplies one to
	// drive waitForExit without waiting out a real deadline.
	settle func(context.Context) time.Duration

	// exited records that some Wait saw the command end; finishing reads the
	// outcome once after that, and finished closes when result and err hold it.
	exited    atomic.Bool
	finishing sync.Once
	mu        sync.Mutex
	finished  chan struct{}
	result    RunResult
	err       error
}

// Pane returns the pane the command runs in, materialized immediately after
// Start returned. Like any materialized record it does not refresh itself; a
// call after Wait or Kill may no longer describe a live pane.
func (r *Running) Pane() Pane {
	return r.pane
}

// Wait blocks until the command exits, on tmux's own wait-for signal backed by
// a widening liveness check, and reports its exit status and what its terminal
// showed. It removes the window Start created unless [RunOptions.Keep] was
// set. A command whose process tmux never reaps has no outcome to report, and
// Wait ends with [ErrOutcomeUnrecorded] rather than the zero status that would
// make a failed command look successful.
//
// Wait may be called more than once and concurrently; every call observes the
// same completion. The outcome is read once, as soon as any call sees the
// command end, on a context no caller's cancellation reaches, because from
// then on it belongs to every caller. A call whose context ends first reports
// that context and leaves the window alone; a later call gets the outcome.
//
// On a [Connection]-bound session the wait holds a control client of its own
// rather than a lane, and ending it closes that client. Closing the
// connection ends it with [ErrControlClosed].
func (r *Running) Wait(ctx context.Context) (RunResult, error) {
	finished := r.finishedSignal()
	if !r.exited.Load() {
		if err := r.waitForExit(ctx); err != nil {
			// Another Wait may have claimed the command's end while this one
			// was waiting: exited is stored before that claim's own tmux
			// round trips run, so seeing it true here means this call's
			// failure is that claim's cleanup making the pane look gone,
			// not a real outcome of its own. That completion is the answer
			// every caller shares once claimed, however long finishing it
			// takes, so this waits for it rather than reporting the
			// cleanup's side effect as this call's own failure.
			if r.exited.Load() {
				select {
				case <-finished:
					return r.outcome()
				case <-ctx.Done():
					return RunResult{}, fmt.Errorf("wait for command: %w", context.Cause(ctx))
				}
			}
			return RunResult{}, fmt.Errorf("wait for command: %w", err)
		}
	}
	r.finishing.Do(func() {
		r.exited.Store(true)
		go func() {
			finishCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), finishLimit)
			defer cancel()
			result, err := r.finish(finishCtx)
			r.mu.Lock()
			r.result, r.err = result, err
			r.mu.Unlock()
			close(finished)
		}()
	})
	select {
	case <-finished:
		return r.outcome()
	case <-ctx.Done():
		return RunResult{}, fmt.Errorf("wait for command: %w", context.Cause(ctx))
	}
}

// finishLimit bounds reading an ended command's outcome: a handful of tmux
// commands, which only a server that has stopped answering takes this long.
const finishLimit = 10 * time.Second

// finishedSignal returns the channel closed once the outcome is stored.
func (r *Running) finishedSignal() chan struct{} {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.finished == nil {
		r.finished = make(chan struct{})
	}
	return r.finished
}

// outcome returns the stored outcome as a copy the caller owns.
func (r *Running) outcome() (RunResult, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.result.clone(), r.err
}

// livenessDelay bounds how long waitForExit trusts tmux's signal before it
// asks whether the pane is already dead, and how far that interval backs off.
// The first check is soon enough to rescue a short command whose signal was
// missed; the ceiling keeps a long command from being polled.
const (
	initialLivenessDelay = 250 * time.Millisecond
	maximumLivenessDelay = 30 * time.Second
)

// outcomeSettleDelay is how soon a pane found dead is re-read while tmux has
// yet to record how its command ended, and the first of a series that doubles
// from there; outcomeReapDelay is how long the settling may take before the
// server is asked to reap, and outcomeSettleLimit how long the whole wait is
// worth before reporting ErrOutcomeUnrecorded. Both are far past the moment
// tmux normally needs and are none of a healthy command's time.
// outcomeSettleLimit is a floor rather than a ceiling: a caller who gave ctx
// a longer deadline asked to wait that long, and a loaded machine is exactly
// where tmux takes more than five seconds to reap.
const (
	outcomeSettleDelay = 20 * time.Millisecond
	outcomeReapDelay   = 200 * time.Millisecond
	outcomeSettleLimit = 5 * time.Second
	// maximumSettleDelay caps the backoff, so a wait bounded by a long
	// deadline still asks often enough to answer soon after tmux catches up.
	maximumSettleDelay = time.Second
)

// signalHandoverDelay is how long the liveness check waits for tmux's own
// signal once it has found the command's outcome readable. tmux records the
// outcome as it reaps the command and signals afterwards, from the point where
// it has finished with the pane's terminal, so the screen the command printed
// arrives between the two.
const signalHandoverDelay = 500 * time.Millisecond

// waitForExit returns when tmux signals the pane's death, or when the pane is
// found already dead. The signal is edge-triggered and arrives once, so a wait
// that trusted it alone would hang for as long as ctx allowed if it never
// came; the liveness check is the second exit, and it backs off so a command
// that runs for an hour is asked about a handful of times.
func (r *Running) waitForExit(ctx context.Context) error {
	signaled := make(chan error, 1)
	waitCtx, endWait := context.WithCancel(ctx)
	defer endWait()
	go func() {
		signaled <- r.session.server.WaitFor(waitCtx, WaitForRequest{Channel: r.channel})
	}()

	// Read once. Recomputing it each pass would compare a limit shrinking with
	// the deadline against a total growing toward it, and the two would meet
	// at half the time the caller allowed.
	limit := r.settleFor(ctx)
	delay := initialLivenessDelay
	// settleDelay doubles from half a step, so the first settle waits one.
	settleDelay := outcomeSettleDelay / 2
	var settling time.Duration
	var asked bool
	for {
		timer := time.NewTimer(delay)
		select {
		case err := <-signaled:
			timer.Stop()
			return err
		case <-ctx.Done():
			timer.Stop()
			return context.Cause(ctx)
		case <-timer.C:
		}
		pane, err := r.pane.Refresh(ctx)
		if err != nil {
			return err
		}
		if dead, ok := pane.Dead(); ok && dead {
			if outcomeRecorded(pane) {
				return awaitDeathSignal(ctx, signaled)
			}
			if settling >= limit {
				return fmt.Errorf("%w: pane %s is dead and its command unreaped",
					ErrOutcomeUnrecorded, pane.ID())
			}
			if settling >= outcomeReapDelay && !asked {
				asked = true
				r.askForAReap(ctx)
			}
			// tmux closes a pane's terminal before it reaps the command,
			// and reports pane_dead from that closed descriptor alone, so
			// reading the outcome now would call a command that exited 7 a
			// command that exited 0. Wait for tmux to catch up, asking less
			// often the longer it takes: tmux normally needs one or two of
			// these, and a caller who allowed minutes should not spend them
			// listing panes fifty times a second.
			//
			// Settling is timed on its own. The liveness backoff before it
			// grows to half a minute for a long command, and charging that
			// to the first settle would spend the whole allowance on the
			// wait that found the pane dead - the reap nudge below included.
			settleDelay = nextSettleDelay(settleDelay)
			settling += settleDelay
			delay = settleDelay
			continue
		}
		delay = min(delay*2, maximumLivenessDelay)
	}
}

// nextSettleDelay is how long to wait before asking tmux again whether it has
// recorded an outcome. It doubles, so a pane tmux is slow to reap is asked
// about a handful of times rather than fifty times a second, and stops
// doubling at maximumSettleDelay, so a wait bounded by a long deadline still
// answers soon after tmux catches up.
func nextSettleDelay(current time.Duration) time.Duration {
	return min(current*2, maximumSettleDelay)
}

// settleLimit is how long to let tmux catch up before reporting that it never
// recorded an outcome. A caller whose ctx runs longer than the built-in floor
// gets its whole remaining time, because a deadline is the caller saying how
// long the answer is worth. A shorter deadline still ends the wait: ctx.Done
// is selected on alongside this.
func settleLimit(ctx context.Context) time.Duration {
	deadline, ok := ctx.Deadline()
	if !ok {
		return outcomeSettleLimit
	}
	return max(outcomeSettleLimit, time.Until(deadline))
}

// settleFor answers this run's settle limit.
func (r *Running) settleFor(ctx context.Context) time.Duration {
	if r.settle != nil {
		return r.settle(ctx)
	}
	return settleLimit(ctx)
}

// outcomeRecorded reports whether tmux has recorded how the command in pane
// ended. A pane reads as dead as soon as tmux closes its terminal, which it
// does before reaping the command: server_destroy_pane closes the descriptor
// and only then returns early when the status is not ready, and through tmux
// 3.5a pane_dead is that closed descriptor and nothing more. Either field
// being readable is proof the command has been reaped.
func outcomeRecorded(pane Pane) bool {
	if _, ok := pane.DeadStatus(); ok {
		return true
	}
	_, ok := pane.DeadSignal()
	return ok
}

// awaitDeathSignal hands a wait that found the pane finished back to tmux's
// own signal, which says more: tmux sends it once it has finished with the
// pane's terminal, and the last of what the command printed reaches the screen
// on the way there. The liveness check is there to notice a signal that never
// comes, not to answer ahead of one that is on its way, so it gives up only
// after a delay no healthy pane needs.
func awaitDeathSignal(ctx context.Context, signaled <-chan error) error {
	timer := time.NewTimer(signalHandoverDelay)
	defer timer.Stop()
	select {
	case err := <-signaled:
		return err
	case <-ctx.Done():
		return context.Cause(ctx)
	case <-timer.C:
		return nil
	}
}

// askForAReap gives the server one more child to notice, which is what makes
// it collect the one it has already lost.
//
// tmux reads a command's exit status only in the waitpid drain that a SIGCHLD
// sends it through, and a server can miss that signal: a tmux linked against
// libutempter forks a helper to update utmp as a pane's terminal closes and
// raises SIGCHLD at itself afterwards to cover what the helper disturbs, which
// is the shape of the loss seen here -- the command left a zombie child of the
// server, pane_dead_status never appeared, and neither did the pane-died hook.
// The drain is unconditional and takes every child that is ready, so any later
// child death runs it again and collects the stalled one with it. This asks
// for that by the shortest command tmux will run for us, and ignores its own
// outcome: the wait's next read of the pane is the only answer that counts.
func (r *Running) askForAReap(ctx context.Context) {
	_, _ = r.session.server.Cmd(ctx, "run-shell", "-b", "true")
}

// finish reads the command's outcome after tmux has signaled its pane-died
// hook and removes the window unless Keep was set. A Keep'd window that Start
// piped for compatibility keeps that pipe only until here: its job is done
// once the outcome is read, and a caller can hold the window indefinitely.
func (r *Running) finish(ctx context.Context) (result RunResult, err error) {
	defer func() {
		if r.keep {
			// Nothing else ever stops a compatibility pipe on a kept window,
			// so it runs on every path out of this function, not only the one
			// that reads the outcome cleanly.
			if r.installedPipe {
				stopCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 2*time.Second)
				defer cancel()
				_ = r.pane.Pipe(stopCtx, PipePaneRequest{})
			}
			return
		}
		cleanupCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 2*time.Second)
		defer cancel()
		if killErr := r.window.Kill(cleanupCtx); killErr != nil && err == nil {
			err = fmt.Errorf("remove window: %w", killErr)
		}
	}()
	finished, err := r.pane.Refresh(ctx)
	if err != nil {
		return RunResult{}, err
	}
	result.Pane = finished.ID()
	// A signal-killed pane reports pane_dead_signal and no pane_dead_status, so
	// a missing status is the documented Signal case rather than an error.
	result.Status = -1
	if status, ok := finished.DeadStatus(); ok {
		result.Status = status
	}
	reported, _ := finished.DeadSignal()
	result.Signal = deadSignal(reported)
	lines, err := captureFinishedScreen(ctx, finished)
	if err != nil {
		return RunResult{}, fmt.Errorf("read screen: %w", err)
	}
	result.Lines = trimScreen(lines)
	return result, nil
}

// captureFinishedScreen reads pane's screen. A connection cannot print a
// capture safely, so a bound pane stages it through a tmux buffer and a
// scratch file, which tmux writes and this process reads.
func captureFinishedScreen(ctx context.Context, pane Pane) ([]string, error) {
	request := CapturePaneRequest{
		Start: CaptureBoundary, End: CaptureBoundary, JoinWrapped: true,
	}
	if !pane.server.ConnectionBound() {
		return pane.Capture(ctx, request)
	}
	file, err := os.CreateTemp("", "libtmux-go-run-*")
	if err != nil {
		return nil, err
	}
	path := file.Name()
	defer func() { _ = os.Remove(path) }()
	if err := file.Close(); err != nil {
		return nil, err
	}
	return pane.CaptureToFile(ctx, path, request)
}

// StreamTo copies what the command prints into destination as it prints it and
// then reports how it ended, so following a command and collecting its outcome
// are one blocking call rather than a goroutine the caller writes. It returns
// exactly what [Running.Wait] returns and, like Wait, removes the window unless
// [RunOptions.Keep] was set. destination is written only by this call, so it
// needs no synchronization of its own, and [Running.Kill] may be called from
// another goroutine while it runs.
//
// The stream is what tmux pushed, which is not quite everything: output the
// command printed before StreamTo opened its observation may or may not be in
// it, and tmux can drop a line printed with nothing between it and the
// command's exit. [RunResult.Lines] is a screen capture rather than a
// notification stream and remains the authoritative record of what the command
// showed. Streaming needs a control client, which a [Connection]-bound value
// does not have, so it returns [ErrConnectionRequiresProcess] there before
// waiting and leaves the command running; Wait alone does not.
func (r *Running) StreamTo(
	ctx context.Context,
	destination io.Writer,
) (RunResult, error) {
	if destination == nil {
		return RunResult{}, invalidServerCommandRequest(
			"capture-pane", "destination", "", "must not be nil",
		)
	}
	observation, err := r.pane.OpenObservation(ctx)
	if err != nil {
		return RunResult{}, fmt.Errorf("observe command: %w", err)
	}
	defer func() { _ = observation.Close() }()

	streamCtx, stopStreaming := context.WithCancel(ctx)
	defer stopStreaming()
	copied := make(chan error, 1)
	go func() {
		_, copyErr := io.Copy(destination, observation.Reader(streamCtx))
		copied <- copyErr
	}()

	result, waitErr := r.Wait(ctx)
	// The command has ended, so nothing more is coming; ending the read is what
	// lets the copy return at all, because a pane's output stream has no end of
	// its own.
	stopStreaming()
	// A destination that blocks regardless of cancellation must not hold this
	// call: ending the read does not end a stuck Write.
	copyErr := awaitCopy(ctx, copied)
	switch {
	case waitErr != nil:
		return result, waitErr
	case copyErr != nil && !errors.Is(copyErr, context.Canceled) &&
		!errors.Is(copyErr, ErrPaneObservationLost):
		return result, fmt.Errorf("stream command: %w", copyErr)
	default:
		return result, nil
	}
}

// Kill asks the tmux server to send SIGKILL to the process group running the
// command. It does not wait for the process to stop; call Wait to observe the
// resulting status or signal.
//
// Kill runs through [Server.RunShell] with the pane as its target, so tmux
// resolves the process group id itself, at the moment it runs, on whatever
// host the server is on, rather than trusting a process id this program read
// earlier. A pane that no longer exists makes that id resolve empty and Kill
// a no-op; Kill reports only whether tmux could dispatch the request, not
// whether a process still existed to receive it.
func (r *Running) Kill(ctx context.Context) error {
	if _, err := r.session.server.RunShell(ctx, RunShellRequest{
		TargetPane: r.pane.ID(),
		Background: true,
		// Nothing to kill is not a failure. Background never reports this
		// command's exit to the caller, but tmux still posts a nonzero one as
		// a message once the job finishes, so a pane that has gone must leave
		// this exiting zero rather than surfacing kill's own failure.
		Command: "[ -n \"#{pane_pid}\" ] && kill -s KILL -- -#{pane_pid} 2>/dev/null; true",
	}); err != nil {
		return fmt.Errorf("kill command: %w", err)
	}
	return nil
}

// trimScreen drops the blank lines tmux pads a screen to its height with.
func trimScreen(lines []string) []string {
	// Joining wrapped lines keeps the spaces that pad each row out to the
	// window's width, which some tmux versions then leave in place.
	for index, line := range lines {
		lines[index] = strings.TrimRight(line, " ")
	}
	end := len(lines)
	for end > 0 && strings.TrimSpace(lines[end-1]) == "" {
		end--
	}
	return lines[:end]
}

