package tmux

import (
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

// SocketSelection describes the Unix filesystem endpoint selected by a
// [Server]. It does not report whether a server is listening there or whether
// tmux would accept the named-socket directory's ownership and permissions.
type SocketSelection struct {
	// Path is the absolute path selected by the frozen socket options,
	// environment, and working directory.
	Path string
	// NamedDirectory is the directory tmux uses for named and default sockets.
	// It can differ from Path's directory when -S or TMUX selects another path.
	NamedDirectory string
}

// SocketSelection returns tmux's -S, -L, TMUX, and default-socket precedence
// snapshotted by [NewServer]. It does not start tmux or require the selected
// socket to exist.
func (s Server) SocketSelection() (SocketSelection, error) {
	state, err := s.stateForUse()
	if err != nil {
		return SocketSelection{}, err
	}
	return state.config.socketSelection, nil
}

func resolveSocketSelection(config serverConfig) SocketSelection {
	namedDirectory := tmuxNamedSocketDirectory(config)
	return SocketSelection{
		Path:           selectedSocketPath(config, namedDirectory),
		NamedDirectory: namedDirectory,
	}
}

func selectedSocketPath(config serverConfig, namedDirectory string) string {
	path := config.socketPath
	switch {
	case path != "":
	case config.socketName != "":
		path = filepath.Join(namedDirectory, config.socketName)
	default:
		if selected, ok := tmuxEnvironmentSocketPath(config); ok {
			path = selected
		} else {
			path = filepath.Join(namedDirectory, "default")
		}
	}
	return absoluteSocketPath(config.directory, path)
}

func tmuxEnvironmentSocketPath(config serverConfig) (string, bool) {
	value, _ := processEnvironmentValue(config.processEnvironment, "TMUX")
	if value == "" || value[0] == ',' {
		return "", false
	}
	path, _, _ := strings.Cut(value, ",")
	return path, path != ""
}

func freezeNamedSocketEnvironment(config *serverConfig) {
	if config.socketPath != "" {
		return
	}
	if config.socketName == "" {
		if _, selectedByEnvironment := tmuxEnvironmentSocketPath(*config); selectedByEnvironment {
			return
		}
	}
	root := filepath.Dir(config.socketSelection.NamedDirectory)
	config.processEnvironment = setProcessEnvironmentValue(
		config.processEnvironment,
		"TMUX_TMPDIR",
		root,
	)
}

func tmuxNamedSocketDirectory(config serverConfig) string {
	base := ""
	if configured, found := processEnvironmentValue(
		config.processEnvironment,
		"TMUX_TMPDIR",
	); found && configured != "" {
		resolved, err := filepath.EvalSymlinks(
			absoluteSocketPath(config.directory, configured),
		)
		if err == nil {
			base = resolved
		}
	}
	if base == "" {
		base = absoluteSocketPath(config.directory, "/tmp")
		if resolved, err := filepath.EvalSymlinks(base); err == nil {
			base = resolved
		}
	}
	return filepath.Join(base, "tmux-"+strconv.Itoa(os.Getuid()))
}

func absoluteSocketPath(directory, path string) string {
	if filepath.IsAbs(path) {
		return filepath.Clean(path)
	}
	return filepath.Clean(filepath.Join(directory, path))
}

tmux/sparse_array.go.content:
package tmux

import (
	"errors"
	"fmt"
	"iter"
	"slices"
)

var (
	// ErrInvalidSparseIndex identifies a negative or overflowing sparse index.
	ErrInvalidSparseIndex = errors.New("tmux: invalid sparse array index")
	// ErrDuplicateSparseIndex identifies repeated constructor indices.
	ErrDuplicateSparseIndex = errors.New("tmux: duplicate sparse array index")
)

// SparseEntry is one indexed [SparseArray] value.
type SparseEntry[T any] struct {
	// Index is the nonnegative sparse-array index.
	Index int
	// Value is the value stored at Index.
	Value T
}

// SparseArray stores values at sorted, nonnegative indices. Its zero value is
// an empty array. Constructors and functional updates own their entry slices;
// copies of reference-bearing T values remain shallow.
type SparseArray[T any] struct {
	entries []SparseEntry[T]
}

// NewSparseArray builds an array from entries, sorting them by index. It returns
// errors matching [ErrInvalidSparseIndex] or [ErrDuplicateSparseIndex] for
// negative, overflowing, or duplicate indices.
func NewSparseArray[T any](entries ...SparseEntry[T]) (SparseArray[T], error) {
	owned := append(make([]SparseEntry[T], 0, len(entries)), entries...)
	for _, entry := range owned {
		if entry.Index < 0 {
			return SparseArray[T]{}, fmt.Errorf("%w: %d", ErrInvalidSparseIndex, entry.Index)
		}
	}
	slices.SortFunc(owned, func(left, right SparseEntry[T]) int {
		switch {
		case left.Index < right.Index:
			return -1
		case left.Index > right.Index:
			return 1
		default:
			return 0
		}
	})
	for index := 1; index < len(owned); index++ {
		if owned[index-1].Index == owned[index].Index {
			return SparseArray[T]{}, fmt.Errorf(
				"%w: %d",
				ErrDuplicateSparseIndex,
				owned[index].Index,
			)
		}
	}
	return SparseArray[T]{entries: owned}, nil
}

// Get returns the value at index and reports whether it is present. A missing
// index, including a sparse hole, returns the zero value and false.
func (a SparseArray[T]) Get(index int) (T, bool) {
	position, found := a.position(index)
	if !found {
		var zero T
		return zero, false
	}
	return a.entries[position].Value, true
}

// Len returns the number of present entries, not the highest index.
func (a SparseArray[T]) Len() int {
	return len(a.entries)
}

// Indices returns a fresh slice of present indices in ascending order.
func (a SparseArray[T]) Indices() []int {
	indices := make([]int, len(a.entries))
	for index, entry := range a.entries {
		indices[index] = entry.Index
	}
	return indices
}

// Entries returns a fresh shallow copy in ascending index order.
func (a SparseArray[T]) Entries() []SparseEntry[T] {
	return append(make([]SparseEntry[T], 0, len(a.entries)), a.entries...)
}

// Values returns a fresh shallow slice in ascending index order.
func (a SparseArray[T]) Values() []T {
	values := make([]T, len(a.entries))
	for index, entry := range a.entries {
		values[index] = entry.Value
	}
	return values
}

// All returns an iterator over indices and values in ascending index order.
func (a SparseArray[T]) All() iter.Seq2[int, T] {
	return func(yield func(int, T) bool) {
		for _, entry := range a.entries {
			if !yield(entry.Index, entry.Value) {
				return
			}
		}
	}
}

// With returns a copy with value inserted or replaced at index. It leaves the
// receiver unchanged and returns an error matching [ErrInvalidSparseIndex] for
// a negative index.
func (a SparseArray[T]) With(index int, value T) (SparseArray[T], error) {
	if index < 0 {
		return SparseArray[T]{}, fmt.Errorf("%w: %d", ErrInvalidSparseIndex, index)
	}
	position, found := a.position(index)
	entries := a.Entries()
	if found {
		entries[position].Value = value
		return SparseArray[T]{entries: entries}, nil
	}
	entries = append(entries, SparseEntry[T]{})
	copy(entries[position+1:], entries[position:])
	entries[position] = SparseEntry[T]{Index: index, Value: value}
	return SparseArray[T]{entries: entries}, nil
}

// Append returns a copy with value stored after the highest present index. It
// leaves the receiver unchanged and returns an error matching
// [ErrInvalidSparseIndex] when that index overflows.
func (a SparseArray[T]) Append(value T) (SparseArray[T], error) {
	index := 0
	if len(a.entries) != 0 {
		highest := a.entries[len(a.entries)-1].Index
		if highest == int(^uint(0)>>1) {
			return SparseArray[T]{}, fmt.Errorf("%w: append after %d", ErrInvalidSparseIndex, highest)
		}
		index = highest + 1
	}
	return a.With(index, value)
}

func (a SparseArray[T]) position(index int) (int, bool) {
	return slices.BinarySearchFunc(a.entries, index, func(entry SparseEntry[T], target int) int {
		switch {
		case entry.Index < target:
			return -1
		case entry.Index > target:
			return 1
		default:
			return 0
		}
	})
}

tmux/target.go.content:
package tmux

import (
	"errors"
	"fmt"
)

// Target error sentinels classify malformed identities. [TargetError] matches
// ErrInvalidTarget through errors.Is.
var (
	// ErrMissingTarget identifies an operation on a zero-value model identity.
	ErrMissingTarget = errors.New("tmux: object target is required")
	// ErrInvalidTarget identifies a malformed stable tmux identifier. It is
	// matched by errors.Is for TargetError.
	ErrInvalidTarget = errors.New("tmux: invalid object target")
)

// TargetError reports a malformed stable identifier before command execution.
// It matches [ErrInvalidTarget] through errors.Is; callers can recover Object
// and Target with errors.As.
type TargetError struct {
	// Object names the tmux object kind whose target was validated.
	Object string
	// Target is the submitted target text.
	Target string
}

// Error implements error.
func (e *TargetError) Error() string {
	return fmt.Sprintf("%v: %s %q", ErrInvalidTarget, e.Object, e.Target)
}

// Unwrap makes TargetError compatible with ErrInvalidTarget.
func (e *TargetError) Unwrap() error { return ErrInvalidTarget }

// MissingTargetError reports an operation attempted on a zero-value model
// identity. It matches [ErrMissingTarget] through errors.Is; callers can
// recover Object with errors.As.
//
// A relation accessor such as [Session.ActiveWindow] or [Session.Windows]
// returns ok false rather than a value with no id, and a creation call such
// as [Server.NewSession] carries no relations at all - so using a discarded
// or freshly created value's zero-value fields reaches this error on the
// first operation. Resolve live state with a Resolve* method or a fresh
// [Server.Snapshot] instead.
type MissingTargetError struct {
	// Object names the tmux object kind with no id: "session", "window",
	// "pane", or "client".
	Object string
}

// Error implements error.
func (e *MissingTargetError) Error() string {
	message := fmt.Sprintf("%v: %s has no id", ErrMissingTarget, e.Object)
	if resolvers := missingTargetResolvers[e.Object]; resolvers != "" {
		message += "; a relation accessor whose ok was false returns a zero " +
			e.Object + ", and a created value carries no relations: use " + resolvers
	}
	return message
}

// missingTargetResolvers names the live lookups that return each object kind,
// the fix for a zero value reached through a discarded relation result.
var missingTargetResolvers = map[string]string{
	"session": "Window.ResolveSession or Pane.ResolveSession",
	"window":  "Session.ResolveActiveWindow or Pane.ResolveWindow",
	"pane":    "Session.ResolveActivePane or Window.ResolveActivePane",
}

// Unwrap makes MissingTargetError compatible with ErrMissingTarget.
func (e *MissingTargetError) Unwrap() error { return ErrMissingTarget }

func validateTypedTarget(subcommand, field, object, target string) error {
	if err := validateServerCommandArgument(subcommand, field, target, true); err != nil {
		return err
	}
	return validateStableTarget(object, target)
}

func validateStableTarget(object, target string) error {
	if target == "" {
		return &MissingTargetError{Object: object}
	}
	var sigil byte
	switch object {
	case "session":
		sigil = '$'
	case "window":
		sigil = '@'
	case "pane":
		sigil = '%'
	case "client":
		return nil
	default:
		return &TargetError{Object: object, Target: target}
	}
	if len(target) < 2 || target[0] != sigil {
		return &TargetError{Object: object, Target: target}
	}
	for index := 1; index < len(target); index++ {
		if target[index] < '0' || target[index] > '9' {
			return &TargetError{Object: object, Target: target}
		}
	}
	return nil
}

tmux/tmuxtest/control.go.content:
package tmuxtest

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"slices"
	"strconv"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/libtmux/libtmux-go/tmux"
)

const (
	controlStartTimeout = 3 * time.Second
	controlStopGrace    = 250 * time.Millisecond
)

// ControlMode is an attached tmux control client for real-tmux tests. It owns
// one stdout reader and a temporary-file spool, which preserves unread protocol
// output until [ControlMode.Close] releases it. Instances come from
// [NewControlMode]; do not construct them directly or read concurrently.
type ControlMode struct {
	command *exec.Cmd
	stdin   io.WriteCloser
	stdout  *controlOutputSpool
	done    chan struct{}

	server     tmux.Server
	session    tmux.Session
	clientName tmux.ClientName
	waitErr    error
	closeOnce  sync.Once
	closeDone  chan struct{}
	closeErr   error
}

// NewControlMode starts a [ControlMode] attached to session and registers
// cleanup with t. It requires an explicitly configured process environment and
// validates that session belongs to server. The client pins the server's frozen
// effective socket path. Validation or startup failures call [testing.TB.Fatal].
// ctx bounds startup and registration only, not the returned client's lifetime.
func NewControlMode(
	ctx context.Context,
	t testing.TB,
	server tmux.Server,
	session tmux.Session,
) *ControlMode {
	t.Helper()
	ctx, cancel := context.WithTimeout(ctx, controlStartTimeout)
	defer cancel()
	control, err := startControlMode(ctx, server, session)
	if err != nil {
		t.Fatal(harnessFailure("start control client", err))
	}
	t.Cleanup(func() {
		if err := control.Close(); err != nil {
			t.Error(harnessFailure("cleanup control client", err))
		}
	})
	return control
}

// CloseContext starts an idempotent shutdown and waits within ctx. Concurrent
// calls join the same shutdown. If ctx ends after shutdown starts, shutdown
// continues and a later call may wait for completion; an already-ended ctx does
// not start shutdown.
func (c *ControlMode) CloseContext(ctx context.Context) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	c.closeOnce.Do(func() { go c.close() })
	select {
	case <-c.closeDone:
		return c.closeErr
	case <-ctx.Done():
		return ctx.Err()
	}
}

// ClientName returns the tmux-assigned identity captured at registration.
func (c *ControlMode) ClientName() tmux.ClientName {
	return c.clientName
}

// Server returns the validated server handle captured at construction.
func (c *ControlMode) Server() tmux.Server {
	return c.server
}

// Session returns the validated session handle captured at construction.
func (c *ControlMode) Session() tmux.Session {
	return c.session
}

// Read reads control-protocol output within ctx. Exactly one caller may read at
// a time. After the client exits, callers may drain preserved output through
// [io.EOF]; after [ControlMode.Close], a non-empty Read returns [os.ErrClosed].
// It returns ctx errors while waiting for output.
func (c *ControlMode) Read(ctx context.Context, data []byte) (int, error) {
	return c.stdout.ReadContext(ctx, data)
}

// Wait blocks until the control client exits or ctx ends. It does not stop or
// close the client; use [ControlMode.Close] to release it.
func (c *ControlMode) Wait(ctx context.Context) error {
	select {
	case <-c.done:
		return c.waitErr
	case <-ctx.Done():
		return ctx.Err()
	}
}

// Close stops the control client and releases its output spool. It is safe to
// call concurrently and more than once.
func (c *ControlMode) Close() error {
	ctx, cancel := context.WithTimeout(
		context.Background(), cleanupTimeout+2*controlStopGrace,
	)
	defer cancel()
	return c.CloseContext(ctx)
}

func (c *ControlMode) close() {
	defer close(c.closeDone)
	defer func() {
		stdoutErr := c.stdout.Close()
		if errors.Is(stdoutErr, os.ErrClosed) {
			stdoutErr = nil
		}
		c.closeErr = errors.Join(c.closeErr, stdoutErr)
	}()
	stdinErr := c.stdin.Close()
	if errors.Is(stdinErr, os.ErrClosed) {
		stdinErr = nil
	}
	select {
	case <-c.done:
		c.closeErr = stdinErr
		return
	case <-time.After(controlStopGrace):
	}

	killErr := c.command.Process.Kill()
	if errors.Is(killErr, os.ErrProcessDone) {
		killErr = nil
	}
	select {
	case <-c.done:
		c.closeErr = errors.Join(stdinErr, killErr)
	case <-time.After(cleanupTimeout):
		c.closeErr = errors.Join(
			stdinErr, killErr, errors.New("control client did not exit after kill"),
		)
	}
}

func startControlMode(
	ctx context.Context,
	server tmux.Server,
	session tmux.Session,
) (*ControlMode, error) {
	if err := validateControlTarget(server, session); err != nil {
		return nil, err
	}
	prefix, err := controlCommandPrefix(ctx, server)
	if err != nil {
		return nil, err
	}
	environment, err := controlProcessEnvironment(server)
	if err != nil {
		return nil, err
	}
	arguments := append(
		slices.Clone(prefix),
		"-C", "attach-session", "-t", session.ID().String(),
	)
	command := exec.Command(arguments[0], arguments[1:]...)
	command.WaitDelay = controlStopGrace
	command.Env = environment

	stdout, err := newControlOutputSpool()
	if err != nil {
		return nil, err
	}
	command.Stdout = stdout
	stdin, err := command.StdinPipe()
	if err != nil {
		return nil, errors.Join(fmt.Errorf("open stdin: %w", err), stdout.Close())
	}
	var stderr strings.Builder
	command.Stderr = &stderr
	control := &ControlMode{
		command:   command,
		stdin:     stdin,
		stdout:    stdout,
		done:      make(chan struct{}),
		closeDone: make(chan struct{}),
		server:    server,
		session:   session,
	}
	if err := command.Start(); err != nil {
		return nil, errors.Join(
			fmt.Errorf("start process: %w", err),
			stdin.Close(),
			stdout.Close(),
		)
	}
	go func() {
		control.waitErr = command.Wait()
		stdout.finish()
		close(control.done)
	}()

	if err := control.waitForRegistration(ctx, server, stderr.String); err != nil {
		closeErr := control.Close()
		return nil, errors.Join(err, closeErr)
	}
	return control, nil
}

func controlProcessEnvironment(server tmux.Server) ([]string, error) {
	environment := server.ProcessEnvironment()
	if environment == nil {
		return nil, errors.New(
			"control mode requires ServerOptions with explicit ProcessEnvironment",
		)
	}
	return scrubTmuxEnvironment(environment), nil
}

func validateControlTarget(server tmux.Server, session tmux.Session) error {
	if session.ID() == "" {
		return errors.New("session id is empty")
	}
	serverSocketPath := server.SocketPath()
	if serverSocketPath == "" {
		return errors.New("server socket path is empty")
	}
	sessionServer := session.Server()
	sessionSocketPath := sessionServer.SocketPath()
	if sessionSocketPath == "" {
		return errors.New("session server socket path is empty")
	}
	if sessionSocketPath != serverSocketPath || !sessionServer.Equal(server) {
		return fmt.Errorf(
			"session server socket path %q does not match server socket path %q",
			sessionSocketPath,
			serverSocketPath,
		)
	}
	return nil
}

func controlCommandPrefix(ctx context.Context, server tmux.Server) ([]string, error) {
	const suffixLength = 3
	result, err := server.Cmd(ctx, "display-message", "-p", "#{pid}")
	if err != nil {
		return nil, err
	}
	if result.ExitCode != 0 {
		return nil, fmt.Errorf(
			"display-message exited %d: %s",
			result.ExitCode,
			strings.Join(result.Stderr, "\n"),
		)
	}
	if len(result.Command) <= suffixLength {
		return nil, fmt.Errorf("display-message command is incomplete: %#v", result.Command)
	}
	prefix := result.Command[:len(result.Command)-suffixLength]
	if len(prefix) == 0 {
		return nil, errors.New("display-message command has no executable")
	}
	path := server.SocketPath()
	if path == "" {
		return nil, errors.New("server socket path is empty")
	}
	// The daemon already exists, so the control process needs neither the
	// startup configuration file nor the original selector spelling. Preserve
	// color capability flags and pin the absolute endpoint selected at server
	// construction.
	command := []string{prefix[0]}
	for _, argument := range prefix[1:] {
		if argument == "-2" {
			command = append(command, argument)
		}
	}
	return append(command, "-S"+path), nil
}

func (c *ControlMode) waitForRegistration(
	ctx context.Context,
	server tmux.Server,
	stderr func() string,
) error {
	pid := strconv.Itoa(c.command.Process.Pid)
	ticker := time.NewTicker(10 * time.Millisecond)
	defer ticker.Stop()
	for {
		result, err := server.Cmd(ctx, "list-clients", "-F", "#{client_pid}\t#{client_name}")
		if err != nil {
			return err
		}
		if result.ExitCode == 0 {
			for _, line := range result.Stdout {
				clientPID, clientName, ok := strings.Cut(line, "\t")
				if ok && clientPID == pid && clientName != "" {
					c.clientName = tmux.ClientName(strings.TrimSpace(clientName))
					return nil
				}
			}
		}
		select {
		case <-c.done:
			return controlRegistrationExitError(c.waitErr, stderr())
		case <-ctx.Done():
			return ctx.Err()
		case <-ticker.C:
		}
	}
}

func controlRegistrationExitError(waitErr error, stderr string) error {
	if waitErr == nil {
		return fmt.Errorf("process exited before registration; stderr=%q", stderr)
	}
	return fmt.Errorf("process exited before registration: %w; stderr=%q", waitErr, stderr)
}

tmux/tmuxtest/harness.go.content:
// Package tmuxtest runs your program inside a real tmux and lets a test assert
// on what it drew. It isolates servers and polls panes instead of sleeping.
//
// It needs a real tmux, so it runs on Unix; [Main] reports an unsupported
// platform rather than starting one. [StartPTYProcess] needs Linux.
//
// # Testing a program
//
// [RunInPane] owns the server, session, and pane for the test:
//
//	func TestReadyBanner(t *testing.T) {
//		ctx := context.Background()
//		pane := tmuxtest.RunInPane(ctx, t, "./mytui --watch")
//
//		tmuxtest.WaitForText(ctx, t, pane, "ready")
//		tmuxtest.Type(ctx, t, pane, "q")
//	}
//
// Failed waits print the last screen. [WaitForLine] matches a whole line,
// [WaitForScreen] takes a condition, and [Screen] reads without waiting.
//
// [RunInPane] uses a startup-file-free POSIX shell and fixed [ShellPrompt]. Use
// [ServerOptions.FixedShell] for the same behavior on a custom server.
//
// # Testing tmux itself
//
// [NewServer] returns an isolated [tmux.Server]. [NewSession] and [NewWindow]
// register resource cleanup with the test.
//
// # Setup and lifecycle
//
// Call [Main] exactly once from TestMain before creating servers. It redirects
// temporary and tmux socket roots, then cleans registered servers.
//
//	func TestMain(m *testing.M) {
//		os.Exit(tmuxtest.Main(m))
//	}
//	func TestWindow(t *testing.T) {
//		ctx := context.Background()
//		server := tmuxtest.NewServer(ctx, t)
//		session := tmuxtest.NewSession(ctx, t, server, tmux.NewSessionRequest{})
//		window := tmuxtest.NewWindow(ctx, t, session, tmux.NewWindowRequest{})
//		_ = window
//	}
//
// Setup failures call [testing.TB.Fatal].
//
// # Isolation and compatibility
//
// Each server uses a short private socket, harness-owned config, and environment
// without tmux targeting variables. tmux 3.3a or newer is required. The harness
// supports Unix; [StartPTYProcess] requires Linux. Cleanup uses stable tmux IDs,
// remains owned by the creating test, and is bounded and retried.
//
// # Context and failures
//
// [NewServer] and [NewControlMode] contexts bound startup, not returned-resource
// lifetime. [StartPTYProcess] is the exception: its context owns the child.
// Resource cleanup uses fresh bounded contexts, and request inputs are copied.
// Nil and empty environments or names retain their documented distinction.
// Failure guidance omits commands, output, paths, options, and environment values.
//
// # Control clients and subprocesses
//
// [NewControlMode] attaches a tmux control client with one output reader and a
// disk-backed spool. [StartPTYProcess] starts a child with a private controlling
// terminal and a memory-backed transcript. Call [ControlMode.Close] or
// [PTYProcess.Close] to release these owned resources.
//
// # Concurrency
//
// [WaitFor] calls its condition serially. [ControlMode.Read] has one reader,
// and [PTYProcess.Write] serializes writers. Close operations on [ControlMode]
// and [PTYProcess] are safe to call concurrently and more than once.
package tmuxtest

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"slices"
	"strconv"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/libtmux/libtmux-go/tmux"
)

// ServerOptions configures a harness-owned [tmux.Server]. All inputs are copied
// before filesystem or process operations, so callers retain ownership.
type ServerOptions struct {
	// Binary is the tmux executable. An empty value resolves tmux from PATH.
	Binary string
	// Config is appended to the harness-owned config file; it cannot replace the
	// private file that prevents user configuration from loading.
	Config []byte
	// ProcessEnvironment supplies the server environment. Nil snapshots the
	// current process environment, while a non-nil empty slice remains empty.
	// Tmux targeting variables are removed in either case.
	ProcessEnvironment []string
	// InitialSession starts the daemon with this copied request. Nil returns a
	// lazy bare server; a later tmux command may start it.
	InitialSession *tmux.NewSessionRequest
	// FixedShell gives panes without an explicit command a POSIX shell with no
	// startup files and the prompt ShellPrompt. RunInPane sets it; the default
	// preserves tmux process behavior for tests that need it.
	FixedShell bool
}

// ShellPrompt is the prompt drawn when [ServerOptions.FixedShell] is enabled.
const ShellPrompt = "tmuxtest$ "

const (
	// An empty private config still prevents tmux from loading user configuration.
	harnessIsolationConfig = ""
	// fixedShellConfig supplies the default command for panes without one.
	fixedShellConfig = "set -g default-shell /bin/sh\n" +
		"set -g default-command \"ENV= PS1='" + ShellPrompt + "' /bin/sh -i\"\n"
	maxSocketPathBytes  = 103
	cleanupTimeout      = 3 * time.Second
	perTestCleanupTries = 3
	// cleanupRetryGap gives an in-progress daemon shutdown time to complete.
	cleanupRetryGap = 100 * time.Millisecond
	// lostServerMessage is what a tmux client reports when the connection it
	// made is closed without a reply.
	lostServerMessage = "server exited unexpectedly"
)

var (
	errInvalidHarnessState  = errors.New("tmuxtest: invalid harness state")
	errHarnessProcessExited = errors.New("tmuxtest: process exited")
	errHarnessOperation     = errors.New("tmuxtest: operation error")
)

type harnessOperationError struct {
	operation      string
	status         string
	classification error
}

func (e *harnessOperationError) Error() string {
	return fmt.Sprintf("tmuxtest: %s failed: %s", e.operation, e.status)
}

func (e *harnessOperationError) Unwrap() error { return e.classification }

func harnessFailure(operation string, cause error) error {
	if cause == nil {
		return nil
	}
	status := "operation error"
	classification := errHarnessOperation
	switch {
	case errors.Is(cause, context.Canceled):
		status = "canceled"
		classification = context.Canceled
	case errors.Is(cause, context.DeadlineExceeded):
		status = "deadline exceeded"
		classification = context.DeadlineExceeded
	case errors.Is(cause, exec.ErrNotFound):
		status = "not found"
		classification = exec.ErrNotFound
	case errors.Is(cause, os.ErrNotExist):
		status = "not found"
		classification = os.ErrNotExist
	case errors.Is(cause, os.ErrPermission):
		status = "permission denied"
		classification = os.ErrPermission
	case errors.Is(cause, tmux.ErrCommand):
		status = "command failed"
		classification = tmux.ErrCommand
	case errors.Is(cause, errInvalidHarnessState):
		status = "invalid state"
		classification = errInvalidHarnessState
	default:
		if _, ok := errors.AsType[*exec.ExitError](cause); ok {
			status = "process exited"
			classification = errHarnessProcessExited
		}
	}
	return &harnessOperationError{
		operation:      operation,
		status:         status,
		classification: classification,
	}
}

type serverRecord struct {
	server        tmux.Server
	tempDir       string
	socketPath    string
	configFile    string
	pid           int
	daemonStopped bool
}

var suite = struct {
	sync.Mutex
	active  bool
	root    string
	records map[string]*serverRecord
}{records: make(map[string]*serverRecord)}

type failureGuidanceState struct {
	sync.Mutex
	allSocketsCleaned bool
}

var failureGuidance = struct {
	sync.Mutex
	states map[testing.TB]*failureGuidanceState
}{states: make(map[testing.TB]*failureGuidanceState)}

// These variables keep derived paths short and named sockets inside the suite root.
var suiteEnvironment = []string{"TMPDIR", "GOTMPDIR", "TMUX_TMPDIR"}

// SuiteRootTagVariable names the environment variable that tags a suite's
// temporary root. go test runs packages in parallel and every suite among them
// creates a root beside the others, so a test spawning a child suite sets this
// to tell its child's root from theirs.
const SuiteRootTagVariable = "LIBTMUX_SUITE_ROOT_TAG"

func suiteRootPrefix() string {
	if tag := os.Getenv(SuiteRootTagVariable); tag != "" {
		return "ltg-" + tag + "-"
	}
	return "ltg-"
}

// Main runs the one-call package lifecycle for tmuxtest. It prepares short
// temporary paths, redirects [suiteEnvironment] into them, runs m, cleans
// registered servers, restores the environment, and returns the final status.
// TestMain should return its result through [os.Exit].
func Main(m *testing.M) int {
	if !platformSupported() {
		fmt.Fprintf(os.Stderr, "tmuxtest: real tmux tests are unsupported on %s\n", runtime.GOOS)
		return 2
	}
	return runSuite(m.Run)
}

func runSuite(run func() int) int {
	root, err := os.MkdirTemp(shortTempBase(), suiteRootPrefix())
	if err != nil {
		fmt.Fprintln(os.Stderr, harnessFailure("create short temporary root", err))
		return 2
	}
	restoreEnvironment, err := replaceSuiteEnvironment(root)
	if err != nil {
		fmt.Fprintln(os.Stderr, harnessFailure("redirect the suite environment", err))
		_ = os.RemoveAll(root)
		return 2
	}

	suite.Lock()
	if suite.active {
		suite.Unlock()
		fmt.Fprintln(os.Stderr, "tmuxtest: Main called while another suite is active")
		_ = restoreEnvironment()
		_ = os.RemoveAll(root)
		return 2
	}
	suite.active = true
	suite.root = root
	suite.records = make(map[string]*serverRecord)
	suite.Unlock()

	code := run()
	cleanupErr := cleanupRegisteredServers()
	surviving := registeredServers()
	if cleanupErr != nil {
		fmt.Fprintln(os.Stderr, "tmuxtest: suite cleanup failed")
		if code == 0 {
			code = 1
		}
	}

	suite.Lock()
	suite.active = false
	suite.root = ""
	suite.records = make(map[string]*serverRecord)
	suite.Unlock()
	if err := restoreEnvironment(); err != nil {
		fmt.Fprintln(os.Stderr, harnessFailure("restore the suite environment", err))
		if code == 0 {
			code = 1
		}
	}
	if cleanupErr == nil || !reachableDaemonRemains(surviving) {
		if err := os.RemoveAll(root); err != nil {
			fmt.Fprintln(os.Stderr, harnessFailure("remove temporary root", err))
			if code == 0 {
				code = 1
			}
		}
	}
	return code
}

// NewServer starts an isolated [tmux.Server] with a session named "work".
// Startup uses ctx and the harness timeout, whichever ends first. It registers
// bounded cleanup with t; setup failures call [testing.TB.Fatal]. The context
// does not govern later server cleanup or daemon lifetime.
func NewServer(ctx context.Context, t testing.TB) tmux.Server {
	t.Helper()
	initialSession := tmux.NewSessionRequest{Name: "work"}
	server := NewServerWithOptions(ctx, t, ServerOptions{InitialSession: &initialSession})
	return server
}

// NewServerWithOptions prepares an isolated harness-owned [tmux.Server] from
// options. Initial startup uses ctx and the harness timeout, whichever ends
// first. The daemon starts only when [ServerOptions.InitialSession] is non-nil
// or a later tmux command starts it. It registers bounded cleanup with t; setup
// failures call [testing.TB.Fatal]. The context does not govern later cleanup
// or daemon lifetime.
func NewServerWithOptions(
	ctx context.Context,
	t testing.TB,
	options ServerOptions,
) tmux.Server {
	t.Helper()
	server, _ := newServerWithOptions(ctx, t, captureServerOptions(options), true, true)
	return server
}

func newServer(
	ctx context.Context,
	t testing.TB,
	binary string,
	registerCleanup bool,
	exactConfig bool,
) (tmux.Server, *serverRecord) {
	t.Helper()
	initialSession := tmux.NewSessionRequest{Name: "work"}
	return newServerWithOptions(ctx, t, ServerOptions{
		Binary:         binary,
		InitialSession: &initialSession,
	}, registerCleanup, exactConfig)
}

func newServerWithOptions(
	ctx context.Context,
	t testing.TB,
	options ServerOptions,
	registerCleanup bool,
	exactConfig bool,
) (tmux.Server, *serverRecord) {
	t.Helper()
	var guidance *failureGuidanceState
	if registerCleanup {
		guidance = registerFailureGuidance(t)
	}

	binary := options.Binary
	if binary == "" {
		var err error
		binary, err = exec.LookPath("tmux")
		if err != nil {
			t.Fatal(harnessFailure("resolve tmux executable", err))
		}
		binary, err = filepath.Abs(binary)
		if err != nil {
			t.Fatal(harnessFailure("resolve tmux executable path", err))
		}
	}
	root, err := activeSuiteRoot()
	if err != nil {
		t.Fatal(err)
	}
	tempDir, err := os.MkdirTemp(root, "s-")
	if err != nil {
		t.Fatal(harnessFailure("create server directory", err))
	}
	socketPath := filepath.Join(tempDir, "s")
	configFile := ""
	if exactConfig {
		configFile = filepath.Join(tempDir, "tmux.conf")
		config := make([]byte, 0, len(harnessIsolationConfig)+len(options.Config))
		config = append(config, harnessIsolationConfig...)
		if options.FixedShell {
			config = append(config, fixedShellConfig...)
		}
		config = append(config, options.Config...)
		if err := os.WriteFile(configFile, config, 0o600); err != nil {
			_ = os.RemoveAll(tempDir)
			t.Fatal(harnessFailure("create isolated tmux config", err))
		}
	}
	if len([]byte(socketPath)) > maxSocketPathBytes {
		_ = os.RemoveAll(tempDir)
		t.Fatal(harnessFailure("validate socket path", errInvalidHarnessState))
	}

	processEnvironment := options.ProcessEnvironment
	if processEnvironment == nil {
		processEnvironment = os.Environ()
	}
	server, err := tmux.NewServer(tmux.ServerOptions{
		Binary:             binary,
		SocketPath:         socketPath,
		ConfigFile:         configFile,
		ProcessEnvironment: scrubTmuxEnvironment(processEnvironment),
	})
	if err != nil {
		_ = os.RemoveAll(tempDir)
		t.Fatal(harnessFailure("construct tmux server", err))
	}
	record := &serverRecord{
		server:     server,
		tempDir:    tempDir,
		socketPath: socketPath,
		configFile: configFile,
	}
	registerServer(record)
	if registerCleanup {
		t.Cleanup(func() {
			err := cleanupWithRetries(record, perTestCleanupTries)
			recordSocketCleanup(guidance, err == nil)
			if err != nil {
				t.Errorf(
					"tmuxtest: harness-owned socket cleanup failed after %d attempts",
					perTestCleanupTries,
				)
			}
		})
	}

	if options.InitialSession == nil {
		return server, record
	}
	startupCtx, cancel := context.WithTimeout(ctx, cleanupTimeout)
	defer cancel()
	_, err = server.NewSession(startupCtx, *options.InitialSession)
	if err != nil {
		t.Fatal(harnessFailure("create initial session", err))
	}
	pidResult := runCommand(startupCtx, server, "display-message", "-p", "#{pid}")
	if err := commandFailure("display-message", pidResult); err != nil {
		t.Fatal(err)
	}
	if len(pidResult.Stdout) != 1 {
		t.Fatal(harnessFailure("read server pid", errInvalidHarnessState))
	}
	pid, err := strconv.Atoi(pidResult.Stdout[0])
	if err != nil {
		t.Fatal(harnessFailure("parse server pid", err))
	}
	record.pid = pid
	return server, record
}

func registerFailureGuidance(t testing.TB) *failureGuidanceState {
	failureGuidance.Lock()
	defer failureGuidance.Unlock()
	if state, ok := failureGuidance.states[t]; ok {
		return state
	}
	state := &failureGuidanceState{allSocketsCleaned: true}
	failureGuidance.states[t] = state
	t.Cleanup(func() {
		failureGuidance.Lock()
		delete(failureGuidance.states, t)
		failureGuidance.Unlock()
		if !t.Failed() {
			return
		}
		state.Lock()
		cleaned := state.allSocketsCleaned
		state.Unlock()
		name := sanitizedTopLevelTestName(t.Name())
		t.Logf("tmuxtest: reproduce: go test -run '^%s$' .", name)
		if cleaned {
			t.Log("tmuxtest: harness-owned socket cleaned: yes")
			return
		}
		t.Log("tmuxtest: harness-owned socket cleaned: no")
	})
	return state
}

func recordSocketCleanup(state *failureGuidanceState, cleaned bool) {
	if cleaned {
		return
	}
	state.Lock()
	state.allSocketsCleaned = false
	state.Unlock()
}

func sanitizedTopLevelTestName(name string) string {
	name, _, _ = strings.Cut(name, "/")
	var sanitized strings.Builder
	for _, character := range name {
		if character >= 'a' && character <= 'z' ||
			character >= 'A' && character <= 'Z' ||
			character >= '0' && character <= '9' ||
			character == '_' {
			sanitized.WriteRune(character)
		} else {
			sanitized.WriteByte('_')
		}
		if sanitized.Len() == 128 {
			break
		}
	}
	if sanitized.Len() == 0 {
		return "Test"
	}
	return sanitized.String()
}

func captureServerOptions(options ServerOptions) ServerOptions {
	options.Config = slices.Clone(options.Config)
	options.ProcessEnvironment = slices.Clone(options.ProcessEnvironment)
	if options.InitialSession != nil {
		initialSession := captureNewSessionRequest(*options.InitialSession)
		options.InitialSession = &initialSession
	}
	return options
}

func activeSuiteRoot() (string, error) {
	suite.Lock()
	defer suite.Unlock()
	if !suite.active {
		return "", errors.New("tmuxtest: NewServer requires tmuxtest.Main in TestMain")
	}
	return suite.root, nil
}

func runCommand(ctx context.Context, server tmux.Server, args ...string) tmux.CommandResult {
	result, err := server.Cmd(ctx, args...)
	if err != nil {
		return tmux.CommandResult{Command: result.Command, Stderr: []string{err.Error()}, ExitCode: -1}
	}
	return result
}

func runCleanupCommand(server tmux.Server, args ...string) tmux.CommandResult {
	ctx, cancel := context.WithTimeout(context.Background(), cleanupTimeout)
	defer cancel()
	return runCommand(ctx, server, args...)
}

func commandFailure(operation string, result tmux.CommandResult) error {
	if result.ExitCode == 0 {
		return nil
	}
	cause := tmux.ErrCommand
	if result.ExitCode == -1 && len(result.Stderr) == 1 {
		switch result.Stderr[0] {
		case context.Canceled.Error():
			cause = context.Canceled
		case context.DeadlineExceeded.Error():
			cause = context.DeadlineExceeded
		}
	}
	return harnessFailure(operation, cause)
}

func cleanupServer(record *serverRecord) error {
	if record.daemonStopped {
		return removeServerArtifacts(record)
	}
	currentPID, unavailable, err := probeServerPID(record)
	if err != nil {
		return err
	}
	if unavailable {
		record.daemonStopped = true
		return removeServerArtifacts(record)
	}
	record.pid = currentPID

	result := runCleanupCommand(record.server, "kill-server")
	if !waitForProcessDeath(currentPID, time.Now().Add(cleanupTimeout)) {
		return errors.Join(
			commandFailure("kill-server", result),
			harnessFailure("stop tmux server", errInvalidHarnessState),
		)
	}

	replacementPID, unavailable, err := probeServerPID(record)
	if err != nil {
		return errors.Join(commandFailure("kill-server", result), err)
	}
	if !unavailable {
		record.pid = replacementPID
		return harnessFailure("verify tmux server stopped", errInvalidHarnessState)
	}
	record.daemonStopped = true
	return removeServerArtifacts(record)
}

func probeServerPID(record *serverRecord) (pid int, unavailable bool, err error) {
	result := runCleanupCommand(record.server, "display-message", "-p", "#{pid}")
	if result.ExitCode != 0 {
		if serverUnavailable(result) && (record.pid <= 0 || !processAlive(record.pid)) {
			return 0, true, nil
		}
		if serverUnavailable(result) {
			return 0, false, harnessFailure(
				"probe tmux server",
				errInvalidHarnessState,
			)
		}
		return 0, false, commandFailure("display-message", result)
	}
	if len(result.Stderr) != 0 {
		return 0, false, harnessFailure("probe tmux server", tmux.ErrCommand)
	}
	if len(result.Stdout) != 1 {
		return 0, false, harnessFailure("read server pid", errInvalidHarnessState)
	}
	pid, err = strconv.Atoi(result.Stdout[0])
	if err != nil {
		return 0, false, harnessFailure("parse server pid", err)
	}
	if pid <= 0 {
		return 0, false, harnessFailure("validate server pid", errInvalidHarnessState)
	}
	return pid, false, nil
}

// serverUnavailable reports whether result says nobody is serving the socket.
//
// "server exited unexpectedly" counts. A distribution tmux built with systemd
// support moves each new pane's child into its own cgroup before it closes the
// descriptors it inherited from the server, and signals stay blocked until
// then. A server killed in that window leaves its listening socket open in the
// child, so a client connects and is reset when the child finally closes it.
// Callers still require the recorded process to be gone.
func serverUnavailable(result tmux.CommandResult) bool {
	if result.ExitCode == 0 || len(result.Stdout) != 0 {
		return false
	}
	for _, line := range result.Stderr {
		if strings.HasPrefix(line, "no server running on ") ||
			line == lostServerMessage {
			return true
		}
		if strings.HasPrefix(line, "error connecting to ") &&
			(strings.Contains(line, "No such file or directory") ||
				strings.Contains(line, "Connection refused")) {
			return true
		}
	}
	return false
}

func removeServerArtifacts(record *serverRecord) error {
	var failures []error
	if err := os.Remove(record.socketPath); err != nil && !errors.Is(err, os.ErrNotExist) {
		failures = append(failures, harnessFailure("remove tmux socket", err))
	}
	if record.configFile != "" {
		if err := os.Remove(record.configFile); err != nil && !errors.Is(err, os.ErrNotExist) {
			failures = append(failures, harnessFailure("remove tmux config", err))
		}
	}
	if record.tempDir != "" {
		if filepath.Dir(record.socketPath) != record.tempDir ||
			(record.configFile != "" && filepath.Dir(record.configFile) != record.tempDir) {
			failures = append(failures, harnessFailure("validate server directory", errInvalidHarnessState))
		} else if err := os.Remove(record.tempDir); err != nil && !errors.Is(err, os.ErrNotExist) {
			failures = append(failures, harnessFailure("remove server directory", err))
		}
	}
	return errors.Join(failures...)
}

func cleanupAndUnregister(record *serverRecord) error {
	if err := cleanupServer(record); err != nil {
		return err
	}
	unregisterServer(record.socketPath)
	return nil
}

func cleanupWithRetries(record *serverRecord, attempts int) error {
	return retryCleanup(attempts, cleanupRetryGap, func() error {
		return cleanupAndUnregister(record)
	})
}

// retryCleanup waits between attempts so an in-progress shutdown can complete.
func retryCleanup(attempts int, gap time.Duration, attempt func() error) error {
	if attempts < 1 {
		return errors.New("tmuxtest: cleanup requires at least one attempt")
	}
	var failures []error
	for try := range attempts {
		if try > 0 {
			time.Sleep(gap)
		}
		if err := attempt(); err != nil {
			failures = append(failures, harnessFailure("cleanup tmux server", err))
			continue
		}
		return nil
	}
	return errors.Join(failures...)
}

func waitForProcessDeath(pid int, deadline time.Time) bool {
	for processAlive(pid) && time.Now().Before(deadline) {
		time.Sleep(5 * time.Millisecond)
	}
	return !processAlive(pid)
}

func registerServer(record *serverRecord) {
	suite.Lock()
	defer suite.Unlock()
	suite.records[record.socketPath] = record
}

func unregisterServer(socketPath string) {
	suite.Lock()
	defer suite.Unlock()
	delete(suite.records, socketPath)
}

// registeredServers returns the records still registered. A record is
// unregistered as it is cleaned, so after cleanup what remains is what failed.
func registeredServers() []*serverRecord {
	suite.Lock()
	defer suite.Unlock()
	records := make([]*serverRecord, 0, len(suite.records))
	for _, record := range suite.records {
		records = append(records, record)
	}
	return records
}

// reachableDaemonRemains decides whether the suite root must survive for a
// daemon whose socket is otherwise no longer reachable.
func reachableDaemonRemains(records []*serverRecord) bool {
	for _, record := range records {
		if !record.daemonStopped && record.pid > 0 && processAlive(record.pid) {
			return true
		}
	}
	return false
}

func cleanupRegisteredServers() error {
	suite.Lock()
	records := make([]*serverRecord, 0, len(suite.records))
	for _, record := range suite.records {
		records = append(records, record)
	}
	suite.Unlock()

	var failures []error
	for _, record := range records {
		if err := cleanupAndUnregister(record); err != nil {
			failures = append(failures, err)
		}
	}
	return errors.Join(failures...)
}

func scrubTmuxEnvironment(environment []string) []string {
	cleaned := make([]string, 0, len(environment))
	for _, entry := range environment {
		key, _, _ := strings.Cut(entry, "=")
		switch key {
		case "TMUX", "TMUX_PANE", "TMUX_TMPDIR":
			continue
		default:
			cleaned = append(cleaned, entry)
		}
	}
	return cleaned
}

// replaceSuiteEnvironment points every variable in [suiteEnvironment] at root
// and returns one call that restores all of them. A variable that cannot be set
// undoes the ones already replaced, so a failure leaves the environment as it
// was found rather than half redirected.
func replaceSuiteEnvironment(root string) (func() error, error) {
	restores := make([]func() error, 0, len(suiteEnvironment))
	restore := func() error {
		var first error
		for _, undo := range slices.Backward(restores) {
			if err := undo(); err != nil && first == nil {
				first = err
			}
		}
		return first
	}
	for _, key := range suiteEnvironment {
		undo, err := replaceEnvironment(key, root)
		if err != nil {
			_ = restore()
			return nil, fmt.Errorf("%s: %w", key, err)
		}
		restores = append(restores, undo)
	}
	return restore, nil
}

func replaceEnvironment(key, value string) (func() error, error) {
	previous, existed := os.LookupEnv(key)
	if err := os.Setenv(key, value); err != nil {
		return nil, err
	}
	return func() error {
		if existed {
			return os.Setenv(key, previous)
		}
		return os.Unsetenv(key)
	}, nil
}

