package tmuxtest

import (
	"context"
	"errors"
	"fmt"
	"time"
)

var errNilWaitCondition = errors.New("tmuxtest: wait condition is nil")

// WaitFor checks condition serially and immediately, then after each interval,
// until it succeeds, returns an error, or ctx ends. It validates interval,
// condition, and ctx in that order: interval must be positive, condition must
// be non-nil, and an already-ended context prevents every check. Condition
// errors and context errors are returned unchanged. A running condition receives
// ctx and must observe it itself; WaitFor cannot interrupt the condition.
func WaitFor(
	ctx context.Context,
	interval time.Duration,
	condition func(context.Context) (bool, error),
) error {
	if interval <= 0 {
		return fmt.Errorf("tmuxtest: wait interval must be positive, got %s", interval)
	}
	if condition == nil {
		return errNilWaitCondition
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for {
		ready, err := condition(ctx)
		if err != nil {
			return err
		}
		if ready {
			return nil
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-ticker.C:
		}
	}
}

tmux/version_check.go.content:
package tmux

import (
	"context"
	"errors"
	"regexp"
	"runtime"
	"slices"
	"strconv"
	"strings"

	"github.com/libtmux/libtmux-go/tmux/internal/tmuxcmd"
)

var (
	minimumSupportedVersion = Version{raw: MinimumSupportedVersion, major: 3, minor: 3}

	// versionReleasePattern is the grammar tmux has reported through
	// #{version}: a release with at most one patch letter, a release
	// candidate (bare or numbered) of an unpatched release, or the development
	// build next-X.Y. Suffixes such as -master or -dev never came from tmux.
	versionReleasePattern = regexp.MustCompile(
		`^(?:(next)-([0-9]+)\.([0-9]+)|([0-9]+)\.([0-9]+)(?:\.([0-9]+))?` +
			`(?:([a-z])|-rc([0-9]*))?)$`,
	)
)

// Release stages order next-X.Y below X.Y-rc below X.Y, which a patch letter
// then follows.
const (
	stageNext = iota
	stageCandidate
	stageRelease
)

// versionKey orders qualified tokens: major, minor, patch, stage, then the
// candidate number or patch letter. ok is false outside the grammar.
func versionKey(raw string) (key [6]int, ok bool) {
	match := versionReleasePattern.FindStringSubmatch(raw)
	if match == nil {
		return key, false
	}
	number := func(text string) int {
		value, err := strconv.Atoi(text)
		if err != nil {
			return 0
		}
		return value
	}
	if match[1] == "next" {
		return [6]int{number(match[2]), number(match[3]), 0, stageNext, 0, 0}, true
	}
	key = [6]int{number(match[4]), number(match[5]), number(match[6]), stageRelease, 0, 0}
	switch {
	case match[7] != "":
		key[4] = int(match[7][0]-'a') + 1
	case strings.Contains(raw, "-rc"):
		key[3] = stageCandidate
		key[4] = number(match[8])
	}
	return key, true
}

// meetsMinimum orders tokens by the grammar above, so a candidate or
// development build ranks below the release it names. A token outside the
// grammar never meets a minimum.
func (v Version) meetsMinimum(minimum Version) bool {
	current, ok := versionKey(v.raw)
	if !ok {
		return false
	}
	required, ok := versionKey(minimum.raw)
	if !ok {
		return false
	}
	return slices.Compare(current[:], required[:]) >= 0
}

func requireSupportedVersion(current Version) error {
	if !current.meetsMinimum(minimumSupportedVersion) {
		return refuseVersion(current, minimumSupportedVersion)
	}
	return nil
}

// refuseVersion builds the refusal for a version below minimum, marking one
// outside the release grammar as unrecognized rather than older.
func refuseVersion(current, minimum Version) *VersionTooLowError {
	_, recognized := versionKey(current.raw)
	return &VersionTooLowError{Current: current, Minimum: minimum, unrecognized: !recognized}
}

// checkCore binds a live daemon to the same identity guard as materialized
// records. An absent daemon is checked by the executable that can create it.
func (s Server) checkCore(ctx context.Context, absentCleanup bool) (Server, error) {
	checked, err := s.checkCoreVersion(ctx, absentCleanup)
	return checked, notSent(err)
}

// ErrVersionCheckFailed identifies a failure of the check that precedes every
// ordinary command, a refusal included: an ErrVersionTooLow from Cmd matches
// it too. The check is a read-only probe, so a command that fails with it was
// never sent, whatever else the error matches.
var ErrVersionCheckFailed = errors.New("tmux: version check failed")

type versionCheckError struct{ err error }

func (e *versionCheckError) Error() string { return e.err.Error() }

func (e *versionCheckError) Unwrap() error { return e.err }

// Is matches [ErrVersionCheckFailed].
func (e *versionCheckError) Is(target error) bool { return target == ErrVersionCheckFailed }

// notSent marks a check failure as one that sent nothing and removes the
// outcome-unknown classification from it: the check is a read-only probe, so
// however it ended, the caller's request was never sent.
func notSent(err error) error {
	if err == nil {
		return nil
	}
	cause, stripped := err, false
	if unknown, ok := errors.AsType[*outcomeUnknownError](cause); ok {
		cause, stripped = unknown.cause, true
	}
	if unknown, ok := errors.AsType[*tmuxcmd.OutcomeUnknownError](cause); ok {
		cause, stripped = unknown.Err, true
	}
	if stripped {
		err = &commandTransportError{err: cause}
	}
	return &versionCheckError{err: err}
}

func (s Server) checkCoreVersion(ctx context.Context, absentCleanup bool) (Server, error) {
	if err := ctx.Err(); err != nil {
		return Server{}, err
	}
	if s.daemon != nil {
		return s, requireSupportedVersion(s.daemon.version)
	}
	// Connections are checked before their creating control process starts and
	// keep addressing that exact daemon for their entire lifetime.
	if s.connection != nil {
		return s, nil
	}
	identity, err := s.probeServerIdentity(ctx, coreVersionIdentityFields())
	if err == nil {
		if err := requireSupportedVersion(identity.version); err != nil {
			return Server{}, err
		}
		return s.withDaemon(identity), nil
	}
	if !errors.Is(err, ErrNoServer) {
		return Server{}, err
	}
	if absentCleanup {
		return s, nil
	}
	version, err := s.queryExecutableVersion(ctx, runtime.GOOS)
	if err != nil {
		return Server{}, err
	}
	if err := requireSupportedVersion(version); err != nil {
		return Server{}, err
	}
	s.startupVersion = &version
	return s, nil
}

func coreVersionIdentityFields() []formatField {
	return []formatField{
		{name: "pid"},
		{name: "start_time"},
		{name: "socket_path"},
		{name: "version"},
	}
}

tmux/version.go.content:
package tmux

import (
	"errors"
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

const (
	// MinimumSupportedVersion is the oldest tmux release supported by this package.
	MinimumSupportedVersion = "3.3a"
	// MinimumConnectionVersion is the oldest tmux feature level that supports
	// terminal Connection ownership. Later releases may strengthen individual
	// lifecycle guarantees without changing this floor.
	MinimumConnectionVersion = MinimumSupportedVersion
	// MaximumTestedVersion is the newest numbered tmux feature level covered by
	// this package's tests, and the level ParseVersion gives a bare master
	// build.
	MaximumTestedVersion = "3.8"

	latestTestedMajor = 3
	latestTestedMinor = 8
)

// ErrInvalidVersion classifies [VersionError] through errors.Is.
var (
	// ErrInvalidVersion identifies malformed tmux version tokens. It is matched by
	// errors.Is for VersionError.
	ErrInvalidVersion = errors.New("tmux: invalid version")

	versionPattern = regexp.MustCompile(
		`^(?:(next)-)?([0-9]+)(?:\.([0-9]+))?(?:\.([0-9]+))?` +
			`(?:([a-z][a-z0-9]*(?:[.-][a-z0-9]+)*)|(-[a-z0-9]+(?:[.-][a-z0-9]+)*))?$`,
	)
	releaseCandidatePattern  = regexp.MustCompile(`(?:^|-)rc([0-9]*)$`)
	openBSDVersionPattern    = regexp.MustCompile(`^openbsd-[0-9]+(?:\.[0-9]+)?$`)
	legacyVersionPartPattern = regexp.MustCompile(`[0-9]+|[a-z]+|[.-]`)
)

// VersionError reports a tmux version token that cannot be parsed. It matches
// [ErrInvalidVersion] through errors.Is; callers can recover Token with errors.As.
type VersionError struct {
	// Token is the rejected tmux version text.
	Token string
}

// Error implements error.
func (e *VersionError) Error() string {
	return fmt.Sprintf("%v %q", ErrInvalidVersion, e.Token)
}

// Unwrap makes VersionError compatible with ErrInvalidVersion.
func (e *VersionError) Unwrap() error {
	return ErrInvalidVersion
}

// Version is a parsed tmux version that preserves its original token. Obtain a
// value with [ParseVersion], [Server.Version], or [Snapshot.Version]. Its zero
// value has no feature level and is useful only as an absent version. Parsed
// OpenBSD base-system tokens also have no feature level until [Server.Version]
// probes the configured binary's commands.
type Version struct {
	raw         string
	major       int
	minor       int
	patch       int
	development int
	// candidate is zero for a release and one more than the candidate number
	// for X.Y-rcN, so a bare -rc is one.
	candidate int
}

// ParseVersion parses a raw tmux version token. It returns a [VersionError]
// matching [ErrInvalidVersion] when the token cannot be parsed.
func ParseVersion(raw string) (Version, error) {
	if openBSDVersionPattern.MatchString(raw) {
		return Version{raw: raw}, nil
	}
	if raw == "master" {
		return Version{
			raw:         raw,
			major:       latestTestedMajor,
			minor:       latestTestedMinor,
			development: 1,
		}, nil
	}

	matches := versionPattern.FindStringSubmatch(raw)
	if matches == nil {
		return Version{}, &VersionError{Token: raw}
	}

	major, err := parseVersionNumber(raw, matches[2])
	if err != nil {
		return Version{}, err
	}
	minor, err := parseVersionNumber(raw, matches[3])
	if err != nil {
		return Version{}, err
	}
	patch, err := parseVersionNumber(raw, matches[4])
	if err != nil {
		return Version{}, err
	}

	qualifier := matches[5]
	if qualifier == "" {
		qualifier = matches[6]
	}
	development := 0
	if strings.Contains(qualifier, "master") {
		if qualifier != "master" && !strings.HasSuffix(qualifier, "-master") {
			return Version{}, &VersionError{Token: raw}
		}
		development = 1
	}
	candidate := 0
	if rc := releaseCandidatePattern.FindStringSubmatch(qualifier); rc != nil {
		candidate = 1
		if rc[1] != "" {
			number, err := strconv.Atoi(rc[1])
			if err != nil {
				return Version{}, &VersionError{Token: raw}
			}
			candidate = number + 1
		}
	}
	if matches[1] == "next" {
		// A "next-X.Y" token names the release its development track is
		// heading toward, not one it has reached, so it ranks below X.Y:
		// one step under whatever development a same-named qualifier would
		// already carry, while its own numeric core keeps it correctly
		// ordered against every other release.
		development--
	}
	return Version{
		raw:         raw,
		major:       major,
		minor:       minor,
		patch:       patch,
		development: development,
		candidate:   candidate,
	}, nil
}

func parseVersionNumber(raw, value string) (int, error) {
	if value == "" {
		return 0, nil
	}
	number, err := strconv.Atoi(value)
	if err != nil {
		return 0, &VersionError{Token: raw}
	}
	return number, nil
}

// String returns the original tmux version token.
func (v Version) String() string {
	return v.raw
}

// Major returns the capability-level major component. Development tokens use
// the latest tested feature core. Unprobed OpenBSD base-system tokens return
// zero.
func (v Version) Major() int {
	return v.major
}

// Minor returns the capability-level minor component, or zero when absent.
// Development tokens use the latest tested feature core. Unprobed OpenBSD
// base-system tokens return zero.
func (v Version) Minor() int {
	return v.minor
}

// Patch returns the capability-level patch component, or zero when absent.
func (v Version) Patch() int {
	return v.patch
}

// Compare orders versions by feature level and returns -1, 0, or 1. Patch
// letters share their release's level, but a development build ranks below
// the release it names and a candidate below its release:
//
//	next-X.Y < X.Y-rc < X.Y-rcN < X.Y == X.Ya
//
// A feature gate therefore opens on a candidate only when it names that
// candidate, so it names the earliest build measured to have the feature.
func (v Version) Compare(other Version) int {
	left := v.rank()
	right := other.rank()
	for i := range left {
		if left[i] < right[i] {
			return -1
		}
		if left[i] > right[i] {
			return 1
		}
	}
	return 0
}

// rank is Compare's key. A release outranks every candidate of it.
func (v Version) rank() [6]int {
	final := 0
	if v.candidate == 0 {
		final = 1
	}
	return [6]int{v.major, v.minor, v.patch, v.development, final, v.candidate}
}

// CompareRelease compares raw release suffixes using libtmux's legacy order.
// Use Compare for feature gates, where point-release suffixes intentionally
// share one capability level.
func (v Version) CompareRelease(other Version) int {
	left := legacyVersionKey(v.raw)
	right := legacyVersionKey(other.raw)
	for index := range min(len(left), len(right)) {
		if left[index] < right[index] {
			return -1
		}
		if left[index] > right[index] {
			return 1
		}
	}
	if len(left) < len(right) {
		return -1
	}
	if len(left) > len(right) {
		return 1
	}
	return 0
}

func legacyVersionKey(raw string) []string {
	parts := legacyVersionPartPattern.FindAllString(strings.ToLower(raw), -1)
	key := make([]string, 0, len(parts)+1)
	for _, part := range append(parts, "final") {
		switch part {
		case ".":
			continue
		case "pre", "preview", "rc":
			part = "c"
		case "dev":
			part = "@"
		case "-":
			part = "final-"
		}

		if part[0] >= '0' && part[0] <= '9' {
			if padding := 8 - len(part); padding > 0 {
				part = strings.Repeat("0", padding) + part
			}
		} else {
			part = "*" + part
			if part < "*final" {
				for len(key) > 0 && key[len(key)-1] == "*final-" {
					key = key[:len(key)-1]
				}
			}
			for len(key) > 0 && key[len(key)-1] == "00000000" {
				key = key[:len(key)-1]
			}
		}
		key = append(key, part)
	}
	return key
}

// AtLeast reports whether v provides the same or a newer feature level.
func (v Version) AtLeast(minimum Version) bool {
	return v.Compare(minimum) >= 0
}

tmux/warning.go.content:
package tmux

import (
	"fmt"
	"strconv"
	"strings"
)

// UnsupportedPolicy selects what a request does when it needs an optional tmux
// capability the running server does not have.
//
// The default refuses because dropping a flag can change behavior while still
// returning success.
//
// Choose degradation only when omission is acceptable:
//
//	server, err := tmux.NewServer(tmux.ServerOptions{
//		Unsupported:    tmux.DegradeUnsupported,
//		WarningHandler: func(w tmux.Warning) { log.Printf("tmux: %s", w) },
//	})
//	if err != nil {
//		log.Fatal(err)
//	}
//
// Set [ServerOptions.WarningHandler] alongside it to observe omissions.
type UnsupportedPolicy uint8

const (
	// FailUnsupported refuses a request naming a capability the running tmux
	// does not have, with a VersionTooLowError naming the subcommand and the
	// capability. It is the zero value.
	FailUnsupported UnsupportedPolicy = iota
	// DegradeUnsupported omits the capability, runs the reduced command, and
	// reports the decision to ServerOptions.WarningHandler as a
	// WarningUnsupportedFeature.
	DegradeUnsupported
)

// String implements fmt.Stringer.
func (p UnsupportedPolicy) String() string {
	switch p {
	case FailUnsupported:
		return "fail"
	case DegradeUnsupported:
		return "degrade"
	default:
		return "UnsupportedPolicy(" + strconv.Itoa(int(p)) + ")"
	}
}

// WarningKind identifies one closed class of nonfatal library warning.
type WarningKind uint8

const (
	// WarningUnsupportedFeature reports a requested feature omitted because
	// the connected tmux binary is too old.
	WarningUnsupportedFeature WarningKind = iota + 1
	// WarningCommandStderr reports stderr from a completed command whose Python
	// API treats the diagnostic as nonfatal.
	WarningCommandStderr
)

// Warning describes one nonfatal compatibility decision delivered to a
// [WarningHandler].
type Warning struct {
	// Kind classifies the compatibility decision.
	Kind WarningKind
	// Subcommand names the tmux subcommand affected by the decision.
	Subcommand string
	// Feature names the optional tmux capability involved.
	Feature string
	// CurrentVersion is the observed tmux version.
	CurrentVersion Version
	// RequiredVersion is the minimum tmux version for Feature.
	RequiredVersion Version
	// Message describes the nonfatal compatibility decision.
	Message string
}

// WarningHandler receives warnings synchronously on the caller goroutine:
//
//	server, err := tmux.NewServer(tmux.ServerOptions{
//		WarningHandler: func(warning tmux.Warning) {
//			log.Printf("tmux: %s", warning.Message)
//		},
//	})
//	if err != nil {
//		log.Fatal(err)
//	}
//
// Operations may invoke it concurrently; synchronize shared state. Diagnostics
// may contain caller-supplied arguments and are delivered only to this handler.
type WarningHandler func(Warning)

// String implements fmt.Stringer by returning Message.
func (w Warning) String() string { return w.Message }

func (s Server) warn(warning Warning) {
	if s.state == nil {
		return
	}
	handler := s.state.config.warningHandler
	if handler != nil {
		handler(warning)
	}
}

func newCommandStderrWarning(subcommand string, stderr []string) Warning {
	return Warning{
		Kind:       WarningCommandStderr,
		Subcommand: subcommand,
		Message:    subcommand + ": " + strings.Join(stderr, "; "),
	}
}

// unsupportedFeature either refuses or warns before the caller omits its flag.
func (s Server) unsupportedFeature(
	subcommand string,
	feature string,
	current Version,
	required Version,
) error {
	if s.state == nil || s.state.config.unsupported == FailUnsupported {
		return &VersionTooLowError{
			Current:    current,
			Minimum:    required,
			Subcommand: subcommand,
			Feature:    feature,
		}
	}
	s.warn(newUnsupportedFeatureWarning(subcommand, feature, current, required))
	return nil
}

func newUnsupportedFeatureWarning(
	subcommand string,
	feature string,
	current Version,
	required Version,
) Warning {
	return Warning{
		Kind:            WarningUnsupportedFeature,
		Subcommand:      subcommand,
		Feature:         feature,
		CurrentVersion:  current,
		RequiredVersion: required,
		Message: fmt.Sprintf(
			"%s: %s requires tmux %s or newer; current %s; feature ignored",
			subcommand,
			feature,
			required,
			current,
		),
	}
}

// reportUnsupported applies the server's policy to renderer warnings.
func (s Server) reportUnsupported(warnings []Warning) error {
	for _, warning := range warnings {
		if warning.Kind != WarningUnsupportedFeature {
			s.warn(warning)
			continue
		}
		if err := s.unsupportedFeature(
			warning.Subcommand,
			warning.Feature,
			warning.CurrentVersion,
			warning.RequiredVersion,
		); err != nil {
			return err
		}
	}
	return nil
}

// reportUnsupported applies one run's policy to the warnings an operation's
// renderer produced. It mirrors the [Server] method so a planned operation
// refuses or reports exactly what the same request does when issued directly.
func (c planRenderContext) reportUnsupported(warnings []Warning) error {
	for _, warning := range warnings {
		if warning.Kind != WarningUnsupportedFeature {
			c.warn(warning)
			continue
		}
		if c.unsupported == FailUnsupported {
			return &VersionTooLowError{
				Current:    warning.CurrentVersion,
				Minimum:    warning.RequiredVersion,
				Subcommand: warning.Subcommand,
				Feature:    warning.Feature,
			}
		}
		c.warn(warning)
	}
	return nil
}

func (c planRenderContext) warn(warning Warning) {
	if c.warningHandler != nil {
		c.warningHandler(warning)
	}
}

tmux/window_layout.go.content:
package tmux

import (
	"context"
	"encoding/json"
	"regexp"
	"slices"
	"strings"

	"github.com/libtmux/libtmux-go/tmux/internal/layout"
)

// SelectLayoutRequest selects one layout operation. Its zero value reapplies
// the last preset layout. Layout, Spread, Next, and Previous are mutually
// exclusive and are validated before execution; an empty Layout is omitted
// rather than passed explicitly. The request contains no retained
// caller-owned storage and is supported on tmux 3.3a or later.
type SelectLayoutRequest struct {
	// Layout names a preset or supplies a tmux layout string - either the
	// classic checksum-prefixed grammar every supported version accepts, or
	// the JSON shape tmux 3.8+ also accepts, exactly as #{window_layout}
	// reported it; empty selects the zero-value behavior.
	Layout string
	// Spread distributes pane space evenly.
	Spread bool
	// Next selects the next preset layout.
	Next bool
	// Previous selects the previous preset layout.
	Previous bool
}

// Validate checks mode exclusivity, NUL bytes, candidate preset names and
// classic checksummed syntax and JSON envelopes without running tmux. Its zero
// value is valid.
// Invalid requests match [ErrInvalidServerCommandRequest]. Names and abbreviations
// valid on any supported tmux are accepted here; execution checks daemon support.
// tmux validates JSON contents, geometry and live pane counts when applying it.
func (request SelectLayoutRequest) Validate() error {
	if err := validateServerCommandArgument("select-layout", "Layout", request.Layout, true); err != nil {
		return err
	}
	modes := 0
	if request.Layout != "" {
		modes++
	}
	if request.Spread {
		modes++
	}
	if request.Next {
		modes++
	}
	if request.Previous {
		modes++
	}
	if modes > 1 {
		return invalidServerCommandRequest(
			"select-layout",
			"Mode",
			"",
			"Layout, Spread, Next, and Previous are mutually exclusive",
		)
	}

	if request.Layout == "" || layoutLooksLikeJSON(request.Layout) {
		return nil
	}
	if _, err := validateLayout(request.Layout, Version{}); err == nil {
		return nil
	}
	_, err := validateLayout(request.Layout, layoutMirroredVersion)
	return err
}

// SelectLayout applies one layout operation to the receiver's exact winlink.
// It changes pane geometry without selecting the window or promising client
// focus. The materialized receiver is not refreshed, so callers that need
// current pane geometry must obtain a new snapshot or refresh related models.
// A transport or context error can be delivery-ambiguous; the void result
// cannot carry partial state and no rollback is attempted.
func (w Window) SelectLayout(ctx context.Context, request SelectLayoutRequest) error {
	if err := request.Validate(); err != nil {
		return err
	}
	target, err := exactWindowTarget(w)
	if err != nil {
		return err
	}
	version, err := w.server.validateLayouts(ctx, func(yield func(string, int) bool) {
		yield(request.Layout, 1)
	})
	if err != nil {
		return err
	}
	arguments, err := selectLayoutArguments(target, request, version)
	if err != nil {
		return err
	}
	return runWindowLayoutCommand(ctx, w.server, "select-layout", arguments)
}

// layoutPresetNames are the arrangements tmux names, and are accepted on
// every supported version.
var layoutPresetNames = []string{
	"even-horizontal", "even-vertical", "main-horizontal", "main-vertical", "tiled",
}

// layoutPresets are the arrangements tmux names, and are accepted on every
// supported version.
var layoutPresets = presetSet(layoutPresetNames)

// layoutMirroredPresetNames are the arrangements tmux added at 3.5, which put
// the main pane on the far side. Below that they are names tmux does not
// know, and an unrecognised name is what the check below exists to stop.
var layoutMirroredPresetNames = []string{
	"main-horizontal-mirrored", "main-vertical-mirrored",
}

// layoutMirroredPresets are the arrangements tmux added at 3.5, which put the
// main pane on the far side. Below that they are names tmux does not know, and
// an unrecognised name is what the check below exists to stop.
var layoutMirroredPresets = presetSet(layoutMirroredPresetNames)

// layoutAllPresetNames is every preset name this package knows on any
// version, for resolving a prefix against - version-gating which of them are
// valid candidates happens separately.
var layoutAllPresetNames = append(slices.Clone(layoutPresetNames), layoutMirroredPresetNames...)

func presetSet(names []string) map[string]bool {
	set := make(map[string]bool, len(names))
	for _, name := range names {
		set[name] = true
	}
	return set
}

// layoutNeedsVersion reports whether resolving layout requires knowing the
// connected tmux's version: the JSON shape and the mirrored presets both
// depend on it, and so does any prefix that could match a mirrored preset
// name, because whether that candidate exists changes the resolution. An
// exact base preset name, a classic checksum-prefixed layout string, a
// prefix that can only ever match a base preset name, and garbage that
// prefixes nothing all skip the round trip.
func layoutNeedsVersion(value string) bool {
	if value == "" || isClassicLayout(value) || layoutPresets[value] {
		return false
	}
	if layoutLooksLikeJSON(value) || layoutMirroredPresets[value] {
		return true
	}
	for _, preset := range layoutMirroredPresetNames {
		if strings.HasPrefix(preset, value) {
			return true
		}
	}
	return false
}

var layoutMirroredVersion = Version{raw: "3.5", major: 3, minor: 5}

// layoutJSONVersion is the earliest build measured to report #{window_layout}
// as a JSON subset for non-control clients and to accept that shape back in
// select-layout, alongside the classic grammar it still accepts: 3.8-rc2.
// tmux CHANGES, 3.7c to 3.8: "Layout strings now use a JSON subset format
// which includes floating panes. The old format is still accepted."
var layoutJSONVersion = Version{raw: "3.8-rc2", major: 3, minor: 8, candidate: 3}

func isClassicLayout(value string) bool {
	_, valid := layout.Cells(value)
	return valid
}

// layoutLooksLikeJSON reports whether layout is shaped like the JSON layout
// tmux 3.8+ reports from #{window_layout} and accepts back from
// select-layout. It checks only the outer envelope - this package treats a
// layout as an opaque string tmux hands back and forth, never a structure to
// parse - so a caller's own well-formed JSON round-trips exactly like tmux's.
func layoutLooksLikeJSON(layout string) bool {
	trimmed := strings.TrimSpace(layout)
	if !strings.HasPrefix(trimmed, "{") {
		return false
	}
	return json.Valid([]byte(layout))
}

// layoutPanePattern matches one layout cell that holds a pane. tmux dumps such
// a cell as width x height, offsets, and the pane's own number; cells that only
// arrange other cells stop after the offsets. It never matches inside the JSON
// shape, which carries no such comma-joined run.
var layoutPanePattern = regexp.MustCompile(`[0-9]+x[0-9]+,-?[0-9]+,-?[0-9]+,([0-9]+)`)

// layoutJSONPanePattern matches one pane's id in the JSON layout shape. Unlike
// the classic grammar's bare pane number, the JSON id already carries its %
// sigil.
var layoutJSONPanePattern = regexp.MustCompile(`"I":"(%[0-9]+)"`)

// layoutListsPane reports whether layout still arranges pane. A layout holding
// no readable cell reports true, so an arrangement this does not recognise is
// never mistaken for a pane that closed.
func layoutListsPane(layout string, pane PaneID) bool {
	if layoutLooksLikeJSON(layout) {
		ids := layoutJSONPanePattern.FindAllStringSubmatch(layout, -1)
		if len(ids) == 0 {
			return true
		}
		return slices.ContainsFunc(ids, func(id []string) bool {
			return PaneID(id[1]) == pane
		})
	}
	cells := layoutPanePattern.FindAllStringSubmatch(layout, -1)
	if len(cells) == 0 {
		return true
	}
	return slices.ContainsFunc(cells, func(cell []string) bool {
		return PaneID("%"+cell[1]) == pane
	})
}

// validateLayout resolves layout against the presets valid on version and
// returns the exact string to send tmux. tmux's own layout_set_lookup is
// already a prefix match, so a unique prefix ("tile", "even-h") applies on
// every version and can never reach layout_parse, the 3.3a crash path; this
// accepts one and refuses an ambiguous prefix by naming its candidates,
// rather than forwarding an ambiguous or unrecognised value for tmux itself
// to reject. A resolved preset's canonical full name is what reaches tmux,
// never the prefix the caller typed, so tmux's own resolution never runs on
// a value this package already classified.
//
// tmux 3.3a exited the server for an unknown layout instead of returning an
// error, so an unrecognised name is refused on every version, not only 3.3a.
func validateLayout(value string, version Version) (string, error) {
	if value == "" || isClassicLayout(value) {
		return value, nil
	}
	if layoutPresets[value] {
		return value, nil
	}
	if layoutMirroredPresets[value] {
		if version.AtLeast(layoutMirroredVersion) {
			return value, nil
		}
		return "", &VersionTooLowError{Current: version, Minimum: layoutMirroredVersion}
	}
	if layoutLooksLikeJSON(value) {
		if version.AtLeast(layoutJSONVersion) {
			return value, nil
		}
		return "", &VersionTooLowError{Current: version, Minimum: layoutJSONVersion}
	}
	candidates := layoutPresetNames
	if version.AtLeast(layoutMirroredVersion) {
		candidates = layoutAllPresetNames
	}
	var matches []string
	for _, candidate := range candidates {
		if strings.HasPrefix(candidate, value) {
			matches = append(matches, candidate)
		}
	}
	switch len(matches) {
	case 1:
		return matches[0], nil
	case 0:
		if !version.AtLeast(layoutMirroredVersion) {
			for _, candidate := range layoutMirroredPresetNames {
				if strings.HasPrefix(candidate, value) {
					return "", &VersionTooLowError{Current: version, Minimum: layoutMirroredVersion}
				}
			}
		}
		return "", invalidServerCommandRequest(
			"select-layout",
			"Layout",
			value,
			"is neither a layout preset nor a tmux layout string; refused on "+
				"every version, since tmux 3.3a once exited the server and "+
				"destroyed every session on the socket for exactly this",
		)
	default:
		return "", invalidServerCommandRequest(
			"select-layout",
			"Layout",
			value,
			"is ambiguous among "+strings.Join(matches, ", ")+"; use one of those exact spellings",
		)
	}
}

// selectLayoutArguments renders one select-layout argument vector. It performs
// no I/O, so a [Plan] can render a layout it has not applied.
func selectLayoutArguments(
	target string,
	request SelectLayoutRequest,
	version Version,
) ([]string, error) {
	if err := validateServerCommandArgument("select-layout", "Target", target, true); err != nil {
		return nil, err
	}
	if err := request.Validate(); err != nil {
		return nil, err
	}
	resolvedLayout, err := validateLayout(request.Layout, version)
	if err != nil {
		return nil, err
	}

	arguments := []string{"select-layout", "-t", target}
	switch {
	case request.Layout != "":
		arguments = append(arguments, resolvedLayout)
	case request.Spread:
		arguments = append(arguments, "-E")
	case request.Next:
		arguments = append(arguments, "-n")
	case request.Previous:
		arguments = append(arguments, "-p")
	}
	return arguments, nil
}

// NextLayout applies the next preset layout to the receiver's exact winlink.
// It changes pane geometry without selecting or refreshing the window. A
// transport or context error can be delivery-ambiguous; the void result cannot
// carry partial state and no rollback is attempted.
func (w Window) NextLayout(ctx context.Context) error {
	target, err := exactWindowTarget(w)
	if err != nil {
		return err
	}
	return runWindowLayoutCommand(
		ctx,
		w.server,
		"next-layout",
		[]string{"next-layout", "-t", target},
	)
}

// PreviousLayout applies the previous preset layout to the receiver's exact
// winlink. It changes pane geometry without selecting or refreshing the
// window. A transport or context error can be delivery-ambiguous; the void
// result cannot carry partial state and no rollback is attempted.
func (w Window) PreviousLayout(ctx context.Context) error {
	target, err := exactWindowTarget(w)
	if err != nil {
		return err
	}
	return runWindowLayoutCommand(
		ctx,
		w.server,
		"previous-layout",
		[]string{"previous-layout", "-t", target},
	)
}

func runWindowLayoutCommand(
	ctx context.Context,
	server Server,
	subcommand string,
	arguments []string,
) error {
	result, err := server.literalCmd(ctx, arguments...)
	return requireServerCommandNoStderr(subcommand, result, err)
}

tmux/window_lifecycle.go.content:
package tmux

import (
	"context"
	"fmt"
	"maps"
	"strconv"
	"strings"
)

// NewWindowRequest configures window creation on tmux 3.3a or later. Its zero
// value uses inherited defaults; placement behavior depends on the receiver.
// [Session.NewWindow] uses tmux's next free index. [Window.NewWindow] instead
// targets the receiver's occupied index and normally returns a command error;
// KillExisting may replace it. [Window.NewWindow] rejects Index. SelectExisting
// may run name-expansion probes before creation.
//
// Pointer fields are explicit when nonnil. Methods copy them and Environment
// before I/O; concurrent mutation during the copy is unsafe.
type NewWindowRequest struct {
	// Name is omitted when nil. A nonnil empty string remains an explicit
	// -n operand. The value is copied before tmux is called.
	Name *string
	// Attach lets the created or selected winlink become current in the target
	// session; false preserves its current window.
	Attach bool
	// Index selects an explicit nonnegative winlink index for
	// Session.NewWindow; nil uses the next free index.
	Index *int
	// StartDirectory expands ~ and ~/... for the current user. Named-user
	// forms such as ~other are rejected; empty inherits tmux's default.
	// A directory that does not exist is not an error: tmux starts the
	// process in the home directory instead, or in / without one.
	StartDirectory string
	// Command starts the window with this shell command; empty uses tmux's
	// default command.
	Command string
	// Environment is emitted in lexically sorted key order. The map is not
	// retained; nil and an empty map both add no entries.
	Environment map[string]string
	// Direction places the new winlink relative to the target. Its zero value
	// uses tmux's next free index with Session.NewWindow when Index is nil, but
	// keeps Window.NewWindow on the receiver's occupied target. Use
	// NewWindowDirectionAfter or NewWindowDirectionBefore for non-destructive
	// relative creation through Window.NewWindow.
	Direction NewWindowDirection
	// KillExisting asks tmux to destroy a window occupying the target index.
	KillExisting bool
	// SelectExisting asks tmux to select an existing expanded-name match instead
	// of creating another window. It requires Name.
	SelectExisting bool
}

// NewWindowDirection selects placement relative to the target winlink on every
// supported tmux. Its zero value lets [Session.NewWindow] with nil Index use the
// next free index, while [Window.NewWindow] keeps the receiver's exact occupied
// target.
type NewWindowDirection uint8

// Supported new-window placements.
const (
	// NewWindowDirectionDefault uses the next free index with Session.NewWindow
	// when Index is nil; Window.NewWindow instead keeps the receiver's exact
	// occupied target.
	NewWindowDirectionDefault NewWindowDirection = iota
	// NewWindowDirectionAfter places the new winlink after the target.
	NewWindowDirectionAfter
	// NewWindowDirectionBefore places the new winlink before the target.
	NewWindowDirectionBefore
)

// NewWindow creates a winlink in the receiver session. Attach selects it as
// that session's current window; it is not a guarantee about clients attached
// to other sessions. The returned [Window] is freshly materialized in the
// receiver's exact session context, including when its stable [WindowID] is
// linked elsewhere.
//
// SelectExisting no-output recovery is available only when Index is nil. It
// expands Name with tmux's version-specific rules and requires exactly one
// matching window name in the receiver session. An explicit Index has no such
// recovery. If tmux reports a WindowID before a transport or refresh failure,
// the partial result contains that ID and the receiver SessionID with Index -1.
// Other failures return zero; creation is not rolled back.
func (s Session) NewWindow(ctx context.Context, request NewWindowRequest) (Window, error) {
	request = captureNewWindowRequest(request)
	target := s.sessionID.String()
	if request.Index != nil {
		target += ":" + strconv.Itoa(*request.Index)
	}
	return newWindow(ctx, s.server, s.sessionID, target, request, request.Index == nil, "")
}

// NewWindow creates a window relative to the receiver's exact winlink. Set
// Direction to [NewWindowDirectionAfter] or [NewWindowDirectionBefore] for
// non-destructive relative creation. With the zero Direction, tmux targets the
// receiver's occupied index and normally returns a command error;
// KillExisting can destroy and replace that target. Attach changes the current
// window only in that target session. Index is rejected before execution
// because the receiver already supplies the target position. On tmux 3.8 and
// later, SelectExisting's -S also matches the receiver's own exact target
// (extended there to match -t as well as a window's name), so it always
// selects the receiver itself and prints nothing; the identity is already
// known without a probe. Earlier tmux only matched -S by name here, and
// always printed a created WindowID because the exact-target form never
// carries a bare name to match against.
//
// If tmux reports an ID before a transport or refresh failure, the partial result
// contains it and the receiver SessionID with Index -1. Other failures return
// zero; creation is not rolled back.
func (w Window) NewWindow(ctx context.Context, request NewWindowRequest) (Window, error) {
	request = captureNewWindowRequest(request)
	if request.Index != nil {
		return Window{}, invalidLifecycleRequest("Index cannot be used with Window.NewWindow")
	}
	target, err := exactWindowTarget(w)
	if err != nil {
		return Window{}, err
	}
	return newWindow(ctx, w.server, w.sessionID, target, request, false, w.windowID)
}

// newWindowArguments renders one new-window argument vector. It performs no
// I/O, so a [Plan] can render a window it has not created.
func newWindowArguments(
	target string,
	request NewWindowRequest,
) ([]string, error) {
	name := ""
	if request.Name != nil {
		name = *request.Name
	}
	if err := validateServerCommandArguments(
		"new-window",
		serverCommandArgument{field: "Name", value: name},
		serverCommandArgument{field: "StartDirectory", value: request.StartDirectory},
		serverCommandArgument{field: "Command", value: request.Command},
		serverCommandArgument{field: "Target", value: target},
	); err != nil {
		return nil, err
	}
	if request.Index != nil && *request.Index < 0 {
		return nil, invalidLifecycleRequest("Index must be nonnegative")
	}
	if request.Direction > NewWindowDirectionBefore {
		return nil, invalidLifecycleRequest("unsupported new window direction")
	}
	if request.SelectExisting && request.Name == nil {
		return nil, invalidLifecycleRequest("SelectExisting requires Name")
	}
	environment, err := lifecycleEnvironmentArguments(request.Environment)
	if err != nil {
		return nil, err
	}
	startDirectory, err := expandLifecycleDirectory(request.StartDirectory)
	if err != nil {
		return nil, err
	}

	arguments := []string{"new-window", "-t", target}
	if !request.Attach {
		arguments = append(arguments, "-d")
	}
	arguments = append(arguments, "-P")
	if startDirectory != "" {
		arguments = append(arguments, "-c"+startDirectory)
	}
	arguments = append(arguments, "-F#{window_id}")
	if request.Name != nil {
		arguments = append(arguments, "-n", name)
	}
	arguments = append(arguments, environment...)
	switch request.Direction {
	case NewWindowDirectionDefault:
	case NewWindowDirectionAfter:
		arguments = append(arguments, "-a")
	case NewWindowDirectionBefore:
		arguments = append(arguments, "-b")
	}
	if request.KillExisting {
		arguments = append(arguments, "-k")
	}
	if request.SelectExisting {
		arguments = append(arguments, "-S")
	}
	if request.Command != "" {
		arguments = append(arguments, "--", request.Command)
	}
	return arguments, nil
}

func newWindow(
	ctx context.Context,
	server Server,
	sessionID SessionID,
	target string,
	request NewWindowRequest,
	selectExistingEligible bool,
	// exactTargetWindowID is the receiver's own WindowID when target names an
	// exact window (Window.NewWindow), empty otherwise (Session.NewWindow).
	// It resolves -S's no-output selection on tmux 3.8+ without a probe: the
	// window tmux selected there can only be the receiver itself.
	exactTargetWindowID WindowID,
) (Window, error) {
	name := ""
	if request.Name != nil {
		name = *request.Name
	}
	if err := validateTypedTarget(
		"new-window", "Target", "session", sessionID.String(),
	); err != nil {
		return Window{}, err
	}
	// Rendered before the name probe below, so a request tmux would refuse is
	// refused without reading anything first.
	arguments, err := newWindowArguments(target, request)
	if err != nil {
		return Window{}, err
	}
	selectionName := ""
	if request.SelectExisting && selectExistingEligible {
		selectionName, err = newWindowSelectionName(ctx, server, target, name)
		if err != nil {
			return Window{}, err
		}
	}
	result, err := server.literalCmd(ctx, arguments...)
	if err != nil {
		if identity, identityErr := lifecycleStableIdentity("window", result.Stdout); identityErr == nil {
			return Window{
				server: server, sessionID: sessionID,
				windowID: WindowID(identity), windowIndex: -1,
			}, err
		}
		return Window{}, err
	}
	result, err = requireRedactedLifecycleSuccess("new-window", result, nil)
	if err != nil {
		return Window{}, err
	}
	if len(result.Stdout) == 0 && request.SelectExisting {
		switch {
		case selectExistingEligible:
			return selectedExistingWindow(ctx, server, sessionID, selectionName)
		case exactTargetWindowID != "":
			// tmux 3.8 extended -S to match an exact -t target, not only a
			// window name (cmd-new-window.c, 3.7c to 3.8-rc: idx != -1 now
			// selects winlink_find_by_index(idx) before falling back to name
			// matching). The receiver's own target always resolves to
			// itself, so tmux selects the receiver and prints nothing.
			return refreshCreatedWindow(ctx, server, sessionID, exactTargetWindowID)
		}
	}
	identity, err := lifecycleStableIdentity("window", result.Stdout)
	if err != nil {
		return Window{}, err
	}
	predicted := Window{
		server: server, sessionID: sessionID,
		windowID: WindowID(identity), windowIndex: -1,
	}
	window, err := refreshCreatedWindow(ctx, server, sessionID, predicted.windowID)
	if err != nil {
		return predicted, err
	}
	return window, nil
}

func newWindowSelectionName(
	ctx context.Context,
	server Server,
	target string,
	name string,
) (string, error) {
	version, err := server.Version(ctx)
	if err != nil {
		return "", err
	}
	version34 := Version{raw: "3.4", major: 3, minor: 4}
	version37 := Version{raw: "3.7", major: 3, minor: 7}
	if !version.AtLeast(version34) {
		return name, nil
	}
	name, err = expandNewWindowSelectionName(ctx, server, target, name)
	if err != nil {
		return "", err
	}
	if !version.AtLeast(version37) {
		return name, nil
	}
	// tmux 3.7 added clean_name between two format expansions. For valid
	// window names its observable transformation is escaping backslashes.
	name = strings.ReplaceAll(name, `\`, `\\`)
	return expandNewWindowSelectionName(ctx, server, target, name)
}

func expandNewWindowSelectionName(
	ctx context.Context,
	server Server,
	target string,
	name string,
) (string, error) {
	result, err := server.literalCmd(ctx, "display-message", "-p", "-t", target, "-F", name)
	result, err = requireRedactedLifecycleSuccess("display-message", result, err)
	if err != nil {
		return "", err
	}
	if len(result.Stdout) != 1 {
		return "", fmt.Errorf(
			"%w: window name expansion printed %d lines",
			ErrInvalidCommandOutput,
			len(result.Stdout),
		)
	}
	return result.Stdout[0], nil
}

func selectedExistingWindow(
	ctx context.Context,
	server Server,
	sessionID SessionID,
	name string,
) (Window, error) {
	windows, err := (Session{server: server, sessionID: sessionID}).SearchWindows(ctx, nil)
	if err != nil {
		return Window{}, err
	}
	matches := make([]Window, 0, 1)
	for _, window := range windows {
		windowName, ok := window.Name()
		if ok && windowName == name {
			matches = append(matches, window)
		}
	}
	if len(matches) != 1 {
		return Window{}, fmt.Errorf(
			"%w: selected window lookup returned %d matches",
			ErrInvalidCommandOutput,
			len(matches),
		)
	}
	return matches[0], nil
}

// Rename changes the stable window through the receiver's exact winlink and
// returns a canonical freshly materialized [Window]. The returned winlink may
// therefore use another session when the WindowID is linked. If the command
// succeeds but refresh fails, Rename returns the receiver with that error. A
// transport or context error can be delivery-ambiguous; no rollback is
// attempted.
func (w Window) Rename(ctx context.Context, name string) (Window, error) {
	if err := validateServerCommandArguments(
		"rename-window",
		serverCommandArgument{field: "Target", value: w.windowID.String()},
		serverCommandArgument{field: "Name", value: name},
	); err != nil {
		return Window{}, err
	}
	target, err := exactWindowTarget(w)
	if err != nil {
		return Window{}, err
	}
	result, err := w.server.literalCmd(ctx, "rename-window", "-t", target, "--", name)
	if _, err = requireLifecycleSuccess("rename-window", result, err); err != nil {
		return Window{}, err
	}
	refreshed, err := w.Refresh(ctx)
	if err != nil {
		return w, err
	}
	return refreshed, nil
}

// Select makes the receiver's exact winlink current in its session. It does
// not promise focus for clients attached to other sessions. Select returns a
// canonical freshly materialized [Window], which may use another linked
// session for the same WindowID. If the command succeeds but refresh fails, it
// returns the receiver with that error. A transport or context error can be
// delivery-ambiguous; no rollback is attempted.
func (w Window) Select(ctx context.Context) (Window, error) {
	target, err := exactWindowTarget(w)
	if err != nil {
		return Window{}, err
	}
	result, err := w.server.literalCmd(ctx, "select-window", "-t", target)
	if _, err = requireLifecycleSuccess("select-window", result, err); err != nil {
		return Window{}, err
	}
	refreshed, err := w.Refresh(ctx)
	if err != nil {
		return w, err
	}
	return refreshed, nil
}

func captureNewWindowRequest(request NewWindowRequest) NewWindowRequest {
	request.Name = copyOptionalString(request.Name)
	request.Index = copyOptionalInt(request.Index)
	request.Environment = maps.Clone(request.Environment)
	return request
}

tmux/window_link_move.go.content:
package tmux

import (
	"context"
	"strconv"
)

// LinkWindowRequest configures linking a window into another session on every
// supported tmux. Its zero value is invalid because TargetSession is required.
// Nil TargetIndex asks tmux for a destination index; a nonnil value is
// explicit and must be nonnegative. After and Before are mutually exclusive
// and are rejected before execution. TargetIndex is read during the call and
// is not retained; callers must not mutate it concurrently.
type LinkWindowRequest struct {
	// TargetSession identifies the destination session in the receiver's tmux
	// server.
	TargetSession SessionID
	// TargetIndex selects a destination winlink index; nil lets tmux choose.
	TargetIndex *int
	// KillExisting destroys a window already occupying the destination.
	KillExisting bool
	// After inserts the new winlink after the destination target.
	After bool
	// Before inserts the new winlink before the destination target.
	Before bool
	// Detach leaves the target session's current window unchanged.
	Detach bool
}

// UnlinkWindowRequest configures unlinking one exact winlink on tmux 3.3a or
// later. Its zero value removes the link only when the stable window has
// another link. The request contains no retained caller-owned storage and has
// no invalid field combinations.
type UnlinkWindowRequest struct {
	// KillIfLast permits unlinking and destroying a stable window with no other
	// links.
	KillIfLast bool
}

// MoveWindowRequest configures moving one exact winlink on tmux 3.3a or later.
// Its zero value moves the receiver within its current session to a tmux-chosen
// index and lets the moved winlink become current. Nil TargetIndex asks tmux
// for that index; a nonnil value is explicit and must be nonnegative. After
// and Before are mutually exclusive. Renumber is a standalone mode mutually
// exclusive with TargetIndex, After, Before, NoSelect, and KillTarget. Invalid
// combinations are rejected before execution. TargetIndex is read during the
// call and is not retained; callers must not mutate it concurrently.
type MoveWindowRequest struct {
	// TargetSession identifies the destination session; zero uses the receiver
	// session.
	TargetSession SessionID
	// TargetIndex selects a destination winlink index; nil lets tmux choose.
	TargetIndex *int
	// After inserts the moved winlink after the destination target.
	After bool
	// Before inserts the moved winlink before the destination target.
	Before bool
	// NoSelect leaves the destination session's current window unchanged.
	NoSelect bool
	// KillTarget destroys a window already occupying the destination.
	KillTarget bool
	// Renumber renumbers the target session according to its base-index option
	// instead of moving the receiver to a new destination.
	Renumber bool
}

// Link adds the stable window to TargetSession as another winlink, targeting
// the source through the receiver's exact session. Unless Detach is set, tmux
// makes the new link current in the target session; this is not a global
// client-focus guarantee. Link does not refresh or mutate the materialized
// source [Window]. A transport or context error can be delivery-ambiguous; the
// void result cannot carry the new winlink identity and no rollback is
// attempted.
func (w Window) Link(ctx context.Context, request LinkWindowRequest) error {
	source, err := exactWindowTarget(w)
	if err != nil {
		return err
	}
	if err := validateTypedTarget(
		"link-window", "TargetSession", "session", request.TargetSession.String(),
	); err != nil {
		return err
	}
	if request.TargetIndex != nil && *request.TargetIndex < 0 {
		return invalidWindowIndex("link-window", *request.TargetIndex)
	}
	if request.After && request.Before {
		return invalidServerCommandRequest(
			"link-window",
			"Position",
			"",
			"After and Before are mutually exclusive",
		)
	}

	arguments, err := linkWindowArguments(request.TargetSession.String(), source, request)
	if err != nil {
		return err
	}

	result, err := w.server.literalCmd(ctx, arguments...)
	return requireServerCommandNoStderr("link-window", result, err)
}

// linkWindowArguments renders one link-window argument vector, linking source
// into destination. It performs no I/O, so a [Plan] can render a link it has not
// made. destination carries the session, and TargetIndex the position in it.
func linkWindowArguments(
	destination string,
	source string,
	request LinkWindowRequest,
) ([]string, error) {
	if request.TargetIndex != nil && *request.TargetIndex < 0 {
		return nil, invalidWindowIndex("link-window", *request.TargetIndex)
	}
	if request.After && request.Before {
		return nil, invalidServerCommandRequest(
			"link-window",
			"Position",
			"",
			"After and Before are mutually exclusive",
		)
	}
	arguments := []string{"link-window"}
	if request.KillExisting {
		arguments = append(arguments, "-k")
	}
	if request.After {
		arguments = append(arguments, "-a")
	}
	if request.Before {
		arguments = append(arguments, "-b")
	}
	if request.Detach {
		arguments = append(arguments, "-d")
	}
	target := destination
	if request.TargetIndex != nil {
		target += ":" + strconv.Itoa(*request.TargetIndex)
	}
	return append(arguments, "-s", source, "-t", target), nil
}

// Unlink removes the receiver's exact session winlink without refreshing the
// materialized receiver. Without KillIfLast, tmux rejects removal of a stable
// window's only link; with it, that window is destroyed. A transport or
// context error can be delivery-ambiguous; the void result cannot carry
// partial identity and no rollback is attempted.
func (w Window) Unlink(ctx context.Context, request UnlinkWindowRequest) error {
	target, err := exactWindowTarget(w)
	if err != nil {
		return err
	}
	arguments := []string{"unlink-window"}
	if request.KillIfLast {
		arguments = append(arguments, "-k")
	}
	arguments = append(arguments, "-t", target)

	result, err := w.server.literalCmd(ctx, arguments...)
	return requireServerCommandNoStderr("unlink-window", result, err)
}

// Move removes the receiver's exact winlink and places it in TargetSession, or
// renumbers the selected session when Renumber is set. Unless NoSelect is set,
// tmux makes the moved winlink current in the destination session; this is not
// a global client-focus guarantee. The stable WindowID does not by itself
// identify either linked view.
//
// Move returns a canonical freshly materialized [Window], which may use a
// different linked session than the destination. If the command succeeds but
// refresh fails, it returns the receiver with that error. Earlier failures
// return zero; transport errors are delivery-ambiguous.
func (w Window) Move(ctx context.Context, request MoveWindowRequest) (Window, error) {
	source, err := exactWindowTarget(w)
	if err != nil {
		return Window{}, err
	}
	targetSession := request.TargetSession
	if targetSession == "" {
		targetSession = w.sessionID
	}
	if err := validateTypedTarget(
		"move-window", "TargetSession", "session", targetSession.String(),
	); err != nil {
		return Window{}, err
	}
	if request.TargetIndex != nil && *request.TargetIndex < 0 {
		return Window{}, invalidWindowIndex("move-window", *request.TargetIndex)
	}
	if request.After && request.Before {
		return Window{}, invalidServerCommandRequest(
			"move-window",
			"Position",
			"",
			"After and Before are mutually exclusive",
		)
	}
	if request.Renumber && (request.TargetIndex != nil || request.After || request.Before ||
		request.NoSelect || request.KillTarget) {
		return Window{}, invalidServerCommandRequest(
			"move-window",
			"Renumber",
			"true",
			"is mutually exclusive with move options",
		)
	}

	arguments, err := moveWindowArguments(targetSession.String(), source, request)
	if err != nil {
		return Window{}, err
	}

	result, err := w.server.literalCmd(ctx, arguments...)
	if err := requireServerCommandNoStderr("move-window", result, err); err != nil {
		return Window{}, err
	}
	refreshed, err := w.Refresh(ctx)
	if err != nil {
		return w, err
	}
	return refreshed, nil
}

func invalidWindowIndex(subcommand string, index int) error {
	return invalidServerCommandRequest(
		subcommand,
		"TargetIndex",
		strconv.Itoa(index),
		"must be nonnegative",
	)
}

// moveWindowArguments renders one move-window argument vector, moving source
// into destination. It performs no I/O, so a [Plan] can render a move it has not
// made. destination carries the session, and TargetIndex the position in it.
func moveWindowArguments(
	destination string,
	source string,
	request MoveWindowRequest,
) ([]string, error) {
	if request.TargetIndex != nil && *request.TargetIndex < 0 {
		return nil, invalidWindowIndex("move-window", *request.TargetIndex)
	}
	if request.After && request.Before {
		return nil, invalidServerCommandRequest(
			"move-window", "Position", "", "After and Before are mutually exclusive",
		)
	}
	if request.Renumber && (request.After || request.Before || request.KillTarget ||
		request.TargetIndex != nil) {
		return nil, invalidServerCommandRequest(
			"move-window", "Renumber", "true", "is mutually exclusive with move options",
		)
	}

	arguments := []string{"move-window"}
	if request.After {
		arguments = append(arguments, "-a")
	}
	if request.Before {
		arguments = append(arguments, "-b")
	}
	if request.NoSelect {
		arguments = append(arguments, "-d")
	}
	if request.KillTarget {
		arguments = append(arguments, "-k")
	}
	if request.Renumber {
		arguments = append(arguments, "-r")
	}
	target := destination
	if !request.Renumber {
		target += ":"
		if request.TargetIndex != nil {
			target += strconv.Itoa(*request.TargetIndex)
		}
	}
	return append(arguments, "-s", source, "-t", target), nil
}

tmux/window_pane_swap.go.content:
package tmux

import "context"

// SwapWindowRequest configures swapping the receiver with one exact winlink on
// tmux 3.3a or later. Its zero value is invalid because Target must be a
// complete Window handle. The endpoints must be proven to share a daemon
// through connection state or the same nonempty SocketPath; matching socket
// names alone are insufficient. Validation completes before execution.
type SwapWindowRequest struct {
	// Target is the exact other winlink to swap with the receiver.
	Target Window
	// Detach leaves the affected sessions' current-window selection unchanged.
	Detach bool
}

// WindowSwapResult contains both original stable window identities in their
// post-swap exact winlink views. Its zero value contains no usable endpoints.
type WindowSwapResult struct {
	// Window is the receiver's original WindowID at its post-swap exact winlink.
	Window Window
	// Target is the target's original WindowID at its post-swap exact winlink.
	Target Window
}

// SwapPaneDirection selects an adjacent pane for swap-pane on tmux 3.3a or
// later. Its zero value selects no adjacent pane.
type SwapPaneDirection uint8

// Supported adjacent-pane swap directions.
const (
	// SwapPaneDirectionNone selects no adjacent pane.
	SwapPaneDirectionNone SwapPaneDirection = iota
	// SwapPaneDirectionUp swaps with the previous pane in index order.
	SwapPaneDirectionUp
	// SwapPaneDirectionDown swaps with the next pane in index order.
	SwapPaneDirectionDown
)

// SwapPaneRequest configures swapping with an exact or adjacent pane on every
// supported tmux. Its zero value is invalid: exactly one complete Target or
// Direction is required. An explicit Target must differ from the receiver and
// must be proven to share a daemon through connection state or the same
// nonempty SocketPath; matching socket names alone are insufficient. Invalid
// choices are rejected before execution.
type SwapPaneRequest struct {
	// Target selects an exact other pane; a zero Pane omits it.
	Target Pane
	// Direction selects an adjacent pane; zero omits it.
	Direction SwapPaneDirection
	// Detach leaves the active-pane selection unchanged.
	Detach bool
	// KeepZoom preserves the affected window's zoomed state.
	KeepZoom bool
}

// PaneSwapResult contains original stable pane identities in their post-swap
// exact linked-pane views. Its zero value contains no usable endpoints. Target
// is zero for a directional swap because tmux does not report the adjacent
// pane identity.
type PaneSwapResult struct {
	// Pane is the receiver's original PaneID at its post-swap exact view.
	Pane Pane
	// Target is the explicit target's original PaneID at its post-swap exact
	// view, or zero after a directional swap.
	Target Pane
}

// Swap exchanges the receiver and Target exact winlinks. Their stable
// WindowIDs move to the opposite session-and-index views; a WindowID alone
// does not identify either endpoint. Unless Detach is set, tmux may change the
// affected sessions' current-window selection; this is not a global
// client-focus guarantee.
//
// Swap returns both freshly materialized exact endpoint views. If exact
// refresh fails after the command, it returns a predicted [WindowSwapResult]
// carrying both stable IDs and post-swap session/index contexts with the
// error. Earlier failures return zero; transport errors are delivery-ambiguous.
func (w Window) Swap(ctx context.Context, request SwapWindowRequest) (WindowSwapResult, error) {
	receiverTarget, err := exactWindowTarget(w)
	if err != nil {
		return WindowSwapResult{}, err
	}
	if err := requireTopologyServer(w.server, request.Target.server); err != nil {
		return WindowSwapResult{}, err
	}
	target, err := exactWindowTarget(request.Target)
	if err != nil {
		return WindowSwapResult{}, err
	}
	arguments := []string{"swap-window", "-t", receiverTarget}
	if request.Detach {
		arguments = append(arguments, "-d")
	}
	arguments = append(arguments, "-s", target)
	result, err := w.server.literalCmd(ctx, arguments...)
	if _, err = requireLifecycleSuccess("swap-window", result, err); err != nil {
		return WindowSwapResult{}, err
	}
	predicted := WindowSwapResult{
		Window: Window{
			server: w.server, sessionID: request.Target.sessionID,
			windowID: w.windowID, windowIndex: request.Target.windowIndex,
		},
		Target: Window{
			server: w.server, sessionID: w.sessionID,
			windowID: request.Target.windowID, windowIndex: w.windowIndex,
		},
	}
	if w.windowID == request.Target.windowID {
		predicted.Window.sessionID, predicted.Window.windowIndex = w.sessionID, w.windowIndex
		predicted.Target.sessionID = request.Target.sessionID
		predicted.Target.windowIndex = request.Target.windowIndex
	}
	refreshed, err := refreshExactWindowSwap(ctx, predicted)
	if err != nil {
		return predicted, err
	}
	return refreshed, nil
}

// Swap exchanges the receiver with one exact or adjacent pane. Explicit
// targets use exact linked-pane views; PaneID alone does not distinguish linked
// views. Unless Detach is set, tmux may change active-pane selection; this is
// not a global client-focus guarantee. A directional swap cannot identify the
// adjacent target because tmux does not report it, so the returned
// [PaneSwapResult].Target is zero.
//
// An explicit swap returns freshly materialized exact views for both original
// PaneIDs. If exact refresh fails after the command, Swap returns a predicted
// result carrying every known identity with the error. Earlier failures return
// zero; transport errors are delivery-ambiguous.
func (p Pane) Swap(ctx context.Context, request SwapPaneRequest) (PaneSwapResult, error) {
	receiverTarget, err := exactPaneTarget(p)
	if err != nil {
		return PaneSwapResult{}, err
	}
	if request.Direction > SwapPaneDirectionDown {
		return PaneSwapResult{}, invalidLifecycleRequest("unsupported pane swap direction")
	}
	hasTarget := request.Target.paneID != "" || request.Target.windowID != "" ||
		request.Target.sessionID != ""
	if hasTarget == (request.Direction != SwapPaneDirectionNone) {
		return PaneSwapResult{}, invalidLifecycleRequest("Target and Direction require exactly one choice")
	}
	arguments := []string{"swap-pane", "-t", receiverTarget}
	if request.Detach {
		arguments = append(arguments, "-d")
	}
	switch request.Direction {
	case SwapPaneDirectionNone:
	case SwapPaneDirectionUp:
		arguments = append(arguments, "-U")
	case SwapPaneDirectionDown:
		arguments = append(arguments, "-D")
	}
	if request.KeepZoom {
		arguments = append(arguments, "-Z")
	}
	var target string
	if hasTarget {
		if err := requireTopologyServer(p.server, request.Target.server); err != nil {
			return PaneSwapResult{}, err
		}
		if request.Target.paneID == p.paneID {
			return PaneSwapResult{}, invalidLifecycleRequest("Target must differ from the receiver")
		}
		target, err = exactPaneTarget(request.Target)
		if err != nil {
			return PaneSwapResult{}, err
		}
		arguments = append(arguments, "-s", target)
	}
	result, err := p.server.literalCmd(ctx, arguments...)
	if _, err = requireLifecycleSuccess("swap-pane", result, err); err != nil {
		return PaneSwapResult{}, err
	}
	predicted := PaneSwapResult{Pane: p}
	if hasTarget {
		predicted.Pane = Pane{
			server: p.server, sessionID: request.Target.sessionID,
			windowID: request.Target.windowID, windowIndex: request.Target.windowIndex,
			paneID: p.paneID, paneIndex: request.Target.paneIndex,
		}
		predicted.Target = Pane{
			server: p.server, sessionID: p.sessionID,
			windowID: p.windowID, windowIndex: p.windowIndex,
			paneID: request.Target.paneID, paneIndex: p.paneIndex,
		}
	}
	refreshed, err := refreshExactPaneSwap(ctx, predicted)
	if err != nil {
		return predicted, err
	}
	return refreshed, nil
}

tmux/window_pane_topology.go.content:
package tmux

import "context"

// PaneSelectDirection selects a pane relative to the command target on tmux
// 3.3a or later. Its zero value selects no relative direction.
type PaneSelectDirection uint8

// Supported pane-selection directions.
const (
	// PaneSelectDirectionNone selects no relative pane.
	PaneSelectDirectionNone PaneSelectDirection = iota
	// PaneSelectDirectionUp selects the pane above the target.
	PaneSelectDirectionUp
	// PaneSelectDirectionDown selects the pane below the target.
	PaneSelectDirectionDown
	// PaneSelectDirectionLeft selects the pane to the left of the target.
	PaneSelectDirectionLeft
	// PaneSelectDirectionRight selects the pane to the right of the target.
	PaneSelectDirectionRight
	// PaneSelectDirectionLast selects the previously active pane.
	PaneSelectDirectionLast
)

// PaneMarkMode changes tmux's server-wide marked pane on tmux 3.3a or later.
// Its zero value leaves the mark unchanged.
type PaneMarkMode uint8

// Supported marked-pane changes.
const (
	// PaneMarkUnchanged leaves the server-wide marked pane unchanged.
	PaneMarkUnchanged PaneMarkMode = iota
	// PaneMarkSet makes the target the server-wide marked pane without selecting
	// it.
	PaneMarkSet
	// PaneMarkClear clears the server-wide marked pane without selecting the
	// target.
	PaneMarkClear
)

// PaneInputMode changes whether a pane accepts input on tmux 3.3a or later.
// Its zero value leaves input state unchanged.
type PaneInputMode uint8

// Supported pane-input changes.
const (
	// PaneInputUnchanged leaves the target pane's input state unchanged.
	PaneInputUnchanged PaneInputMode = iota
	// PaneInputDisable disables input without selecting the target pane.
	PaneInputDisable
	// PaneInputEnable enables input without selecting the target pane.
	PaneInputEnable
)

// WindowSelectPaneRequest selects either one exact pane or one relative pane.
// Its zero value is invalid: exactly one of Target and Direction is required.
// Target must be a complete pane handle in the receiver's exact winlink and
// must be proven to share a daemon through connection state or the same
// nonempty SocketPath; matching socket names alone are insufficient. Invalid
// values are rejected before execution.
type WindowSelectPaneRequest struct {
	// Target selects one exact pane in the receiver winlink; a zero Pane omits
	// this choice.
	Target Pane
	// Direction selects a pane relative to the receiver window's active pane;
	// zero omits this choice.
	Direction PaneSelectDirection
	// KeepZoom preserves the window's zoomed state.
	KeepZoom bool
}

// PaneSelectRequest configures select-pane for one exact receiver. Closed
// enums prevent conflicting direction, mark, and input flags. Its zero value
// selects the receiver. Mark rejects every other option. Input rejects
// Direction and KeepZoom because changing input does not select a pane. These
// combinations and enum ranges are validated before execution.
type PaneSelectRequest struct {
	// Direction selects a pane relative to the receiver; zero selects the
	// receiver unless Mark or Input is set.
	Direction PaneSelectDirection
	// KeepZoom preserves the window's zoomed state while selecting.
	KeepZoom bool
	// Mark changes the server-wide marked pane without selecting; zero leaves it
	// unchanged.
	Mark PaneMarkMode
	// Input changes whether the receiver accepts input without selecting; zero
	// leaves input state unchanged.
	Input PaneInputMode
}

// LastPaneRequest configures last-pane on tmux 3.3a or later. Its zero value
// selects the previously active pane. Input and KeepZoom are mutually
// exclusive and are validated before execution; an Input mode changes the
// previous pane's input state without selecting it.
type LastPaneRequest struct {
	// Input changes the previous pane's input state; zero performs selection.
	Input PaneInputMode
	// KeepZoom preserves the window's zoomed state during selection.
	KeepZoom bool
}

// RotateWindowDirection selects rotate-window's direction on tmux 3.3a or
// later. Its zero value uses tmux's default rotation.
type RotateWindowDirection uint8

// Supported window-rotation directions.
const (
	// RotateWindowDefault uses tmux's default rotation.
	RotateWindowDefault RotateWindowDirection = iota
	// RotateWindowUp rotates pane positions toward lower indexes.
	RotateWindowUp
	// RotateWindowDown rotates pane positions toward higher indexes.
	RotateWindowDown
)

// RotateWindowRequest configures rotate-window. Its zero value uses tmux's
// default rotation; enum validation happens before execution.
type RotateWindowRequest struct {
	// Direction selects the rotation direction; zero uses tmux's default.
	Direction RotateWindowDirection
	// KeepZoom preserves the window's zoomed state.
	KeepZoom bool
}

// SelectPane makes an exact or relative pane active in the receiver's exact
// winlink without selecting the window in its session. Target must belong to
// that same SessionID and WindowID; a PaneID alone does not identify a linked
// view. The returned [Pane] is the freshly materialized active pane in the
// receiver context, not a canonical ID-only view.
//
// Command or refresh failures return zero because active-pane selection has no
// reliable partial identity. Transport errors are delivery-ambiguous.
func (w Window) SelectPane(
	ctx context.Context,
	request WindowSelectPaneRequest,
) (Pane, error) {
	windowTarget, err := exactWindowTarget(w)
	if err != nil {
		return Pane{}, err
	}
	if err := validatePaneSelectDirection(request.Direction); err != nil {
		return Pane{}, err
	}
	hasTarget := request.Target.paneID != "" || request.Target.windowID != "" ||
		request.Target.sessionID != ""
	if hasTarget == (request.Direction != PaneSelectDirectionNone) {
		return Pane{}, invalidLifecycleRequest("Target and Direction require exactly one choice")
	}
	target := windowTarget
	arguments := []string{"select-pane", "-t"}
	if hasTarget {
		if err := requireTopologyServer(w.server, request.Target.server); err != nil {
			return Pane{}, err
		}
		if request.Target.sessionID != w.sessionID || request.Target.windowID != w.windowID {
			return Pane{}, invalidLifecycleRequest("Target must belong to the receiver's exact winlink")
		}
		target, err = exactPaneTarget(request.Target)
		if err != nil {
			return Pane{}, err
		}
	}
	arguments = append(arguments, target)
	if request.Direction != PaneSelectDirectionNone {
		arguments = append(arguments, paneSelectDirectionFlag(request.Direction))
	}
	if request.KeepZoom {
		arguments = append(arguments, "-Z")
	}
	result, err := w.server.literalCmd(ctx, arguments...)
	if _, err = requireLifecycleSuccess("select-pane", result, err); err != nil {
		return Pane{}, err
	}
	return refreshExactActivePane(ctx, w)
}

// Select applies select-pane to the receiver's exact linked-pane view.
// Direction makes an adjacent pane active, but the returned [Pane] is a fresh
// exact refresh of the receiver rather than the newly active pane. With no
// Direction, Mark, or Input, the receiver becomes active. Mark changes the
// server-wide marked pane without selection; Input changes the receiver's
// input state without selection. None of these modes selects the window in its
// session or promises client focus.
//
// A refresh failure returns the receiver with the error; earlier failures return zero.
func (p Pane) Select(ctx context.Context, request PaneSelectRequest) (Pane, error) {
	target, err := exactPaneTarget(p)
	if err != nil {
		return Pane{}, err
	}
	arguments, err := paneSelectArguments(target, request)
	if err != nil {
		return Pane{}, err
	}
	result, err := p.server.literalCmd(ctx, arguments...)
	if _, err = requireLifecycleSuccess("select-pane", result, err); err != nil {
		return Pane{}, err
	}
	refreshed, err := refreshExactPane(ctx, p)
	if err != nil {
		return p, err
	}
	return refreshed, nil
}

// LastPane targets the receiver's exact winlink. Its zero request makes the
// previously active pane active without selecting the window in its session.
// With an Input mode, tmux changes the previous pane's input state without
// selecting it; the returned [Pane] is still the freshly materialized active
// pane in the receiver context.
//
// Command or refresh failures return zero because the active view needs refresh.
func (w Window) LastPane(ctx context.Context, request LastPaneRequest) (Pane, error) {
	target, err := exactWindowTarget(w)
	if err != nil {
		return Pane{}, err
	}
	if request.Input > PaneInputEnable {
		return Pane{}, invalidLifecycleRequest("unsupported pane input mode")
	}
	if request.Input != PaneInputUnchanged && request.KeepZoom {
		return Pane{}, invalidLifecycleRequest("Input and KeepZoom are mutually exclusive")
	}
	arguments := []string{"last-pane", "-t", target}
	switch request.Input {
	case PaneInputUnchanged:
	case PaneInputDisable:
		arguments = append(arguments, "-d")
	case PaneInputEnable:
		arguments = append(arguments, "-e")
	}
	if request.KeepZoom {
		arguments = append(arguments, "-Z")
	}
	result, err := w.server.literalCmd(ctx, arguments...)
	if _, err = requireLifecycleSuccess("last-pane", result, err); err != nil {
		return Pane{}, err
	}
	return refreshExactActivePane(ctx, w)
}

// Rotate rotates pane positions in the receiver's exact winlink without
// selecting the window or promising client focus. It returns a freshly
// materialized exact [Window] preserving the receiver SessionID, rather than
// a canonical ID-only view. If the command succeeds but refresh fails, Rotate
// returns the receiver with that error; earlier failures return zero.
func (w Window) Rotate(ctx context.Context, request RotateWindowRequest) (Window, error) {
	target, err := exactWindowTarget(w)
	if err != nil {
		return Window{}, err
	}
	arguments, err := rotateWindowArguments(target, request)
	if err != nil {
		return Window{}, err
	}
	result, err := w.server.literalCmd(ctx, arguments...)
	if _, err = requireLifecycleSuccess("rotate-window", result, err); err != nil {
		return Window{}, err
	}
	refreshed, err := refreshExactWindow(ctx, w)
	if err != nil {
		return w, err
	}
	return refreshed, nil
}

// paneSelectArguments renders one select-pane argument vector. It performs no
// I/O, so a [Plan] can render a selection it has not made.
func paneSelectArguments(
	target string,
	request PaneSelectRequest,
) ([]string, error) {
	if err := validatePaneSelectDirection(request.Direction); err != nil {
		return nil, err
	}
	if request.Mark > PaneMarkClear {
		return nil, invalidLifecycleRequest("unsupported pane mark mode")
	}
	if request.Input > PaneInputEnable {
		return nil, invalidLifecycleRequest("unsupported pane input mode")
	}
	if request.Mark != PaneMarkUnchanged &&
		(request.Direction != PaneSelectDirectionNone || request.KeepZoom ||
			request.Input != PaneInputUnchanged) {
		return nil, invalidLifecycleRequest(
			"Mark is mutually exclusive with selection and input options")
	}
	if request.Input != PaneInputUnchanged &&
		(request.Direction != PaneSelectDirectionNone || request.KeepZoom) {
		return nil, invalidLifecycleRequest(
			"Input is mutually exclusive with selection and KeepZoom")
	}
	arguments, err := targetedArguments("select-pane", target)
	if err != nil {
		return nil, err
	}
	if request.Direction != PaneSelectDirectionNone {
		arguments = append(arguments, paneSelectDirectionFlag(request.Direction))
	}
	if request.KeepZoom {
		arguments = append(arguments, "-Z")
	}
	switch request.Mark {
	case PaneMarkUnchanged:
	case PaneMarkSet:
		arguments = append(arguments, "-m")
	case PaneMarkClear:
		arguments = append(arguments, "-M")
	}
	switch request.Input {
	case PaneInputUnchanged:
	case PaneInputDisable:
		arguments = append(arguments, "-d")
	case PaneInputEnable:
		arguments = append(arguments, "-e")
	}
	return arguments, nil
}

// rotateWindowArguments renders one rotate-window argument vector. It performs
// no I/O, so a [Plan] can render a rotation it has not applied.
func rotateWindowArguments(
	target string,
	request RotateWindowRequest,
) ([]string, error) {
	if request.Direction > RotateWindowDown {
		return nil, invalidLifecycleRequest("unsupported window rotation direction")
	}
	arguments, err := targetedArguments("rotate-window", target)
	if err != nil {
		return nil, err
	}
	switch request.Direction {
	case RotateWindowDefault:
	case RotateWindowUp:
		arguments = append(arguments, "-U")
	case RotateWindowDown:
		arguments = append(arguments, "-D")
	}
	if request.KeepZoom {
		arguments = append(arguments, "-Z")
	}
	return arguments, nil
}

func validatePaneSelectDirection(direction PaneSelectDirection) error {
	if direction > PaneSelectDirectionLast {
		return invalidLifecycleRequest("unsupported pane selection direction")
	}
	return nil
}

func paneSelectDirectionFlag(direction PaneSelectDirection) string {
	switch direction {
	case PaneSelectDirectionNone:
		return ""
	case PaneSelectDirectionUp:
		return "-U"
	case PaneSelectDirectionDown:
		return "-D"
	case PaneSelectDirectionLeft:
		return "-L"
	case PaneSelectDirectionRight:
		return "-R"
	case PaneSelectDirectionLast:
		return "-l"
	}
	return ""
}

func requireTopologyServer(left, right Server) error {
	leftState, err := left.stateForUse()
	if err != nil {
		return err
	}
	rightState, err := right.stateForUse()
	if err != nil {
		return err
	}
	if leftState == rightState {
		return nil
	}
	leftPath := leftState.config.socketSelection.Path
	if leftPath != "" && leftPath == rightState.config.socketSelection.Path {
		return nil
	}
	return invalidLifecycleRequest("source and target are not proven to use the same tmux server")
}

tmux/window_resize.go.content:
package tmux

import (
	"context"
	"strconv"
)

// WindowResizeDirection selects one directional resize operation on tmux 3.3a
// or later. Its zero value selects no directional adjustment.
type WindowResizeDirection uint8

// Supported window resize directions.
const (
	// WindowResizeDirectionNone selects no directional adjustment.
	WindowResizeDirectionNone WindowResizeDirection = iota
	// WindowResizeDirectionUp adjusts the window upward.
	WindowResizeDirectionUp
	// WindowResizeDirectionDown adjusts the window downward.
	WindowResizeDirectionDown
	// WindowResizeDirectionLeft adjusts the window leftward.
	WindowResizeDirectionLeft
	// WindowResizeDirectionRight adjusts the window rightward.
	WindowResizeDirectionRight
)

// ResizeWindowRequest selects one directional, manual, expand, or shrink
// operation. Height and Width may be set together. A zero request asks tmux to
// reapply the current manual size. Direction requires a positive Adjustment;
// that pair, dimensions, Expand, and Shrink are mutually exclusive and are
// validated before execution. Zero Adjustment, Height, and Width omit their
// modes; nonzero values must be positive. The request is supported on every
// supported tmux.
type ResizeWindowRequest struct {
	// Direction selects a directional adjustment; zero selects another mode.
	Direction WindowResizeDirection
	// Adjustment is the required positive amount for Direction; zero omits it.
	Adjustment int
	// Height sets a positive manual height; zero preserves the current height.
	Height int
	// Width sets a positive manual width; zero preserves the current width.
	Width int
	// Expand sets the window to the size of the largest session containing it.
	Expand bool
	// Shrink sets the window to the size of the smallest session containing it.
	Shrink bool
}

// Resize changes the stable window's size through the receiver's exact
// winlink. It does not select the window or promise any client focus. Resize
// returns a canonical freshly materialized [Window], which may use another
// linked session for the same WindowID. If the command succeeds but refresh
// fails, it returns the receiver with that error; other command failures return
// a zero Window. A transport or context error can be delivery-ambiguous and no
// rollback is attempted.
func (w Window) Resize(ctx context.Context, request ResizeWindowRequest) (Window, error) {
	target, err := exactWindowTarget(w)
	if err != nil {
		return Window{}, err
	}
	arguments, err := resizeWindowArguments(target, request)
	if err != nil {
		return Window{}, err
	}

	result, err := w.server.literalCmd(ctx, arguments...)
	if err := requireServerCommandNoStderr("resize-window", result, err); err != nil {
		return Window{}, err
	}
	refreshed, err := w.Refresh(ctx)
	if err != nil {
		return w, err
	}
	return refreshed, nil
}

// resizeWindowArguments renders one resize-window argument vector. It performs
// no I/O, so a [Plan] can render a resize it has not applied.
func resizeWindowArguments(
	target string,
	request ResizeWindowRequest,
) ([]string, error) {
	if err := validateResizeWindowRequest(request); err != nil {
		return nil, err
	}
	arguments, err := targetedArguments("resize-window", target)
	if err != nil {
		return nil, err
	}
	switch {
	case request.Direction != WindowResizeDirectionNone:
		arguments = append(
			arguments,
			windowResizeDirectionFlag(request.Direction),
			strconv.Itoa(request.Adjustment),
		)
	case request.Height != 0 || request.Width != 0:
		if request.Height != 0 {
			arguments = append(arguments, "-y"+strconv.Itoa(request.Height))
		}
		if request.Width != 0 {
			arguments = append(arguments, "-x"+strconv.Itoa(request.Width))
		}
	case request.Expand:
		arguments = append(arguments, "-A")
	case request.Shrink:
		arguments = append(arguments, "-a")
	}
	return arguments, nil
}

func validateResizeWindowRequest(request ResizeWindowRequest) error {
	if request.Direction > WindowResizeDirectionRight {
		return invalidServerCommandRequest(
			"resize-window",
			"Direction",
			strconv.FormatUint(uint64(request.Direction), 10),
			"is unsupported",
		)
	}
	hasDirection := request.Direction != WindowResizeDirectionNone
	hasAdjustment := request.Adjustment != 0
	if hasDirection != hasAdjustment {
		return invalidServerCommandRequest(
			"resize-window",
			"Adjustment",
			"",
			"Direction and Adjustment must be set together",
		)
	}
	if request.Adjustment < 0 {
		return invalidServerCommandRequest(
			"resize-window",
			"Adjustment",
			strconv.Itoa(request.Adjustment),
			"must be positive",
		)
	}
	if request.Height < 0 {
		return invalidServerCommandRequest(
			"resize-window",
			"Height",
			strconv.Itoa(request.Height),
			"must be positive",
		)
	}
	if request.Width < 0 {
		return invalidServerCommandRequest(
			"resize-window",
			"Width",
			strconv.Itoa(request.Width),
			"must be positive",
		)
	}

	modes := 0
	if hasDirection {
		modes++
	}
	if request.Height != 0 || request.Width != 0 {
		modes++
	}
	if request.Expand {
		modes++
	}
	if request.Shrink {
		modes++
	}
	if modes > 1 {
		return invalidServerCommandRequest(
			"resize-window",
			"Mode",
			"",
			"adjustment, dimensions, Expand, and Shrink are mutually exclusive",
		)
	}
	return nil
}

func windowResizeDirectionFlag(direction WindowResizeDirection) string {
	switch direction {
	case WindowResizeDirectionNone:
		return ""
	case WindowResizeDirectionUp:
		return "-U"
	case WindowResizeDirectionDown:
		return "-D"
	case WindowResizeDirectionLeft:
		return "-L"
	case WindowResizeDirectionRight:
		return "-R"
	default:
		return ""
	}
}

tmux/window_respawn.go.content:
package tmux

import (
	"context"
	"maps"
	"slices"
)

// RespawnRequest configures restarting a window's or pane's process on every
// supported tmux. Its zero value reuses the stored command and directory and
// requires the target process to be inactive. Nil pointer fields omit their
// options; nonnil pointers are explicit, including empty strings. There are no
// mutually exclusive fields. Arguments and environment entries are validated
// before execution.
//
// Methods read pointer and map values during argument construction; do not
// mutate them concurrently.
type RespawnRequest struct {
	// Command is omitted when nil so tmux reuses the stored command. A
	// nonnil empty string remains an explicit operand.
	Command *string
	// StartDirectory expands ~ and ~/... for the current user. Nil reuses the
	// stored directory; a nonnil empty string selects the current directory.
	// A directory that does not exist is not an error: tmux starts the
	// process in the home directory instead, or in / without one.
	StartDirectory *string
	// Environment is emitted in lexically sorted key order; nil and an empty map
	// both add no environment entries.
	Environment map[string]string
	// Kill terminates an active target process before restarting it.
	Kill bool
}

// Respawn restarts the stable window process through the receiver's exact
// winlink. It does not select the window or promise any client focus. Respawn
// returns a canonical freshly materialized [Window], which may use another
// linked session for the same WindowID. If the command succeeds but refresh
// fails, it returns the receiver with that error; earlier failures return zero.
// Completed stderr produces a redacted [CommandError]; nonzero exits without
// stderr are followed by refresh.
func (w Window) Respawn(ctx context.Context, request RespawnRequest) (Window, error) {
	target, err := exactWindowTarget(w)
	if err != nil {
		return Window{}, err
	}
	options, err := respawnRequestArguments("respawn-window", request)
	if err != nil {
		return Window{}, err
	}
	arguments := append([]string{"respawn-window", "-t", target}, options...)
	result, err := w.server.literalCmd(ctx, arguments...)
	if err != nil {
		return Window{}, err
	}
	if len(result.Stderr) != 0 {
		return Window{}, newRedactedCommandError("respawn-window", result)
	}
	refreshed, err := w.Refresh(ctx)
	if err != nil {
		return w, err
	}
	return refreshed, nil
}

func respawnRequestArguments(subcommand string, request RespawnRequest) ([]string, error) {
	if request.Command != nil {
		if err := validateServerCommandArgument(subcommand, "Command", *request.Command, true); err != nil {
			return nil, err
		}
	}

	startDirectory := ""
	if request.StartDirectory != nil {
		if err := validateServerCommandArgument(
			subcommand, "StartDirectory", *request.StartDirectory, true,
		); err != nil {
			return nil, err
		}
		startDirectory = *request.StartDirectory
		if startDirectory == "" {
			startDirectory = "."
		}
		var err error
		startDirectory, err = expandLifecycleDirectory(startDirectory)
		if err != nil {
			return nil, err
		}
	}

	keys := slices.Sorted(maps.Keys(request.Environment))
	for _, key := range keys {
		if err := validateEnvironmentName(key); err != nil {
			return nil, err
		}
		if err := validateEnvironmentValue(request.Environment[key]); err != nil {
			return nil, err
		}
	}

	arguments := make([]string, 0, 2+len(keys))
	if request.Kill {
		arguments = append(arguments, "-k")
	}
	if request.StartDirectory != nil {
		arguments = append(arguments, "-c"+startDirectory)
	}
	for _, key := range keys {
		arguments = append(arguments, "-e"+key+"="+request.Environment[key])
	}
	if request.Command != nil {
		arguments = append(arguments, "--", *request.Command)
	}
	return arguments, nil
}

tmuxq/filter.go.content:
package tmuxq

import "iter"

// Filter is anything that compiles itself into a predicate over T, which is
// what the tmux package's generated model filters do. It exists so a filter
// and a query can meet without this package naming a model.
type Filter[T any] interface {
	// Predicate returns the test this filter describes, or the reason it
	// cannot be one.
	Predicate() (func(*T) bool, error)
}

// Matching returns a fresh slice of shallow copies for values that filter
// accepts, retaining their source order, and reports the one error a filter
// can have rather than leaving it for the caller to unpack first. It evaluates
// every input value, so a no-match result is an empty slice.
//
//	active, err := tmuxq.Matching(snapshot.Panes(), tmux.PaneActiveIs(true))
func Matching[T any](values []T, filter Filter[T]) ([]T, error) {
	predicate, err := filter.Predicate()
	if err != nil {
		return nil, err
	}
	return Where(values, predicate), nil
}

// MatchingSeq returns a lazy sequence of shallow copies for values that filter
// accepts, retaining source order. The filter is compiled before iteration
// begins, so an invalid filter is an error here rather than a sequence that
// yields nothing.
func MatchingSeq[T any](values iter.Seq[T], filter Filter[T]) (iter.Seq[T], error) {
	predicate, err := filter.Predicate()
	if err != nil {
		return nil, err
	}
	return WhereSeq(values, predicate), nil
}

tmuxq/query.go.content:
package tmuxq

import (
	"errors"
	"iter"
)

// Cardinality sentinels classify [ExactlyOne] and [ExactlyOneSeq] results
// through [errors.Is].
var (
	// ErrNoMatch identifies an ExactlyOne or ExactlyOneSeq query with no
	// matching value. Cardinality errors can be checked with errors.Is.
	ErrNoMatch = errors.New("tmuxq: no match")
	// ErrMultipleMatches identifies an ExactlyOne or ExactlyOneSeq query
	// with more than one matching value. The queries stop when they find the
	// second match. Cardinality errors can be checked with errors.Is.
	ErrMultipleMatches = errors.New("tmuxq: multiple matches")
)

// Where returns a fresh slice of shallow copies for values accepted by
// predicate, retaining their source order. It evaluates every input value, so
// a no-match result is an empty slice.
func Where[T any](values []T, predicate func(*T) bool) []T {
	matches := make([]T, 0, len(values))
	for index := range values {
		candidate := values[index]
		if predicate(&candidate) {
			matches = append(matches, values[index])
		}
	}
	return matches
}

// First returns a shallow copy of the first source-ordered value accepted by
// predicate and stops evaluating later values. If no value matches, it returns
// the zero value of T and false.
func First[T any](values []T, predicate func(*T) bool) (T, bool) {
	for index := range values {
		candidate := values[index]
		if predicate(&candidate) {
			return values[index], true
		}
	}
	var zero T
	return zero, false
}

// ExactlyOne returns a shallow copy when exactly one source-ordered value is
// accepted by predicate. It examines values until source exhaustion confirms a
// sole match, or stops at the second match. It returns the zero value of T
// with [ErrNoMatch] for no matches or [ErrMultipleMatches] for multiple
// matches; callers can classify either error with [errors.Is].
func ExactlyOne[T any](values []T, predicate func(*T) bool) (T, error) {
	var match T
	found := false
	for index := range values {
		candidate := values[index]
		if !predicate(&candidate) {
			continue
		}
		if found {
			var zero T
			return zero, ErrMultipleMatches
		}
		match = values[index]
		found = true
	}
	if !found {
		var zero T
		return zero, ErrNoMatch
	}
	return match, nil
}

// WhereSeq returns a lazy sequence of shallow copies for values accepted by
// predicate, retaining source order. It does not pull values until the result
// is iterated. When its consumer stops, WhereSeq stops pulling from values.
// For an infinite input, it runs until its consumer stops.
func WhereSeq[T any](values iter.Seq[T], predicate func(*T) bool) iter.Seq[T] {
	return func(yield func(T) bool) {
		for value := range values {
			candidate := value
			if predicate(&candidate) && !yield(value) {
				return
			}
		}
	}
}

// FirstSeq returns a shallow copy of the first source-ordered sequence value
// accepted by predicate and stops pulling later values. If no value matches,
// it returns the zero value of T and false. With an infinite input that never
// matches, FirstSeq does not return.
func FirstSeq[T any](values iter.Seq[T], predicate func(*T) bool) (T, bool) {
	for value := range values {
		candidate := value
		if predicate(&candidate) {
			return value, true
		}
	}
	var zero T
	return zero, false
}

// ExactlyOneSeq returns a shallow copy when exactly one source-ordered
// sequence value is accepted by predicate. It stops pulling at the second
// match. If input ends with no matches, it returns the zero value of T with
// [ErrNoMatch]; if it finds a second match, it returns the zero value of T with
// [ErrMultipleMatches]. Callers can classify either error with [errors.Is].
// With an infinite input, ExactlyOneSeq returns only after a second match; it
// cannot confirm a no-match or exactly-one result without source exhaustion.
func ExactlyOneSeq[T any](values iter.Seq[T], predicate func(*T) bool) (T, error) {
	var match T
	found := false
	for value := range values {
		candidate := value
		if !predicate(&candidate) {
			continue
		}
		if found {
			var zero T
			return zero, ErrMultipleMatches
		}
		match = value
		found = true
	}
	if !found {
		var zero T
		return zero, ErrNoMatch
	}
	return match, nil
}

workspace/builder.go.content:
package workspace

import (
	"context"
	"errors"
	"fmt"
	"maps"
	"slices"
	"time"

	"github.com/libtmux/libtmux-go/tmux"
)

// InitialSessionRequest validates w and returns the request that creates its
// session and initial window. Use the resulting materialized session with
// [BuildInto] to continue the build over a caller-owned transport.
func (w Workspace) InitialSessionRequest() (tmux.NewSessionRequest, error) {
	if err := w.Validate(); err != nil {
		return tmux.NewSessionRequest{}, err
	}
	first := w.Windows[0]
	return tmux.NewSessionRequest{
		Name:           w.SessionName,
		StartDirectory: windowDirectory(first, firstWindowDirectory(w, first)),
		WindowName:     first.Name,
		Command:        windowCommand(first),
	}, nil
}

// Build creates the workspace on server and returns the created session.
//
// Build is not atomic. A failure after session creation returns that session;
// completed mutations remain in tmux. Command failures are not normalized.
// Every layout is checked against the selected daemon and desired pane count
// before session creation. tmux validates geometry when applying each layout.
//
// Build creates the session and an attached control connection in one process,
// uses that connection for the build, and closes it before returning. The
// returned Session is not bound to the closed connection. Build verifies that
// the session remains reachable after closing it. An attached connection may
// fire client hooks and policies.
//
// Each pane receives workspace, window, and pane CommandsBefore, then its own
// Commands. Sleep values pause Build rather than the pane.
func Build(ctx context.Context, server tmux.Server, workspace Workspace) (tmux.Session, error) {
	request, err := workspace.InitialSessionRequest()
	if err != nil {
		return tmux.Session{}, err
	}
	if err := workspace.validateLayouts(ctx, server); err != nil {
		return tmux.Session{}, err
	}
	created, connection, err := server.NewSessionConnection(
		ctx,
		request,
		tmux.ConnectionOptions{},
	)
	if err != nil {
		return created, fmt.Errorf("create session %q: %w", workspace.SessionName, err)
	}

	buildErr := BuildInto(ctx, connection.Session(), workspace)
	closeErr := connection.Close()
	if closeErr != nil {
		closeErr = fmt.Errorf("close workspace connection: %w", closeErr)
	}
	if err := errors.Join(buildErr, closeErr); err != nil {
		return created, err
	}
	refreshed, err := created.Refresh(ctx)
	if err != nil {
		return created, fmt.Errorf(
			"refresh built session after closing workspace connection: %w",
			err,
		)
	}
	return refreshed, nil
}

// BuildInto populates the initial session described by workspace. The session
// must already have been created from [Workspace.InitialSessionRequest].
// BuildInto uses the session's existing server and transport; it neither
// creates a session nor opens or owns a connection.
//
// BuildInto is not atomic. A failure leaves completed mutations in tmux.
// Every layout is checked before changing the initial session.
func BuildInto(ctx context.Context, session tmux.Session, workspace Workspace) error {
	if session.ID() == "" {
		return tmux.ErrMissingTarget
	}
	if err := workspace.Validate(); err != nil {
		return err
	}
	server := session.Server()
	if err := workspace.validateLayouts(ctx, server); err != nil {
		return err
	}

	// The initial window is created with the session before these values are set;
	// later windows can inherit them at creation.
	for _, name := range slices.Sorted(maps.Keys(workspace.GlobalOptions)) {
		if err := setGlobalOption(ctx, server, name, workspace.GlobalOptions[name]); err != nil {
			return fmt.Errorf("set global option %q: %w", name, err)
		}
	}

	for _, name := range slices.Sorted(maps.Keys(workspace.Environment)) {
		if err := session.SetEnvironment(
			ctx, name, workspace.Environment[name], tmux.SetEnvironmentOptions{},
		); err != nil {
			return fmt.Errorf("set environment %q: %w", name, err)
		}
	}
	for _, name := range slices.Sorted(maps.Keys(workspace.Options)) {
		if err := setSessionOption(ctx, session, name, workspace.Options[name]); err != nil {
			return fmt.Errorf("set session option %q: %w", name, err)
		}
	}

	var focusWindow *tmux.Window
	for index, described := range workspace.Windows {
		window, err := buildWindow(ctx, session, workspace, described, index)
		if err != nil {
			return err
		}
		if bool(described.Focus) {
			focused := window
			focusWindow = &focused
		}
	}

	if focusWindow != nil {
		if _, err := focusWindow.Select(ctx); err != nil {
			return fmt.Errorf("focus window: %w", err)
		}
	}
	return nil
}

func (w Workspace) validateLayouts(ctx context.Context, server tmux.Server) error {
	return server.ValidateLayouts(ctx, func(yield func(string, int) bool) {
		for _, window := range w.Windows {
			if !yield(window.Layout, max(1, len(window.Panes))) {
				return
			}
		}
	})
}

// buildWindow resolves the session's initial window or creates a later one,
// then builds its panes.
func buildWindow(
	ctx context.Context,
	session tmux.Session,
	workspace Workspace,
	described Window,
	position int,
) (tmux.Window, error) {
	directory := described.StartDirectory
	if directory == "" {
		directory = workspace.StartDirectory
	}

	var window tmux.Window
	var err error
	if position == 0 {
		window, err = session.ResolveActiveWindow(ctx)
		if err != nil {
			return window, fmt.Errorf("resolve initial window: %w", err)
		}
		// new-session cannot choose the initial winlink index, so move it
		// afterward unless it already occupies the requested index.
		if described.Index != nil && !windowAlreadyAt(window, *described.Index) {
			window, err = window.Move(ctx, tmux.MoveWindowRequest{
				TargetIndex: described.Index,
				NoSelect:    true,
			})
			if err != nil {
				return window, fmt.Errorf(
					"move initial window to index %d: %w", *described.Index, err)
			}
		}
	} else {
		request := tmux.NewWindowRequest{
			StartDirectory: windowDirectory(described, directory),
			Command:        windowCommand(described),
			Index:          described.Index,
		}
		if described.Name != "" {
			name := described.Name
			request.Name = &name
		}
		window, err = session.NewWindow(ctx, request)
		if err != nil {
			return window, fmt.Errorf("create window %q: %w", described.Name, err)
		}
	}

	for _, name := range slices.Sorted(maps.Keys(described.Environment)) {
		if err := session.SetEnvironment(
			ctx, name, described.Environment[name], tmux.SetEnvironmentOptions{},
		); err != nil {
			return window, fmt.Errorf("set window environment %q: %w", name, err)
		}
	}
	for _, name := range slices.Sorted(maps.Keys(described.Options)) {
		if err := window.SetOption(ctx, name, described.Options[name], tmux.SetOptionOptions{}); err != nil {
			return window, fmt.Errorf("set window option %q: %w", name, err)
		}
	}

	panes, err := buildPanes(ctx, session, window, workspace, described, directory)
	if err != nil {
		return window, err
	}

	for _, name := range slices.Sorted(maps.Keys(described.OptionsAfter)) {
		if err := window.SetOption(ctx, name, described.OptionsAfter[name], tmux.SetOptionOptions{}); err != nil {
			return window, fmt.Errorf("set window option %q after panes: %w", name, err)
		}
	}

	if described.Layout != "" {
		if err := window.SelectLayout(ctx, tmux.SelectLayoutRequest{
			Layout: described.Layout,
		}); err != nil {
			return window, fmt.Errorf("apply layout %q: %w", described.Layout, err)
		}
	}
	// With no pane declaring focus, tmuxp leaves the last pane it created
	// active; splitting detached leaves the first.
	focused := len(panes) - 1
	for index := range panes {
		if index < len(described.Panes) && bool(described.Panes[index].Focus) {
			focused = index
		}
	}
	if focused >= 0 {
		if _, err := panes[focused].Select(ctx, tmux.PaneSelectRequest{}); err != nil {
			return window, fmt.Errorf("focus pane %d: %w", focused, err)
		}
	}
	return window, nil
}

// buildPanes creates all panes before running commands so layout changes cannot
// interleave their output.
func buildPanes(
	ctx context.Context,
	session tmux.Session,
	window tmux.Window,
	workspace Workspace,
	described Window,
	directory string,
) ([]tmux.Pane, error) {
	first, err := window.ResolveActivePane(ctx)
	if err != nil {
		return nil, fmt.Errorf("resolve initial pane: %w", err)
	}
	panes := []tmux.Pane{first}

	// tmuxp allows a window with no panes; it still has the one tmux created.
	for index := 1; index < len(described.Panes); index++ {
		paneDirectory := described.Panes[index].StartDirectory
		if paneDirectory == "" {
			paneDirectory = directory
		}
		// Split the preceding pane so tmux preserves document order.
		pane, err := panes[index-1].Split(ctx, tmux.SplitPaneRequest{
			Direction:      tmux.PaneDirectionBelow,
			StartDirectory: paneDirectory,
			Command:        described.Panes[index].Shell,
		})
		if err != nil {
			return nil, fmt.Errorf("split pane %d: %w", index, err)
		}
		panes = append(panes, pane)
		// Keep the window rebalanced while it grows so a split never starves
		// for room. described.Layout, applied once every pane exists, still
		// has the final say.
		if err := window.SelectLayout(ctx, tmux.SelectLayoutRequest{
			Layout: "tiled",
		}); err != nil {
			return nil, fmt.Errorf("rebalance after pane %d: %w", index, err)
		}
	}

	for index, pane := range panes {
		if index >= len(described.Panes) {
			continue
		}
		describedPane := described.Panes[index]
		for _, name := range slices.Sorted(maps.Keys(describedPane.Environment)) {
			if err := session.SetEnvironment(
				ctx, name, describedPane.Environment[name], tmux.SetEnvironmentOptions{},
			); err != nil {
				return nil, fmt.Errorf("set pane environment %q: %w", name, err)
			}
		}
		suppress := paneSuppressHistory(workspace, described, describedPane)
		commands := make([]Command, 0, len(describedPane.Commands)+4)
		commands = append(commands, workspace.CommandsBefore...)
		commands = append(commands, described.CommandsBefore...)
		commands = append(commands, describedPane.CommandsBefore...)
		commands = append(commands, describedPane.Commands...)

		for _, command := range applyPaneDefaults(describedPane, commands) {
			if err := sleep(ctx, command.SleepBefore); err != nil {
				return nil, err
			}
			if command.Command != "" {
				text := command.Command
				if err := pane.SendKeys(ctx, tmux.SendKeysRequest{
					Command:         &text,
					SuppressHistory: suppress,
					SkipEnter:       !command.sends(),
					// A command that is also a tmux key name -- Space, Up,
					// Escape -- is that key without this.
					Literal: true,
				}); err != nil {
					return nil, fmt.Errorf("run %q in pane %d: %w", command.Command, index, err)
				}
			}
			if err := sleep(ctx, command.SleepAfter); err != nil {
				return nil, err
			}
		}
	}
	return panes, nil
}

func applyPaneDefaults(pane Pane, commands []Command) []Command {
	resolved := make([]Command, 0, len(commands))
	for _, command := range commands {
		if command.Enter == nil && pane.Enter != nil {
			enter := *pane.Enter
			command.Enter = &enter
		}
		if command.SleepBefore == 0 && pane.SleepBefore > 0 {
			command.SleepBefore = pane.SleepBefore
		}
		if command.SleepAfter == 0 && pane.SleepAfter > 0 {
			command.SleepAfter = pane.SleepAfter
		}
		resolved = append(resolved, command)
	}
	return resolved
}

func paneSuppressHistory(workspace Workspace, window Window, pane Pane) bool {
	if pane.SuppressHistory != nil {
		return bool(*pane.SuppressHistory)
	}
	if window.SuppressHistory != nil {
		return bool(*window.SuppressHistory)
	}
	return workspace.SuppressHistory == nil || bool(*workspace.SuppressHistory)
}

func sleep(ctx context.Context, duration time.Duration) error {
	if duration <= 0 {
		return nil
	}
	timer := time.NewTimer(duration)
	defer timer.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-timer.C:
		return nil
	}
}

func firstWindowDirectory(workspace Workspace, first Window) string {
	if first.StartDirectory != "" {
		return first.StartDirectory
	}
	return workspace.StartDirectory
}

// windowAlreadyAt lets tmux decide when the materialized index is unavailable.
func windowAlreadyAt(window tmux.Window, index int) bool {
	current, ok := window.Formats().WindowIndex()
	return ok && current == index
}

// The first pane is created with its window, so its directory must be passed
// to NewWindow. A pane-specific value wins.
func windowDirectory(described Window, fallback string) string {
	if len(described.Panes) > 0 && described.Panes[0].StartDirectory != "" {
		return described.Panes[0].StartDirectory
	}
	return fallback
}

// The first pane is created with its window, so its command must be passed to
// NewWindow. Validate rejects competing window and pane commands.
func windowCommand(described Window) string {
	if described.Shell != "" {
		return described.Shell
	}
	if len(described.Panes) > 0 {
		return described.Panes[0].Shell
	}
	return ""
}

// setSessionOption reproduces tmuxp's untyped dispatch across the session and
// window tables. It returns the session-scope error when neither accepts name.
func setSessionOption(ctx context.Context, session tmux.Session, name, value string) error {
	first := session.SetOption(ctx, name, value, tmux.SetOptionOptions{})
	if first == nil {
		return nil
	}
	window, err := session.ResolveActiveWindow(ctx)
	if err != nil {
		return first
	}
	if err := window.SetOption(ctx, name, value, tmux.SetOptionOptions{}); err == nil {
		return nil
	}
	return first
}

// setGlobalOption reproduces tmuxp's untyped dispatch across the global
// session, window, and server tables. It returns the session-scope error when
// none accepts name.
func setGlobalOption(ctx context.Context, server tmux.Server, name, value string) error {
	first := server.GlobalSessionScope().SetOption(ctx, name, value, tmux.SetOptionOptions{})
	if first == nil {
		return nil
	}
	if err := server.GlobalWindowScope().SetOption(
		ctx, name, value, tmux.SetOptionOptions{},
	); err == nil {
		return nil
	}
	if err := server.SetOption(ctx, name, value, tmux.SetOptionOptions{}); err == nil {
		return nil
	}
	return first
}

